def _organization_plan_tick():
    from services.organization_contract import feature_flags
    if not feature_flags()["ORGANIZATION_SHARED_PAYER_ENABLED"]:
        return
    from services.organization_plans import schedule_one_due_occurrence
    from services.organization_worker import dispatch_one_automatic_work

    async def _run_plan_tick():
        schedule_error = None
        try:
            await schedule_one_due_occurrence()
        except Exception as exc:
            schedule_error = exc
            logger.error("[organization-plan] occurrence reservation failed: %s", exc)
        dispatched = await dispatch_one_automatic_work()
        if schedule_error is not None and dispatched is None:
            raise schedule_error
        return dispatched

    asyncio.run(_run_plan_tick())


