def _activate_all_cron(via: str):
    """选主成功后激活全部 cron:开触发闸 → 启动两个 scheduler → 注册所有 job。
    幂等:scheduler.running / get_job(id) / add_job 幂等保证重复调用无副作用。"""
    from services.cron_gate import set_cron_active
    set_cron_active(True)  # 开闸:两个 scheduler 的 .start() 从此放行

    # 1) 主 scheduler(api.scheduler):get_scheduler() 现因闸开而 start;
    #    register_v32_core_tasks 已在模块导入期注册(见下方 v32 块);load_saved_schedule
    #    再补注册 DB 驱动的 monitoring + mhz job。
    try:
        from api.scheduler import get_scheduler, load_saved_schedule
        _main_scheduler = get_scheduler()  # 触发 .start()(闸已开)
        load_saved_schedule()    # 注册 monitoring + mhz jobs
        if not _main_scheduler.get_job("organization-plan-occurrences"):
            _main_scheduler.add_job(
                _organization_plan_tick, "interval", seconds=30,
                id="organization-plan-occurrences", coalesce=True,
                max_instances=1, misfire_grace_time=30,
            )
        if not _main_scheduler.get_job("organization-reservation-recovery"):
            _main_scheduler.add_job(
                _organization_recovery_tick, "interval", seconds=60,
                id="organization-reservation-recovery", coalesce=True,
                max_instances=1, misfire_grace_time=60,
            )
        if not _main_scheduler.get_job("geo-content-reconciliation"):
            _main_scheduler.add_job(
                _geo_content_recovery_tick, "interval", seconds=60,
                id="geo-content-reconciliation", coalesce=True,
                max_instances=1, misfire_grace_time=60,
            )
        if not _main_scheduler.get_job("publication-url-verification"):
            _main_scheduler.add_job(
                _publication_url_verification_tick, "interval", seconds=300,
                id="publication-url-verification", coalesce=True,
                max_instances=1, misfire_grace_time=120,
            )
        if not _main_scheduler.get_job("organization-invite-delivery"):
            _main_scheduler.add_job(
                _organization_invite_delivery_tick, "interval", seconds=30,
                id="organization-invite-delivery", coalesce=True,
                max_instances=1, misfire_grace_time=30,
            )
        logger.info(f"[cron-leader] 主调度器已激活({via})")
    except Exception as e:
        logger.error(f"[cron-leader] 主调度器激活失败({via}): {e}", exc_info=True)

    # 2) 根 scheduler(scheduler.py):init + 注册默认 job + start(闸已开)
    try:
        from scheduler import init_scheduler, setup_default_jobs, start_scheduler
        init_scheduler()
        setup_default_jobs()
        start_scheduler()
        logger.info(f"[cron-leader] 根调度器已激活({via})")
    except Exception as e:
        logger.warning(f"[cron-leader] 根调度器激活失败({via}): {e}")

    # 3) 调研监测 job(复用主 scheduler · 随 leader start 触发)
    try:
        from services.research_monitor.scheduler_setup import schedule_research_monitor_jobs
        rm = schedule_research_monitor_jobs()
        logger.info(f"[cron-leader] 调研监测 cron 已注册({via}): {rm}")
    except Exception as e:
        logger.warning(f"[cron-leader] 调研监测 cron 注册失败({via}): {e}")


def _pause_all_cron(reason: str):
    """丢租/降级:关闸 + best-effort 暂停两个 scheduler(SPEC §2.1 丢租 pause)。
    正确性由 sched_job_runs claim + 业务幂等兜底,不依赖此暂停。"""
    from services.cron_gate import set_cron_active
    set_cron_active(False)
    logger.error(f"[cron-leader] 丢失 leadership · 暂停 cron 触发: {reason}")
    try:
        from api.scheduler import get_scheduler
        _sch = get_scheduler()
        if _sch.running:
            _sch.pause()
    except Exception as e:
        logger.warning(f"[cron-leader] 暂停主调度器失败(best-effort): {e}")
    try:
        from scheduler import scheduler as _root_sched
        if _root_sched and _root_sched.running:
            _root_sched.pause()
    except Exception as e:
        logger.warning(f"[cron-leader] 暂停根调度器失败(best-effort): {e}")


def _resume_all_cron():
    """重新选上后恢复触发(scheduler 之前被 pause)。"""
    from services.cron_gate import set_cron_active
    set_cron_active(True)
    try:
        from api.scheduler import get_scheduler
        _sch = get_scheduler()
        if _sch.running:
            _sch.resume()
    except Exception as e:
        logger.warning(f"[cron-leader] 恢复主调度器失败(best-effort): {e}")
    try:
        from scheduler import scheduler as _root_sched
        if _root_sched and _root_sched.running:
            _root_sched.resume()
    except Exception as e:
        logger.warning(f"[cron-leader] 恢复根调度器失败(best-effort): {e}")


def _start_cron_leader_renew():
    """后台每 25s 续租(owner-CAS Lua);丢租 → pause + 回竞选循环。"""
    import threading
    import time as _t
    RENEW_INTERVAL = 25

    def _loop():
        global _cron_leader_lock
        while True:
            _t.sleep(RENEW_INTERVAL)
            lock = _cron_leader_lock
            if lock is None:
                return
            if lock.renew():
                continue
            _pause_all_cron("renew 返回 False(丢租 / Redis 故障 fail-closed)")
            _start_cron_leader_retry(resume=True)
            return

    threading.Thread(target=_loop, daemon=True, name="cron-leader-renew").start()
    logger.info(f"[cron-leader] 续租线程已启动(每 {RENEW_INTERVAL}s 刷 60s TTL)")


def _start_cron_leader_retry(resume: bool = False):
    """竞选循环:每 30s(120 次后 5min)尝试 acquire,成功即激活(或 resume)+ 起续租。
    无限重试 —— 蓝绿/Redis 故障最终必接管。"""
    import threading
    import time as _t

    def _loop():
        global _cron_leader_lock
        attempt = 0
        while True:
            attempt += 1
            # [FF12 P0-2] 前 60s 快速 retry(5s)→ 蓝绿切换旧 cron owner-CAS 释放锁后**秒级接管**
            #   (不必等 60s TTL 过期);之后回落 30s(至 ~12min)再 5min,省无谓竞选。
            _t.sleep(5 if attempt <= 12 else (30 if attempt <= 132 else 300))
            try:
                from cache.leader_lock import LeaderLock
                lock = LeaderLock(ttl_seconds=60)
                epoch = lock.acquire()
                if epoch is not None:
                    _cron_leader_lock = lock
                    if resume:
                        _resume_all_cron()
                        logger.info(f"[cron-leader] 第 {attempt} 次竞选成功 · 恢复 cron(epoch={epoch})")
                    else:
                        _activate_all_cron(f"retry epoch={epoch} 第 {attempt} 次")
                    _start_cron_leader_renew()
                    return
            except Exception as e:
                logger.warning(f"[cron-leader] 竞选 attempt {attempt} 异常: {e}")
            if attempt % 20 == 0:
                logger.error(f"[cron-leader] 已竞选 {attempt} 次仍未成为 leader · 集群可能暂无 cron 持有者,请检查")

    threading.Thread(target=_loop, daemon=True, name="cron-leader-retry").start()


@app.on_event("startup")
def startup_scheduler():
    """[WORKERS=4 · SPEC §2.1] cron 选主 + 激活(取代旧 scheduler:lock 内联续租/文件锁降级)。

    - 非 cron 角色(web/backup/prestart)直接跳过 → 4 worker 不再各跑 cron(修 4× 病根)。
    - cron 角色:LeaderLock 单 Lua 原子拿三把键(D3 互斥),赢则激活全部 cron + 续租;
      未赢(蓝绿另一 cron 持锁 / Redis 故障 fail-closed)→ background 竞选等接管。
    - 旧行为差异(已知 · 交付文档标注):Redis 故障期不再文件锁降级"仅一 worker 跑",
      而是 fail-closed 不跑(宁可漏跑靠 sweeper/结算重试补,不可双跑扣钱)。
    """
    if not _IS_CRON_ROLE:
        logger.info(f"[cron] ROLE={_SCHED_ROLE or 'web'} · 非 cron 角色,跳过全部 cron 触发(WORKERS=4)")
        return

    # 单机 dev(win32 未设 ROLE):无 Redis 选主,直接激活
    if sys.platform == 'win32' and _SCHED_ROLE == "":
        _activate_all_cron("win32-dev")
        logger.info("[cron] win32 dev · 已直接激活全部 cron(无选主)")
        return

    global _cron_leader_lock
    from cache.leader_lock import LeaderLock
    _cron_leader_lock = LeaderLock(ttl_seconds=60)
    epoch = _cron_leader_lock.acquire()
    if epoch is None:
        _cron_leader_lock = None
        logger.warning("[cron-leader] 未选上(蓝绿另一 cron 持锁 / Redis 故障 fail-closed)· 起 background 竞选等接管")
        _start_cron_leader_retry(resume=False)
        return

    _activate_all_cron(f"leader epoch={epoch}")
    _start_cron_leader_renew()


@app.on_event("shutdown")
async def _release_cron_leader_on_shutdown():
    """[FF12 P0-2] cron 优雅停机(SIGTERM → uvicorn shutdown)时 **owner-CAS 释放 LeaderLock 三键**,
    让新色 cron 秒级接管(不必等 60s TTL 过期)· 缩短蓝绿切换接管空窗。

    只有本进程是 cron leader(_cron_leader_lock 非空)才动作;web/非 leader 为 no-op。
    先摘 _cron_leader_lock(续租线程下一拍见 None 自然退出)再 release(owner-CAS 只删仍归本 token 的键)。"""
    global _cron_leader_lock
    lock = _cron_leader_lock
    if lock is None:
        return
    try:
        _cron_leader_lock = None
        lock.release()
        logger.info("[cron-leader] shutdown · 已 owner-CAS 释放 LeaderLock 三键(新 cron 可秒级接管)")
    except Exception as e:
        logger.warning(f"[cron-leader] shutdown 释放 LeaderLock 失败(键 60s TTL 自然过期兜底): {e}")


