# ========== 公开报告 v3 narrative runner ==========
# 默认不开自动扩写；开启 report_v3_auto_enrich 后，每 30s 扫一次 pending/stuck job。
@app.on_event("startup")
async def _start_report_v3_narrative_runner():
    if not _IS_CRON_ROLE:
        return  # [WORKERS=4] 周期副作用 runner 属 cron-only · web/backup 不起(防 4× 空转/双跑)
    async def _runner_loop():
        await asyncio.sleep(15)
        while True:
            try:
                from services.cron_gate import cron_should_fire
                from config.settings_manager import load_settings

                settings = load_settings()
                # 仅 leader 真正跑(cron 非 leader / 丢租期 cron_should_fire=False → 只空转不做副作用)
                if cron_should_fire() and getattr(settings, "report_v3_auto_enrich", False):
                    from services.narrative_job_runner import run_pending_once

                    results = await run_pending_once()
                    active = [item for item in results if item.get("status") not in ("skipped",)]
                    if active:
                        logger.info("[report-v3] narrative runner results=%s", active)
            except Exception as e:
                logger.warning(f"[report-v3] narrative runner skipped: {type(e).__name__}: {e}")
            await asyncio.sleep(30)

    asyncio.create_task(_runner_loop())
    logger.info("[startup] report-v3 narrative runner 已启动(auto_enrich=false 时空转)")


