# #2 修复：指定具体 origins，不再 allow_origins=["*"] + allow_credentials=True
# 生产环境通过 ALLOWED_ORIGINS 环境变量配置，逗号分隔
# Docker 容器内前端走 Nginx 同域不需要 CORS，但外部访问需要
_default_origins = [
    "http://localhost:1688",   # Vite 开发服务器
    "http://127.0.0.1:1688",
    "http://localhost:8000",    # 直连后端
    "http://127.0.0.1:8000",
    "http://localhost",         # Docker Nginx (port 80)
    "http://127.0.0.1",
]
_env_origins = os.getenv("ALLOWED_ORIGINS", "")
_cors_origins = [o.strip() for o in _env_origins.split(",") if o.strip()] if _env_origins else _default_origins
app.add_middleware(
    CORSMiddleware,
    allow_origins=_cors_origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)



