async def _bill_feature(http_request, feature_code: str):
    """通用扣费辅助函数（管理员免费）。

    注意: 这是"先扣不退"的版本。长耗时任务应改用 _bill_feature_ctx 获得
    自动退费能力。
    """
    if not http_request:
        return
    user = getattr(http_request.state, "user", None)
    if not user or user.get("is_admin"):
        return
    user_id = user.get("user_id")
    if not user_id:
        return
    from middleware.billing import deduct_points
    await deduct_points(user_id, feature_code)


from contextlib import asynccontextmanager as _acm

@_acm
async def _bill_feature_ctx(http_request, feature_code: str, multiplier: int = 1):
    """后扣费上下文（2026-04-18 升级"完成才扣"语义）

    [CTO-15.23 2026-05-19] 加 multiplier 参数支持 N 倍批量扣费
    - default multiplier=1 · 现有 caller 行为不变 ✓
    - multiplier=N(批量端点) · 自动 extra_cost=(N-1)*base · 总扣 N*base

    用法:
        # 单篇(单倍 · 跟旧版兼容)
        async with _bill_feature_ctx(http_request, "article_rewrite"):
            result = await do_expensive_work()

        # 批量 N 篇(多倍 · 防漏扣)
        async with _bill_feature_ctx(http_request, "article_gen", multiplier=len(topic_ids)):
            result = await batch_work()

        # 业务抛异常 → 未扣不退；正常结束 → 退出时才扣费
    """
    user = None
    user_id = None
    if http_request:
        user = getattr(http_request.state, "user", None)
        if user and not user.get("is_admin"):
            user_id = user.get("user_id")

    if not user_id:
        # 管理员或无上下文 → 跳过扣费直接执行
        yield
        return

    from middleware.billing import check_balance_only, deduct_points

    # [CTO-15.23 2026-05-19] multiplier > 1 → extra_cost = (multiplier - 1) * base
    extra_cost = 0
    if multiplier > 1:
        from db.wallet_db import get_feature_pricing
        from services.fallback_observability import priced as _fb_priced
        pricing = get_feature_pricing(feature_code)
        # 🔴 [WO_240] 八处里**最该出声的一处**,理由和别处不同:
        #    这是通用计费上下文,`feature_code` 是变量 —— 它替**很多个功能**取价;
        #    而它的默认值是 **0**,意思不是"恒等元",是 **「这一份免费」**:
        #    取价没走通 ⇒ `extra_cost = 0` ⇒ multiplier 份直接**只收一份**,**静默少收**。
        #    (我自己的枚举脚本一开始把默认值 0 当恒等元排除掉了,漏了这一处 ——
        #     是本包的分母锁把它找回来的。判据里每一个"排除",都是一块自陈的盲区。)
        base = int(_fb_priced(pricing, "cost_points", 0,
                              feature=feature_code,
                              where="server.py:_bill_feature_ctx"))
        extra_cost = (multiplier - 1) * base

    # 预检余额（不足 402 直接抛出，不进 with 体）
    await check_balance_only(user_id, feature_code, extra_cost=extra_cost)

    try:
        yield
    except Exception:
        # 业务失败 → 未扣不退
        raise

    # with 体正常结束 → 真扣
    # [CTO-15.23 2026-05-19 Codex P0 复验] 扣费失败不静默吞 · 升级 critical + 写 in-memory alert
    # 业务已完成 · 扣费失败 = 资金漏点 · 必须运维可见 + 后续 backfill
    # 不 raise(保业务返回结果) · 但 logger.critical + _BILLING_FAILURES list 给 admin 可查
    try:
        await deduct_points(user_id, feature_code, extra_cost=extra_cost)
    except Exception as e:
        logger.critical(
            f"[BILLING-FAILURE] {feature_code} 后扣费失败 user={user_id} extra={extra_cost} · "
            f"业务已完成 · 资金漏点需补扣 · {e}"
        )
        # 写入 in-memory alert(MAX 1000 项 · 后端重启丢失但 admin 可实时查)
        try:
            _BILLING_FAILURES.append({
                "user_id": user_id,
                "feature_code": feature_code,
                "extra_cost": extra_cost,
                "error": str(e)[:200],
                "occurred_at": datetime.now().isoformat() if 'datetime' in globals() else None,
            })
            if len(_BILLING_FAILURES) > 1000:
                _BILLING_FAILURES.pop(0)
        except Exception:
            pass


# [CTO-15.23 2026-05-19 Codex P0 复验] 扣费失败 in-memory alert log
# 给 /api/admin/billing-failures 端点查 + 后续接 Slack/邮件告警
# 跟 _bill_feature_ctx 配对 · 不写 DB 避免循环依赖 + 高频写入压力
_BILLING_FAILURES: list = []


def get_billing_failures() -> list:
    """admin 查询扣费失败 alert list(最近 1000 项)"""
    return list(_BILLING_FAILURES)


def _record_diag_settlement_issue(run_token: str, user_id, phase: str, detail) -> None:
    """[WORKERS=4 · SPEC §8 B4-8] 诊断结算未即时成功 → 记 _BILLING_FAILURES(admin 可查)。
    非终态问题(sweeper 会继续退避重试);真终态转人工由 diagnosis_runs 走 Redis 告警列表。"""
    try:
        _BILLING_FAILURES.append({
            "user_id": user_id,
            "feature_code": f"diagnosis_settlement:{phase}",
            "run_token": run_token,
            "extra_cost": 0,
            "error": (json.dumps(detail, ensure_ascii=False)[:300] if isinstance(detail, dict) else str(detail)[:300]),
            "occurred_at": datetime.now().isoformat() if 'datetime' in globals() else None,
        })
        if len(_BILLING_FAILURES) > 1000:
            _BILLING_FAILURES.pop(0)
    except Exception:
        pass


def _gate_diagnosis_visibility(record, *, allow_pending: bool = False):
    """[返工 P0-2b] 结果可见性统一拦截(withheld 全读取链不可见):
    - withheld(结算退款/失败/中断)→ 404 不可见(杜绝"退款仍拿结果" · 含 owner);
    - pending(生成中/结算前)→ 404 生成中(除非 allow_pending,如轮询状态端点只给状态);
    - NULL(旧数据兼容)/ published → 放行。
    record 为含 result_visibility 列的行 dict(get_diagnosis_by_id 走 SELECT * 即含此列)。"""
    if not isinstance(record, dict):
        return
    vis = record.get("result_visibility")
    if vis == "withheld":
        raise HTTPException(status_code=404, detail="该报告当前不可用(已退款或未完成)")
    if vis == "pending" and not allow_pending:
        raise HTTPException(status_code=404, detail="报告正在生成中,请稍后刷新查看")


# Request Models
class QuestionMeta(BaseModel):
    """[#149 · 2026-09-08] 一道题的**来源**元数据。

    题单里现在会混着两种题:AI 出的(候选直接进题单)与客户自己写的。
    后端必须能分辨,否则:
      · 品牌定向豁免会把 AI 出的品牌题也豁免掉,顶高提及率(承重墙,见工作流 §2.3);
      · 报告会把 AI 出的题写成「您填写的问题」。

    🔴 `layer` 不受限取值:层的取值域归生成器所有,在 DTO 写死 Literal
       会让生成器新增一层时**整页 500**(#139 那种炸法)。
    """
    text: str
    origin: Literal["ai_suggested", "customer"]
    side: Optional[Literal["growth", "defensive"]] = None
    layer: Optional[str] = None


class DiagnosisRequest(BaseModel):
    brand_name: str
    industry: str
    # 🔴 [订正二十三] 原为 `Field(..., min_length=1)`。
    # 题单编辑器取代旧关键词框之后,前端不再送 keywords ——
    # min_length=1 会让**每一次体检提交 422**,与题走哪个字段无关。
    # 空了不拒,改由下面的 model_validator 一处派生。
    keywords: List[str] = Field(default_factory=list)
    additional_info: Optional[str] = ""
    file_content: Optional[str] = ""
    # [NEW] 品牌账号排除功能
    own_accounts: Optional[List[str]] = None  # 客户自有账号（排除在竞品外）
    competitors: Optional[List[str]] = None   # 指定竞品（优先分析）
    # [P2] 复测时传入上次的业务上下文，确保测试问题一致
    business_context: Optional[dict] = None
    # [NEW] 诊断范围: "geo" GEO专项 / "social" 社媒专项 / "full" 全面诊断
    diagnosis_scope: Optional[str] = "geo"
    # [DEPRECATED] 保留向后兼容旧前端
    report_style: Optional[str] = None
    brand_display_names: Optional[List[str]] = None  # 用户确认的品牌常用名，用于诊断与后续监测
    client_location: Optional[str] = ""  # 客户区域（如"深圳"），用于长尾词地域锁定
    # [P0-4 2026-07-26] 业务范围:'regional'(默认 · 区域生意) | 'national'(全国生意)。
    #   区域客户的非品牌题必须带地域限定；全国客户才允许无地域大词。
    #   缺省/非法值一律按 regional 处理（services.diagnosis_question_quality）。
    business_scope: Optional[str] = ""
    brand_id: Optional[int] = None  # 前端传入品牌ID，确保诊断记录关联正确的品牌
    # [CTO-15.23 2026-05-21] 自定义诊断问题(老板拍板 + 5/21 订正)
    # 用户自定义 LLM 检测问题 · 默认 verbatim 跑(不主动优化 · 客户填啥跑啥)
    custom_questions: Optional[List[str]] = None
    # [#149 · 2026-09-08] 题面元数据(**可选**)。缺省 = 老前端,全部按 customer 处理
    #   ⇒ 与今天逐字节同行为。`custom_questions` 的形状一个字没动,
    #   所以价哈希那一带(题集 + 计价规则)继续成立。
    question_meta: Optional[List[QuestionMeta]] = None
    # [CTO-15.23 2026-05-21 老板订正] 主动优化 toggle:
    # - False(默认 · 老板诉求):只跑 custom verbatim · 主表=custom · 8 内 650 / 8 外 +100
    # - True(用户主动选):双轨 system+custom · 主表=system · 计费 650 + N×100(每自定义题加价)
    ai_optimize_custom: Optional[bool] = False
    # [#84 sec3] 只读价预览(POST)发的 id = 题集 + 计价规则的哈希。
    # 缺 -> 400;对不上 -> 409。legacy 的 freeze/扣费路径一行不动。
    price_preview_id: Optional[str] = None
    # [WORKERS=4 · SPEC §3.3a HC1] 请求级幂等标识:前端首次点击生成 uuid,重试/重发一律复用。
    #   缺省时服务端代生成 + WARN(WORKERS=1 兼容窗口;翻 4 前 Deploy 核 dist 已强制前端传真值)。
    #   同 (owner_user_id, client_request_id) 唯一 → 响应超时重试不再重复冻结第二笔。
    client_request_id: Optional[str] = None

    @field_validator("keywords")
    @classmethod
    def validate_keywords(cls, v):
        # 空列表放行:下限交给 `start_diagnosis` 一处派生。
        # 🔴 上限从**唯一定义处**取:档案词是在本校验之后赋进去的,
        #    两处各写一遍 20/50,漂了不会有任何东西报错。
        from services.diagnosis_keyword_source import (
            MAX_KEYWORDS as _MAXKW, MAX_KEYWORD_CHARS as _MAXCH)
        if len(v) > _MAXKW:
            raise ValueError(f"关键词不能超过 {_MAXKW} 个")
        for kw in v:
            if len(kw) > _MAXCH:
                raise ValueError(f"单个关键词不能超过 {_MAXCH} 字符: {kw[:20]}...")
            if not kw.strip():
                raise ValueError("关键词不能为空字符串")
        return [kw.strip() for kw in v]

    # 🔴 [订正二十六] keywords 的派生**整个搬到** `start_diagnosis` 了,
    #    这里**不留空壳**:DTO 无库,而派生要读 `client_profiles.seed_keywords`。
    #    留一半在这儿就是两处派生 —— 落库记空而 workflow 跑了派生值,且不报错。
    #    三源皆空的 422 一并随迁(档案有词而品牌名/行业皆空时不该拒)。
    @field_validator("custom_questions")
    @classmethod
    def validate_custom_questions(cls, v):
        if v is None:
            return None
        # 单题 100 字防 prompt 注入 · 空字符串过滤 · 去重
        cleaned = []
        seen = set()
        for q in v:
            if not isinstance(q, str):
                continue
            q = q.strip()
            if not q or q in seen:
                continue
            # [#157] 上限口径走**唯一那一份**(services.diagnosis_question_pricing)。
            #   报文逐字不变 —— 本次只是把"100"这个数字搬到 SSOT,不改行为。
            from services.diagnosis_question_pricing import (
                MAX_QUESTION_CHARS, question_length_violation)
            if question_length_violation(q) is not None:
                raise ValueError(
                    f"自定义问题不能超过 {MAX_QUESTION_CHARS} 字符: {q[:30]}...")
            cleaned.append(q)
            seen.add(q)
        return cleaned if cleaned else None

    @field_validator("brand_display_names")
    @classmethod
    def validate_brand_display_names(cls, v):
        if v is None:
            return None
        from services.brand_identity_resolver import normalize_confirmed_display_names

        return list(normalize_confirmed_display_names(v))

    @model_validator(mode="after")
    def validate_question_meta_subset(self):
        """🔴 [#149] `question_meta.text` 必须 ⊆ `custom_questions`(归一化后)。

        多出来的条目 = 前端以为要跑、而**没有进题集**的题 ——
        它既没被计价、也不会被跑。放行的话:报告按 meta 的条数说「本次 N 道」,
        实跑却少几道,而两边各自看都正常。所以 422 拒,并**明说没扣算力**
        (她最关心的是「我是不是被扣了钱」)。

        归一化走 `normalize_questions` **同一份口径** —— 这里再写一遍
        strip/去重,就是「同一谓词写两处」:哪天一处改了大小写口径,
        表现是用户被 422 挡住而不是报错。
        """
        if not self.question_meta:
            return self
        from services.diagnosis_question_pricing import normalize_questions

        allowed = set(normalize_questions(self.custom_questions or []))
        extra = [(m.text or "").strip() for m in self.question_meta
                 if (m.text or "").strip() not in allowed]
        if extra:
            raise ValueError(
                "question_meta 里有 %d 道题不在题单(custom_questions)里:%s。"
                "这些题不会被跑、**也没有扣你的算力**;"
                "请把它们加进题单,或从元数据里去掉。"
                % (len(extra), "、".join(repr(t) for t in extra[:3])))
        return self

# Global mapping to keep track of running tasks?
# Not strictly needed if we trust the session_id passed to callbacks.

async def progress_callback_wrapper(session_id: str, stage_id: str, progress: int, message: str):
    """
    Wrapper to match the signature expected by diagnosis_workflow if we change it,
    or just direct call.
    """
    payload = {
        "type": "progress",
        "stage": stage_id,     # 前端主要用stage
        "stage_id": stage_id,  # 兼容旧版
        "progress": progress,
        "message": message
    }
    logger.info(f"[WS进度] {session_id}: {stage_id} = {progress}% ({message})")
    await manager.send_message(session_id, payload)

# [audit P1 2026-06-10] 诊断任务总超时(秒)· 正常 lite ~3-8min / full ~15-25min · 30min=卡死判定线
_DIAGNOSIS_TOTAL_TIMEOUT_SECONDS = 1800


async def run_diagnosis_task(
    request: DiagnosisRequest,
    session_id: str,
    creator_user_id: int = None,
    run_token: str = None,
    slot_mode: str = "none",
    organization_identity=None,
    organization_charge_id: int = None,
    organization_charge_points: int = None,
    organization_claim_token: str = None,
    ai_engines: list = None,
):
    """诊断任务包装器（WORKERS=4 · SPEC §3 诊断资金状态机接线）

    - run_token 存在(有身份)→ 走 diagnosis_runs 状态机:心跳(run 行 heartbeat_at + 续 Redis 槽)·
      成功 commit_run(paid→commit_pending→commit+published / exempt→completed_exempt)· 失败
      release_run(退款 · withheld)· finally 释放并发槽。**billing.py 只调不改**(结算四参在
      services.diagnosis_runs 内 · task_ref='diag_'+run_token + freeze_id 直达)。
    - run_token 为 None(无身份/无计费)→ 仅跑 impl,无结算(旧无身份路径行为保留)。
    - slot_mode:'redis'(admission 已抢槽 · 此处续+释)/ 'semaphore'(WORKERS=1·Redis 抖动兜底 ·
      进程内 _diagnosis_semaphore 限并发保 I4)/ 'none'(无闸)。
    """
    from services import diagnosis_runs as _dr
    from cache import diagnosis_slots as _slots

    async def _run_body():
        _hb_stop = asyncio.Event() if run_token else None
        _lease_lost = asyncio.Event()
        _hb_task = None
        if run_token:
            async def _hb_loop():
                # 心跳 60s:刷 run 行 heartbeat_at + 续 Redis 槽。
                # [返工 P1-1] 心跳**确定丢失**(命中 0 行=被收尸)或 Redis 槽**确定丢失**(renew False)
                #   → 置 _lease_lost → 主体中止诊断(不再写产物/调 LLM/突破并发上限);None(抖动)不判丢。
                while not _hb_stop.is_set():
                    try:
                        await asyncio.wait_for(_hb_stop.wait(), timeout=60)
                        break
                    except asyncio.TimeoutError:
                        pass
                    try:
                        held = await asyncio.to_thread(_dr.heartbeat_run, run_token)
                        renewed = True
                        if slot_mode == "redis":
                            renewed = await asyncio.to_thread(_slots.renew_slot, run_token)
                        if held is False or renewed is False:
                            logger.warning(f"[Diagnosis] run={run_token} lease 确定丢失(hb={held}/slot={renewed})· "
                                           f"中止诊断任务(run 交 sweeper 处置)")
                            _lease_lost.set()
                            break
                    except Exception:
                        pass
            _hb_task = asyncio.create_task(_hb_loop())
        try:
            if organization_charge_id is not None:
                from services.organization_billing import mark_external_side_effect_started
                await asyncio.to_thread(
                    mark_external_side_effect_started,
                    charge_link_id=organization_charge_id,
                    claim_token=organization_claim_token,
                )
            # [audit P1] 诊断总超时看门狗:任一内部 await 挂死 → 30min 强制 TimeoutError → 走 except release 路径
            # [返工 P0-2a] impl 返回完成 payload(不再自己发 done=true complete)
            # [返工 P1-1] impl 跑成任务,与 _lease_lost 竞争;lease 丢 → cancel impl 早停,不再写产物
            _impl_task = asyncio.create_task(asyncio.wait_for(
                _run_diagnosis_impl(
                    request,
                    session_id,
                    creator_user_id,
                    run_token=run_token,
                    organization_identity=organization_identity,
                    ai_engines=ai_engines,
                ),
                timeout=_DIAGNOSIS_TOTAL_TIMEOUT_SECONDS,
            ))
            if run_token:
                _lease_wait = asyncio.create_task(_lease_lost.wait())
                await asyncio.wait({_impl_task, _lease_wait}, return_when=asyncio.FIRST_COMPLETED)
                if _lease_lost.is_set() and not _impl_task.done():
                    _impl_task.cancel()
                    try:
                        await _impl_task
                    except BaseException:
                        pass
                    _lease_wait.cancel()
                    # run 已被 sweeper 收尸(release_pending)· 任务不重复动钱 · finally 清理心跳/槽
                    logger.warning(f"[Diagnosis] run={run_token} lease 丢失中止(sweeper 处置结算)")
                    return
                _lease_wait.cancel()
            completion = await _impl_task   # 正常完成取 payload;异常(含 30min 超时)抛出走 except release
            _complete_snap = completion if isinstance(completion, dict) else {
                "type": "complete", "stage": "done", "progress": 100, "done": True,
                "terminal": True, "message": "诊断完成"}
            if run_token:
                diagnosis_id = _complete_snap.get("diagnosis_id")
                complete_product = await asyncio.to_thread(
                    _dr.require_complete_product,
                    session_id,
                    diagnosis_id,
                )
                diagnosis_id = int(complete_product["id"])
                _complete_snap["diagnosis_id"] = diagnosis_id
                # 产物写入后 stamp pending(覆盖 brand_id=None save_diagnosis 直建 · brand_id 有占位则 no-op)
                await asyncio.to_thread(
                    _dr.mark_product_pending,
                    run_token,
                    session_id,
                    diagnosis_id,
                    _complete_snap,
                )
                # 成功 → 结算(commit_run:exempt→completed_exempt 无 billing / paid→commit_pending→commit+published)
                #   终态 snapshot 用 impl 返回 payload(含 diagnosis_id/share_token · P1-2 前端跳转 + reconciler 回补)
                try:
                    # [P0-3c 件2] org / 非 org 的结算分派抽成了可测函数
                    #   `_dr.dispatch_success_settlement` —— 原来那段 if/else 长在这里,
                    #   而判据目录**零条在运行时执行 server.py**,所以"方向反了会怎样"
                    #   没有任何东西在守(同族守卫反转后 92 条判据全绿)。
                    #   搬走之后两条臂可以被真跑:真 settle_charge / 真 commit_run / 真终态落库。
                    out = await _dr.dispatch_success_settlement(
                        run_token=run_token,
                        session_id=session_id,
                        diagnosis_id=diagnosis_id,
                        snapshot=_complete_snap,
                        organization_charge_id=organization_charge_id,
                        organization_charge_points=organization_charge_points,
                        organization_claim_token=organization_claim_token,
                        brand_id=request.brand_id,
                    )
                    if out.get("ok") and not _dr.commit_outcome_is_success(out):
                        # [P0-3 · 2026-08-24] commit 在结算内部**改道退款了**(产物证明不过关 ——
                        #   典型是零成功观测的"没测成"),`ok=True` 说的是"这次结算动作成功了",
                        #   不是"这一单成交了"。原来这里只看 ok 就发 _complete_snap,而
                        #   _complete_snap 带着 done=true / diagnosis_id / share_token /
                        #   result.level("隐形级")—— 钱退了却告诉客户"诊断完成 · 隐形级",
                        #   既误导又和已 withheld 的报告(点进去 404)自相矛盾。
                        logger.warning(f"[Diagnosis] run={run_token} commit 改道退款 终态=released")
                        try:
                            await manager.send_message(session_id, {
                                "type": "error", "stage": "failed", "progress": 100, "done": True,
                                "terminal": True, "not_measured": True,
                                "message": _dr.NOT_MEASURED_MESSAGE,
                                "error": _dr.NOT_MEASURED_MESSAGE})
                        except Exception:
                            pass
                        manager.clear_task(session_id)
                    elif _dr.commit_outcome_is_success(out):
                        logger.info(f"[Diagnosis] run={run_token} 结算终态={out.get('terminal')}")
                        # [P0-2a] **结算成功后才**发成功终态 complete(含 diagnosis_id/share_token)+ 清缓存
                        try:
                            await manager.send_message(session_id, _complete_snap)
                        except Exception:
                            pass
                        manager.clear_task(session_id)
                    elif out.get("terminal") == "delivery_repair_pending":
                        # [返工2 P0-2] 钱已 committed 但产物 0 行(被并发删/未落库)→ **非成功终态** ·
                        #   绝不发 complete(含分数/诊断 ID),发异常终态让用户看到"报告异常待补发",转人工。
                        logger.error(f"[Diagnosis] run={run_token} committed 但产物缺 → delivery_repair_pending: {out}")
                        _record_diag_settlement_issue(run_token, creator_user_id, "delivery_repair", out)
                        try:
                            await manager.send_message(session_id, {
                                "type": "error", "stage": "failed", "progress": 100, "done": True,
                                "terminal": True, "error": "报告生成异常",
                                "message": "报告生成异常,已记录并将尽快为你补发,如有疑问请联系客服"})
                        except Exception:
                            pass
                        manager.clear_task(session_id)
                    else:
                        # 结算未即时成功(交 sweeper 重试)→ **绝不发成功终态**;发"结算中"进度,终态由 reconciler 补发
                        logger.warning(f"[Diagnosis] run={run_token} commit 未即时成功(交 sweeper 重试): {out}")
                        _record_diag_settlement_issue(run_token, creator_user_id, "commit", out)
                        try:
                            # [P0-3b 挂账 B] 「疑似品牌识别失败」是**确定的终态**(冻结挂着等人裁),
                            #   不是"稍等一下就好了"。继续发 done:false 的"正在完成结算"会让前端
                            #   一直转圈,用户既不知道要等人工、也不知道钱还没扣。如实说一句就好。
                            _manual_identity = (
                                out.get("terminal") == "settlement_manual"
                                and out.get("reason") == _dr.IDENTITY_REVIEW_REASON)
                            if _manual_identity:
                                await manager.send_message(session_id, {
                                    "type": "error", "stage": "failed", "progress": 100,
                                    "done": True, "terminal": True, "needs_manual_review": True,
                                    "message": _dr.IDENTITY_REVIEW_MESSAGE,
                                    "error": _dr.IDENTITY_REVIEW_MESSAGE})
                                manager.clear_task(session_id)
                            elif out.get("terminal") == "settlement_manual":
                                # [settlement-manual-ux · 档A] commit 判成**转人工**(非品牌识别那一支,
                                #   典型是 reserved_split_order_unknown / sum_mismatch / order_invalid)。
                                #   这是**确定终态**(冻结挂着等人裁),不是"稍等一下就好了" ——
                                #   原来跟"交 sweeper 重试"共用同一句 done:false"正在完成结算",
                                #   于是前端永远转圈。
                                #   ⚠️ 只有这一支发终态;下面那个 else(真的还在重试)一个字没动。
                                await manager.send_message(
                                    session_id, _dr.settlement_manual_terminal())
                                manager.clear_task(session_id)
                            else:
                                await manager.send_message(session_id, {
                                    "type": "progress", "stage": "settling", "progress": 99,
                                    "message": "正在完成结算,请稍候...", "done": False})
                        except Exception:
                            pass
                except Exception as cex:
                    logger.error(f"[Diagnosis] run={run_token} commit 异常(交 sweeper): {cex}")
                    _record_diag_settlement_issue(run_token, creator_user_id, "commit_exc", {"error": str(cex)[:200]})
                    # [P0-3b · R-a] organization 计费口的**内层**异常兜底。
                    #   这一层 except 会把异常吞掉,外层 `except Exception as e` 的 org release 分支
                    #   **够不到** —— 于是 settle_charge 中途抛(竞态窗可达)时,charge link 就那么
                    #   冻着,既没 commit 也没 release,用户侧也没有终态。补上与外层同款的 release 路由。
                    #   非 org 的 legacy 冻结不在这里补:它有 sweeper 按 run_status 兜底
                    #   (commit_pending/release_pending 到期重试),org charge link 没有那条兜底。
                    if organization_charge_id is not None:
                        try:
                            from services.organization_billing import release_charge as _release_org_cex
                            await _release_org_cex(
                                charge_link_id=organization_charge_id,
                                reason=f"commit_exc:{str(cex)[:160]}",
                                diagnosis_run_token=run_token,
                                diagnosis_session_id=session_id,
                                failure_snapshot=_dr._failed_snapshot(),
                            )
                            logger.info(f"[Diagnosis] run={run_token} commit 异常 → org charge 已释放")
                            try:
                                await manager.send_message(session_id, {
                                    "type": "error", "stage": "failed", "progress": 100,
                                    "done": True, "terminal": True,
                                    "message": "诊断结算异常,算力已退回,请重试",
                                    "error": str(cex)[:500]})
                            except Exception:
                                pass
                            manager.clear_task(session_id)
                        except Exception as _rex2:
                            # 释放也失败 → 记问题单交人工,绝不假装已退。
                            logger.error(f"[Diagnosis] run={run_token} commit 异常后 org 释放亦失败: {_rex2}")
                            _record_diag_settlement_issue(
                                run_token, creator_user_id, "commit_exc_release_failed",
                                {"error": str(_rex2)[:200]})
                            # [settlement-manual-ux · 档C] 这一档原来**什么都不发** ——
                            #   钱既没扣也没退、交人工了,而用户侧一个字没有,前端停在 99% 一直转。
                            #   "绝不假装已退"是对的,"什么都不说"是另一回事。
                            #   只在 run 真的停在 settlement_manual 时说 —— 状态由 run 行说了算,
                            #   不由"走进了哪个 except"说了算。
                            if await asyncio.to_thread(_dr.run_is_settlement_manual, run_token):
                                try:
                                    await manager.send_message(
                                        session_id, _dr.settlement_manual_terminal())
                                except Exception:
                                    pass
                                manager.clear_task(session_id)
            else:
                # run_token=None(无身份/无计费)→ 无结算 · 直接发完成 payload(旧行为保留)
                try:
                    await manager.send_message(session_id, _complete_snap)
                except Exception:
                    pass
                manager.clear_task(session_id)
        except Exception as e:
            logger.error(f"[Diagnosis] 任务 {session_id} 失败,准备释放冻结: {e}")
            if run_token:
                # [返工3 P1] 付费路径:**禁在退款终态确认前宣布终止/费用已退**。原实现先发 done:true"任务失败"再 release,
                #   若退款进 release_pending/settlement_manual(未即时确认),前端已停轮询 → 永远看不到"费用已退"正式终态。
                #   改:先发 done:false"结算处理中" → 退款终态(released/failed_exempt)确认后才发正式终态;未即时终态则
                #   保持 done:false,终态由 sweeper 完成后 _publish_run_terminal_best_effort 跨 worker 回推。
                #   另:付费路径**不删占位诊断**(保留做刷新追踪 · 同步压 pending 可见性防状态端点回退成假完成 · 见下)。
                try:
                    # 压 pending:轮询回退显 done:false 而非 NULL-score 假完成(保留占位行做刷新追踪的配套)
                    await asyncio.to_thread(_dr.mark_session_visibility_pending, session_id)
                except Exception:
                    pass
                # [P0-3 · 2026-08-24] 「没测成」是一类**要如实说清楚**的失败,不能混进
                #   笼统的"诊断任务失败"。它走到这里是因为 :2781 结算前的产物证明
                #   (require_complete_product)判出零成功观测 —— 客户该听到的是
                #   "这次没有测成,算力已退回",而不是一句让人以为是自己品牌有问题的话。
                from services.diagnosis_sample_contract import DiagnosisNotMeasuredError as _NotMeasured
                _not_measured = isinstance(e, _NotMeasured)
                _fail_line = _dr.NOT_MEASURED_MESSAGE if _not_measured else f"诊断任务失败：{str(e)[:200]}"
                try:
                    await manager.send_message(session_id, {
                        "type": "progress", "stage": "failed", "progress": 100,
                        "message": (_fail_line if _not_measured else f"{_fail_line},费用结算处理中..."),
                        "done": False, "error": str(e)[:500]})
                except Exception:
                    pass
                _rel_snap = (
                    _dr._not_measured_snapshot() if _not_measured
                    else {"type": "error", "stage": "failed", "progress": 0, "done": True,
                          "terminal": True, "message": "诊断任务失败,费用已退,请重试"}
                )
                _settling = True
                try:
                    if organization_charge_id is not None:
                        from services.organization_billing import release_charge as _release_org_charge
                        _released_charge = await _release_org_charge(
                            charge_link_id=organization_charge_id,
                            reason=str(e)[:200],
                            diagnosis_run_token=run_token,
                            diagnosis_session_id=session_id,
                            failure_snapshot=_rel_snap,
                        )
                        out = {"ok": True, "terminal": "released", "charge": _released_charge}
                    else:
                        out = await _dr.release_run(run_token, reason=str(e)[:200], snapshot=_rel_snap)
                    _term = out.get("terminal")
                    if out.get("ok") and _term in ("released", "failed_exempt"):
                        # 退款终态确认 → 发正式终态(released=已退款 / failed_exempt=免单无退款)
                        _settling = False
                        if _not_measured:
                            _msg = _dr.NOT_MEASURED_MESSAGE
                        else:
                            _msg = "诊断任务失败,费用已退,请重试" if _term == "released" else "诊断任务失败,请重试"
                        logger.info(f"[Diagnosis] run={run_token} 释放冻结 终态={_term}")
                        try:
                            await manager.send_message(session_id, {
                                "type": "error", "stage": "failed", "progress": 0, "done": True,
                                "terminal": True, "not_measured": _not_measured,
                                "message": _msg, "error": str(e)[:500]})
                        except Exception:
                            pass
                    else:
                        logger.warning(f"[Diagnosis] run={run_token} release 未即时终态(交 sweeper 回推终态): {out}")
                        _record_diag_settlement_issue(run_token, creator_user_id, "release", out)
                except Exception as rex:
                    logger.error(f"[Diagnosis] run={run_token} 释放调用异常(交 sweeper 回推): {rex}")
                    _record_diag_settlement_issue(run_token, creator_user_id, "release_exc", {"error": str(rex)[:200]})
                if _settling:
                    # [settlement-manual-ux · 档B] 这里原来一律发 done:false"结算处理中" ——
                    #   但它同时盖住了两种完全不同的处境:
                    #     ① 退款没即时确认,**sweeper 还会重试并回推真终态** → 该继续 done:false;
                    #     ② 退款被拒绝、run 已经落 **settlement_manual**(确定终态,等人裁)
                    #        → sweeper 不会再推,继续 done:false 就是让前端永远转圈。
                    #   分辨这两种只能问 run 行,不能看"走进了哪个分支"。
                    _manual_now = await asyncio.to_thread(_dr.run_is_settlement_manual, run_token)
                    try:
                        if _manual_now:
                            await manager.send_message(
                                session_id, _dr.settlement_manual_terminal())
                            manager.clear_task(session_id)
                        else:
                            # 退款未即时终态 → 保持 done:false"结算处理中"(禁提前宣布)· 终态交 sweeper 回推
                            await manager.send_message(session_id, {
                                "type": "progress", "stage": "settling", "progress": 100,
                                "message": "诊断任务失败,费用结算处理中,稍后可刷新查看", "done": False})
                    except Exception:
                        pass
            else:
                # 无 run_token(无身份/无计费)→ 无结算 · 保留旧行为:立即 done:true 报错 + 回删 NULL 占位
                try:
                    await manager.send_message(session_id, {
                        "type": "error", "stage": "failed", "progress": 0,
                        "message": f"诊断任务失败：{str(e)[:200]}", "done": True, "error": str(e)[:500]})
                except Exception:
                    pass
                try:
                    await asyncio.to_thread(_delete_diagnosis_placeholder, session_id)
                except Exception as pex:
                    logger.warning(f"[Diagnosis] session={session_id} 占位回删异常: {pex}")
            # 不 re-raise,避免 asyncio.create_task 打印 unhandled exception
        finally:
            if _hb_stop is not None:
                _hb_stop.set()
            if _hb_task is not None:
                _hb_task.cancel()
            if run_token and slot_mode == "redis":
                await asyncio.to_thread(_slots.release_slot, run_token)

    if slot_mode == "semaphore":
        async with _diagnosis_semaphore:   # WORKERS=1 · Redis 抖动兜底(保 I4 并发上限)
            await _run_body()
    else:
        await _run_body()

async def _run_diagnosis_impl(request: DiagnosisRequest, session_id: str, creator_user_id: int = None,
                              run_token: str = None, organization_identity=None,
                              ai_engines: list = None):
    logger.info(f"Starting diagnosis for {session_id}")

    # [P0-3b hotfix · Deploy-CTO 2026-08-25] `_dr` 在 server.py 里从来只有【函数内】绑定
    #   (`run_diagnosis_task`:2708 与 `start_diagnosis`:3447),模块级没有。
    #   P0-3b 把一处 `_dr.settlement_signals_from_result(result)` 加进了本函数的完成 payload
    #   (:3321),而本函数从来不 import 它 → **每一单走到完成 payload 的诊断都抛 NameError**,
    #   四引擎跑完、报告已入库,却在 99% 处整单转失败并退款(生产实证 run_3ae63ad3 / diagnosis_id=657)。
    #   保持【函数内 import】而不是提到模块级:与既有两处同形,且模块级导入有循环导入风险。
    from services import diagnosis_runs as _dr

    # [NEW] 获取诊断scope（向后兼容 report_style）
    diagnosis_scope = request.diagnosis_scope or request.report_style or "geo"
    # 兼容旧前端: sales→geo, technical→full
    if diagnosis_scope == "sales": diagnosis_scope = "geo"
    if diagnosis_scope == "technical": diagnosis_scope = "full"

    # Trusted display names must come from the same persisted brand_id. A
    # global name/fuzzy lookup can attach another tenant's aliases and is never
    # used as a commercial or brand-identity fallback.
    # Brandless diagnostics may use only the names explicitly confirmed in
    # this request. Persisted brands always reload the brand-scoped SSOT.
    brand_display_names = (
        list(request.brand_display_names or []) if not request.brand_id else None
    )
    if request.brand_id:
        def _lookup_brand_display_names(brand_id: int):
            from db.connection import get_connection as _get_conn
            conn = _get_conn()
            try:
                cursor = conn.cursor()
                cursor.execute(
                    "SELECT brand_display_names FROM brands WHERE id = %s",
                    (int(brand_id),),
                )
                row = cursor.fetchone()
                cursor.close()
                if row and row.get("brand_display_names"):
                    raw = row["brand_display_names"]
                    return raw if isinstance(raw, list) else json.loads(raw)
                return None
            finally:
                conn.close()
        try:
            _names = await asyncio.to_thread(_lookup_brand_display_names, request.brand_id)
            if _names:
                brand_display_names = _names
                logger.info("[品牌别名] 已按 brand_id 加载 count=%s", len(brand_display_names))
        except Exception as e:
            logger.warning("[品牌别名] 按 brand_id 加载失败 error_type=%s", type(e).__name__)

    # Notify start - 包含diagnosis_scope让前端显示正确的进度步骤
    await manager.send_message(session_id, {
        "type": "status",
        "status": "started",
        "session_id": session_id,
        "diagnosis_scope": diagnosis_scope,
        "report_style": diagnosis_scope,  # 向后兼容旧前端
    })

    try:
        # Define the callback to be passed to the workflow
        async def callback(stage: str, msg: str, progress: int):
            await progress_callback_wrapper(session_id, stage, progress, msg)

        # [P4 知识库同步根治] 把客户已确认/整理资料(client_materials)拼进业务分析输入,
        # 让诊断对客户业务的理解/建议更贴合实际(纯增强 LLM 输入 · 不碰评分 · 不改 workflow 主链)
        _client_materials_ctx = ""
        if getattr(request, "brand_id", None):
            try:
                from db.diagnosis_db import get_client_materials_by_brand
                import json as _json
                _m = get_client_materials_by_brand(request.brand_id)
                if _m:
                    _parts = []
                    for _k, _label in (
                        ("company_intro", "公司简介"), ("unique_value", "独特价值"),
                        ("service_area", "服务范围"), ("methodology", "方法/打法"),
                    ):
                        _v = _m.get(_k)
                        if isinstance(_v, str) and _v.strip():
                            _parts.append(f"{_label}：{_v.strip()}")
                    for _k, _label in (
                        ("core_selling_points", "核心卖点"), ("case_studies", "成功案例"),
                        ("testimonials", "客户证言"),
                    ):
                        _v = _m.get(_k)
                        if _v:
                            _txt = _v if isinstance(_v, str) else _json.dumps(_v, ensure_ascii=False)
                            if _txt and _txt.strip() and _txt.strip() not in ("[]", "{}", "null"):
                                _parts.append(f"{_label}：{_txt.strip()}")
                    if _parts:
                        _client_materials_ctx = "\n【客户已确认资料】\n" + "\n".join(_parts)
                        logger.info(f"[诊断·资料同步] 已并入客户整理资料 brand_id={request.brand_id} · {len(_parts)} 项")
            except Exception as _e:
                logger.warning(f"[诊断·资料同步] 读取 client_materials 失败(已忽略·保持旧行为): {_e}")

        # Run workflow
        result = await run_diagnosis_workflow(
            brand_name=request.brand_name,
            industry=request.industry,
            keywords=request.keywords,
            additional_info=(request.additional_info or "") + "\n" + (request.file_content or "") + _client_materials_ctx,
            own_accounts=request.own_accounts,    # [NEW] 品牌账号排除
            competitors=request.competitors,       # [NEW] 指定竞品
            business_context=request.business_context,  # [P2] 复测时使用相同业务上下文
            session_id=session_id,
            progress_callback=callback,  # We will add this param to the workflow
            diagnosis_scope=diagnosis_scope,
            brand_display_names=brand_display_names,  # [NEW] 品牌别名（可能从DB自动加载）
            client_location=request.client_location or "",  # [NEW] 客户区域
            business_scope=request.business_scope or "",  # [P0-4] 全国 / 区域(默认区域)
            creator_user_id=creator_user_id,  # [FIX] 品牌 owner 关联
            brand_id=request.brand_id,
            custom_questions=request.custom_questions,  # [CTO-15.23 2026-05-21] 自定义诊断问题
            # [#149 · 2026-09-08] 题面来源元数据:转成裸 dict 再进工作流 ——
            #   它要落进 `input_params` 的 JSON,pydantic 对象过不去。
            question_meta=([m.model_dump() for m in request.question_meta]
                           if request.question_meta else None),
            ai_optimize_custom=bool(request.ai_optimize_custom),  # [CTO-15.23 2026-05-21 老板订正] toggle
            run_token=run_token,  # [返工2 P1-4] DB fencing:落库前确认 run 仍 running(lease 丢失即中止落库)
            organization_identity=organization_identity,
            # [P0-2 返修③ 2026-08-23] 客户**付费买下的那个检索面**真的传进管线。
            # 在此之前这个参数从来没人传 ⇒ 管线永远回落到自己的默认清单,
            # 于是"计价集"与"真跑集"是两套互不相干的东西(门四实证:
            # 客户为 kimi 付钱、报告里跑的是 yuanbao)。
            # 🔴 None = 保持既有行为**逐字节不变**(管线走它自己的默认),
            #    所以 legacy 诊断入口一个字都不用改。ai_engines 刻意**不进
            #    DiagnosisRequest**:那是客户可控的入参,放进去等于让客户
            #    自报检索面 —— 引擎数直接决定成本,这是自报价格的另一种写法。
            ai_engines=ai_engines,
        )

        # Notify complete - 确保字段格式与前端匹配
        diagnosis_id = result.get("diagnosis_id")
        logger.info(f"[WS完成] {session_id}: diagnosis_id={diagnosis_id}")

        # 🔧 修复品牌关联：用前端传的 brand_id 精确关联，不靠名字匹配
        if diagnosis_id and request.brand_id:
            try:
                from db.connection import get_db
                with get_db() as _conn:
                    _cur = _conn.cursor()
                    _cur.execute("UPDATE diagnosis_records SET brand_id = %s WHERE id = %s AND (brand_id IS NULL OR brand_id != %s)",
                                (request.brand_id, diagnosis_id, request.brand_id))
                    if _cur.rowcount > 0:
                        logger.info(f"[品牌关联] 诊断 {diagnosis_id} 关联到前端传入的 brand_id={request.brand_id}")
            except Exception as e:
                logger.warning(f"[品牌关联] 修正失败: {e}")

        # 自动分配品牌给创建者
        if creator_user_id and diagnosis_id:
            try:
                from db.diagnosis_db import get_diagnosis_by_id
                from db.auth_db import auto_assign_brand_to_user
                diag = get_diagnosis_by_id(diagnosis_id)
                target_brand_id = diag.get("brand_id") if diag else None
                if not target_brand_id and request.brand_id:
                    target_brand_id = request.brand_id
                if target_brand_id:
                    auto_assign_brand_to_user(creator_user_id, target_brand_id)
            except Exception as e:
                logger.warning(f"[RBAC] 自动分配品牌失败: {e}")

        # 🔧 GEO→社媒数据同步：诊断收集的 business_context 回写到 profile
        _sync_brand_id = request.brand_id or (diag.get("brand_id") if 'diag' in dir() else None)
        if diagnosis_id and _sync_brand_id:
            try:
                from db.diagnosis_db import get_diagnosis_by_id as _get_diag
                from db.profile_db import list_profiles, update_profile
                _diag_data = _get_diag(diagnosis_id)
                if _diag_data:
                    _raw = _diag_data.get("raw_data_json")
                    if _raw:
                        import json as _jj
                        _raw_dict = _jj.loads(_raw) if isinstance(_raw, str) else _raw
                        _biz = _raw_dict.get("data", {}).get("business_context", {})
                        if _biz:
                            # 找该品牌下的 profile
                            _profiles = list_profiles(brand_ids=[_sync_brand_id])
                            if _profiles:
                                _pid = _profiles[0]["id"]
                                _updates = {}
                                # 只填空字段，不覆盖已有数据
                                if _biz.get("core_business") and not _profiles[0].get("company_intro"):
                                    _updates["company_intro"] = _biz["core_business"]
                                if _biz.get("value_proposition") and not _profiles[0].get("core_value"):
                                    _updates["core_value"] = _biz["value_proposition"]
                                if _biz.get("target_customer") and not _profiles[0].get("target_users"):
                                    _updates["target_users"] = _biz["target_customer"]
                                if _biz.get("keywords") and not _profiles[0].get("selling_points"):
                                    kws = _biz["keywords"]
                                    _updates["selling_points"] = ", ".join(kws) if isinstance(kws, list) else str(kws)
                                if _updates:
                                    update_profile(_pid, **_updates)
                                    logger.info(f"[GEO→社媒] 诊断数据回写 profile {_pid}: {list(_updates.keys())}")
            except Exception as e:
                logger.warning(f"[GEO→社媒] 数据同步失败（不影响诊断）: {e}")

        # [CTO-15.23 2026-05-05] P1 中间进度:让用户看到 95% → 96% 在干活
        try:
            await progress_callback_wrapper(session_id, "share_link", 96, "正在生成分享链接...")
        except Exception:
            pass

        # 自动生成分享短链
        _share_token = None
        if diagnosis_id:
            try:
                from api.share_api import _create_short_link
                from services.owned_image_policy import public_base_origin  # [WO_331 · 2026-10-03] 唯一出处
                _share_code = _create_short_link(
                    f"{public_base_origin()}/public/report/{diagnosis_id}",
                    "report", creator_user_id or 0,
                    {"diagnosis_id": diagnosis_id}
                )
                from db.connection import get_connection as _get_share_conn
                _sc = _get_share_conn()
                try:
                    _scur = _sc.cursor()
                    _scur.execute("UPDATE diagnosis_records SET share_token = %s WHERE id = %s", (_share_code, diagnosis_id))
                    _sc.commit()
                    _share_token = _share_code
                    logger.info(f"[分享链接] 诊断 {diagnosis_id} 自动生成短链: {_share_code}")
                finally:
                    _sc.close()
            except Exception as e:
                logger.warning(f"[分享链接] 自动生成失败（不影响诊断）: {e}")

        # [CTO-15.23 2026-05-05] P1 中间进度:HTML 生成是耗时大头(~30s)
        # 让用户看到 98% 知道还在干活 · 不要以为已完成跑去其他地方找
        try:
            await progress_callback_wrapper(session_id, "render_html", 98, "正在渲染可视化报告页面...")
        except Exception:
            pass

        # 自动生成 HTML 版报告（公开分享页用 PDF 同款模板）
        # [并发-1 2026-06-10] subprocess 渲染移入 asyncio.to_thread：原 2 次 subprocess.run(各 timeout=60)
        #   在主事件循环上同步阻塞 → 高并发下任一诊断收尾会把整个进程卡死最多 120s(全场用户一起卡)。
        #   移入线程池后不再阻塞事件循环；逻辑零变化(含失败兜底/临时文件清理)。
        if diagnosis_id:
            def _gen_html_report_sync():
                try:
                    import subprocess, tempfile
                    _md_content, _brand_name, _md_err = _get_diagnosis_md_content(diagnosis_id)
                    if _md_content and not _md_err:
                        base_dir = os.path.dirname(os.path.abspath(__file__))
                        html_output_dir = os.path.join(base_dir, "output", "reports")
                        os.makedirs(html_output_dir, exist_ok=True)
                        html_output_path = os.path.join(html_output_dir, f"{diagnosis_id}_report.html")

                        with tempfile.NamedTemporaryFile(suffix='.md', delete=False, mode='w', encoding='utf-8') as _tf:
                            _tf.write(_md_content)
                            _tmp_md = _tf.name

                        # 尝试先提取结构化数据（用 LLM），失败则 JS 侧用 regex 兜底
                        _json_data_path = _tmp_md.replace('.md', '_data.json')
                        try:
                            _extract_cmd = ['python', os.path.join(base_dir, 'scripts', 'extract_report_data.py'), _tmp_md, _json_data_path]
                            subprocess.run(_extract_cmd, capture_output=True, text=True, timeout=60, cwd=base_dir)
                        except Exception:
                            pass  # regex 兜底

                        _script = os.path.join(base_dir, 'scripts', 'pptx_workspace', 'generate_pdf_themes.js')
                        _html_cmd = ['node', _script, '--html-only', _tmp_md, html_output_path, 'dark_premium']
                        if os.path.exists(_json_data_path):
                            _html_cmd.append(_json_data_path)
                        # WO_329 开源版署名位:只在开关开着时把字与主页传给页脚(关着时 env=None,与改动前同一个调用)
                        from config import oss_attribution as _oss_attr
                        _oss_env = ({**os.environ, "OSS_ATTRIBUTION_TEXT": _oss_attr.REPORT_TEXT, "OSS_ATTRIBUTION_HREF": _oss_attr.HOMEPAGE}
                                    if _oss_attr.ENABLED else None)
                        _html_result = subprocess.run(_html_cmd, capture_output=True, text=True, timeout=60, cwd=base_dir, env=_oss_env)
                        if _html_result.returncode == 0:
                            logger.info(f"[HTML报告] 诊断 {diagnosis_id} HTML 生成成功: {html_output_path}")
                        else:
                            logger.warning(f"[HTML报告] 生成失败: {_html_result.stderr[:200]}")

                        # 清理临时文件
                        for _fp in [_tmp_md, _json_data_path]:
                            try:
                                os.unlink(_fp)
                            except Exception:
                                pass
                except Exception as e:
                    logger.warning(f"[HTML报告] 自动生成失败（不影响诊断）: {e}")
            await asyncio.to_thread(_gen_html_report_sync)

        # [返工 P0-2a] **结算前绝不发成功终态**:impl 不再直接发 done=true 的 complete,而是
        #   构造完成 payload **返回**给 run_diagnosis_task,由后者在 commit_run 结算成功后才发 complete
        #   (paid 未结算前退款窗口内前端不得看到 done+diagnosis_id+share_token → 杜绝"退款仍拿结果")。
        #   此处只发一条 99% "正在完成结算" 让用户知道仍在干活。
        try:
            await progress_callback_wrapper(session_id, "settling", 99, "正在完成结算...")
        except Exception:
            pass
        return {
            "type": "complete", "stage": "done", "progress": 100, "done": True, "terminal": True,
            "diagnosis_id": diagnosis_id,       # 前端用于跳转
            "share_token": _share_token,
            "message": "诊断完成",
            # [P0-3 / P0-3b] 把**结算要用的判定信号**带进快照(delivery_verdict / identity_suspicion)。
            #   两条信号的历史病是同一个:判定算了却没进快照 → 结算侧读不到 → 守卫从未开火。
            #   [R2-② · Review 亲毒] 这里原来是两条内联 dict 字面量,只能被"键在不在"的
            #   结构锁盯着 —— 而**留着键、把值钉成 None** 同样让两道守卫失效,52 条判据全绿存活。
            #   所以抽成 `settlement_signals_from_result`(照 commit_outcome_is_success 的先例):
            #   取值逻辑变成可直接驱动的函数,判据能断言 workflow 结果里的值**真的穿透**到 payload,
            #   而不只是断言键名出现过。
            **_dr.settlement_signals_from_result(result),
            "result": {
                "total_score": result.get("scores", {}).get("total_score"),
                "level": result.get("scores", {}).get("level"),
                "report_file": f"output/{request.brand_name}_{session_id}.md"
            }
        }

    except Exception as e:
        logger.error(f"Diagnosis failed: {e}", exc_info=True)
        # [§13 rollout] 诊断终态告警走机器合同(code+reason+impact+actions),不再裸 str(e)
        # 死胡同(accident #8)。保留 SSE 传输键(type/done/stage/progress/error)向后兼容。
        from services.governance_alerts import diagnosis_failed_alert
        error_status = {
            "type": "error",
            "done": True,
            "stage": "error",
            "progress": 100,
            "error": True,
            **diagnosis_failed_alert(str(e)),
        }
        await manager.send_message(session_id, error_status)
        # 保留 error 状态在 task_status 里，让 HTTP 轮询也能查到失败原因
        # 不立即 clear_task（之前的 bug：清了就查不到了 → 显示"已失效"而非真实错误）
        manager._set_status(session_id, error_status)
        # [audit P1 2026-06-10] 必须 re-raise:旧版吞掉异常 → run_diagnosis_task 永远走 commit_freeze,
        # 失败也把 650-1040+ 冻结结成正式消费(reason 还写"诊断完成"),release_freeze 分支成死代码。
        # re-raise 后外层 except 走既有 release 路径(task_ref/user_id 与 freeze_points 对称·幂等)。
        raise


def _delete_diagnosis_placeholder(session_id: str):
    """[audit #10 2026-06-10] 回删诊断占位行(freeze 失败时防孤儿占位在 30min 窗口内挡重试)·
    只删本 session 的未完成占位(total_score IS NULL),绝不误删已出分的正式诊断行。"""
    try:
        from db.connection import get_connection
        _conn = get_connection()
        try:
            _cur = _conn.cursor()
            _cur.execute(
                "DELETE FROM diagnosis_records WHERE session_id = %s AND total_score IS NULL",
                (session_id,),
            )
            _conn.commit()
        finally:
            _conn.close()
    except Exception as _e:
        logger.warning(f"[Diagnosis] 占位回删失败 session={session_id}: {_e}")


@app.post("/api/diagnosis")
async def start_diagnosis(request: DiagnosisRequest, http_request: Request = None):
    # 🔴 [#84 sec3] 看到的价 == 提交的题集 == 扣的钱 —— legacy 侧的服务端底线。
    #    这道闸必须排在**任何写/冻结之前**:一旦 freeze 了,再拒也收不回来。
    #
    #    🔴 哈希是**两轴**的(题集 + 计价规则输入)。只绑题集会漏掉一整类:
    #    「题集没变、价目表变了」时哈希不动、闸不响,按**旧价**扣钱。
    #
    #    🔴 实现边界:提交这一刻服务端**不知道系统题**(它们要到
    #    analyze_client_business 才生成),所以绑的是**提交的自定义题集**。
    #    custom 为空那一支没有用户特异内容可绑,但计价规则那一轴仍然绑住。
    _preview_id = (request.price_preview_id or "").strip()
    if not _preview_id:
        raise HTTPException(
            status_code=400,
            detail="这次提交少了价格确认标识,刷新页面重新确认一次即可;没有扣除任何算力。",
        )
    # 🔴 [返修] 基价按 scope、开关按 request —— 与实际扣费(:3849 一带)同解。
    #    上一版两处都写死(False / geo_diagnosis),于是切「双轨」或换 scope 时
    #    哈希不动、闸不响,按另一个价扣钱。
    # 🔴 [订正二十六] keywords **一处派生**,在两个消费点之前。
    #    消费点:`_run_diagnosis_impl` 跑 workflow(其中三处进 LLM 输入)与落库。
    #    两者拿的是**同一个 request 对象**(create_task 传本体),所以在这里回写一次,
    #    结构上不可能一处看到档案词、另一处看到品牌名。
    from services.diagnosis_keyword_source import (
        NoKeywordSource as _NoKwSrc, resolve_keywords as _resolve_kw)
    try:
        _kw_conn = get_connection()
        try:
            _kw_cur = _kw_conn.cursor()
            request.keywords = _resolve_kw(
                _kw_cur, given=request.keywords, brand_id=request.brand_id,
                brand_name=request.brand_name, industry=request.industry)
        finally:
            _kw_conn.close()
    except _NoKwSrc as _kw_err:
        # 🔴 每条错误路径都要说清钱 —— 本包的既有锁抓到我这条漏了。
        #    她看到一个拒绝时,第一件想知道的事就是扣没扣钱。
        raise HTTPException(
            status_code=422,
            detail=str(_kw_err) + " 这次没有扣除任何算力。")
    from services.diagnosis_question_pricing import feature_code_for_scope as _fcs
    _feature_guard = _fcs(request.diagnosis_scope)
    _ai_guard = bool(request.ai_optimize_custom)
    try:
        from db.wallet_db import get_feature_pricing as _gfp
        from services.diagnosis_question_pricing import price_preview_matches as _ppm
        _row = _gfp(_feature_guard) or {}
        _base = int(_row.get("cost_points") or 0)
    except Exception:
        _base = 0
    if _base <= 0:
        # 读不到价目就**不放行**:放行等于按一个我们并不知道的价扣钱。
        raise HTTPException(status_code=503, detail="价目暂时读不到,请稍后再试")
    if not _ppm(_preview_id, request.custom_questions or [], base_points=_base,
                ai_optimized=_ai_guard, feature_code=_feature_guard):
        raise HTTPException(
            status_code=409,
            detail="题目或价格在你确认之后又变了。刷新页面会重新算一次价,再确认即可;"
                   "这次没有扣除任何算力。",
        )

    # [GEO-R1-CAN-044 P1] 跨租户防护:有 brand_id 时,校验调用者对该品牌的归属,
    # 防止用他人 brand_id 触发诊断(读他人品牌上下文 + 冻结/耗算力)。
    # allow_null=True 保留无品牌的匿名诊断;http_request=None 仅内部可信调用,放行。
    _organization_identity = (
        getattr(http_request.state, "organization_identity", None)
        if http_request is not None else None
    )
    _organization_member = bool(
        _organization_identity is not None and _organization_identity.is_member
    )
    if http_request is not None:
        from auth.brand_access import require_brand_access
        require_brand_access(http_request, request.brand_id, allow_null=not _organization_member)
    # The diagnosis form is an explicit operator confirmation point. Persist
    # supplied display names before any freeze/provider call so recurring
    # monitoring reads the same brand-scoped identity instead of losing this
    # request-only field. Omitted means preserve; [] means explicitly clear.
    if request.brand_id and request.brand_display_names is not None:
        from services.brand_identity_resolver import persist_confirmed_display_names

        try:
            await asyncio.to_thread(
                persist_confirmed_display_names,
                int(request.brand_id),
                request.brand_display_names,
            )
        except LookupError as exc:
            raise HTTPException(status_code=404, detail="品牌不存在") from exc
        except Exception as exc:
            logger.exception(
                "[Diagnosis] 品牌常用名保存失败 brand_id=%s",
                request.brand_id,
            )
            raise HTTPException(
                status_code=503,
                detail="品牌常用名暂时无法保存，本次诊断未启动，请稍后重试",
            ) from exc
    # 🛡️ 有 brand_id 时强制用品牌表的标准名称，防止名称不一致
    # [Deploy-CTO 2026-05-07] 同步 DB 调用包 asyncio.to_thread · 不阻塞 event loop
    if request.brand_id:
        def _lookup_brand_name(brand_id: int):
            from db.connection import get_connection as _get_conn_bn
            _bn_conn = _get_conn_bn()
            try:
                _bn_cur = _bn_conn.cursor()
                _bn_cur.execute("SELECT name FROM brands WHERE id = %s LIMIT 1", (brand_id,))
                _bn_row = _bn_cur.fetchone()
                _bn_cur.close()
                return _bn_row["name"] if _bn_row and _bn_row.get("name") else None
            finally:
                _bn_conn.close()
        try:
            _bn_name = await asyncio.to_thread(_lookup_brand_name, request.brand_id)
            if _bn_name:
                request.brand_name = _bn_name
        except Exception as e:
            logger.warning(f"[Diagnosis] 品牌名回填失败: {e}")

    # session_id 生成（提前到防重之前 · 原子占位 INSERT 需要它）
    import datetime
    import shortuuid
    timestamp = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    uid = shortuuid.uuid()[:6]
    session_id = f"{request.brand_name}_{timestamp}_{uid}"
    session_id = "".join(c for c in session_id if c.isalnum() or c in ('_', '-'))

    # ============================================================================
    # [WORKERS=4 · SPEC §3.3/§3.3a/§4] 诊断资金状态机 admission(替换旧 advisory-lock 防重)
    #   ① §4 Redis 并发闸抢全局槽(run_token · 跨 worker 一致 · 旧 semaphore 每进程×4 失效)
    #   ② HC1 diagnosis_runs 请求级幂等 INSERT(uq_diag_active_per_brand DB 唯一约束比 advisory-lock 更强·原子)
    #   ③ 占位产物 stamp run_token + result_visibility='pending'
    #   ④ freeze(task_ref='diag_'+run_token · 不再 session_id)→ R0 五分支 → activate
    #   🔴 billing.py 只调不改。
    # ============================================================================
    from services import diagnosis_runs as _dr
    from cache import diagnosis_slots as _slots
    run_token = _dr.mint_run_token()
    _freeze_ref = _dr.freeze_task_ref(run_token)

    # 用户身份 + billing_mode(admin → exempt · 否则 paid;零价 free=True 由 R0 归 exempt)
    creator_user_id = None
    _is_admin = False
    if http_request:
        _u = getattr(http_request.state, "user", None)
        if _u:
            creator_user_id = _u.get("user_id")
            _is_admin = bool(_u.get("is_admin"))
    # Organization members use the owner-wallet + member-limit reservation.
    # diagnosis_runs stays exempt from the legacy wallet state machine; its
    # terminal transition is closed atomically by organization_billing.
    billing_mode = "exempt" if (_is_admin or _organization_member) else "paid"

    # HC1 client_request_id(缺省服务端代生成 + WARN · WORKERS=1 兼容窗口 · 翻 4 前 Deploy 核 dist 前端已带真值)
    client_request_id = (request.client_request_id or "").strip()
    _client_req_missing = not client_request_id
    if _organization_member and _client_req_missing:
        raise HTTPException(
            status_code=422,
            detail={"code": "ORG_IDEMPOTENCY_KEY_REQUIRED", "message": "员工诊断必须携带请求标识"},
        )
    if _client_req_missing:
        client_request_id = "srvgen:" + run_token
        logger.warning(f"[Diagnosis] 缺 client_request_id · 服务端代生成 {client_request_id}"
                       f"(WORKERS=1 兼容窗口 · 翻 4 前须前端传真值)")

    slot_mode = "none"   # 'redis' | 'semaphore' | 'none'(无身份不走状态机)
    if creator_user_id:
        try:
            _workers_multi = int(os.getenv("WORKERS", "1")) > 1
        except (TypeError, ValueError):
            _workers_multi = False
        # [对抗审核 P1 #3 HC2 硬校验] WORKERS>1 下付费请求**必须**带前端 client_request_id:
        #   srvgen 每请求唯一(run_token 全新)→ uq_diag_request_idem 永不命中 → brandless(brand_id=None ·
        #   uq_diag_active_per_brand 因 PG NULL-distinct 不去重)超时重试/并发双 freeze 双扣。WORKERS=1 保
        #   srvgen 兼容(brandless 无请求级去重 = 同旧 advisory-lock brand-gated 口径 · pre-existing);翻 4 =
        #   Deploy 已核 dist 前端带真值 → 此时缺失即前端契约违反,fail-fast 400(在抢槽前 · 无泄漏)。
        if _workers_multi and billing_mode == "paid" and _client_req_missing:
            raise HTTPException(status_code=400,
                                detail="请刷新页面后重试(系统升级中 · 缺少请求标识)")
        # §4 抢并发槽 · §6.6:WORKERS>1 抢槽/freeze 前 Redis 必达;WORKERS=1 回退进程内 semaphore(I4 兼容)
        _slot = await asyncio.to_thread(_slots.acquire_slot, run_token)
        if _slot.redis_down:
            if _workers_multi:
                raise HTTPException(status_code=503, detail="系统繁忙,请稍后重试(进度服务暂不可用)")
            slot_mode = "semaphore"   # WORKERS=1 · Redis 抖动 → 进程内 semaphore 兜底
        elif not _slot.acquired:
            _n = _slot.current if _slot.current >= 0 else _slots.cap()
            raise HTTPException(status_code=429, detail=f"当前已有 {_n} 个诊断在跑,系统繁忙,请稍后重试")
        else:
            slot_mode = "redis"

        async def _release_slot_if_held():
            if slot_mode == "redis":
                await asyncio.to_thread(_slots.release_slot, run_token)

        # HC1 admission —— 无目标 INSERT ON CONFLICT DO NOTHING + 0 行三路定性(冲突路径精确释槽 · 绝不冻结)
        try:
            admit = await asyncio.to_thread(
                _dr.admit_run, creator_user_id, client_request_id, request.brand_id,
                session_id, run_token, billing_mode)
        except Exception as e:
            await _release_slot_if_held()
            logger.error(f"[Diagnosis] admission 异常: {e}", exc_info=True)
            raise HTTPException(status_code=503, detail="诊断服务暂时不可用,请稍后再试")
        if not admit.admitted:
            await _release_slot_if_held()   # 冲突路径精确释放本次抢的槽
            if admit.run:
                # [返工2 P1-1] 幂等命中的旧 run 若已**终态**(cancelled/released/committed/... 非活跃)→ 绝不返回
                #   status='started'(前端会跳进"进行中"轮询一个永不运行的死任务)。返回 status='resolved' + 真实
                #   终态,前端据此不进轮询(提示"该请求此前已结束,请重新发起";确定性失败前端已清 client_request_id)。
                _old_status = admit.run.get("run_status")
                _is_active = _old_status in _dr.ACTIVE_STATUSES
                return {
                    "session_id": admit.run.get("session_id"),
                    "run_token": admit.run.get("run_token"),
                    "status": "started" if _is_active else "resolved",
                    "run_status": _old_status,
                    "idempotent": admit.reason == "idempotent_retry",
                    "resolved": not _is_active,
                    "message": ("已有进行中的诊断,已为你定位" if admit.reason == "brand_active"
                                else ("该请求此前已结束,请重新发起" if not _is_active else "重复请求已合并")),
                }
            logger.error(f"[Diagnosis] admission 内部一致性错误 owner={creator_user_id} req={client_request_id}")
            raise HTTPException(status_code=409, detail="诊断创建冲突,请重试")

    # 占位产物行 INSERT(A0 · stamp run_token + result_visibility='pending')
    #   [对抗审核 P1 #4] 改为 **creator_user_id 有(有 run)即占位**(不再 brand_id 有才占位):
    #   brand_id=None(C 端/未选品牌)时旧口径不占位 → save_diagnosis 直建行 result_visibility=NULL(=published)
    #   → 3 公开端点可见退款结果泄露窗口。现无条件占位置 'pending' → 从产物诞生即 pending,终态才 published/withheld。
    if creator_user_id:
        def _insert_placeholder():
            from db.connection import get_connection
            _conn = get_connection()
            try:
                _cur = _conn.cursor()
                _cur.execute("""
                    INSERT INTO diagnosis_records
                        (session_id, brand_name, industry, brand_id, diagnosis_type, keywords,
                         run_token, result_visibility, organization_id,created_by_user_id,
                         created_by_membership_id,created_by_actor_kind,responsible_user_id,
                         artifact_visibility,created_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, 'pending',%s,%s,%s,%s,%s,%s,NOW())
                    ON CONFLICT (session_id) DO NOTHING
                """, (session_id, request.brand_name, request.industry, request.brand_id,
                      request.diagnosis_scope or "geo", json.dumps(request.keywords, ensure_ascii=False),
                      run_token,
                      _organization_identity.organization_id if _organization_member else None,
                      # 🔴 [#130] 这两行的 else 分支原来是 None ⇒ **非组织用户两列全空**。
                      #    不是「忘了写」—— 是写了,但只在组织成员那一支给真值,
                      #    而绝大多数代理不是组织成员。后果三个月后才显形:
                      #    `snapshot_store.persist_report_snapshot` 的守卫
                      #    `COALESCE(responsible_user_id, created_by_user_id)` 恒 NULL
                      #    ⇒ 每份报告都 return None,`defgeo_report_snapshots` 全仓 0 行。
                      #    `creator_user_id` 在此必非空(外层 `if creator_user_id:` 守着)。
                      #    organization_id / membership_id / actor_kind / artifact_visibility
                      #    **保持 None**:非组织用户确实没有组织,给它们编值才是错的。
                      _organization_identity.actor_user_id if _organization_member else creator_user_id,
                      _organization_identity.membership_id if _organization_member else None,
                      _organization_identity.actor_kind if _organization_member else None,
                      _organization_identity.actor_user_id if _organization_member else creator_user_id,
                      "private" if _organization_member else None))
                _conn.commit()
            finally:
                _conn.close()
        try:
            await asyncio.to_thread(_insert_placeholder)
        except Exception as e:
            # [返工5 P0] 占位失败必须 **fail-closed**:占位行(result_visibility='pending')是"结算前防泄露"的唯一屏障。
            #   若吞异常继续冻结/外呼,save_diagnosis 会**直建 result_visibility=NULL 的行**(读取链把 NULL 当已发布)→
            #   诊断结果在扣费结算前对 3 公开端点泄露。故占位失败 → 不冻结/不外呼:释放槽 + 把未冻结 run CAS 到终态
            #   cancelled(withheld · 此时尚未 freeze · 无资金风险)+ 503(前端可重试)。禁"靠任务完成后补标"。
            logger.error(f"[Diagnosis] 占位 INSERT 失败 · fail-closed 中止(不冻结/不外呼防结算前泄露): {e}")
            if slot_mode == "redis":
                try:
                    await asyncio.to_thread(_slots.release_slot, run_token)
                except Exception:
                    pass
            try:
                await asyncio.to_thread(
                    _dr.activate_after_freeze, run_token, creator_user_id,
                    _dr.FreezeClassification("cancelled", None, None,
                                             "paid" if billing_mode == "paid" else "exempt"))
            except Exception:
                pass
            raise HTTPException(status_code=503, detail="诊断初始化失败,请稍后再试")

    # Shared pricing inputs for legacy and organization reservation paths.
    scope = request.diagnosis_scope or "geo"
    # 🔴 [订正二十二] 与守卫/预览共用**同一份**映射(原先三处各写一份)。
    _feature_charge = _fcs(scope)
    custom_q_count = len(request.custom_questions) if request.custom_questions else 0
    ai_optimize_flag = bool(request.ai_optimize_custom)
    # 🔴 [P0 2026-09-02] 规则本体搬到 services/diagnosis_question_pricing ——
    #    防御/混合线要用**同一条**规则(Owner 拍板),两处各写一份必有一处没人验,
    #    而这一处漂了就是钱漂了(方向还不定:多收要退款,少收是收入漏)。
    #    行为逐值不变:这里原来就是 0 / n*100 / max(0,n-8)*100 三支。
    from services.diagnosis_question_pricing import extra_points_for_questions

    extra_cost = extra_points_for_questions(
        custom_q_count, ai_optimized=ai_optimize_flag)

    _organization_charge_id = None
    _organization_charge_points = None
    _organization_claim_token = None
    if creator_user_id and _organization_member:
        from services.organization_billing import claim_live_charge, release_charge, reserve_charge
        _organization_execution_id = (
            f"diagnosis:{_organization_identity.organization_id}:"
            f"{_organization_identity.membership_id}:{client_request_id}"
        )
        try:
            _organization_charge = await reserve_charge(
                _organization_identity,
                execution_id=_organization_execution_id,
                feature_code=_feature_charge,
                work_kind="diagnosis.run",
                payload={
                    "brand_id": request.brand_id,
                    "scope": scope,
                    "custom_question_count": custom_q_count,
                    "ai_optimize_custom": ai_optimize_flag,
                    "run_token": run_token,
                },
                brand_id=request.brand_id,
                task_ref=run_token,
                dynamic_ceiling_extra_points=extra_cost,
                dispatch_ttl_seconds=_DIAGNOSIS_TOTAL_TIMEOUT_SECONDS + 300,
            )
            if _organization_charge.get("status") != "reserved":
                raise HTTPException(
                    status_code=409,
                    detail={"code": "ORG_DIAGNOSIS_REPLAY_TERMINAL", "message": "该员工诊断请求已结算"},
                )
            _organization_charge_id = int(_organization_charge["id"])
            _organization_charge_points = int(_organization_charge["reserved_ceiling_points"])
            _organization_claim = claim_live_charge(
                _organization_identity,
                charge_link_id=_organization_charge_id,
                lease_seconds=_DIAGNOSIS_TOTAL_TIMEOUT_SECONDS + 300,
            )
            if _organization_claim.get("in_progress"):
                _organization_charge_id = None
                raise HTTPException(
                    status_code=409,
                    detail={"code": "ORG_WORK_ALREADY_RUNNING", "message": "同一诊断请求正在执行"},
                )
            _organization_claim_token = str(_organization_claim["claim_token"])
            await asyncio.to_thread(
                _dr.activate_after_freeze,
                run_token,
                creator_user_id,
                _dr.FreezeClassification("exempt", None, None, "exempt"),
            )
        except Exception:
            if _organization_charge_id is not None:
                try:
                    await release_charge(
                        charge_link_id=_organization_charge_id,
                        reason="diagnosis admission failed before provider call",
                        diagnosis_run_token=run_token,
                        diagnosis_session_id=session_id,
                    )
                except Exception:
                    logger.exception("[Diagnosis] organization reservation recovery failed")
            else:
                try:
                    await asyncio.to_thread(
                        _dr.activate_after_freeze,
                        run_token,
                        creator_user_id,
                        _dr.FreezeClassification("cancelled", None, None, "exempt"),
                    )
                except Exception:
                    pass
            if slot_mode == "redis":
                await asyncio.to_thread(_slots.release_slot, run_token)
            raise
    # freeze + R0(仅 paid · 有身份)· exempt/admin 无 freeze
    elif creator_user_id and billing_mode == "paid":
        _freeze_result = None
        _freeze_exc = None
        try:
            from middleware.billing import freeze_points
            _freeze_result = await freeze_points(
                creator_user_id,
                _feature_charge,
                task_ref=_freeze_ref,   # ★ 'diag_'+run_token(不再 session_id · 结算凭 freeze_id 直达)
                brand_id=request.brand_id,
                extra_cost=extra_cost,
                reason=f"启动{scope}诊断" + (
                    f" + {custom_q_count} 自定义题({'优化' if ai_optimize_flag else 'verbatim'} · +{extra_cost} 积分)"
                    if custom_q_count else ""
                ),
            )
            # 🔴 [#79] 记下这次到底扣没扣 —— 错误响应的信封从这里取。
            #    没写过 ⇒ 处理器兜底 `no`(还没走到扣费那步),那是安全的默认。
            try:
                from middleware.billing import charged_envelope as _chg_env
                http_request.state.charged_envelope = _chg_env(_freeze_result)
            except Exception:
                pass        # 信封是附加信息,绝不因它影响主流程
        except HTTPException as he:
            _freeze_exc = he
        except Exception as e:
            _freeze_exc = e
        # R0 五分支判定 → activate_after_freeze 落地状态(DB 操作 to_thread)
        cls = _dr.classify_freeze_result(_freeze_result, _freeze_exc)
        final_status = await asyncio.to_thread(_dr.activate_after_freeze, run_token, creator_user_id, cls)
        if final_status != "running":
            # 非 running(cancelled/unknown/anomaly/release_pending/settlement_manual)→ 不启动任务
            if slot_mode == "redis":
                await asyncio.to_thread(_slots.release_slot, run_token)
            await asyncio.to_thread(_delete_diagnosis_placeholder, session_id)
            if final_status == "cancelled":
                # 确定性失败(余额不足 402 / 参数非法 400)→ 抛原错
                if isinstance(_freeze_exc, HTTPException):
                    raise _freeze_exc
                raise HTTPException(status_code=402, detail="余额不足或参数非法,诊断未启动")
            # unknown/anomaly/release_pending/settlement_manual → 钱可能已冻,交 sweeper 兜底处置 · 用户侧繁忙
            raise HTTPException(status_code=503, detail="积分系统繁忙,诊断未启动,请稍后再试")
    elif creator_user_id and billing_mode == "exempt":
        # 免单/admin:无 freeze · 直接 activate exempt → running
        await asyncio.to_thread(
            _dr.activate_after_freeze, run_token, creator_user_id,
            _dr.FreezeClassification("exempt", None, None, "exempt"))

    # 🔧 create_task 前先把 session 注册到 task_status(防前端 /status 拿到 found:False)
    # [门八第三发现] payload 搬进 `mark_session_queued` 单点 —— 防御体检 confirm
    # 那一侧要写**同一格**,两边各拼一份迟早漂。行为逐字不变。
    mark_session_queued(session_id, driven_in_process=True)   # legacy 由本进程 create_task 推进
    asyncio.create_task(run_diagnosis_task(
        request, session_id, creator_user_id,
        run_token=(run_token if creator_user_id else None), slot_mode=slot_mode,
        organization_identity=(_organization_identity if _organization_member else None),
        organization_charge_id=_organization_charge_id,
        organization_charge_points=_organization_charge_points,
        organization_claim_token=_organization_claim_token))

    return {"session_id": session_id, "run_token": run_token, "status": "started"}

# 兼容前端调用 /api/diagnosis/start
@app.post("/api/diagnosis/start")
async def start_diagnosis_alias(request: DiagnosisRequest, http_request: Request = None):
    return await start_diagnosis(request, http_request)


# ==========================================
# LLM 自动填写表单（联网搜索 Fallback 链）
# ==========================================
class AutofillRequest(BaseModel):
    brand_name: str
    provider: str = ""  # 可选：doubao / dashscope / kimi，空=自动 fallback
    # 用户在表单里已经填过的字段，作为强约束传给 LLM，避免幻觉（见 sprint0_findings.md 诊断 4）
    user_city: str = ""       # 用户已填的 clientLocation
    user_industry: str = ""   # 用户已填的 industry

class SuggestedQuestion(BaseModel):
    """一条出题提议。**side 与 mode 语义同源**,不靠下游按顺序猜。"""
    question: str
    side: Literal["growth", "defensive"]
    # 🔴 [#149 · 2026-09-08] 漏斗层由**生成器**给(`question_types`),端点今天把它扔了。
    #    候选要直接进题单,层就必须一路带到后端 —— 否则 verbatim 分支会对
    #    每一道 AI 出的题重新跑一次 LLM 归层,既费钱又可能把已知的层猜错。
    #    不受限取值:层的取值域归生成器所有(`super_tier1` / `brand_awareness` /
    #    …),在这里写死 Literal 会让生成器新增一层时整页 500(#139 那种炸法)。
    layer: Optional[str] = None


class SuggestQuestionsResponse(BaseModel):
    """🔴 [#145 · 2026-09-07] 显式声明响应形状。

    必须覆盖端点返回的**每一个**键 —— 漏一个,`response_model` 会把它丢掉或直接 500。
    (#139 就是这么炸的:返回值里多了个 Literal 不认的值 ⇒ 整页 500,
     而判据在响应层之下,完全看不见。所以本单配了走真出口的 HTTP 臂。)
    """
    questions: List[str]
    candidates: List[SuggestedQuestion]
    source: str
    fallbackReason: Optional[str] = None
    # 🔴 [#147-B] 关键词来自阶梯的**哪一级**(given/last_diagnosis/brand_name/
    #    industry/none)。**不复用 `fallbackReason`**:那个键的含义是「为什么没拿到题」,
    #    而取词失败时题仍然出得来 —— 把两件事压进一个键,运维就分不出该查哪一头。
    keywordSource: Optional[str] = None
    mode: str
    cacheKey: str
    cachedAt: Optional[str] = None

class SuggestQuestionsRequest(BaseModel):
    brand_id: int
    mode: str = "growth"          # growth | defensive | full
    business_scope: str = ""      # 表单值 —— 它**不是**品牌属性(brands 上没有这一列)


#: [#84 §2 · 2026-09-05] 出题提议的进程内缓存。
#: 🔴 刻意不落库、不加迁移:缓存的语义只是「省一次 LLM 调用」,丢了只多算一次、
#:    不影响正确性。生产 WORKERS=1(CLAUDE.md 真相表第 1 条)⇒ 进程内即全局。
#:    **代价:重启即失效。** 这是明知的取舍,不是遗漏。
#: 🔴 也刻意不复用 `ai_suggestions` 表 —— 那是(E3 已删的)社媒智能建议模块的**用户可见建议**表,表仍在库里
#:    (带 is_read / action_taken,且有 `SELECT * FROM ai_suggestions`),
#:    把缓存行塞进去,它们会混进用户看到的建议列表。
_SUGGEST_CACHE: dict = {}
_SUGGEST_CACHE_TTL_SECONDS = 30 * 60

from services.diagnosis_generator_inputs import (          # noqa: E402
    BRAND_SIDE_KEYS, brand_side_generator_inputs)


def _suggest_cache_key(brand_row: dict, mode: str, business_scope: str,
                       brand_side: dict = None) -> str:
    """缓存键 = 品牌三项 + mode + **表单 scope** + **品牌侧输入**(订正十五① · #147-B)。

    🔴 [#147-B] `brand_side` 进键是**必须**的,不是锦上添花:关键词现在可能来自
       「上次已发布的诊断」—— 用户又跑了一次诊断,喂给出题器的词变了,
       而键里没有它 ⇒ 30 分钟内继续返**旧题**,且屏幕上一切正常。
       键必须覆盖**每一个会改变输出的输入**,少一个就是一格静默失效的闸。

    🔴 scope 进键是刻意的:用户把区域切成全国,题就该重出 ——
    「区域→全国换题」正是原型要的;把它排除在外会让她拿到上一档区域的题。
    🔴 `brands` 上**没有** business_scope 列(实测 information_schema:
    只有 name / company_name / industry / cities),所以它只能从表单来。
    """
    import hashlib
    raw = chr(10).join([
        str(brand_row.get("name") or ""),
        str(brand_row.get("industry") or ""),
        str(brand_row.get("cities") or ""),
        str(mode or ""),
        str(business_scope or ""),
        # 品牌侧四项按**固定键序**摊平 —— dict 序不进键,免得同样的输入算出两个键。
        repr([(k, (brand_side or {}).get(k)) for k in BRAND_SIDE_KEYS]),
    ])
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


_KWSUG_CACHE: dict = {}
_KWSUG_CACHE_TTL_SECONDS = 30 * 60


@app.get("/api/diagnosis/keyword-suggestion")
async def diagnosis_keyword_suggestion(brand_id: int, http_request: Request = None):
    """启动页的**关键词预填**(订正三十① · 契约见 WO_KEYWORD_SUGGESTION_CONTRACT_C)。

    🔴 只读:零 DB 写、零扣费。她换品牌会反复触发,所以走进程内 TTL 缓存。

    🔴 词从**提交路径同一个阶梯**出(`resolve_keywords_with_source`)。
       两份「应该等价」的实现漂开那天不会有任何东西变红,而表现是
       **她看到 A、系统跑 B** —— 与 #62 同形。
    """
    import time as _time

    user = getattr(http_request.state, "user", None) if http_request else None
    if not user:
        raise HTTPException(status_code=401, detail="未登录")
    _uid = user.get("user_id") or user.get("id")

    from db.diagnosis_db import get_brand_by_id
    brand = get_brand_by_id(int(brand_id))
    # 🔴 越权用 **404 而不是 403**:403 等于告诉探测者
    #    「这个 brand_id 存在,只是不是你的」。
    if not brand or (not user.get("is_admin")
                     and int(brand.get("owner_user_id") or 0) != int(_uid or 0)):
        raise HTTPException(status_code=404, detail="品牌不存在")

    _ck = ("kwsug", int(brand_id))
    _hit = _KWSUG_CACHE.get(_ck)
    if _hit and (_time.time() - _hit["at"]) < _KWSUG_CACHE_TTL_SECONDS:
        return _hit["payload"]

    from services.diagnosis_keyword_source import (
        NoKeywordSource, clamp_keywords, resolve_keywords_with_source)

    conn = get_connection()
    try:
        cur = conn.cursor()
        try:
            _kw, _src = resolve_keywords_with_source(
                cur, given=None, brand_id=int(brand_id),
                brand_name=brand.get("name"), industry=brand.get("industry"))
        except NoKeywordSource:
            # 🔴 与提交路径**故意不同**的一格:提交时三源皆空要 422
            #    (不许零搜索词的诊断跑起来),预填只是建议、没有「提交」可拒。
            #    派生是同一份,只有空态的呈现不同。
            _kw, _src = [], "none"
    except Exception as _err:
        logger.warning("[keyword-suggestion] 取词失败 brand=%s: %s", brand_id, _err)
        raise HTTPException(status_code=503, detail="这次没能取到建议词,不填也可以继续")
    finally:
        try:
            conn.close()
        except Exception:
            pass

    # 阶梯只到品牌名/行业 ⇒ 追加一次 AI 规划词(Owner 订正三十①)。**不扣算力**:
    # 她此刻还没提交、还没看到价,这时扣一笔她没主动要的钱会撞「按钮级确认扣费」。
    _ai = False
    if _src in ("brand_name", "industry"):
        try:
            from tools.keyword_generator import analyze_client_business
            _biz = await analyze_client_business(
                brand_name=brand.get("name") or "", industry=brand.get("industry") or "",
                keywords=list(_kw))
            _groups = _biz.get("search_keyword_groups") or []
            _extra = [" ".join(g) if isinstance(g, (list, tuple)) else str(g) for g in _groups]
            if _extra:
                _kw = clamp_keywords(list(_kw) + _extra, source="AI 规划词")
                _ai = True
        except Exception as _aerr:
            # AI 拿不到不阻断:她仍拿到阶梯那一档,只是没被增强。
            logger.warning("[keyword-suggestion] AI 规划词失败 brand=%s: %s", brand_id, _aerr)

    payload = {"keywords": list(_kw), "source": _src, "aiAugmented": bool(_ai)}
    _KWSUG_CACHE[_ck] = {"at": _time.time(), "payload": payload}
    return payload


@app.post("/api/diagnosis/suggest-questions",
          response_model=SuggestQuestionsResponse)
async def suggest_diagnosis_questions(request: SuggestQuestionsRequest,
                                      http_request: Request = None):
    """页面加载时的**出题提议**。只读、**不向用户扣费**(今天 legacy 在 650 内做同一件事)。

    生产者 = `tools.keyword_generator.analyze_client_business` 的 `real_user_questions`
    (`workflows/diagnosis_workflow.py:727` 用的就是它)。
    🔴 **不是** `keyword_expander` —— 那个扩的是**关键词**,是另一种产物;
       接错了返回的还是 8 条字符串,两种情况读数完全一样,直到有人去读内容才发现。
    """
    import time as _time

    user = getattr(http_request.state, "user", None) if http_request else None
    if not user:
        raise HTTPException(status_code=401, detail="未登录")

    mode = (request.mode or "growth").strip().lower()
    if mode not in ("growth", "defensive", "full"):
        raise HTTPException(status_code=400, detail="mode 只能是 growth / defensive / full")

    from db.diagnosis_db import get_brand_by_id
    brand = get_brand_by_id(int(request.brand_id))
    if not brand:
        raise HTTPException(status_code=404, detail="没找到这个品牌")

    # 🔴 [#147-B] 品牌侧输入必须在**算键之前**解析 —— 键要覆盖它们。
    #    这比缓存命中省下的那点开销值:贵的是下面两次 LLM 调用,不是这一次库读。
    #    `resolve_missing_keywords=True`:预览端上游**没有任何人**跑过阶梯
    #    (工作流那侧是调用方跑的,所以那边是 False)。
    #    阶梯三源皆空时 helper 自己回落 `([], "none")` —— 页面加载路径**绝不 500**。
    brand_side, brand_side_meta = await brand_side_generator_inputs(
        brand_id=int(request.brand_id),
        brand_name=str(brand.get("name") or ""),
        industry=str(brand.get("industry") or ""),
        client_location=str(brand.get("cities") or ""),
        keywords=None,
        resolve_missing_keywords=True,
    )

    key = _suggest_cache_key(brand, mode, request.business_scope, brand_side)
    hit = _SUGGEST_CACHE.get(key)
    if hit and (_time.time() - hit["at"]) < _SUGGEST_CACHE_TTL_SECONDS:
        return {**hit["payload"], "cacheKey": key,
                "cachedAt": hit["iso"]}

    from tools.keyword_generator import analyze_client_business

    async def _ask(framing):
        """跑一次生产者。**异常与空列表都算整批不可用**(订正十五③)——
        对她而言两者一样:没拿到题。但 reason 分开记,可观测出口按 reason 分列。"""
        try:
            out = await analyze_client_business(
                brand_name=str(brand.get("name") or ""),
                industry=str(brand.get("industry") or ""),
                business_scope=request.business_scope or "",
                # 🔴 `question_framing` 是**两侧刻意不同**的那一项:工作流不传取默认,
                #    预览按 mode 传 None/"brand_directed" 才产得出增长/防守两侧。
                #    它是两侧的**来源**,不是「没对齐」—— 谁统一它,两侧就没了。
                question_framing=framing,
                # 品牌侧四项与实跑同源(见 services/diagnosis_generator_inputs)。
                **brand_side,
            )
        except Exception as exc:
            logger.warning("[suggest-questions] 生成器抛异常 brand=%s: %s",
                           request.brand_id, exc)
            return [], {}, "exception"
        qs = [str(q).strip() for q in (out or {}).get("real_user_questions") or []
              if str(q or "").strip()]
        # 🔴 [#149] `question_types` 一并带出来 —— 生成器**已经**算好了每题的层,
        #    端点今天把它丢掉,下游只能再花一次 LLM 重新猜。
        types = (out or {}).get("question_types")
        types = types if isinstance(types, dict) else {}
        return (qs, types, None) if qs else ([], {}, "empty")

    # 🔴 [#145 · 2026-09-07] 每条候选**自带 side**,不让下游按顺序猜。
    #
    #    改之前 full 模式返的是 `g_qs[:4] + d_qs[:4]` 一个扁平字符串列表。
    #    下游只能按位置推侧别,而那依赖一个**没人声明、也没人锁**的不变量:
    #    「总数是 8 ⟺ 两侧各取满 4」。
    #    今天它碰巧成立(取不满就凑不够 8),但哪天有人加去重、换拼接顺序,
    #    或缓存里躺着旧形状 —— 增长题会被标成防守题,**而屏幕上一切正常**。
    #    ⇒ 能消灭的轴就别去诊断它:让 side 从**产出的那一刻**就带上。
    #    `questions` 从 `candidates` **一处派生**,两者不可能不一致。
    #
    # 🔴 [#149 · 2026-09-08] `layer` 与 `side` **同源同处**产出:两者都来自
    #    「产出这条题的那一次调用」,不是事后按位置或按题面回推。
    def _cand(q, side, types):
        # 层缺省跟生成器的默认口径一致(`super_tier1`),不是 None ——
        # 下游据此判断「这题带层」,给 None 会让它退回 LLM 重新归层。
        return {"question": q, "side": side,
                "layer": str(types.get(q) or "super_tier1")}

    candidates: List[dict] = []
    if mode == "full":
        # 各取 4(订正十一)。两次调用,成本归平台。
        g_qs, g_types, g_reason = await _ask(None)
        d_qs, d_types, d_reason = await _ask("brand_directed")
        candidates = ([_cand(q, "growth", g_types) for q in g_qs[:4]]
                      + [_cand(q, "defensive", d_types) for q in d_qs[:4]])
        fallback_reason = g_reason or d_reason
    else:
        raw, raw_types, fallback_reason = await _ask(
            "brand_directed" if mode == "defensive" else None)
        side = "defensive" if mode == "defensive" else "growth"
        candidates = [_cand(q, side, raw_types) for q in raw[:8]]
    questions = [c["question"] for c in candidates]

    source = "ai" if questions else "fallback"
    payload = {
        "questions": questions,
        "candidates": candidates,
        "source": source,
        # 🔴 `exception` 与 `empty` 分开:AI 挂了和 AI 返空是两种运维处置,
        #    压成一个 "fallback" 就看不出该去查网络还是查 prompt。
        "fallbackReason": None if source == "ai" else (fallback_reason or "empty"),
        "keywordSource": brand_side_meta.get("keyword_source"),
        "mode": mode,
    }
    if source == "ai":
        _SUGGEST_CACHE[key] = {"at": _time.time(), "payload": payload,
                               "iso": datetime.now().isoformat()}
    # 🔴 fallback **不进缓存**:AI 挂了要让下一次重试,不是把失败缓存 30 分钟。
    return {**payload, "cacheKey": key, "cachedAt": None}


@app.post("/api/diagnosis/autofill")
async def autofill_diagnosis_form(request: AutofillRequest, http_request: Request = None):
    """
    根据品牌名称，联网搜索企业信息，自动填写诊断表单。
    使用手动扣费 + 末尾 try/except 退费（函数体过长不便用 ctx 包裹）
    """
    import httpx
    import re

    brand_name = request.brand_name.strip()
    if not brand_name:
        raise HTTPException(status_code=400, detail="品牌名称不能为空")

    # 2026-04-18 L2 改造：预检不扣 → LLM 成功 → 再真扣（"工具真实成功才收费"）
    # 老行为是入口直接扣，中途挂了靠 _refund_on_fail 退。新行为：根本不扣就不需要退。
    _user = getattr(http_request.state, "user", None) if http_request else None
    _bill_user_id = None
    if _user and not _user.get("is_admin"):
        _bill_user_id = _user.get("user_id")
    if _bill_user_id:
        from middleware.billing import check_balance_only as _check_bf
        await _check_bf(_bill_user_id, "brand_fill")   # 余额不足 → 402 直接抛

    # 真实扣费（LLM 成功返回且校验通过后调用）
    async def _commit_charge():
        if _bill_user_id:
            try:
                from middleware.billing import deduct_points as _dp_bf
                await _dp_bf(_bill_user_id, "brand_fill")
            except Exception as _e:
                # 理论上余额预检已经过，这里失败只记 log 不挂用户（让用户先拿到数据）
                logger.error(f"[autofill] commit 扣费失败（已发放数据）: {_e}")

    # 老接口保留但 no-op：新流程根本没扣过就不需要退
    async def _refund_on_fail(reason: str):
        logger.info(f"[autofill] 跳过退费（后扣费模式，本次根本没扣）: {reason}")

    # ---- JSON 提取 prompt（供结构化输出的模型使用）----
    # 用户已填信息强约束（防止 LLM 幻觉把北京填成丽江这类问题）
    _user_context_parts = []
    if request.user_city.strip():
        _user_context_parts.append(f"- 城市：**{request.user_city.strip()}**（用户明确说的，clientLocation 必须返回这个值，不要因为搜索结果改成其他城市）")
    if request.user_industry.strip():
        _user_context_parts.append(f"- 行业：**{request.user_industry.strip()}**（用户明确说的，如搜索结果冲突以用户填写为准）")
    _user_context = ("\n".join(_user_context_parts) + "\n\n") if _user_context_parts else ""

    # [CTO-15.5 Q3 2026-04-20] autofill prompt 升级 · 加场景说明 + 品牌名真实性验证 + 业务/案例分字段 + service_scope
    # 老板反馈: 搜"上海骁马豪车租赁"连续两次返回另一家公司简介,LLM 不验证品牌名真实性
    # Root cause 1: 原 prompt 没说明下游用途,LLM 不警觉"张冠李戴"的代价
    # Root cause 2: 原 prompt 无"如果搜到的是别家公司怎么办"的 fallback 分支
    # Root cause 3: 原 prompt 没 service_scope 字段,additionalInfo 会混入案例地点导致后续扩词围绕案例扩
    json_prompt = f"""【任务场景】
你正在为 OmniRank GEO(AI 搜索优化)系统提取品牌资料。这份资料将用于:
1. 生成"潜在客户 AI 搜索关键词"(扩词引擎)
2. 诊断品牌在 AI 搜索引擎(DeepSeek/Kimi/豆包)的被推荐度
3. 生成 GEO 优化文章并发布到百家号/知乎等平台

因此资料必须**真实准确**,不能张冠李戴。如果错把"A 公司"的资料填给"B 公司",整条 GEO 链路(扩词/诊断/写文章)全都围绕错的公司跑,客户看到产出立刻知道被骗,直接退款。

【要搜索的品牌】「{brand_name}」

请联网搜索「{brand_name}」的企业信息,交叉验证多个来源(官网、天眼查、企查查、行业网站)。

{_user_context}【严格约束】用户已经告诉你的信息(上方列出的)必须原样返回,不允许 LLM 推测覆盖。只对用户没说的字段才做推断。

【第一步 · 品牌名真实性验证(最重要)】
判断搜索到的主体公司,和「{brand_name}」是否匹配:
- 资料里多次出现的公司名是否包含「{brand_name}」的关键词?
- 资料里的业务方向是否和「{brand_name}」暗示的业务一致?
  (如搜"上海骁马豪车租赁",资料应有"豪车"/"租赁"/"专车"等关键词)
- 若搜索资料讲的是**另一家公司**(名字完全不同 or 业务不匹配):
  **必须返回 `{{"name_matched": false, "matched_name": "资料里实际的公司名", "reason": "为什么不匹配",
               "suggestion": "请用户核实品牌全名或提供更多关键词(地域/行业)", ...(其他字段留空或null)}}`**
- 若搜不到任何相关信息,返回 `name_matched: null`(无法验证) + suggestion 提示用户提供更多上下文
- 宁可返 "无法确认" 也不要硬填别家公司的资料

【第二步 · 判断客户类型】
先判断该企业的客户是企业(B2B)还是个人消费者(B2C),这决定了关键词的生成逻辑。

【第三步 · 分字段提取(匹配成功才填)】

1. name_matched — 布尔值:true(匹配)/false(不匹配,必须填 reason+suggestion)/null(无法判断)
2. matched_name — 资料里实际的公司全名(核对用)
3. industry — 行业分类,格式"大行业 / 细分领域",如"家居建材 / 全屋定制"。根据搜索到的实际业务判断,不要只看公司名推测。
4. businessType — "B2B" 或 "B2C" 或 "B2B+B2C"
5. service_scope(新字段 · 重要) — 服务范围 4 选 1: "全国线上"/"全省"/"全市"/"本地区"
   - 判断依据:公司官网或资料里明示的覆盖范围,**不要看案例地点**
   - 典型误区:资料写"公司在深圳,服务过龙岗、宝安、南山" → service_scope="全市"(深圳),不是"本地区"
   - 资料写"全国 10 城连锁" → "全国线上"
   - 资料未明确 → 默认填"全市"(保守) + service_scope_reasoning 里注明"资料未明确"
6. service_scope_reasoning — 一句话说明判断依据(如"官网显示覆盖全国"/"仅本地门店服务")
7. keywords — 5-8 个**潜在客户视角搜索关键词**

   核心原则:想象一个真正需要该企业产品/服务的潜在客户,他会在百度/抖音/小红书/AI 搜索引擎里搜什么词?

   **B2C 企业**(客户是个人消费者):
   - 写消费者会搜的具体产品名、服务名、"地域+产品"组合
   - 示例(深圳豪车租赁公司):商务专车租赁、迈巴赫配司机、深圳豪车出行、会议用车服务、机场接送专车
   - 示例(全屋定制公司):全屋定制、定制衣柜、橱柜设计、卧室整体家具

   **B2B 企业**(客户是企业/采购决策者):
   - 写企业采购者/技术负责人/老板会搜的词:产品品类词、行业解决方案词、具体技术/功能词
   - 示例(CRM 软件公司):CRM 系统、客户管理软件、销售管理工具、企业 CRM 哪个好用
   - 示例(SEO/营销服务商):SEO 优化、搜索排名提升、AI 搜索优化
   - B2B 允许包含行业术语

   根据 service_scope 加地域:
   - "全国线上" → 关键词不加城市前缀
   - "全省/全市/本地" → 可加省/市/区前缀(如"深圳全屋定制"),但**不要加案例地点**(如"龙岗")

   通用规则:
   - 每个词 2-10 汉字(B2B 可放宽到 12)
   - 禁止含品牌名「{brand_name}」、"公司""科技""有限公司"后缀
   - 禁止写搜索句式如"XX 排行榜""XX 十大品牌"

8. clientLocation — 企业**总部所在城市**(不是案例地点),如"深圳""上海",不确定写"全国"
9. additionalInfo — 150-250 字**普适业务定位**,客观描述:
   - 主营业务和核心产品/服务(具体产品名)
   - 目标客户群体(谁在买/谁在用)
   - 企业规模、成立时间、发展历程
   - 核心优势或特色(技术、资质、模式)
   - **严禁**写具体案例客户名/地点(这些写到 success_cases 字段)
   - **严禁**把"为 XXX 做了 XXX"当作业务范围
   - 只写客观事实,不写评价/建议
10. success_cases — 具体成功案例数组(无则空数组),格式 ["为 XXX 做了 XXX,实现 XXX 效果", ...]
11. competitors — 同行业 3-5 个真实竞品品牌,优先选线上营销做得好的,**不要**把客户/合作方当竞品

【输出格式(纯 JSON,不要 markdown 代码块)】

成功匹配:
{{"name_matched": true, "matched_name": "...", "industry": "...", "businessType": "...",
  "service_scope": "...", "service_scope_reasoning": "...",
  "keywords": ["词1", "词2", ...], "clientLocation": "...",
  "additionalInfo": "...", "success_cases": [...], "competitors": [...]}}

不匹配(强制):
{{"name_matched": false, "matched_name": "资料里实际公司名",
  "reason": "为什么不匹配(如:资料里的公司名是'XXX',主营 XXX 和'{brand_name}'差距大)",
  "suggestion": "请核实品牌全名或提供更多关键词(地域/行业/产品)"}}"""

    # ---- API Key 配置 ----
    doubao_key = os.environ.get("DOUBAO_SEED_API_KEY", os.environ.get("DOUBAO_API_KEY", ""))
    ds_key = os.environ.get("DASHSCOPE_API_KEY", "")
    kimi_key = os.environ.get("KIMI_API_KEY", "")
    if not doubao_key and not ds_key and not kimi_key:
        raise HTTPException(status_code=500, detail="未配置任何 LLM API Key")

    # ---- 通用 JSON 解析 ----
    def _parse_json(raw: str) -> dict:
        if not raw or not isinstance(raw, str):
            raise ValueError(f"LLM返回内容无效: type={type(raw)}, val={repr(raw)[:100]}")
        cleaned = raw.strip()
        # 去除 <think> 标签
        cleaned = re.sub(r'<think>[\s\S]*?</think>\s*', '', cleaned)
        cleaned = re.sub(r'<think>[\s\S]*$', '', cleaned).strip()
        if not cleaned:
            raise ValueError(f"LLM返回内容清理<think>后为空, raw前200字={raw[:200]}")
        # 兼容 markdown 代码块
        m = re.search(r'```(?:json)?\s*([\s\S]*?)```', cleaned)
        if m:
            cleaned = m.group(1).strip()
        m2 = re.search(r'\{[\s\S]*\}', cleaned)
        if m2:
            cleaned = m2.group(0)
        else:
            raise ValueError(f"LLM返回中未找到JSON对象, cleaned前200字={cleaned[:200]}")
        try:
            return json.loads(cleaned)
        except json.JSONDecodeError as e:
            raise ValueError(f"JSON解析失败: {e}, cleaned前200字={cleaned[:200]}")

    # =============================================
    # Provider 1: 豆包联网搜索 → 文本 → 二次提取JSON
    # =============================================
    async def _call_doubao() -> dict:
        if not doubao_key:
            raise ValueError("DOUBAO key not configured")
        logger.info(f"[Autofill] Provider 1: Doubao doubao_app for '{brand_name}'")

        # Step 1: 豆包应用联网搜索（doubao_app ai_search，¥0.2/次，搜索质量高）
        search_prompt = f"请搜索「{brand_name}」的企业信息，包括：所属行业、客户类型(B2B还是B2C)、主营业务和核心产品/服务（具体产品名称）、目标客户群体、总部所在城市、企业简介（成立时间、规模、核心优势）、同行业3-5个竞争对手品牌名。另外请重点分析：1) 该企业的线上营销现状（官网、社媒、内容营销）；2) 潜在客户在搜索引擎中会用什么关键词来寻找这类产品或服务？如果是B2B企业，关键词应该是采购决策者会搜的专业词。"

        # 使用较短超时+重试
        resp_json = None
        for _retry in range(2):
            try:
                async with httpx.AsyncClient(timeout=90.0) as client:
                    resp = await client.post(
                        "https://ark.cn-beijing.volces.com/api/v3/responses",
                        headers={
                            "Authorization": f"Bearer {doubao_key}",
                            "Content-Type": "application/json",
                            "ark-beta-doubao-app": "true",
                        },
                        json={
                            "model": "doubao-seed-1-6-251015",
                            "input": [
                                {
                                    "type": "message",
                                    "role": "user",
                                    "content": [{"type": "input_text", "text": search_prompt}],
                                }
                            ],
                            "tools": [
                                {
                                    "type": "doubao_app",
                                    "feature": {
                                        "ai_search": {"type": "enabled"}
                                    },
                                }
                            ],
                        },
                    )
                    resp.raise_for_status()
                    resp_json = resp.json()
                    break
            except (httpx.ReadError, httpx.RemoteProtocolError, httpx.ReadTimeout) as e:
                logger.warning(f"[Autofill] Doubao doubao_app retry {_retry+1}: {type(e).__name__}: {e}")
                if _retry == 1:
                    raise
        if not resp_json:
            raise ValueError("Doubao doubao_app无响应")

        # 提取搜索结果文本（doubao_app 格式：output[].type=doubao_app_call → blocks）
        search_text = ""
        for item in resp_json.get("output", []):
            if item.get("type") == "doubao_app_call":
                for block in item.get("blocks", []):
                    if block.get("type") == "output_text":
                        search_text += block.get("text", "")
            # 兼容 web_search message 格式（降级场景）
            elif item.get("type") == "message":
                for c in item.get("content", []):
                    if c.get("type") == "output_text":
                        search_text += c.get("text", "")
        if not search_text.strip():
            search_text = resp_json.get("choices", [{}])[0].get("message", {}).get("content", "")
        if not search_text.strip():
            raise ValueError("Doubao搜索返回空内容")

        logger.info(f"[Autofill] Doubao search text length: {len(search_text)}")
        logger.info(f"[Autofill] Doubao search preview: {search_text[:300]}")

        # Step 2: 用豆包 chat completions 从搜索文本中提取结构化 JSON
        # [CTO-15.5 Q3 2026-04-20] 加场景说明 + 品牌名匹配验证 + 业务/案例分字段 + service_scope
        # 老板反馈: 搜"上海骁马豪车租赁"连续两次返回另一家公司简介,LLM 不验证品牌名真实性
        # 下游场景: 资料进入 OmniRank GEO 诊断系统,用于生成搜索关键词+文章。如果品牌名错位,
        #          诊断/扩词/写文章全都围绕错的公司跑,整条链路崩溃。
        extract_prompt = f"""【任务场景】
你正在为 OmniRank GEO(AI 搜索优化)系统提取品牌资料。这份资料将用于后续:
1. 生成"潜在客户 AI 搜索关键词"
2. 诊断品牌在 AI 搜索引擎(DeepSeek/Kimi/豆包)的被推荐度
3. 生成 GEO 优化文章并发布到百家号/知乎等平台

因此资料必须真实准确,不能张冠李戴。

【要提取的品牌】「{brand_name}」

【搜索资料】
{search_text[:3000]}

【第一步 · 真实性验证(最重要)】
你必须先判断搜索资料里的主体公司,和「{brand_name}」是否匹配:
- 资料里多次出现的公司名是否包含「{brand_name}」的关键词?
- 如果搜索资料讲的是**另外一家公司**(名字完全不同,或业务方向不匹配),
  必须返回 `{{"name_matched": false, "matched_name": "资料里实际的公司名", "reason": "为什么不匹配",
            "suggestion": "请用户核实品牌全名或提供更多关键词(地域/行业)"}}`,其他字段留空或填 null。
- 如果匹配(或资料里没任何公司名能明确判定,属于无法判断)才继续填下面字段。

【第二步 · 分字段提取(匹配后才填)】
返回纯JSON(不要markdown代码块),格式:
{{
  "name_matched": true,
  "industry": "大行业 / 细分领域",
  "businessType": "B2B 或 B2C 或 B2B+B2C",
  "service_scope": "服务范围 · 4 选 1:全国线上/全省/全市/本地区(龙岗/朝阳等)",
  "service_scope_reasoning": "判断依据(一句话) · 如'官网显示覆盖全国'或'仅本地门店服务'",
  "keywords": ["搜索词1", "搜索词2", ...],
  "clientLocation": "公司总部所在城市(不是案例地点)",
  "additionalInfo": "150-250字客户公司介绍(仅普适业务定位,禁含具体客户名/案例地点)",
  "success_cases": ["案例1(可含客户名/效果数据)", "案例2", ...],
  "competitors": ["竞品1", "竞品2", ...]
}}

【字段要求(全部严格遵守)】

additionalInfo(业务定位):
- 150-250 字普适业务定位,描述:主营产品/服务类型、目标客户群体、企业规模、核心优势
- **严禁**写具体客户案例地点,如"在深圳龙岗做了 5 套"(这些写到 success_cases 字段)
- **严禁**把"为 XXX 客户做了 XXX"当作业务范围
- 只写客观事实,不写评价/建议

service_scope(服务范围):
- 4 选 1:"全国线上"/"全省"/"全市"/"本地区"
- 判断依据:看官网/资料里公司覆盖范围,**不要看案例地点**
- 典型误区:
  * 资料写"公司在深圳,服务过龙岗、宝安、南山客户" → service_scope="全市"(深圳市),不是"本地区"
  * 资料写"全国 10 城连锁" → "全国线上"
  * 资料没明说 → 默认填"全市"(保守),reasoning 里注明"资料未明确"

keywords(5-8 个 · 最重要):
- 站在**潜在客户**视角:"该企业的目标用户在 AI 搜索引擎会输入什么词找这类服务"
- B2C:消费者日常搜索词,如"商务专车租赁"/"全屋定制"/"定制衣柜"
- B2B:采购决策者/技术负责人搜的专业词,如"CRM 系统"/"SEO 优化服务"(可含行业术语)
- 可结合 service_scope 加地域前缀:全国线上词不加城市,本地服务词加城市(如"深圳全屋定制")
- **禁止**含品牌名「{brand_name}」、"公司"、"有限公司"后缀词

success_cases(可选 · 无则空数组):
- 具体成功案例,含客户名/效果数据/地点(和 additionalInfo 严格区分)
- 格式:"为 XXX 做了 XXX,实现 XXX 效果"

competitors(2-5 个):
- 同行业同业务的竞品品牌名,**不要**把客户/合作方/供应商当竞品

【禁止行为】
1. 不要编造搜索资料里没有的信息,没查到的字段留空或填 null
2. 不要把成功案例塞进 additionalInfo 或 service_scope
3. 不要把客户/合作方当竞品
4. 如果资料明显是另一家公司,务必 name_matched=false + suggestion,不要硬填"""

        async with httpx.AsyncClient(timeout=60.0) as client:
            resp2 = await client.post(
                "https://ark.cn-beijing.volces.com/api/v3/chat/completions",
                headers={
                    "Authorization": f"Bearer {doubao_key}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": os.environ.get("DOUBAO_ENDPOINT_ID", "") or "doubao-seed-2-0-pro-260215",
                    "messages": [
                        {"role": "system", "content": "你是一个企业信息提取工具。根据提供的搜索资料提取结构化信息，只返回纯JSON。注意：先判断企业是B2B还是B2C，keywords字段必须站在该企业潜在客户的搜索视角——B2C写消费者搜索词，B2B写采购决策者/技术负责人会搜的专业词（可含行业术语）。"},
                        {"role": "user", "content": extract_prompt},
                    ],
                    "temperature": 0.1,
                    "max_tokens": 2000,
                },
            )
            resp2.raise_for_status()
            raw = resp2.json()["choices"][0]["message"]["content"]

        logger.info(f"[Autofill] Doubao extract preview: {raw[:300]}")
        return _parse_json(raw)

    # =============================================
    # Provider 2: DashScope qwen3.6-plus 联网搜索
    # =============================================
    async def _call_dashscope() -> dict:
        if not ds_key:
            raise ValueError("DASHSCOPE key not configured")
        # [CTO-15.5 2026-04-20] 实测对比后回滚: qwen3.6-max-preview 性价比不够(思维链膨胀 token 30x · 成本 10-40x)
        # Q3 prompt 升级(name_matched 验证)已让 qwen3.6-plus 不硬编造,边际价值小,退回原模型
        # qwen3.6-max-preview 定义保留在 config/model_config.py 作为未来 opt-in
        logger.info(f"[Autofill] Provider 2: DashScope qwen3.6-plus for '{brand_name}'")

        async with httpx.AsyncClient(timeout=90.0) as client:
            resp = await client.post(
                "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
                headers={
                    "Authorization": f"Bearer {ds_key}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": "qwen3.6-plus",
                    "messages": [
                        {
                            "role": "system",
                            "content": "你是一位专业的企业信息研究员和营销诊断专家。请联网搜索真实企业信息，只基于搜索结果回答。特别重要：你必须验证搜索到的公司是否真的和用户给的品牌名匹配，如果搜到的是另一家公司，必须返回 name_matched=false + suggestion。先判断企业是B2B还是B2C：B2C的keywords写消费者搜索词；B2B的keywords写采购决策者/技术负责人会搜的专业词（可含行业术语如SaaS、解决方案等）。直接返回纯JSON，不要markdown代码块或解释文字。",
                        },
                        {"role": "user", "content": json_prompt},
                    ],
                    "temperature": 0.1,
                    "max_tokens": 4000,
                    "enable_search": True,
                },
            )
            resp.raise_for_status()
            resp_body = resp.json()
            logger.info(f"[Autofill] DashScope status={resp.status_code}, keys={list(resp_body.keys())}")
            if "choices" not in resp_body:
                raise ValueError(f"DashScope响应无choices字段: {json.dumps(resp_body, ensure_ascii=False)[:300]}")
            raw = resp_body["choices"][0]["message"].get("content") or ""

        if not raw or not raw.strip():
            raise ValueError(f"DashScope返回空content, finish_reason={resp_body['choices'][0].get('finish_reason')}")
        logger.info(f"[Autofill] DashScope raw preview: {raw[:300]}")
        return _parse_json(raw)

    # =============================================
    # Provider 3: Kimi K2.5 $web_search 联网搜索
    # =============================================
    async def _call_kimi() -> dict:
        if not kimi_key:
            raise ValueError("KIMI key not configured")
        logger.info(f"[Autofill] Provider 3: Kimi K2.5 web_search for '{brand_name}'")

        messages = [
            {"role": "system", "content": "你是一位专业的企业信息研究员和营销诊断专家。请联网搜索后，直接返回纯JSON结果。不要解释搜索过程，搜索完成后直接输出JSON。先判断企业是B2B还是B2C：B2C的keywords写消费者搜索词；B2B的keywords写采购决策者/技术负责人会搜的专业词（可含行业术语）。"},
            {"role": "user", "content": json_prompt},
        ]
        tools = [{"type": "builtin_function", "function": {"name": "$web_search"}}]

        async with httpx.AsyncClient(timeout=120.0) as client:
            raw = ""
            for _round in range(8):
                resp = await client.post(
                    "https://api.moonshot.cn/v1/chat/completions",
                    headers={"Authorization": f"Bearer {kimi_key}", "Content-Type": "application/json"},
                    json={
                        "model": "kimi-k2.6",
                        "messages": messages,
                        "max_tokens": 8192,
                        "tools": tools,
                        # [2026-05-16 实测] Kimi K2.6 硬约束:
                        # thinking=disabled → temperature ONLY 0.6(其他值 400)
                        # thinking 默认 enabled → temperature ONLY 1.0
                        # tool_calls 流程必须 disabled → 锁 temperature=0.6
                        "temperature": 0.6,
                        "thinking": {"type": "disabled"},
                    },
                )
                resp.raise_for_status()
                choice = resp.json()["choices"][0]
                msg = choice["message"]
                finish = choice.get("finish_reason")
                logger.info(f"[Autofill] Kimi round {_round+1}: finish_reason={finish}, content_len={len(msg.get('content') or '')}")

                if finish == "stop":
                    raw = msg.get("content", "")
                    break
                if finish == "tool_calls":
                    messages.append(msg)
                    for tc in msg.get("tool_calls", []):
                        messages.append({
                            "role": "tool",
                            "tool_call_id": tc["id"],
                            "name": tc.get("function", {}).get("name"),
                            "content": tc.get("function", {}).get("arguments", "{}"),
                        })
                elif finish == "length":
                    # 输出被截断，尝试从已有内容中提取JSON
                    partial = msg.get("content", "")
                    logger.warning(f"[Autofill] Kimi output truncated at round {_round+1}, partial_len={len(partial)}")
                    if partial and '{' in partial:
                        raw = partial
                    break
                else:
                    raw = msg.get("content", "")
                    break

        if not raw or not raw.strip():
            raise ValueError("Kimi返回空内容")
        logger.info(f"[Autofill] Kimi raw preview: {raw[:300]}")
        return _parse_json(raw)

    # ---- 内部函数：关键词后处理清洗 ----
    def _clean_keywords(keywords: list, company_name: str, business_type: str = "") -> list:
        if not keywords:
            return []

        is_b2b = business_type.upper() in ("B2B", "B2B+B2C") if business_type else False

        # 构建品牌名变体（用于过滤）
        brand_variants = {company_name}
        for suffix in ("科技", "集团", "公司", "企业", "有限", "股份", "实业",
                        "技术", "网络", "信息", "文化", "教育", "传媒", "控股",
                        "国际", "中国", "智能", "数字", "数码"):
            stripped = company_name.replace(suffix, "").strip()
            if len(stripped) >= 2:
                brand_variants.add(stripped)
        for prefix in ("深圳", "北京", "上海", "广州", "杭州", "成都", "武汉",
                        "南京", "苏州", "东莞", "佛山", "厦门", "天津", "重庆"):
            for v in list(brand_variants):
                stripped = v.replace(prefix, "").strip()
                if len(stripped) >= 2:
                    brand_variants.add(stripped)

        # 通用无意义词
        garbage_words = {"公司", "企业", "集团", "科技", "服务", "有限",
                         "技术", "网络", "平台", "品牌", "官网", "官方"}

        # 纯营销黑话（B2B/B2C都不应出现的空洞词）
        universal_jargon = ("赋能", "生态", "闭环", "增长飞轮",
                            "行业壁垒", "核心壁垒", "商业模式", "矩阵")

        # 仅对B2C过滤的行业术语（B2B采购者确实会搜这些词）
        b2c_only_jargon = ("解决方案", "数字化", "智能化", "一体化",
                           "SaaS", "saas", "PaaS", "paas", "B2B", "b2b",
                           "运力调度", "供应链", "中台", "底层", "架构",
                           "全链路", "场景化", "模块化", "标准化体系")

        cleaned = []
        seen = set()
        for kw in keywords:
            if not isinstance(kw, str):
                continue
            kw = kw.strip().strip("、，,。.")
            if not kw or len(kw) < 2:
                continue

            # 过滤：包含品牌名
            if any(v in kw or kw in v for v in brand_variants if len(v) >= 2):
                continue
            # 过滤：纯通用词
            if kw in garbage_words:
                continue
            # 过滤：太长（超过15字很可能是句子不是词）
            if len(kw) > 15:
                continue
            # 过滤：搜索句式（XX哪家好、XX推荐等）
            if any(p in kw for p in ("哪家好", "哪个好", "怎么选", "推荐", "排名", "排行")):
                continue
            # 过滤：任何业务类型都不需要的空洞营销黑话
            if any(j in kw for j in universal_jargon):
                continue
            # 过滤：仅B2C才过滤的行业术语（B2B采购者会搜这些词，保留）
            if not is_b2b and any(j in kw for j in b2c_only_jargon):
                continue
            # 去重
            if kw in seen:
                continue
            seen.add(kw)
            cleaned.append(kw)

        return cleaned[:8]

    # ---- 结果校验与格式化 ----
    # 注意：改成同步 -> async，因为要在返回前 await _commit_charge()（L2 后扣费）
    async def _validate_and_format(result: dict, provider: str) -> dict:
        raw_keywords = result.get("keywords", [])
        business_type = result.get("businessType", "")
        cleaned_keywords = _clean_keywords(raw_keywords, brand_name, business_type)
        logger.info(f"[Autofill] {provider} keywords: {len(raw_keywords)} raw -> {len(cleaned_keywords)} cleaned (businessType={business_type})")

        data_out = {
            "industry": result.get("industry", ""),
            "businessType": business_type,
            "keywords": cleaned_keywords,
            "clientLocation": result.get("clientLocation", ""),
            "additionalInfo": result.get("additionalInfo", ""),
            "competitors": result.get("competitors", []),
        }
        has_content = any([
            data_out["industry"], data_out["keywords"],
            data_out["clientLocation"], data_out["additionalInfo"],
            data_out["competitors"],
        ])
        if not has_content:
            raise ValueError(f"{provider}返回数据全为空")

        logger.info(f"[Autofill] {provider} Success: industry={data_out['industry'][:30]}, "
                     f"kw={len(data_out['keywords'])}, comp={len(data_out['competitors'])}")
        # 真成功 → 这里才扣费（L2 后扣费时序）
        await _commit_charge()
        return {"success": True, "data": data_out, "provider": provider}

    # ---- Provider 映射 ----
    all_providers = {}
    if doubao_key:
        all_providers["doubao"] = ("豆包", _call_doubao)
    if ds_key:
        all_providers["dashscope"] = ("qwen3.6-plus", _call_dashscope)
    if kimi_key:
        all_providers["kimi"] = ("Kimi K2.5", _call_kimi)

    # [CTO-15.23 2026-05-09] llm_call_log 埋点 wrapper · 不改 _call_X 主体
    # 老板报"控制台成本不准"主因之一:autofill 4 callsite 没埋点 · 现在补
    _PROVIDER_MODEL = {
        "doubao": ("doubao", "doubao-seed-1-6-251015"),
        "dashscope": ("dashscope", "qwen3.6-plus"),
        "kimi": ("kimi", "kimi-k2.6"),
    }
    async def _tracked_call(provider_key, fn):
        try:
            from tools.llm_call_tracker import llm_track
        except Exception:
            return await fn()
        platform, model = _PROVIDER_MODEL.get(provider_key, (provider_key, None))
        async with llm_track(
            caller='autofill', platform=platform, model=model,
            user_id=_bill_user_id,
            metadata={'brand_name': (brand_name or '')[:80]},
        ):
            return await fn()

    # 指定了 provider → 只用这一个
    specified = request.provider.strip().lower() if request.provider else ""
    if specified and specified in all_providers:
        display_name, fn = all_providers[specified]
        try:
            result = await _tracked_call(specified, fn)
            return await _validate_and_format(result, display_name)
        except Exception as e:
            logger.warning(f"[Autofill] {display_name} failed: {type(e).__name__}: {e}", exc_info=True)
            # L2 后扣费：根本没扣，直接返错（_refund_on_fail 是 no-op 日志）
            await _refund_on_fail(f"autofill {display_name} 失败: {type(e).__name__}")
            raise HTTPException(status_code=500, detail=f"{display_name}搜索失败: {type(e).__name__}: {e}")

    # 未指定 → 自动 fallback 链
    last_error = None
    for key in ["doubao", "dashscope", "kimi"]:
        if key not in all_providers:
            continue
        display_name, fn = all_providers[key]
        try:
            result = await _tracked_call(key, fn)
            return await _validate_and_format(result, display_name)
        except Exception as e:
            last_error = f"{type(e).__name__}: {e}"
            logger.warning(f"[Autofill] {display_name} failed: {last_error}", exc_info=True)
            continue

    # 所有 provider 都失败 → L2 后扣费：本来就没扣，直接返错
    await _refund_on_fail(f"autofill 所有 provider 失败: {last_error}")
    # [§13 rollout] 返回机器合同(O1:可选 provider 不可用),给重试/手填/取消出口;
    # last_error(含供应商名/异常类)只进日志,不进用户可见文案。
    from services.governance_alerts import autofill_all_providers_failed_alert
    raise HTTPException(
        status_code=500, detail=autofill_all_providers_failed_alert(last_error)
    )


#: [fof8 P1-4] `runState`(统一投影的第一轴)→ legacy 进度端点那两个字段。
#:
#: 这是**呈现映射**,不是第二套状态语义:语义仍旧只在
#: `services/defensive_geo/run_status_projection` 一处。这里回答的是
#: 「这一格在老进度页上画成什么样」。
#: 🔴 **不许有"其余按 collecting 处理"的兜底行** —— 那正是 P1-4 的形状。
#:    键集必须覆盖 RunState 全集(判据机械核对);真取不到时落
#:    `_ALIVE_RUN_STATE_FALLBACK`(可行动的人工态),绝不落 collecting。
_ALIVE_RUN_STATE_VIEW = {
    "queued": ("queued", 0),
    "running": ("collecting", 0),
    "settlement_pending": ("settling", 99),
    "needs_action": ("needs_action", 99),
    "quarantined": ("needs_action", 99),
    # 终态却走到"还没 finished_at"这一支 = 产物行不在的异常。
    # 不伪造完成态(没有 diagnosis_id 的 done=True 会让前端卡在跳转上),
    # 给可行动的人工态。
    "completed": ("needs_action", 99),
    "failed": ("needs_action", 99),
    "cancelled": ("needs_action", 99),
}
_ALIVE_RUN_STATE_FALLBACK = ("needs_action", 99)


@app.get("/api/diagnosis/session/{session_id}/status")
def get_diagnosis_session_status(session_id: str, request: Request):
    """获取诊断任务的实时状态（WebSocket 降级方案）

    当 WebSocket 断连时，前端可通过此接口轮询获取最新进度。
    返回 ConnectionManager 中缓存的最新状态消息。
    RBAC: 只返回用户有权访问的品牌的诊断状态。
    """
    # [foundation-fix #1b 2026-07-13] 统一先做 owner/brand RBAC,再读 Redis 快照或 DB。
    #   原实现先读内存/Redis 缓存(get_task_status)并直接返回,**不校验归属**("信任 session_id"),
    #   任意登录用户可按可猜的 session_id 轮询他人诊断进度(品牌名/阶段/分数)—— 与 WS 侧(audit #731
    #   _ws_authorize_session)不一致的越权面。此处对齐 WS,归属校验前置且 fail-closed。
    _poll_user = getattr(request.state, "user", None)
    if not _poll_user or not isinstance(_poll_user, dict) or not (_poll_user.get("user_id") or _poll_user.get("id")):
        raise HTTPException(status_code=401, detail="未认证")
    if not _ws_authorize_session(_poll_user, session_id):
        raise HTTPException(status_code=403, detail="无权访问该诊断进度")
    _poll_identity = getattr(request.state, "organization_identity", None)
    if _poll_identity is not None and _poll_identity.is_member:
        from db.diagnosis_db import get_diagnosis_by_session as _get_org_poll_diagnosis
        from auth.brand_access import _require_organization_artifact as _require_org_poll_artifact
        _poll_record = _get_org_poll_diagnosis(session_id)
        if not _poll_record:
            raise HTTPException(status_code=404, detail="未找到该诊断任务")
        _require_org_poll_artifact(
            request, "diagnosis", _poll_record["id"]
        )
    # 归属通过 → 内存/Redis 快照(诊断进行中)
    status = manager.get_task_status(session_id)
    # 🔴 [P2-RUNTIME-1] 原来这里是 `if status:` 直接早返。问题在于 `get_task_status`
    #    在 Redis 失联时会回退到**进程内兜底**,而那份兜底可能是别的进程在推进的任务
    #    写下的一句 queued —— 它永远不会更新,却把下面的权威 DB(终态 / 还活着的 run)
    #    整个遮住。于是用户可能一直看到"正在初始化"。
    #    只有当这份快照仍然**权威**(Redis 里有 / 本地兜底还新鲜)时才早返。
    if status and manager.snapshot_is_authoritative(session_id):
        return {"found": True, **status}
    # DB fallback（诊断已完成）— 加 RBAC 过滤
    try:
        from db.diagnosis_db import get_diagnosis_by_session
        from auth.brand_access import filter_organization_artifact_rows, get_user_brand_filter
        record = get_diagnosis_by_session(session_id)
        if record:
            # RBAC: 检查诊断记录的 brand_id 是否在用户可访问范围内
            # 注意：新创建的品牌可能不在 JWT 的 client_brand_ids 里（JWT 缓存了旧值）
            # 所以还要查 DB 确认 owner_user_id
            allowed = get_user_brand_filter(request)
            brand_id = record.get("brand_id")
            if allowed is not None and brand_id not in allowed:
                # JWT 里没有，再查 DB 看是不是 owner
                user = getattr(request.state, "user", None)
                user_id = user.get("user_id") or user.get("id") if user else None
                if user_id and brand_id:
                    from db.connection import get_connection
                    _conn = get_connection()
                    try:
                        _cur = _conn.cursor()
                        _cur.execute("SELECT owner_user_id FROM brands WHERE id = %s", (brand_id,))
                        _row = _cur.fetchone()
                        if not _row or _row.get("owner_user_id") != user_id:
                            return {"found": False, "message": "未找到该诊断任务"}
                    finally:
                        _conn.close()
                else:
                    return {"found": False, "message": "未找到该诊断任务"}
            # [返工2 P0-1b] 结果可见性 fail-closed(Redis 快照过期后此 DB fallback 是唯一后端真相):
            #   终态可见性/run 状态与结算**同事务原子**写,以 result_visibility 为准 ——
            #   withheld(退款/失败/中断)绝不可重构成 complete 泄露分数/等级/诊断 ID;pending(结算前)只给"生成中"。
            #   仅 published / NULL(旧数据兼容)才下发完成数据。
            _vis = record.get("result_visibility")
            if _vis == "withheld":
                return {"found": True, "type": "error", "stage": "failed", "progress": 100,
                        "done": True, "error": "诊断未完成或已退款", "message": "诊断未完成或已退款,请重试"}
            if _vis == "pending":
                return {"found": True, "type": "progress", "stage": "settling", "progress": 99,
                        "done": False, "message": "报告正在生成中,请稍后刷新查看"}
            # [CTO-15.23 2026-05-11 P0-2] 补 score / level / brand_id · 让前端 polling fallback 拿到完整完成数据
            # 原 bug:WS disconnect 后 polling 走这里 · 只返 done=True · 前端进度组件渲染不出"完成"卡 + 跳转按钮
            # 老板看到的现象:诊断已完成 · 但 UI 仍卡"业务理解"第 1 步
            return {
                "found": True,
                "type": "complete",
                "stage": "done",
                "progress": 100,
                "done": True,
                "diagnosis_id": record.get("id"),
                "brand_id": record.get("brand_id"),
                "brand_name": record.get("brand_name"),
                "score": record.get("total_score"),
                "level": record.get("level"),
                "message": "诊断已完成"
            }
    except Exception as e:
        logger.warning(f"Session status DB lookup failed: {e}")
    # [返工2 修复净增量 P3] 产物行不存在(delivery_repair_pending/退款终态·产物被并发删或未落库)时,Redis 快照过期
    #   (>SNAP_TTL)+ reconciler 24h 窗口关后不能返 found:false 让已扣款用户看到"未找到"。读 diagnosis_runs 该
    #   session 的**非成功终态 final_snapshot**(持久)兜底,回稳定的异常/退款信号。仅非成功终态(不泄露成功态)。
    try:
        from db.connection import get_connection as _gc_run
        _rc = _gc_run()
        try:
            _rcur = _rc.cursor()
            _rcur.execute(
                "SELECT run_status, final_snapshot_jsonb FROM diagnosis_runs "
                "WHERE session_id=%s AND finished_at IS NOT NULL ORDER BY finished_at DESC LIMIT 1",
                (session_id,))
            _rrow = _rcur.fetchone()
        finally:
            _rc.close()
        if _rrow and _rrow.get("run_status") not in ("committed", "completed_exempt") \
                and _rrow.get("final_snapshot_jsonb") is not None:
            _snap = _rrow["final_snapshot_jsonb"]
            if isinstance(_snap, str):
                try:
                    _snap = json.loads(_snap)
                except Exception:
                    _snap = None
            if isinstance(_snap, dict):
                return {"found": True, **_snap}
    except Exception as _rex:
        logger.warning(f"Session status diagnosis_runs fallback failed: {_rex}")
    # 🔴 [P2-RUNTIME-1 · 第三支] run **还活着**(finished_at IS NULL)。
    #
    #    走到这儿说明:快照层给不出权威答案(Redis 失联 + 本地兜底已陈旧或压根没有),
    #    产物行还没落,终态兜底也没有。此时**绝不能**回 found:false ——
    #    她刚付过钱,前端拿到 found:false 会在退避窗口走完后挂
    #    「未找到此诊断任务…请返回重新发起」,而"重新发起"意味着再冻一笔。
    #    (门八第三发现治的就是这句话;只查终态的实现会把它原样复发。)
    #
    #    run 行是权威的:它说这次体检还在跑,那就如实说还在跑。
    try:
        from db.connection import get_connection as _gc_alive
        _ac = _gc_alive()
        try:
            _acur = _ac.cursor()
            # 🔴 [fof8 P1-4 2026-08-31] 原来这里是 `SELECT 1` —— **没读 run_status**,
            #    于是所有还没写 finished_at 的可达状态(结算中 / 已转人工)都被映射成
            #    "采集中 0%"。正在结算的用户被告知"刚开始采集",是「重新发起」相邻资金
            #    误导的**新形**。分母(六个活态)由判据从 `diagnosis_runs::_cas` 机械枚举。
            _acur.execute(
                "SELECT run_status FROM diagnosis_runs WHERE session_id=%s "
                "AND finished_at IS NULL ORDER BY created_at DESC LIMIT 1",
                (session_id,))
            _arow = _acur.fetchone()
        finally:
            _ac.close()
        if _arow is not None:
            # 复用**现役统一投影**(§3.5 三轴只读投影),不在端点另编一套状态语义。
            # 未知值由 project() 自己落到 quarantined —— 那一层的铁律是
            # 「未知绝不静默变成 completed/released」,这里接住同一条。
            from services.defensive_geo.run_status_projection import project as _project
            _run_state = _project(_arow.get("run_status")).run_state
            _stage, _progress = _ALIVE_RUN_STATE_VIEW.get(_run_state,
                                                          _ALIVE_RUN_STATE_FALLBACK)
            _msg = ""
            try:
                from services.defensive_geo.copy_registry import user_label as _ul
                # running 那一格用"实时通道暂时不可用"那句:她眼前的进度条不动,
                # 需要的是这个解释;其余几格用 run_state 本身的人话(更准)。
                _msg = (_ul("reason", "progress_channel_degraded")
                        if _run_state == "running" else _ul("run_state", _run_state))
            except Exception as _cex:
                # 取不到就不编 —— 现编一句等于在端点里开第二套文案(SSOT 只有 registry)。
                logger.warning(f"Session status degraded copy lookup failed: {_cex}")
            return {"found": True, "type": "progress", "stage": _stage,
                    "progress": _progress, "done": False, "message": _msg,
                    "run_state": _run_state}
    except Exception as _aex:
        logger.warning(f"Session status alive-run fallback failed: {_aex}")
    return {"found": False, "message": "未找到该诊断任务"}

async def _ws_keepalive_loop(websocket: WebSocket, session_id: str, user: dict):
    """WebSocket保活循环，并在连接存续期持续重验组织授权。"""
    import asyncio
    await manager.connect(session_id, websocket)
    try:
        while True:
            # A WebSocket bypasses HTTP middleware after the handshake.  Re-resolve
            # both the account token version and organization membership/artifact
            # authority on every heartbeat so suspension, reassignment, or token
            # rotation cannot leave an already-open progress stream authorized.
            if not _ws_check_user_active(user, require_current_version=True):
                await websocket.close(code=4001, reason="账户状态已变更")
                return
            if not _ws_authorize_organization_session(user, session_id):
                await websocket.close(code=4003, reason="组织权限已变更")
                return
            try:
                await asyncio.wait_for(websocket.receive_text(), timeout=1.0)
            except asyncio.TimeoutError:
                status = manager.get_task_status(session_id)
                if status and status.get("stage") == "done":
                    break
                continue
    except WebSocketDisconnect:
        pass
    except Exception:
        pass
    finally:
        manager.disconnect(session_id, websocket)


def _ws_authorize_session(user: dict, session_id: str) -> bool:
    """[audit #731/#13 · foundation-fix #1b] 诊断进度归属校验 —— 逻辑已抽到 auth.session_access
    (可单测 · WS + 轮询端点共用同一入口,统一"先 RBAC 再读 Redis/DB")。fail-CLOSED 语义不变。"""
    from auth.session_access import authorize_session
    return authorize_session(user, session_id)


def _ws_authorize_organization_session(user: dict, session_id: str) -> bool:
    """Re-resolve member authority and artifact ownership for every WS join."""
    try:
        from db.organization_db import resolve_identity
        identity = resolve_identity(int(user.get("user_id") or user.get("id")), request_id="websocket")
        if identity is None or identity.is_owner:
            return True
        identity.require("diagnosis.read_own")
        from db.diagnosis_db import get_diagnosis_by_session
        record = get_diagnosis_by_session(session_id)
        if not record:
            return False
        from services.organization_artifacts import require_artifact_access
        require_artifact_access(identity, artifact_type="diagnosis", artifact_id=record["id"])
        return True
    except Exception as exc:
        logger.warning("[ws-authz] organization session rejected: %s", type(exc).__name__)
        return False


def _ws_check_user_active(user: dict, *, require_current_version: bool = False) -> bool:
    """[GEO-R1-CAN-149 安全修] WS 建连时补账户禁用/权限吊销 freshness 校验。
    原 WS 只 decode_jwt 不核 users.is_active / permission_version → 被禁用或权限被吊销的用户
    在 JWT 未过期前仍可持续订阅进度。对齐 HTTP 中间件:perm_version 与缓存不一致时回 DB 核实
    is_active。fail-closed(核验异常拒连·进度只读·代价仅 DB 抖动时正主短暂断线)。"""
    try:
        uid = user.get("user_id")
        if not uid:
            return False
        from auth.perm_cache import get_cached_permission_version
        current_ver = get_cached_permission_version(uid)
        if user.get("perm_version") == current_ver:
            return True  # 权限版本未变·JWT 有效期内可信
        if require_current_version:
            return False
        # 版本变更(禁用/角色权限变更会 bump)→ 回 DB 核实账户仍启用
        from db.auth_db import get_user
        fresh = get_user(uid)
        if not fresh or not fresh.get("is_active", True):
            return False
        return True
    except Exception as _e:
        logger.warning(f"[ws-authz] 账户状态核验异常·fail-closed 拒连: {_e}")
        return False


def _ws_bearer_token(websocket: WebSocket) -> str | None:
    """Prefer non-URI WebSocket auth; retain query fallback for legacy users."""
    protocols = [
        value.strip()
        for value in str(websocket.headers.get("sec-websocket-protocol") or "").split(",")
        if value.strip()
    ]
    if len(protocols) == 2 and protocols[0] == "omnirank-auth":
        return protocols[1]
    return websocket.query_params.get("token")


@app.websocket("/ws/progress/{session_id}")
async def websocket_endpoint(websocket: WebSocket, session_id: str):
    # RBAC: WebSocket 强制 JWT 校验
    token = _ws_bearer_token(websocket)
    if not token:
        await websocket.close(code=4001, reason="缺少 Token")
        return
    from auth.jwt_utils import decode_jwt as ws_decode_jwt
    user = ws_decode_jwt(token)
    if not user:
        await websocket.close(code=4001, reason="Token 无效")
        return
    # [GEO-R1-CAN-149] 账户禁用/权限吊销 freshness 校验(fail-closed)
    if not _ws_check_user_active(user):
        await websocket.close(code=4001, reason="账户状态已变更")
        return
    # [audit #731] 校验 session 归属(原只验 JWT 不验归属·可订阅他人诊断进度)
    if not _ws_authorize_session(user, session_id) or not _ws_authorize_organization_session(user, session_id):
        await websocket.close(code=4003, reason="无权访问该诊断进度")
        return
    await _ws_keepalive_loop(websocket, session_id, user)

# 兼容前端调用 /ws/{session_id}
