@app.post("/api/upload")
async def upload_file(file: UploadFile = File(...)):
    # 文件大小校验: 50MB
    MAX_UPLOAD_SIZE = 50 * 1024 * 1024
    first_chunk = await file.read(MAX_UPLOAD_SIZE + 1)
    if len(first_chunk) > MAX_UPLOAD_SIZE:
        raise HTTPException(status_code=413, detail="文件大小不能超过 50MB")
    # 重置到开头供后续处理
    await file.seek(0)

    content = ""
    try:
        # Basic support for text-based files
        if file.filename.endswith(".md") or file.filename.endswith(".txt"):
            content_bytes = await file.read()
            content = content_bytes.decode("utf-8", errors="ignore")
        # [GEO-R10-CAN-018] 真实提取 PDF 文本(原返回 "[PDF File Uploaded: ...]" 占位串·
        #   前端把占位串当 PDF 证据提交进诊断 additional_info → 每份 PDF 证据静默丢失)。
        #   用 services.pdf_reader(全仓 PDF 唯一入口)提取;无可提取文本(扫描件/加密)显式报错·
        #   绝不返回 success 形态的占位串。
        elif file.filename.endswith(".pdf"):
            try:
                from services import pdf_reader
                pdf_bytes = await file.read()
                content = "\n".join(pdf_reader.page_texts(pdf_bytes)).strip()
            except Exception as _pdf_e:
                logger.error(f"[upload] PDF 解析失败 {file.filename}: {_pdf_e}")
                raise HTTPException(status_code=400, detail="PDF 解析失败·请确认文件未加密/损坏,或改用 .md/.txt")
            if not content:
                raise HTTPException(status_code=422, detail="PDF 无可提取文本(可能是扫描件或加密)·请上传文本版或 .md/.txt")
        else:
            content = f"[File Uploaded: {file.filename}]"

    except HTTPException:
        raise
    except Exception as e:
        return {"error": str(e)}

    return {"filename": file.filename, "content": content}

@app.get("/api/report/{session_id}")
def get_report(session_id: str, request: Request):
    """[P0-10 fix 2026-05-23 老板授权] Codex 跨 AI 审计:
    旧 markdown 文件接口按 session_id 直读,无 owner 校验,user25 可读 user46 markdown。
    修法:反查 session_id → diagnosis_records → require_diagnosis_access · glob 路径白名单防遍历"""
    from auth.brand_access import require_diagnosis_access
    user = getattr(request.state, "user", None)
    if not user:
        raise HTTPException(status_code=401, detail="未登录")
    # 反查 diagnosis_id by session_id
    from db.connection import get_connection
    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute("SELECT id, brand_id, report_md_path, result_visibility FROM diagnosis_records WHERE session_id = %s", (session_id,))
        row = c.fetchone()
    finally:
        conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="报告不存在")
    # require_diagnosis_access 反查 owner
    require_diagnosis_access(request, row.get("id"))
    _gate_diagnosis_visibility(dict(row))   # [返工 P0-2b] withheld/pending 正文 md 不可读

    # 路径白名单 · 防 ../ 遍历(只允许 output/ 目录下)
    from pathlib import Path
    output_root = Path("output").resolve()

    # 优先用 DB 记录的 path · 没有再 glob fallback
    candidate_file = None
    db_path = row.get("report_md_path")
    if db_path:
        p = (output_root / Path(db_path).name).resolve()
        if str(p).startswith(str(output_root)) and p.is_file():
            candidate_file = p
    if not candidate_file:
        files = glob.glob(f"output/*{session_id}.md")
        if not files:
            files = glob.glob(f"output/*{session_id.split('_')[-1]}.md")
        if files:
            latest_path = Path(max(files, key=os.path.getmtime)).resolve()
            if str(latest_path).startswith(str(output_root)):
                candidate_file = latest_path
    if not candidate_file:
        return {"error": "Report not found"}
    try:
        return {"content": candidate_file.read_text(encoding="utf-8")}
    except HTTPException:
        raise
    except Exception as e:
        return {"error": f"Failed to read file: {e}"}

# ==========================================
#  报告重新生成API（根据已有数据生成不同风格报告）
# ==========================================

class RegenerateReportRequest(BaseModel):
    diagnosis_scope: str = "geo"  # "geo" | "social" | "full"
    report_style: str = None  # [DEPRECATED] 向后兼容

@app.post("/api/diagnosis/{diagnosis_id}/regenerate-report")
async def regenerate_report(diagnosis_id: int, request: Request, body: RegenerateReportRequest):
    """
    根据已有诊断数据重新生成报告

    Args:
        diagnosis_id: 诊断记录ID
        diagnosis_scope: "geo" GEO专项 / "social" 社媒专项 / "full" 全面诊断

    Returns:
        新生成的报告内容
    """
    from auth.brand_access import require_diagnosis_access
    require_diagnosis_access(request, diagnosis_id)  # 失败抛 HTTPException

    # 扣费 + 失败自动退费
    async with _bill_feature_ctx(request, "report_regen"):
      try:
        # 1. 从数据库获取诊断数据
        from db.diagnosis_db import get_diagnosis_by_id, update_diagnosis_report
        from agents.report_enhancement_agent import generate_enhanced_report

        # 确定 scope（向后兼容旧 report_style）
        scope = body.diagnosis_scope or body.report_style or "geo"
        if scope == "sales": scope = "geo"
        if scope == "technical": scope = "full"

        diagnosis = get_diagnosis_by_id(diagnosis_id)
        if not diagnosis:
            return {"error": f"诊断记录 {diagnosis_id} 不存在"}

        # 2. 提取数据
        data = diagnosis.get("data", {})
        if isinstance(data, str):
            import json
            try:
                data = json.loads(data)
            except:
                data = {}

        scores = diagnosis.get("scores", {})
        if isinstance(scores, str):
            import json
            try:
                scores = json.loads(scores)
            except:
                scores = {}

        # 旧记录走旧scorer（向后兼容）
        diagnosis_type = diagnosis.get("diagnosis_type", "")

        # [FIX] 如果scores有error或者total_score为0，重新计算评分
        if scores.get("error") or scores.get("total_score", 0) == 0:
            try:
                if diagnosis_type == "sales_lite":
                    # 旧销售版：3维度63分
                    from tools.scoring.sales_lite_scorer import calculate_sales_lite_score
                    logger.info(f"[重新评分-旧销售版] diagnosis_id={diagnosis_id}")
                    scores = calculate_sales_lite_score(
                        ai_visibility_data=data.get("ai_visibility") or {},
                        platform_data=data,
                        web_search_data=data.get("web_search") or {}
                    )
                elif scope == "geo":
                    from tools.scoring.geo_scope_scorer import calculate_geo_scope_score
                    logger.info(f"[重新评分-GEO] diagnosis_id={diagnosis_id}")
                    scores = calculate_geo_scope_score(
                        ai_visibility_data=data.get("ai_visibility") or {},
                        web_search_data=data.get("web_search") or {},
                    )
                elif scope == "social":
                    from tools.scoring.social_scope_scorer import calculate_social_scope_score
                    logger.info(f"[重新评分-社媒] diagnosis_id={diagnosis_id}")
                    scores = calculate_social_scope_score(
                        platform_data=data,
                        brand_content_stats=data.get("brand_identification") or {},
                        competitor_data=data.get("competitor_analysis") or {},
                    )
                else:
                    # full scope = 技术版LLM评分
                    from tools.scoring.llm_geo_scorer import calculate_geo_score_llm
                    logger.info(f"[重新评分-全面] diagnosis_id={diagnosis_id}")
                    scores = await calculate_geo_score_llm(
                        brand_name=diagnosis.get("brand_name", ""),
                        industry=diagnosis.get("industry", ""),
                        douyin_data=data.get("douyin") or {},
                        xiaohongshu_data=data.get("xiaohongshu") or {},
                        web_search_data=data.get("web_search") or {},
                        ai_visibility_data=data.get("ai_visibility") or {},
                        competitor_data=data.get("competitor_analysis") or {}
                    )
                logger.info(f"[重新评分完成] score={scores.get('total_score', 0)}/{scores.get('max_score', 100)}")
            except Exception as e:
                logger.error(f"[重新评分失败] {e}")
                scores = {"total_score": 0, "max_score": 100, "level": "空白", "dimension_scores": {}}

        brand_name = diagnosis.get("brand_name", "")
        industry = diagnosis.get("industry", "")

        # [v3.6 白标] 报告是客户可见产物 → surface=customer 解析归属代理品牌
        # owner/brand 取自诊断记录;平台默认(无白标/拿不到 owner)→ 传 None 保持现状(报告函数内回退平台)
        from services.public_whitelabel import resolve_branding_context
        _brand_ctx = resolve_branding_context(
            surface="customer",
            owner_user_id=diagnosis.get("owner_user_id"),
            brand_id=diagnosis.get("brand_id"),
        )
        _report_branding = _brand_ctx.get("brand") if _brand_ctx.get("source") != "platform_default" else None

        # 3. 调用报告生成函数
        # 旧记录走旧报告生成（向后兼容）
        if diagnosis_type in ("sales_lite", "technical_full"):
            restyle = "sales" if diagnosis_type == "sales_lite" else "technical"
            logger.info(f"[重新生成报告-旧版] diagnosis_id={diagnosis_id}, type={diagnosis_type}")
            new_report = await generate_enhanced_report(
                brand_name=brand_name, industry=industry,
                geo_score_data=scores, platform_data=data,
                ai_visibility_data=data.get("ai_visibility"),
                competitor_data=data.get("competitor_analysis", {}),
                content_insights=data.get("content_insights", {}),
                asr_transcripts=data.get("asr_transcripts", []),
                business_context=data.get("business_context", {}),
                industry_analysis=data.get("industry_analysis", {}),
                web_search_data=data.get("web_search", {}),
                report_style=restyle,
                branding=_report_branding,  # [v3.6 白标]
            )
            report_version = "sales_v4.0" if restyle == "sales" else "technical_v3.0"
        else:
            logger.info(f"[重新生成报告] diagnosis_id={diagnosis_id}, scope={scope}")
            new_report = await generate_enhanced_report(
                brand_name=brand_name, industry=industry,
                geo_score_data=scores, platform_data=data,
                ai_visibility_data=data.get("ai_visibility"),
                competitor_data=data.get("competitor_analysis", {}),
                content_insights=data.get("content_insights", {}),
                asr_transcripts=data.get("asr_transcripts", []),
                business_context=data.get("business_context", {}),
                industry_analysis=data.get("industry_analysis", {}),
                web_search_data=data.get("web_search", {}),
                diagnosis_scope=scope,
                branding=_report_branding,  # [v3.6 白标]
            )
            report_version = f"{scope}_v1.0"

        # 4. 保存新报告到数据库
        update_diagnosis_report(diagnosis_id, new_report, scope, report_version)

        logger.info(f"[重新生成报告完成] diagnosis_id={diagnosis_id}, scope={scope}")

        return {
            "success": True,
            "report": new_report,
            "scope": scope,
            "version": report_version
        }

      except HTTPException:
        raise
      except Exception as e:
        logger.error(f"重新生成报告失败: {e}", exc_info=True)
        # re-raise 让 _bill_feature_ctx 触发退费
        raise HTTPException(status_code=500, detail=str(e))


