class PipelineStageLogRequest(BaseModel):
    """9 步工作流埋点写入请求(API_CONTRACTS §2.1)"""
    brand_id: int
    stage_name: str  # diagnosis/quote/pay/write/publish/monitor/report/renew 等
    event: str = "complete"  # start/complete/fail
    meta: Optional[dict] = None


@app.post("/api/pipeline-stage-log")
async def api_log_pipeline_stage(req: PipelineStageLogRequest, request: Request):
    """M1a · 前端/后端写 pipeline_stage_log · 失败不 block 主流程

    定位: M4 stage_runs 兼容壳(ALTER 演化 · 禁平行重建)
    写入策略: 异步安全 · 失败返 log_id=None 不抛异常
    """
    try:
        user = request.state.user
        user_id = user.get("user_id") if user else None

        # RBAC · 校验 brand 归属(代理只能写自己的 brand · admin 直通)
        try:
            from auth.brand_access import require_brand_access
            require_brand_access(request, req.brand_id)
        except HTTPException:
            raise
        except Exception:
            pass  # helper 不存在时降级 · 仍记录

        from db.pipeline_stage_log_db import log_stage_event
        log_id = log_stage_event(
            brand_id=req.brand_id,
            stage_name=req.stage_name,
            event=req.event,
            meta=req.meta,
            actor_user_id=user_id,
        )
        return {"success": True, "log_id": log_id}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[pipeline-stage-log] endpoint 异常(非 block): {e}")
        return {"success": False, "log_id": None, "error": str(e)}


@app.get("/api/dashboard/flow-funnel")
async def api_flow_funnel(
    request: Request,
    days: int = 90,
    scope: str = "agent",  # agent=只看自己 · global=全局(admin 才能用)
):
    """M1a · 9 步工作流漏斗 · 基于 pipeline_stage_log 聚合

    Query:
      - days: 统计窗口(默认 90)
      - scope: agent(默认 · 只看自己的 brand)· global(admin)

    Response: API_CONTRACTS §2.2 { stages: [{name,label,count,ratio}] }
    """
    try:
        user = request.state.user
        user_id = user.get("user_id") if user else None
        is_admin = bool(user.get("is_admin")) if user else False

        actor_filter: Optional[int] = None
        if scope == "agent":
            actor_filter = user_id
        elif scope == "global":
            if not is_admin:
                raise HTTPException(status_code=403, detail="global scope 仅 admin 可用")
            actor_filter = None
        else:
            raise HTTPException(status_code=400, detail=f"未知 scope={scope}")

        from db.pipeline_stage_log_db import compute_flow_funnel
        stages = compute_flow_funnel(days=days, actor_user_id=actor_filter)

        # 额外汇总(前端仪表盘友好)
        base_count = next((s["count"] for s in stages if s["name"] == "diagnosis"), 0)
        pay_count = next((s["count"] for s in stages if s["name"] == "pay"), 0)
        publish_count = next((s["count"] for s in stages if s["name"] == "publish"), 0)

        return {
            "success": True,
            "days": days,
            "scope": scope,
            "stages": stages,
            "summary": {
                "diagnosis_count": base_count,
                "pay_count": pay_count,
                "publish_count": publish_count,
                "pay_ratio": round(pay_count / base_count, 4) if base_count else 0.0,
                "publish_ratio": round(publish_count / base_count, 4) if base_count else 0.0,
            },
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[flow-funnel] 查询异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


