# ============ P0.5c · 诊断 → GEO 方案书 CTA(CTO-15.7 2026-04-24)============

# P1-3 504 UX (2026-04-27 fix/integration-r3-browser-p1):
# generate-quote ~50s · nginx 30/60s 默认会 504 · 后端却已成功扣费 + 落 quote 行
# 前端在 504 后用本 endpoint 轮询查 diagnosis 是否已有 quote · 命中即跳 proposal
# 不要把这个 endpoint 加重业务逻辑 · 仅 idempotent SQL 同 generate-quote 第 3 步幂等
@app.get("/api/diagnosis/{diagnosis_id}/quote")
async def api_get_quote_for_diagnosis(diagnosis_id: int, request: Request):
    """诊断对应的最新非空壳 quote(幂等查询 · 用于 504 后前端轮询)

    Returns:
        - 200 {success: True, quote_id, brand_id, monthly_price, total_articles, existing: True}
        - 404 {detail: "尚未生成"} — 前端继续轮询或提示后台仍在处理

    RBAC: 同 generate-quote · require_diagnosis_access
    """
    try:
        user = request.state.user
        if not user or not user.get("user_id"):
            raise HTTPException(status_code=401, detail="需要登录")
        # [GEO-R4-CAN-009] fail-closed: 授权依赖抛非 HTTP 异常时按拒绝处理·不落到 quote 查询
        try:
            from auth.brand_access import require_diagnosis_access
            require_diagnosis_access(request, diagnosis_id)
        except HTTPException:
            raise
        except Exception as _auth_err:
            logger.error(f"[get-quote-for-diagnosis] diagnosis 授权校验异常·fail-closed: {_auth_err}")
            raise HTTPException(status_code=403, detail="无法校验诊断归属权限")

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute(
                """
                SELECT id, brand_id, monthly_price, total_articles
                FROM quotes
                WHERE diagnosis_id = %s
                  AND deleted_at IS NULL
                  AND (monthly_price > 0 OR (markdown IS NOT NULL AND markdown != ''))
                ORDER BY id DESC LIMIT 1
                """,
                (diagnosis_id,),
            )
            row = cur.fetchone()
        finally:
            try:
                conn.close()
            except Exception:
                pass

        if not row:
            raise HTTPException(status_code=404, detail="尚未生成")

        try:
            from services.quote_numeric_repair import repair_quote_numeric_fields
            repaired = repair_quote_numeric_fields(row["id"])
            monthly_price = repaired.get("monthly_price") or row["monthly_price"]
            total_articles = repaired.get("total_articles") or row["total_articles"]
        except Exception:
            monthly_price = row["monthly_price"]
            total_articles = row["total_articles"]

        return {
            "success": True,
            "quote_id": row["id"],
            "brand_id": row.get("brand_id") if isinstance(row, dict) else row["brand_id"],
            "monthly_price": monthly_price,
            "total_articles": total_articles,
            "existing": True,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[get-quote-for-diagnosis] 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ============ P0.4b · 代理手动确认已发布(CTO-15.7 2026-04-24)============

class ManualPublicationRequest(BaseModel):
    quote_id: int
    platform_name: str
    platform_url: str
    article_id: Optional[int] = None
    article_title: Optional[str] = None
    publish_date: Optional[str] = None
    screenshot_path: Optional[str] = None  # OSS 路径(P0.4b.2 接 upload · 暂由前端预传)
    notes: Optional[str] = None


@app.post("/api/publications/manual")
async def api_record_manual_publication(request: Request, req: ManualPublicationRequest):
    """
    P0.4b · 代理手动确认"已发布" 统一入口

    复用 services.publication_facts.record_manual_publication:
    - 写 media_publications(quote_id / article_id / platform_url / screenshot_path 等)
    - 冗余回写 articles.first_published_at(老板 §10 批)
    - 幂等:同 (quote_id, article_id, platform_url) 不重复 insert

    截图上传(P0.4b.2 明天单独):前端先走现有 upload endpoint 拿 path · 再调本 endpoint
    OSS bucket omnirank-publish-evidence 需老板在阿里云控制台建
    """
    try:
        user = request.state.user
        user_id = user.get("user_id") if user else None
        if not user_id:
            raise HTTPException(status_code=401, detail="需要登录")

        # RBAC · quote 归属校验(若 helper 存在)
        # [GEO-R4-CAN-014] fail-closed: 授权依赖抛非 HTTP 异常时按拒绝处理·不放行写入
        try:
            from auth.brand_access import require_quote_access
            require_quote_access(request, req.quote_id)
        except HTTPException:
            raise
        except Exception as _auth_err:
            logger.error(f"[record-manual-publication] quote 授权校验异常·fail-closed: {_auth_err}")
            raise HTTPException(status_code=403, detail="无法校验报价归属权限")

        from services.publication_facts import record_manual_publication
        result = record_manual_publication(
            quote_id=req.quote_id,
            platform_name=req.platform_name,
            platform_url=req.platform_url,
            article_id=req.article_id,
            operator_id=str(user_id),
            screenshot_path=req.screenshot_path,
            article_title=req.article_title,
            publish_date=req.publish_date,
        )
        logger.info(
            f"[record-manual-publication] P0.4b · pub_id={result['publication_id']} "
            f"quote={req.quote_id} article={req.article_id} is_new={result['is_new']}"
        )

        # M1a T4 埋点 · stage=publish event=complete(只在新建时打点 · 幂等命中不重复)
        if result.get("is_new"):
            try:
                # 用 quote_id 反查 brand_id
                from db.diagnosis_db import get_connection as _dc
                _conn = _dc()
                _cur = _conn.cursor()
                _cur.execute("SELECT brand_id FROM quotes WHERE id = %s", (req.quote_id,))
                _row = _cur.fetchone()
                _conn.close()
                _brand_id = _row["brand_id"] if _row else None
                if _brand_id:
                    from db.pipeline_stage_log_db import log_stage_event
                    log_stage_event(
                        brand_id=_brand_id,
                        stage_name="publish",
                        event="complete",
                        meta={
                            "publication_id": result["publication_id"],
                            "quote_id": req.quote_id,
                            "article_id": req.article_id,
                            "platform_name": req.platform_name,
                            "platform_url": req.platform_url,
                            "source": "manual_form",
                            "first_published": result.get("first_published", False),
                        },
                        actor_user_id=user_id,
                    )
            except Exception as _le:
                logger.warning(f"[record-manual-publication] stage_log 埋点失败(非 block): {_le}")

        return {"success": True, **result}

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[record-manual-publication] 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== P0.4b.2 (CTO-15.9 session 3 · 2026-04-25) · 发布截图 OSS 直传 ==========
# 老板今天建好 omnirank-publish-evidence bucket + CORS · 复用 omnirank-kyc 子账号 AccessKey

class _UploadEvidenceRequest(BaseModel):
    """请求 OSS PUT 预签名 URL"""
    quote_id: int
    article_id: Optional[int] = None
    ext: str = "jpg"               # jpg / jpeg / png / webp
    content_type: str = "image/jpeg"


@app.post("/api/publications/upload-screenshot/sign")
def api_upload_screenshot_sign(body: _UploadEvidenceRequest, request: Request):
    """P0.4b.2 · 给前端发预签名 URL · 浏览器直传 OSS · 不经过我们后端

    流程:
      1. 前端选图(File picker)→ 拿 ext/content_type
      2. 调本端点 → 拿 upload_url + oss_key(10 分钟有效)
      3. 前端 fetch(upload_url, {method:'PUT', body:fileBlob, headers:{Content-Type:...}})
      4. 上传成功后 · oss_key 提交给 /api/publications/manual 的 screenshot_path 字段

    OSS bucket = omnirank-publish-evidence(老板 2026-04-25 建好 · CORS 已配 omnirank.top)
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, body.quote_id)

        from services.publish_evidence_oss import (
            build_evidence_key, generate_upload_url, is_configured,
            PublishEvidenceConfigError, PublishEvidenceAccessError,
        )

        if not is_configured():
            raise HTTPException(
                status_code=503,
                detail="OSS 未配置 · 暂不支持截图上传 · 老板检查 .env 的 OSS_ACCESS_KEY_ID",
            )

        oss_key = build_evidence_key(
            quote_id=body.quote_id,
            article_id=body.article_id,
            ext=body.ext,
        )
        result = generate_upload_url(
            oss_key=oss_key,
            content_type=body.content_type,
            expires_seconds=600,
        )
        return {"success": True, **result}
    except HTTPException:
        raise
    except (ValueError, PublishEvidenceConfigError, PublishEvidenceAccessError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.warning(f"[upload-screenshot/sign] quote={body.quote_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/publications/screenshot-view-url")
def api_screenshot_view_url(oss_key: str, request: Request):
    """P0.4b.2 · 临时签名 GET URL(15 分钟)· 客户/admin/代理查截图

    用途:
      - admin 在 /admin 看代理上传的发布截图
      - 客户在门户看周报"已发证据"卡 · 点截图弹窗
      - 代理在 PublishHistory 看自己历史截图

    入参:oss_key(从 media_publications.screenshot_path 拿 · publications/{quote_id}/... 格式)
    返:{view_url, expires_in}
    """
    try:
        if not oss_key or not oss_key.startswith("publications/"):
            raise HTTPException(status_code=400, detail="无效 oss_key(必须 publications/ 前缀)")

        # RBAC:从 oss_key 反查 quote_id · 校验访问权
        try:
            quote_id = int(oss_key.split("/")[1])
        except (IndexError, ValueError):
            raise HTTPException(status_code=400, detail="oss_key 格式错误")

        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)

        from services.publish_evidence_oss import (
            generate_view_url, is_configured,
            PublishEvidenceConfigError, PublishEvidenceAccessError,
        )

        if not is_configured():
            raise HTTPException(status_code=503, detail="OSS 未配置")

        view_url = generate_view_url(oss_key, expires_seconds=900)
        return {"success": True, "view_url": view_url, "expires_in": 900}
    except HTTPException:
        raise
    except (PublishEvidenceConfigError, PublishEvidenceAccessError) as e:
        raise HTTPException(status_code=500, detail=str(e))
    except Exception as e:
        logger.warning(f"[screenshot-view-url] 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/diagnosis/{diagnosis_id}/type")
def get_diagnosis_type(diagnosis_id: int, request: Request):
    """获取诊断记录的scope/type（前端用于渲染报告徽章和判断功能）"""
    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, diagnosis_id)
        record = get_diagnosis_by_id(diagnosis_id)
        if not record:
            return {"error": "诊断记录不存在"}

        raw_data = json.loads(record.get("raw_data_json", "{}"))
        diagnosis_type = raw_data.get("data", {}).get("diagnosis_type", "technical_full")

        # 新版scope映射
        scope_map = {"sales_lite": "geo", "technical_full": "full"}
        scope = scope_map.get(diagnosis_type, diagnosis_type)
        is_legacy = diagnosis_type in ("sales_lite", "technical_full")

        return {
            "diagnosis_id": diagnosis_id,
            "diagnosis_type": diagnosis_type,
            "scope": scope,
            "is_legacy": is_legacy,
            "can_upgrade": False,  # 新版不再支持升级
        }
    except HTTPException:
        raise
    except Exception as e:
        return {"error": str(e)}


