# ========== 品牌管理API ==========

_NON_ADMIN_BRAND_PRIVATE_FIELDS = {
    "owner_user_id", "created_by", "updated_by", "agent_user_id",
    "upstream_user_id", "referrer_user_id", "referral_user_id",
    "service_account_code", "channel_account_code", "relationship_id",
    "relationship_version", "cost_multiplier", "cost_multiplier_bps",
}


def _serialize_brand_record_for_request(record: dict, request: Request) -> dict:
    """Keep ownership/audit identifiers on admin surfaces only."""

    data = dict(record or {})
    user = getattr(request.state, "user", None) or {}
    if user.get("is_admin"):
        return data
    for key in _NON_ADMIN_BRAND_PRIVATE_FIELDS:
        data.pop(key, None)
    return data

@app.get("/api/brands")
def api_list_brands(
    request: Request,
    search: Optional[str] = None,
    industry_category: Optional[str] = None,
    limit: int = 50,
    offset: int = 0
):
    """获取品牌列表（支持搜索，RBAC 数据隔离）"""
    try:
        from auth.brand_access import get_user_brand_filter
        brands = list_brands(
            search=search,
            industry_category=industry_category,
            limit=limit,
            offset=offset
        )
        # RBAC: 非管理员只返回分配的品牌
        allowed = get_user_brand_filter(request)
        if allowed is not None:
            brands = [b for b in brands if b.get('id') in allowed]
        return {
            "data": [
                _serialize_brand_record_for_request(brand, request)
                for brand in brands
            ]
        }
    except Exception as e:
        logger.exception("Brands API failed")
        raise HTTPException(status_code=500, detail="品牌列表暂时无法加载，请稍后重试") from e


@app.get("/api/brands/{brand_id}")
def api_get_brand(brand_id: int, request: Request):
    """获取品牌详情（RBAC 数据隔离），支持合并后自动重定向"""
    try:
        from auth.brand_access import require_brand_access
        require_brand_access(request, brand_id)
        brand = get_brand_by_id(brand_id)
        if not brand:
            # 查合并映射表，看是否已被合并到其他品牌
            try:
                from db.diagnosis_db import get_connection
                conn = get_connection()
                cursor = conn.cursor()
                cursor.execute("SELECT new_brand_id FROM brand_merge_map WHERE old_brand_id = %s", (brand_id,))
                row = cursor.fetchone()
                conn.close()
                if row:
                    return {"redirect_to": row["new_brand_id"], "message": "该客户已合并到其他品牌"}
            except Exception:
                pass
            raise HTTPException(status_code=404, detail="Brand not found")
        return {"data": _serialize_brand_record_for_request(brand, request)}
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("Brand detail API failed for brand_id=%s", brand_id)
        raise HTTPException(status_code=500, detail="品牌信息暂时无法加载，请稍后重试") from e


