@app.get("/api/brands/{brand_id}/latest-diagnosis-params")
def api_get_brand_latest_diagnosis_params(brand_id: int, request: Request):
    """获取品牌最近诊断参数 + 档案信息，用于诊断表单预填"""
    from auth.brand_access import require_brand_access
    require_brand_access(request, brand_id)
    import json as _json
    from db.connection import get_connection
    conn = get_connection()
    try:
        cur = conn.cursor()
        # [CTO-15.23 2026-05-06 P1 修复] SELECT 加 cities · 让首次诊断也能预填客户区域
        # 老板 E2E 测试:创建客户填了"城市=深圳"·进诊断"客户区域"空白
        # 根因:此 endpoint 漏读 brands.cities · client_location 默认 "" 只在历史诊断中找
        cur.execute(
            "SELECT name, industry, cities, brand_display_names "
            "FROM brands WHERE id = %s LIMIT 1",
            (brand_id,),
        )
        brand = cur.fetchone()
        if not brand:
            raise HTTPException(404, "品牌不存在")

        from services.brand_identity_resolver import parse_brand_display_names

        raw_brand_display_names = brand.get("brand_display_names")
        has_display_name_ssot = raw_brand_display_names is not None and not (
            isinstance(raw_brand_display_names, str)
            and not raw_brand_display_names.strip()
        )
        result = {
            "brand_id": brand_id,
            "brand_name": brand["name"],
            "industry": brand.get("industry", ""),
            "has_diagnosis": False,
            "has_profile": False,
            "keywords": [],
            "own_accounts": [],
            "competitors": [],
            "additional_info": "",
            # P1 修复:首次诊断从 brands.cities 取 · 历史诊断仍可覆盖(L3343)
            "client_location": brand.get("cities") or "",
            "diagnosis_scope": "geo",
            "brand_display_names": list(
                parse_brand_display_names(raw_brand_display_names)
            ),
        }

        # 最近一次已完成诊断的参数([返工3 P2] 业务消费=用作再诊断输入种子 → published-only · 禁把
        #   pending/withheld(结算前/已退款/中断)诊断当"最新已完成"种子)
        cur.execute("""
            SELECT id, keywords, industry, raw_data_json
            FROM diagnosis_records
            WHERE brand_id = %s AND total_score IS NOT NULL
              AND (result_visibility IS NULL OR result_visibility = 'published')
            ORDER BY created_at DESC LIMIT 1
        """, (brand_id,))
        diag = cur.fetchone()

        if diag and getattr(request.state, "organization_identity", None) is not None:
            try:
                from auth.brand_access import _require_organization_artifact
                _require_organization_artifact(request, "diagnosis", diag["id"])
            except HTTPException as _org_diag_denied:
                if _org_diag_denied.status_code in (403, 404):
                    diag = None
                else:
                    raise

        if diag:
            result["has_diagnosis"] = True
            result["industry"] = diag.get("industry") or result["industry"]
            try:
                result["keywords"] = _json.loads(diag.get("keywords", "[]"))
            except Exception:
                result["keywords"] = []
            try:
                raw = diag.get("raw_data_json", "{}")
                data = _json.loads(raw) if isinstance(raw, str) else (raw or {})
                ip = data.get("input_params", {})
                result["own_accounts"] = ip.get("own_accounts") or []
                result["competitors"] = ip.get("competitors") or []
                result["additional_info"] = ip.get("additional_info") or ""
                # Legacy reports are only a migration fallback when this brand
                # has never established the SSOT.  A persisted [] is an
                # explicit operator clear and must not resurrect old aliases.
                if not has_display_name_ssot:
                    result["brand_display_names"] = list(
                        parse_brand_display_names(ip.get("brand_display_names"))
                    )
                # 历史诊断 input_params.client_location 优先于 brand.cities
                result["client_location"] = ip.get("client_location") or result["client_location"]
                result["diagnosis_scope"] = ip.get("diagnosis_scope") or "geo"
            except Exception:
                pass
        else:
            # 没有诊断记录，从 profile 获取基础信息
            cur.execute("""
                SELECT industry, competitors
                FROM client_profiles
                WHERE brand_id = %s AND (is_deleted = 0 OR is_deleted IS NULL)
                ORDER BY updated_at DESC LIMIT 1
            """, (brand_id,))
            profile = cur.fetchone()
            if profile:
                result["has_profile"] = True
                result["industry"] = profile.get("industry") or result["industry"]
                try:
                    comps = profile.get("competitors", "[]")
                    result["competitors"] = _json.loads(comps) if isinstance(comps, str) else (comps or [])
                except Exception:
                    result["competitors"] = []

        return result
    finally:
        conn.close()


