@app.post("/api/brands/merge")
async def api_merge_brands(request: Request):
    """合并多个品牌到主品牌，迁移所有关联数据（仅管理员 + 密码保护）"""
    # 仅管理员可执行
    _user = getattr(request.state, "user", None)
    if not _user or not _user.get("is_admin"):
        raise HTTPException(status_code=403, detail="仅管理员可合并品牌")
    try:
        body = await request.json()
        primary_id = body.get("primary_brand_id")
        merge_ids = body.get("merge_brand_ids", [])
        display_name = body.get("display_name")
        password = body.get("password", "")

        # [WO_246 2026-09-19] 口令**只有一个出处**:环境变量 `ADMIN_MERGE_PASSWORD`。
        #
        # 改前是 `environ.get("ADMIN_MERGE_PASSWORD",
        #                     environ.get("ADMIN_DELETE_PASSWORD", "<写死的一串>"))`:
        #   ① 两个变量都没设时**回落到源码里写死的一串** —— 而源码等于公开,
        #      那串不是口令,是**一道谁都能过的门**(fail-open);
        #   ② `ADMIN_DELETE_PASSWORD` 在现役代码里只在这儿作内层兜底被读,
        #      没有独立功能(Deploy 09-19 只读探测:生产两槽 + 宿主 .env 三处都未设),
        #      ⇒ 本单只保留一个变量,删掉对它的读取;
        #   ③ 比对是明文 `!=`,**非定时安全**。
        #
        # 照同文件 `clear_monitoring_data_endpoint`(:11599,MONITORING_CLEAR_DATA_PASSWORD)
        # 的现成形态改,两处口径一致:未配置 ⇒ 503 `*_NOT_CONFIGURED`;
        # 比对 ⇒ `hmac.compare_digest`。
        #
        # 🔴 **fail-closed 是有意的**:没配就不让合并,而不是回落到一个人人可得的值。
        #    (`08_billing.md:427`「必须 fail-closed」/`:616`「证据未知时 fail-closed」
        #     讲的是资金,同一条道理在权限上只会更硬。)
        _expected = os.environ.get("ADMIN_MERGE_PASSWORD", "").strip()
        if not _expected:
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "ADMIN_MERGE_PASSWORD_NOT_CONFIGURED",
                    "message": "品牌合并口令未配置，请联系运维",
                },
            )
        if not hmac.compare_digest(str(password), _expected):
            return {"status": "error", "error": "密码错误"}
        if not primary_id or not merge_ids:
            return {"status": "error", "error": "请选择主品牌和待合并品牌"}
        if primary_id in merge_ids:
            return {"status": "error", "error": "主品牌不能在待合并列表中"}

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()

            # 验证主品牌存在
            cursor.execute("SELECT id, name FROM brands WHERE id = %s", (primary_id,))
            primary = cursor.fetchone()
            if not primary:
                conn.close()
                return {"status": "error", "error": "主品牌不存在"}

            # 验证待合并品牌
            cursor.execute("SELECT id, name FROM brands WHERE id = ANY(%s)", (merge_ids,))
            merge_brands = cursor.fetchall()
            if len(merge_brands) != len(merge_ids):
                conn.close()
                return {"status": "error", "error": "部分待合并品牌不存在"}

            cursor.execute("SELECT pg_catalog.to_regclass('public.monitoring_identity_decision_events') AS rel")
            if cursor.fetchone().get("rel"):
                cursor.execute(
                    """
                    SELECT COUNT(*) AS cnt
                      FROM public.monitoring_identity_decision_events
                     WHERE brand_id = ANY(%s)
                    """,
                    (merge_ids,),
                )
                if int(cursor.fetchone()["cnt"] or 0) > 0:
                    conn.rollback()
                    raise HTTPException(
                        status_code=409,
                        detail="待合并客户存在不可改写的监测人工核验审计，请保留原客户身份",
                    )

            # 迁移所有关联表的 brand_id
            simple_tables = [
                "brand_aliases", "client_keywords", "client_materials", "client_profiles",
                "confirmed_keywords", "diagnosis_records", "employee_meetings", "extra_keywords",
                "keyword_insights", "keyword_selection_sessions", "monitoring_config",
                "monitoring_reports", "monitoring_tasks", "notifications", "quotes",
                "social_projects", "work_results",
            ]
            # [GEO-R1-CAN-030 P2] 原子化:任一表迁移失败必须整体中止(raise),让外层
            # 事务回滚全部已迁移 + 绝不执行下方 DELETE FROM brands。
            # 旧逻辑 rollback+重连+继续 → 已迁移表被回滚、后续表在新连接上提交、源品牌仍被删 →
            # 部分迁移 + 孤儿引用 + 破坏性假成功(migrated_counts 还报被回滚的计数)。
            migrated_counts = {}
            for table in simple_tables:
                try:
                    cursor.execute(
                        f"UPDATE {table} SET brand_id = %s WHERE brand_id = ANY(%s)",
                        (primary_id, merge_ids)
                    )
                    migrated_counts[table] = cursor.rowcount
                except Exception as te:
                    logger.error(f"[合并] 迁移表 {table} 失败,整体中止(事务回滚,不删源品牌): {te}")
                    raise RuntimeError(f"品牌合并迁移表 {table} 失败,已中止,未做任何改动") from te

            # user_clients 有复合主键 (user_id, brand_id)，需要特殊处理避免冲突
            try:
                # 先获取主品牌已有的 user_id
                cursor.execute("SELECT user_id FROM user_clients WHERE brand_id = %s", (primary_id,))
                existing_users = {r["user_id"] for r in cursor.fetchall()}
                # 迁移不冲突的记录
                cursor.execute(
                    "SELECT user_id, brand_id FROM user_clients WHERE brand_id = ANY(%s)",
                    (merge_ids,)
                )
                uc_rows = cursor.fetchall()
                for row in uc_rows:
                    if row["user_id"] not in existing_users:
                        cursor.execute(
                            "UPDATE user_clients SET brand_id = %s WHERE user_id = %s AND brand_id = %s",
                            (primary_id, row["user_id"], row["brand_id"])
                        )
                        existing_users.add(row["user_id"])
                # 删除剩余冲突记录
                cursor.execute("DELETE FROM user_clients WHERE brand_id = ANY(%s)", (merge_ids,))
                migrated_counts["user_clients"] = len(uc_rows)
            except Exception as te:
                # [GEO-R1-CAN-030 P2] 同上:user_clients 迁移失败整体中止,不删源品牌
                logger.error(f"[合并] 迁移 user_clients 失败,整体中止(事务回滚,不删源品牌): {te}")
                raise RuntimeError(f"品牌合并迁移 user_clients 失败,已中止,未做任何改动") from te

            # 为被合并品牌创建别名记录（方便后续搜索）
            for mb in merge_brands:
                try:
                    cursor.execute(
                        "INSERT INTO brand_aliases (canonical_name, alias, brand_id, source) VALUES (%s, %s, %s, 'manual') ON CONFLICT DO NOTHING",
                        (display_name or primary["name"], mb["name"], primary_id)
                    )
                except Exception:
                    pass

            # 创建合并映射表（如果不存在）并记录 旧ID→新ID
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS brand_merge_map (
                    old_brand_id INTEGER PRIMARY KEY,
                    new_brand_id INTEGER NOT NULL,
                    merged_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            for mid in merge_ids:
                cursor.execute(
                    "INSERT INTO brand_merge_map (old_brand_id, new_brand_id) VALUES (%s, %s) ON CONFLICT (old_brand_id) DO UPDATE SET new_brand_id = %s",
                    (mid, primary_id, primary_id)
                )

            # 先删除被合并的品牌（避免 name 唯一约束冲突）
            cursor.execute("DELETE FROM brands WHERE id = ANY(%s)", (merge_ids,))
            deleted_count = cursor.rowcount

            # 再更新主品牌显示名称
            if display_name:
                cursor.execute(
                    "UPDATE brands SET name = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
                    (display_name, primary_id)
                )

            conn.commit()
            conn.close()

            merged_names = [mb["name"] for mb in merge_brands]
            logger.info(f"[品牌合并] {merged_names} → {primary['name']}(ID={primary_id}), 删除 {deleted_count} 个品牌")
            return {
                "status": "success",
                "message": f"已合并 {deleted_count} 个品牌到 {display_name or primary['name']}",
                "primary_brand_id": primary_id,
                "merged_count": deleted_count,
                "migrated_tables": migrated_counts,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except Exception as e:
        logger.error(f"Brand merge API error: {e}")
        return {"status": "error", "error": str(e)}


@app.patch("/api/brands/{brand_id}/social")
async def api_toggle_brand_social(brand_id: int, request: Request):
    """切换品牌的社媒操盘手开关"""
    user = getattr(request.state, "user", None)
    if not user or not user.get("is_admin"):
        raise HTTPException(status_code=403, detail="需要管理员权限")
    try:
        body = await request.json()
        social_enabled = bool(body.get("social_enabled", False))
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()
            cursor.execute(
                "UPDATE brands SET social_enabled = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s RETURNING name",
                (social_enabled, brand_id)
            )
            row = cursor.fetchone()
            conn.commit()
            conn.close()
            if not row:
                return {"status": "error", "error": "品牌不存在"}
            logger.info(f"[品牌社媒] {row['name']} (ID={brand_id}) → {'开启' if social_enabled else '关闭'}")
            return {"status": "success", "brand_id": brand_id, "social_enabled": social_enabled}
        finally:
            try:
                conn.close()
            except Exception: pass
    except Exception as e:
        logger.error(f"Brand social toggle error: {e}")
        return {"status": "error", "error": str(e)}


@app.patch("/api/brands/{brand_id}/status")
async def api_update_brand_status(brand_id: int, request: Request):
    """更新客户状态（跟进中/未确定/已成交/已归档）"""
    from auth.brand_access import require_brand_access
    require_brand_access(request, brand_id)
    try:
        body = await request.json()
        from services.client_status import CLIENT_STATUS_OPTIONS, client_status_label, normalize_client_status
        new_status = normalize_client_status(body.get("status"), allow_default=False)
        if not new_status:
            allowed = " / ".join(f"{item['label']}({item['value']})" for item in CLIENT_STATUS_OPTIONS)
            return {"status": "error", "error": f"无效客户状态，仅支持 {allowed}"}

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()
            cursor.execute(
                """
                UPDATE brands
                SET status = %s, updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
                RETURNING name, owner_user_id
                """,
                (new_status, brand_id),
            )
            row = cursor.fetchone()
            conn.commit()
            conn.close()

            if not row:
                return {"status": "error", "error": "品牌不存在"}

            status_label = client_status_label(new_status)
            logger.info(f"[客户状态] {row['name']} (ID={brand_id}) → {status_label}")
            return {
                "status": "success",
                "brand_id": brand_id,
                "new_status": new_status,
                "status_label": status_label,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Brand status update error: {e}")
        return {"status": "error", "error": str(e)}


