# ========== 🆕 全局客户上下文 API ==========

@app.get("/api/client-context/list")
def get_client_context_list(request: Request):
    """获取客户上下文列表（全局客户选择器用）

    RBAC 数据隔离：
    - 管理员：返回全部品牌
    - 非管理员：仅返回 user_clients 分配的品牌
    - 未分配客户的用户：向后兼容，返回全部（相当于无限制）
    """
    try:
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()

            # 获取当前用户信息（中间件已注入 request.state.user）
            user = getattr(request.state, "user", None)
            is_admin = user.get("is_admin", False) if user else True  # 无用户信息时向后兼容
            client_brand_ids = user.get("client_brand_ids", []) if user else []

            # 非管理员 → 只返回 user_clients 分配的品牌（无分配则返回空）
            # 管理员 → 返回全部品牌
            # 子查询：取每个品牌最高级别的报价状态（confirmed > paid > draft）
            quote_status_sql = """
                (SELECT CASE
                    WHEN EXISTS (SELECT 1 FROM quotes q WHERE q.brand_id = b.id AND q.status = 'confirmed') THEN 'confirmed'
                    WHEN EXISTS (SELECT 1 FROM quotes q WHERE q.brand_id = b.id AND q.status = 'paid') THEN 'paid'
                    WHEN EXISTS (SELECT 1 FROM quotes q WHERE q.brand_id = b.id AND q.status = 'draft') THEN 'draft'
                    ELSE NULL
                END) as quote_status
            """

            # [CTO-15.23 2026-05-11 P0#1] 加 latest_diagnosis_at + ORDER BY 改最近诊断优先
            # 老板痛点:报价新建客户下拉按 brand.updated_at 排 · 看不到谁刚诊断 · 难选
            latest_diag_sql = "(SELECT MAX(dr.created_at) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) AS latest_diagnosis_at"

            if is_admin:
                # 管理员 → 返回全部（排除软删除）
                cursor.execute(f"""
                    SELECT
                        b.id, b.name, b.brand_code, b.industry, b.industry_category,
                        b.company_name, (SELECT d.total_score FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_score, (SELECT COUNT(*) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) as diagnosis_count,
                        (SELECT d.id FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_diagnosis_id, b.created_at,
                        COALESCE(b.status, 'active') as brand_status,
                        COALESCE(b.social_enabled, FALSE) as social_enabled,
                        COALESCE(b.brand_type, 'legacy') as brand_type,
                        b.owner_user_id,
                        u.display_name as owner_name,
                        COALESCE(NULLIF(u.display_name, ''), NULLIF(u.username, ''),
                                 CASE WHEN b.owner_user_id IS NOT NULL THEN '账号#' || b.owner_user_id::text ELSE NULL END) as owner_account,
                        (SELECT COUNT(*) FROM quotes q WHERE q.brand_id = b.id) as quote_count,
                        {quote_status_sql},
                        {latest_diag_sql}
                    FROM brands b
                    LEFT JOIN users u ON u.id = b.owner_user_id
                    WHERE (b.is_deleted IS NULL OR b.is_deleted = FALSE)
                    ORDER BY
                        CASE WHEN b.brand_type = 'self' THEN 0 ELSE 1 END,
                        (SELECT MAX(dr.created_at) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) DESC NULLS LAST,
                        b.updated_at DESC
                """)
            elif client_brand_ids:
                # 非管理员 + 有分配客户 → 只返回分配的品牌
                placeholders = ",".join(["%s"] * len(client_brand_ids))
                query = f"""
                    SELECT
                        b.id, b.name, b.brand_code, b.industry, b.industry_category,
                        b.company_name, (SELECT d.total_score FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_score, (SELECT COUNT(*) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) as diagnosis_count,
                        (SELECT d.id FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_diagnosis_id, b.created_at,
                        COALESCE(b.status, 'active') as brand_status,
                        COALESCE(b.social_enabled, FALSE) as social_enabled,
                        COALESCE(b.brand_type, 'legacy') as brand_type,
                        b.owner_user_id,
                        u.display_name as owner_name,
                        COALESCE(NULLIF(u.display_name, ''), NULLIF(u.username, ''),
                                 CASE WHEN b.owner_user_id IS NOT NULL THEN '账号#' || b.owner_user_id::text ELSE NULL END) as owner_account,
                        (SELECT COUNT(*) FROM quotes q WHERE q.brand_id = b.id) as quote_count,
                        {quote_status_sql},
                        {latest_diag_sql}
                    FROM brands b
                    LEFT JOIN users u ON u.id = b.owner_user_id
                    WHERE b.id IN ({placeholders})
                      AND (b.is_deleted IS NULL OR b.is_deleted = FALSE)
                    ORDER BY
                        CASE WHEN b.brand_type = 'self' THEN 0 ELSE 1 END,
                        (SELECT MAX(dr.created_at) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) DESC NULLS LAST,
                        b.updated_at DESC
                """
                cursor.execute(query, client_brand_ids)
            else:
                # 非管理员 + 未分配客户 → 返回自己名下的品牌（owner_user_id）
                user_id = user.get("user_id") if user else None
                if user_id:
                    cursor.execute(f"""
                        SELECT
                            b.id, b.name, b.brand_code, b.industry, b.industry_category,
                            b.company_name, (SELECT d.total_score FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_score, (SELECT COUNT(*) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) as diagnosis_count,
                            (SELECT d.id FROM diagnosis_records d WHERE d.brand_id = b.id AND (d.result_visibility IS NULL OR d.result_visibility = 'published') ORDER BY d.created_at DESC LIMIT 1) AS latest_diagnosis_id, b.created_at,
                            COALESCE(b.status, 'active') as brand_status,
                            COALESCE(b.social_enabled, FALSE) as social_enabled,
                            COALESCE(b.brand_type, 'legacy') as brand_type,
                            b.owner_user_id,
                            u.display_name as owner_name,
                            COALESCE(NULLIF(u.display_name, ''), NULLIF(u.username, ''),
                                     CASE WHEN b.owner_user_id IS NOT NULL THEN '账号#' || b.owner_user_id::text ELSE NULL END) as owner_account,
                            (SELECT COUNT(*) FROM quotes q WHERE q.brand_id = b.id) as quote_count,
                            {quote_status_sql},
                            {latest_diag_sql}
                        FROM brands b
                        LEFT JOIN users u ON u.id = b.owner_user_id
                        WHERE b.owner_user_id = %s
                          AND (b.is_deleted IS NULL OR b.is_deleted = FALSE)
                        ORDER BY
                            CASE WHEN b.brand_type = 'self' THEN 0 ELSE 1 END,
                            (SELECT MAX(dr.created_at) FROM diagnosis_records dr WHERE dr.brand_id = b.id AND (dr.result_visibility IS NULL OR dr.result_visibility = 'published')) DESC NULLS LAST,
                            b.updated_at DESC
                    """, (user_id,))
                else:
                    cursor.execute("SELECT 1 WHERE false")

            rows = cursor.fetchall()
            conn.close()

            clients = []
            from services.client_status import client_status_label, normalize_client_status
            for row in rows:
                brand_status = normalize_client_status(row.get("brand_status"))
                client_payload = {
                    "id": row["id"],
                    "name": row["name"],
                    "brand_code": row.get("brand_code"),
                    "industry": row.get("industry"),
                    "industry_category": row.get("industry_category"),
                    **category_fields(row.get("industry_category")),
                    "company_name": row.get("company_name"),
                    "latest_score": row.get("latest_score"),
                    "diagnosis_count": row.get("diagnosis_count", 0),
                    "latest_diagnosis_id": row.get("latest_diagnosis_id"),
                    "quote_count": row.get("quote_count", 0),
                    "quote_status": row.get("quote_status"),
                    "brand_status": brand_status,
                    "client_status": brand_status,
                    "status_label": client_status_label(brand_status),
                    "social_enabled": bool(row.get("social_enabled", False)),
                    "brand_type": row.get("brand_type", "legacy"),
                    "created_at": row["created_at"].isoformat() if row.get("created_at") else None,
                    "latest_diagnosis_at": row["latest_diagnosis_at"].isoformat() if row.get("latest_diagnosis_at") else None,
                }
                if is_admin:
                    client_payload.update({
                        "owner_user_id": row.get("owner_user_id"),
                        "owner_name": row.get("owner_name"),
                        "owner_account": row.get("owner_account"),
                    })
                clients.append(client_payload)

            # Demo customers are appended from their frozen, redacted snapshot.
            # They never enter user_clients or organization_brand_assignments.
            if user and not is_admin:
                from services.demo_access import list_live_demo_contexts, register_demo_list_access
                real_ids = {int(item["id"]) for item in clients}
                demo_contexts = [
                    item for item in list_live_demo_contexts(int(user.get("user_id") or user.get("id")))
                    if item.brand_id not in real_ids
                ]
                register_demo_list_access(request, demo_contexts)
                for demo in demo_contexts:
                    snapshot = demo.snapshot
                    overview = dict(snapshot.get("customer_overview") or {})
                    diagnosis = dict(snapshot.get("diagnosis_snapshot") or {})
                    clients.append({
                        "id": demo.brand_id,
                        "name": overview.get("brand_name") or "演示客户",
                        "industry": overview.get("industry"),
                        "industry_category": overview.get("industry_category"),
                        **category_fields(overview.get("industry_category")),
                        "latest_score": diagnosis.get("total_score"),
                        "diagnosis_count": 1,
                        "latest_diagnosis_id": demo.diagnosis_id,
                        "quote_count": len(snapshot.get("quote_snapshots") or []),
                        "quote_status": None,
                        "brand_status": "active",
                        "client_status": "active",
                        "status_label": "演示案例",
                        "social_enabled": False,
                        "brand_type": "client",
                        "created_at": snapshot.get("frozen_at"),
                        "latest_diagnosis_at": diagnosis.get("created_at"),
                        "access_mode": "demo",
                        "is_demo": True,
                        "demo_case_id": demo.case_id,
                        "demo_expires_at": demo.expires_at,
                    })

            return {"success": True, "clients": clients, "total": len(clients)}
        finally:
            try:
                conn.close()
            except Exception: pass

    except Exception as e:
        logger.error(f"Client context list error: {e}")
        return {"success": False, "error": "客户列表暂时不可用，请稍后重试", "clients": []}


@app.get("/api/client-context/{brand_id}")
def get_client_context_detail(brand_id: int, request: Request):
    """获取客户完整上下文（合并 brands + profiles + materials）

    数据合并优先级: client_profiles > client_materials > brands
    额外返回 relatedQuoteIds 用于桥接监测模块
    """
    try:
        from auth.brand_access import require_brand_access
        require_brand_access(request, brand_id)
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()

            # 1. 获取品牌基础信息（支持合并重定向，排除已删除）
            cursor.execute("SELECT * FROM brands WHERE id = %s AND (is_deleted IS NULL OR is_deleted = FALSE)", (brand_id,))
            brand_row = cursor.fetchone()
            if not brand_row:
                # 查合并映射
                try:
                    cursor.execute("SELECT new_brand_id FROM brand_merge_map WHERE old_brand_id = %s", (brand_id,))
                    merge_row = cursor.fetchone()
                    if merge_row:
                        conn.close()
                        return {"success": True, "redirect_to": merge_row["new_brand_id"]}
                except Exception:
                    pass
                conn.close()
                raise HTTPException(status_code=404, detail=f"品牌 {brand_id} 不存在或已删除")

            brand = dict(brand_row)
            # 实时诊断次数（覆盖 brands 表的冗余字段）[返工2 P1-2] published-only(排 withheld+pending)
            cursor.execute("SELECT COUNT(*) as cnt FROM diagnosis_records WHERE brand_id = %s "
                           "AND (result_visibility IS NULL OR result_visibility = 'published')", (brand_id,))
            brand["_realtime_diagnosis_count"] = cursor.fetchone()["cnt"]
            cursor.execute("""
                SELECT id, total_score, created_at
                FROM diagnosis_records
                WHERE brand_id = %s
                  AND (result_visibility IS NULL OR result_visibility = 'published')
                ORDER BY created_at DESC
                LIMIT 1
            """, (brand_id,))
            latest_diag_row = cursor.fetchone()
            if latest_diag_row:
                brand["_latest_diagnosis_id"] = latest_diag_row["id"]
                brand["_latest_score"] = latest_diag_row.get("total_score")
                brand["_latest_diagnosis_created_at"] = latest_diag_row.get("created_at")

            # 2. 获取客户档案（client_profiles）
            cursor.execute("""
                SELECT * FROM client_profiles
                WHERE brand_id = %s AND (is_deleted = 0 OR is_deleted IS NULL)
                ORDER BY updated_at DESC LIMIT 1
            """, (brand_id,))
            profile_row = cursor.fetchone()
            profile = dict(profile_row) if profile_row else None

            # 3. 获取客户资料（client_materials）
            cursor.execute("""
                SELECT * FROM client_materials
                WHERE brand_id = %s
                ORDER BY updated_at DESC LIMIT 1
            """, (brand_id,))
            materials_row = cursor.fetchone()
            materials = dict(materials_row) if materials_row else None

            # 4. 获取关联报价ID列表（用于桥接监测模块，只取已确认的报价）
            cursor.execute("""
                SELECT id FROM quotes WHERE brand_id = %s AND status = 'confirmed'
                ORDER BY created_at DESC
            """, (brand_id,))
            quote_rows = cursor.fetchall()
            related_quote_ids = [str(r["id"]) for r in quote_rows]

            # 5. 获取关联社媒项目
            try:
                from db.social_project_db import get_connection as get_social_conn
                social_conn = get_social_conn()
                social_cursor = social_conn.cursor()
                social_cursor.execute("""
                    SELECT id, name FROM social_projects
                    WHERE brand_id = %s AND status = 'active'
                """, (brand_id,))
                social_projects = [{"id": r["id"], "name": r["name"]} for r in social_cursor.fetchall()]
                social_conn.close()
            except Exception:
                try:
                    social_conn.close()
                except Exception:
                    pass
                social_projects = []

            # 6. 检查是否有客户已确认的营销资料
            confirmed_materials = None
            try:
                from db.diagnosis_db import get_confirmed_materials
                confirmed_materials = get_confirmed_materials(brand_id)
            except Exception:
                pass

            # 构建合并后的上下文
            context = {
                "brand": {
                    "id": brand["id"],
                    "name": brand["name"],
                    "brand_code": brand.get("brand_code"),
                    "industry": brand.get("industry"),
                    "industry_category": brand.get("industry_category"),
                    **category_fields(brand.get("industry_category")),
                    "company_name": brand.get("company_name"),
                    # [返工2 修复净增量 P2] 不回落 brands 原始冗余列(装配期写 pending 分 · 会泄露未结算/退款分)·
                    #   _latest_* 由上方 published-only 子查询算(无 published 诊断则 None · 与 _latest_*_created_at 一致)。
                    "latest_score": brand.get("_latest_score"),
                    "latest_diagnosis_id": brand.get("_latest_diagnosis_id"),
                    "latest_diagnosis_created_at": brand.get("_latest_diagnosis_created_at"),
                    "diagnosis_count": brand.get("_realtime_diagnosis_count", brand.get("diagnosis_count", 0)),
                    # CTO-15.13 cleanup · 老板纠偏:M3 完整度阻断 Dialog 据此跳 /brands/:id (self) 或 /my-clients/:id (client/legacy)
                    "brand_type": brand.get("brand_type", "legacy"),
                },
                "profile": (lambda p, u: (
                    {k: v for k, v in p.items() if k not in ("admin_insight", "admin_insight_level", "admin_insight_updated_at")}
                    if p and not (u or {}).get("is_admin", False) else p
                ))(profile, getattr(request.state, "user", None)),
                "materials": confirmed_materials if confirmed_materials else materials,
                "materialsConfirmed": confirmed_materials is not None,
                "relatedQuoteIds": related_quote_ids,
                "socialProjects": social_projects,
            }

            return {"success": True, "context": context}
        finally:
            try:
                conn.close()
            except Exception: pass

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Client context detail error: {e}")
        return {"success": False, "error": "客户资料暂时不可用，请稍后重试"}


# ========== 客户资料管理API ==========

class ClientMaterialsRequest(BaseModel):
    company_intro: Optional[str] = None
    founding_year: Optional[int] = None
    team_size: Optional[str] = None
    service_area: Optional[str] = None
    core_selling_points: Optional[List[dict]] = []  # [{"point": "", "evidence": ""}]
    unique_value: Optional[str] = None
    methodology: Optional[str] = None
    case_studies: Optional[List[dict]] = []  # [{"client": "", "result": "", "timeline": ""}]
    pricing_tiers: Optional[List[dict]] = []  # [{"name": "", "price": "", "includes": []}]
    testimonials: Optional[List[dict]] = []  # [{"name": "", "company": "", "quote": ""}]
    credentials: Optional[List[dict]] = []  # [{"type": "", "name": "", "year": 0}]


@app.get("/api/materials/{diagnosis_id}")
def api_get_materials(diagnosis_id: int, request: Request):
    """获取客户资料
    [self-review r4 2026-05-23] IDOR 闭环:加 require_diagnosis_access · 防跨租户读"""
    try:
        from auth.brand_access import require_client_material_access
        require_client_material_access(request, diagnosis_id)
        from db.diagnosis_db import get_client_materials
        materials = get_client_materials(diagnosis_id)
        if materials:
            return {"data": materials}
        return {"data": None, "message": "暂无资料"}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Get materials error: {e}")
        return {"error": str(e)}


@app.post("/api/materials/{diagnosis_id}")
def api_save_materials(diagnosis_id: int, payload: ClientMaterialsRequest, request: Request):
    """保存客户资料
    [self-review r4 2026-05-23] IDOR 闭环:加 require_diagnosis_access · 防跨租户写"""
    try:
        from auth.brand_access import require_client_material_access
        require_client_material_access(request, diagnosis_id)
        from db.diagnosis_db import save_client_materials
        record_id = save_client_materials(
            diagnosis_id,
            payload.dict(),
            organization_identity=getattr(request.state, "organization_identity", None),
        )
        return {"success": True, "id": record_id, "message": "资料已保存"}
    except HTTPException:
        raise
    except OrganizationError:
        raise
    except Exception as e:
        logger.error("Save materials failed error_type=%s", type(e).__name__, exc_info=True)
        raise HTTPException(
            status_code=500,
            detail={"code": "MATERIAL_SAVE_FAILED", "message": "客户资料保存失败，请稍后重试"},
        )


@app.put("/api/materials/{diagnosis_id}")
def api_update_materials(diagnosis_id: int, payload: ClientMaterialsRequest, request: Request):
    """更新客户资料"""
    return api_save_materials(diagnosis_id, payload, request)


@app.post("/api/materials/{diagnosis_id}/extract")
async def api_extract_materials(diagnosis_id: int, request: Request, file: UploadFile = File(...)):
    """上传文件后AI自动提取客户资料
    [self-review r4 2026-05-23] IDOR 闭环:加 require_diagnosis_access"""
    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, diagnosis_id)
        import json

        # [GEO-R1-CAN-042 DoS 加固] 缓冲/解析前先设请求体字节上限·防超大 PDF/DOCX 全量读入内存 + LLM 前解析。
        MAX_MATERIAL_SIZE = 20 * 1024 * 1024  # 20MB
        _probe = await file.read(MAX_MATERIAL_SIZE + 1)
        if len(_probe) > MAX_MATERIAL_SIZE:
            raise HTTPException(status_code=413, detail="文件过大·物料抽取上限 20MB")
        await file.seek(0)

        # 读取文件内容
        content = ""
        filename = file.filename or ""

        if filename.endswith(".pdf"):
            # 尝试使用PyPDF2解析PDF
            try:
                import PyPDF2
                import io
                file_bytes = await file.read()
                pdf_reader = PyPDF2.PdfReader(io.BytesIO(file_bytes))
                for page in pdf_reader.pages:
                    content += page.extract_text() or ""
            except ImportError:
                logger.warning("PyPDF2 not installed, using placeholder for PDF")
                content = f"[PDF内容: {filename}]"
        elif filename.endswith((".md", ".txt")):
            content_bytes = await file.read()
            content = content_bytes.decode("utf-8", errors="ignore")
        elif filename.endswith((".doc", ".docx")):
            # 尝试使用python-docx
            try:
                import docx
                import io
                file_bytes = await file.read()
                doc = docx.Document(io.BytesIO(file_bytes))
                content = "\n".join([para.text for para in doc.paragraphs])
            except ImportError:
                logger.warning("python-docx not installed")
                content = f"[Word文档: {filename}]"
        else:
            content_bytes = await file.read()
            try:
                content = content_bytes.decode("utf-8", errors="ignore")
            except:
                content = f"[文件: {filename}]"

        if not content or len(content) < 50:
            raise HTTPException(status_code=422, detail="无法解析文件内容，请确保上传的是文本类型文件")

        # 调用LLM提取结构化信息 (内联实现)
        import httpx
        import os

        async def call_llm_inline(prompt: str) -> str:
            """内联的LLM调用函数"""
            api_key = os.getenv("DEEPSEEK_API_KEY") or os.getenv("DASHSCOPE_API_KEY")
            if not api_key:
                raise ValueError("No API key configured")
            async with httpx.AsyncClient(timeout=60.0) as client:
                response = await client.post(
                    "https://api.deepseek.com/v1/chat/completions",
                    headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                    json={"model": DEEPSEEK_OFFICIAL_FLASH, "messages": [{"role": "user", "content": prompt}], "temperature": 0.1}
                )
                if response.status_code == 200:
                    return response.json()["choices"][0]["message"]["content"]
                raise Exception(f"LLM call failed: {response.status_code}")

        extract_prompt = f"""你是一个专业的信息提取助手。请从以下公司资料中提取关键信息，并以JSON格式返回。

【公司资料】
{content[:8000]}

【请提取以下信息，返回JSON格式】
{{
  "company_intro": "公司简介（200字内）",
  "founding_year": 2018,
  "team_size": "团队规模（如50-100人）",
  "service_area": "服务范围",
  "unique_value": "一句话价值主张",
  "methodology": "服务方法论/流程",
  "core_selling_points": [
    {{"point": "核心卖点1", "evidence": "证据/数据"}},
    {{"point": "核心卖点2", "evidence": "证据/数据"}}
  ],
  "case_studies": [
    {{"client": "客户名称", "result": "效果数据", "timeline": "服务周期"}}
  ],
  "pricing_tiers": [
    {{"name": "套餐名", "price": "价格范围"}}
  ],
  "testimonials": [
    {{"name": "客户姓名", "company": "公司", "quote": "评价"}}
  ]
}}

注意：
- 只提取资料中明确提到的信息，不要编造
- 如果某类信息不存在，返回空数组或空字符串
- founding_year如果不确定返回null
- 只返回JSON，不要其他内容
"""

        result = await call_llm_inline(extract_prompt)

        # 解析LLM返回的JSON
        try:
            # 清理可能的markdown代码块
            json_str = result.strip()
            if json_str.startswith("```"):
                json_str = json_str.split("```")[1]
                if json_str.startswith("json"):
                    json_str = json_str[4:]
            json_str = json_str.strip()

            extracted = json.loads(json_str)

            # 保存到数据库
            from db.diagnosis_db import save_client_materials
            save_client_materials(
                diagnosis_id,
                extracted,
                organization_identity=getattr(request.state, "organization_identity", None),
            )

            return {
                "success": True,
                "data": extracted,
                "message": "AI已自动提取资料，请核对后保存"
            }
        except json.JSONDecodeError as e:
            logger.error("Extract materials JSON parse failed error_type=%s", type(e).__name__)
            raise HTTPException(status_code=502, detail="AI 返回格式无法解析，请稍后重试")

    # [GEO-R1-CAN-042] 授权(403)/大小(413)等 HTTPException 直接传播·不被下方 except 吞成 200 error 体
    except HTTPException:
        raise
    except OrganizationError:
        raise
    except Exception as e:
        logger.error("Extract materials failed error_type=%s", type(e).__name__, exc_info=True)
        raise HTTPException(
            status_code=500,
            detail={"code": "MATERIAL_EXTRACT_FAILED", "message": "客户资料处理失败，请稍后重试"},
        )

@app.get("/api/history")
def get_history(
    request: Request,  # 🔒 必须,用于 RBAC 过滤
    brand: Optional[str] = None,
    brand_id: Optional[int] = None,
    industry: Optional[str] = None,
    level: Optional[str] = None,
    days: Optional[int] = 30,
    limit: int = 50,
    offset: int = 0
):
    """
    诊断历史列表 — 带 RBAC 过滤

    🔒 安全修复 2026-04-08 (P0 数据泄漏):
       此前 endpoint 无 request 参数，直接返回全部诊断记录，
       任何登录用户都能看到所有其他用户的诊断。
       修复后通过 get_user_brand_filter 按用户拥有的品牌过滤。
    """
    if not list_diagnoses:
        return {"error": "Database module not loaded"}

    try:
        from auth.brand_access import get_user_brand_filter
        allowed = get_user_brand_filter(request)

        records = list_diagnoses(
            brand_name=brand,
            brand_id=brand_id,
            industry=industry,
            level=level,
            days=days,
            limit=limit,
            offset=offset
        )

        # RBAC 过滤：非管理员只返回自己拥有的品牌下的诊断
        # admin (allowed=None) → 不过滤；其他情况按 brand_id 列表过滤
        if allowed is not None:
            allowed_set = set(allowed)
            records = [r for r in records if r.get("brand_id") in allowed_set]

        # [WO_267 读侧] 每行附大类 key / 中文名(只增不改,原 industry_category 原样保留)。
        #   前端历史筛选按 key 对字典;不附的话存量旧名(房产家居…)只能落「所有行业」。
        records = [{**r, **category_fields(r.get("industry_category"))} for r in records]

        # 分页支持：用 COUNT(*) 查总数
        # [P2-21 fix 2026-05-23] total 必须与 records filter 一致
        # 旧 bug:user 传跨租户 brand_id 时 records=[] 但 total 仍 sum 全 allowed → 总数错位
        total = None
        try:
            from db.diagnosis_db import count_diagnoses
            if allowed is not None:
                # P2-21:跨租户 brand_id 应返 total=0(records 已过滤为 [])
                if brand_id is not None and brand_id not in allowed_set:
                    total = 0
                elif brand_id and brand_id in allowed_set:
                    total = count_diagnoses(brand_name=brand, brand_id=brand_id, industry=industry, level=level, days=days)
                else:
                    total = sum(
                        count_diagnoses(brand_name=brand, brand_id=bid, industry=industry, level=level, days=days)
                        for bid in allowed
                    ) if allowed else 0
            else:
                total = count_diagnoses(brand_name=brand, brand_id=brand_id, industry=industry, level=level, days=days)
        except Exception:
            total = len(records)

        return {"data": records, "total": total, "limit": limit, "offset": offset}
    except Exception as e:
        logger.error(f"History API error: {e}")
        return {"error": str(e)}

@app.get("/api/statistics")
def get_stats(request: Request, days: int = 30):
    """[P1-18 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 非 admin 必须按 brand 过滤"""
    if not list_diagnoses:  # check module availability
        return {"error": "Database module not loaded"}

    user = getattr(request.state, "user", None)
    if not user:
        raise HTTPException(status_code=401, detail="未登录")

    try:
        from db.diagnosis_db import get_statistics, get_token_statistics, get_article_statistics
        from auth.brand_access import get_user_brand_filter

        # P1-18: 非 admin 必须按 brand_ids 过滤 · 防全局统计泄漏
        allowed = get_user_brand_filter(request)
        # 非 admin + 无品牌 → 返 0(不能看全局)
        if allowed == [-1]:
            return {
                "diagnosis_stats": {"total_diagnoses": 0, "average_score": 0, "level_distribution": {}, "industry_distribution": {}},
                "token_stats": {"total_cost": 0, "total_calls": 0},
                "article_stats": {"total_articles": 0, "total_words": 0},
                "publish_external_cost": 0,
                "_scoped": "user",
            }

        # 获取诊断统计(admin allowed=None → 全局 · 非 admin allowed=list 由 get_statistics 处理)
        diagnosis_stats = get_statistics(days=days)
        if allowed is not None:
            # 非 admin: 只统计自己 brands(简化处理 · 直接调用并在 Python 层过滤如需更精细可加 DB 参数)
            try:
                diagnosis_stats = get_statistics(days=days, brand_ids=allowed)  # 若 DB 函数不支持 brand_ids 参数则 fallback
            except TypeError:
                pass  # 老 DB 函数签名不支持 · 暂保留全局(P3 改进)

        # 获取Token统计
        try:
            token_stats = get_token_statistics(days=days)
        except Exception as e:
            logger.warning(f"Token stats error: {e}")
            token_stats = {"total_cost": 0, "total_calls": 0}

        # 获取文章统计
        try:
            article_stats = get_article_statistics(days=days)
        except Exception as e:
            logger.warning(f"Article stats error: {e}")
            article_stats = {"total_articles": 0, "total_words": 0}

        # 媒体发布外采成本(给 mhz 平台付的钱 · 独立于 LLM 总成本)
        # [CTO-15.23 2026-05-17 老板拍方案 A] 加独立 Dashboard 卡片
        try:
            from db.meijiehezi_db import get_publish_external_cost_statistics
            publish_stats = get_publish_external_cost_statistics(days=days)
        except Exception as e:
            logger.warning(f"Publish external cost stats error: {e}")
            publish_stats = {
                "total_external_cost_yuan": 0,
                "total_external_cost_points": 0,
                "total_orders": 0,
                "total_items": 0,
                "status_breakdown": {},
            }

        # 合并返回
        return {
            # 诊断统计
            "total_diagnoses": diagnosis_stats.get("total_records", 0),
            "average_score": diagnosis_stats.get("average_score", 0),
            "level_distribution": diagnosis_stats.get("level_distribution", {}),
            "industry_distribution": diagnosis_stats.get("industry_distribution", {}),
            # Token统计
            "total_cost": token_stats.get("total_cost", 0),
            "total_calls": token_stats.get("total_calls", 0),
            "model_distribution": token_stats.get("model_distribution", {}),
            # 文章统计
            "total_articles": article_stats.get("total_articles", 0),
            "total_words": article_stats.get("total_words", 0),
            "article_type_distribution": article_stats.get("type_distribution", {}),
            "article_success_rate": article_stats.get("success_rate", 0),
            # 计算成本效率 (Cost per Call)
            "cost_per_call": round(token_stats.get("total_cost", 0) / token_stats.get("total_calls", 1), 4) if token_stats.get("total_calls", 0) > 0 else 0,
            #保留原有字段兼容前端防止报错，但逻辑上应该逐步废弃
            "cost_per_article": round(token_stats.get("total_cost", 0) / max(article_stats.get("total_articles", 1), 1), 2),
            # 媒体发布外采(独立于 LLM 总成本 · 给 mhz 平台付的钱)
            "publish_external_cost_yuan": publish_stats.get("total_external_cost_yuan", 0),
            "publish_external_cost_points": publish_stats.get("total_external_cost_points", 0),
            "publish_orders_count": publish_stats.get("total_orders", 0),
            "publish_items_count": publish_stats.get("total_items", 0),
            "publish_status_breakdown": publish_stats.get("status_breakdown", {}),
        }
    except Exception as e:
        logger.error(f"Stats API error: {e}")
        return {"error": str(e)}


