@app.get("/api/diagnosis/{id}")
def get_diagnosis_detail(id: int, request: Request):
    if not list_diagnoses:
        return {"error": "Database module not loaded"}

    try:
        from auth.brand_access import require_diagnosis_access
        record = require_diagnosis_access(request, id)
        _gate_diagnosis_visibility(record)   # [返工 P0-2b] withheld→404 / pending→404(退款/未完成不可见)
        # P1-4 SSOT (2026-04-27 fix/integration-r3-browser-p1):
        # M3 内部视角与 /api/public/report/{id} 公开视角必须读同一份 GEO 总分 + 等级。
        # V2 只取漏斗 3 层 SSOT；V1 才取旧 total_score 列。无效数据 fail-closed。
        # 两个 endpoint 都走
        # 同一 helper · 杜绝 "代理 5/100 起步 vs 公开 18/100 隐形级" 这种 SSOT 破裂。
        try:
            from services.report_v2_score import resolve_canonical_score
            canonical = resolve_canonical_score(record)
        except Exception:
            canonical = {"total_score": None, "level": None, "source": "missing"}
        # Fail closed on invalid score data. Leaving raw columns in place would
        # let legacy clients bypass the versioned scoring SSOT.
        record["total_score"] = canonical.get("total_score")
        record["level"] = canonical.get("level")
        # 字段映射：DB uses total_score/level, API contract expects overall_score/overall_grade
        record["overall_score"] = canonical.get("total_score")
        record["overall_grade"] = canonical.get("level")
        # 前端可观测 · 不影响兼容
        record["score_source"] = canonical.get("source")
        return record
    except HTTPException:
        raise
    except Exception as e:
        return {"error": str(e)}

@app.delete("/api/diagnosis/{id}")
def delete_diagnosis(id: int, request: Request):
    """删除诊断记录"""
    if not list_diagnoses:
        raise HTTPException(status_code=500, detail="Database module not loaded")

    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, id)
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cursor = conn.cursor()
            # [返工4 P1] 结算中禁删:与**品牌删除同一资金保护谓词** —— 活跃/结算中(pending_freeze/running/commit_pending/
            #   release_pending/settlement_manual/manual_resolving)+ **未核销 delivery_repair_pending**(钱 committed 无产物·
            #   删产物令 republish 无法补发;writeoff/refund_confirmed 已核销 ops_resolved 标记 → 放行)→ 拒删。
            #   按 session_id 关联 diagnosis_runs。查询异常 → **fail-closed 503 拒删**(不 fail-open · 防误删在结算/待补发产物)。
            try:
                cursor.execute(
                    "SELECT dr2.run_status FROM diagnosis_records dr "
                    "JOIN diagnosis_runs dr2 ON dr2.session_id = dr.session_id "
                    "WHERE dr.id = %s AND ("
                    "  (dr2.run_status IN ('pending_freeze','running','commit_pending','release_pending',"
                    "                      'settlement_manual','manual_resolving')) "
                    "  OR (dr2.run_status='delivery_repair_pending' "
                    "      AND (dr2.last_settlement_error IS NULL OR dr2.last_settlement_error NOT LIKE 'ops_resolved:%%'))) "
                    "LIMIT 1",
                    (id,),
                )
                _active = cursor.fetchone()
            except Exception as _are:
                logger.error(f"[删除诊断] 活跃 run 检查异常 · fail-closed 拒删 id={id}: {_are}")
                try: conn.rollback()
                except Exception: pass
                try: conn.close()
                except Exception: pass
                raise HTTPException(status_code=503,
                                    detail="资金保护检查暂不可用(诊断状态表异常),为防误删在结算诊断,暂不可删除,请稍后重试")
            if _active:
                conn.rollback()
                conn.close()
                raise HTTPException(status_code=409,
                                    detail=f"该诊断正在结算中({_active['run_status']}),暂不可删除,请稍后再试")
            # 解除外键引用：将引用此诊断的报价单的 diagnosis_id 置空
            cursor.execute("UPDATE quotes SET diagnosis_id = NULL WHERE diagnosis_id = %s", (id,))
            cursor.execute("DELETE FROM diagnosis_records WHERE id = %s", (id,))
            conn.commit()
            affected = cursor.rowcount
            conn.close()

            if affected > 0:
                logger.info(f"Deleted diagnosis record: {id}")
                return {"success": True, "message": f"已删除诊断记录 #{id}"}
            else:
                raise HTTPException(status_code=404, detail="记录不存在")
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Delete diagnosis error: {e}")
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/diagnosis/{id}/retest-data")
def get_retest_data(id: int, request: Request):
    """获取复测所需的完整数据（用于预填表单）"""
    if not list_diagnoses:
        return {"error": "Database module not loaded"}

    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, id)
        record = get_diagnosis_by_id(id)
        if not record:
            return {"error": "Record not found"}
        _gate_diagnosis_visibility(record)   # [返工 P0-2b] withheld/pending 复测数据不下发

        # 返回复测需要的字段
        import json
        keywords = []
        input_params = {}
        business_context = {}

        try:
            keywords = json.loads(record.get("keywords", "[]"))
        except:
            pass

        # 从raw_data_json中提取input_params和business_context
        try:
            raw_data = json.loads(record.get("raw_data_json", "{}"))
            input_params = raw_data.get("input_params", {})
            # 提取业务上下文（用于复测时保持相同的业务理解）
            data = raw_data.get("data", {})
            full_context = data.get("business_context", {})
            # 只保留关键字段，避免返回过多数据
            business_context = {
                "core_business": full_context.get("core_business", ""),
                "target_customers": full_context.get("target_customers", ""),
                "value_proposition": full_context.get("value_proposition", ""),
                "real_user_questions": full_context.get("real_user_questions", []),
                "search_keyword_groups": full_context.get("search_keyword_groups", []),
            }
        except:
            pass

        # 如果本记录没有 client_location，尝试从同品牌最近一次有区域的记录获取
        client_location = input_params.get("client_location", "")
        if not client_location:
            try:
                from db.diagnosis_db import get_connection as get_db_conn
                conn_loc = get_db_conn()
                c_loc = conn_loc.cursor()
                c_loc.execute(
                    "SELECT raw_data_json FROM diagnosis_records WHERE brand_name = %s AND id != %s ORDER BY id DESC LIMIT 5",
                    (record.get("brand_name", ""), id)
                )
                for row_loc in c_loc.fetchall():
                    try:
                        rd = json.loads(row_loc["raw_data_json"] or "{}")
                        loc = rd.get("input_params", {}).get("client_location", "")
                        if loc:
                            client_location = loc
                            break
                    except:
                        pass
                conn_loc.close()
            except:
                pass

        return {
            "brand_name": record.get("brand_name", ""),
            "industry": record.get("industry", ""),
            "keywords": keywords,
            "original_score": record.get("total_score", 0),
            "original_level": record.get("level", ""),
            "original_date": record.get("created_at", ""),
            # 输入参数（用于复测时预填）
            "own_accounts": input_params.get("own_accounts", []),
            "competitors": input_params.get("competitors", []),
            "additional_info": input_params.get("additional_info", ""),
            "client_location": client_location,
            "brand_display_names": input_params.get("brand_display_names", []),
            # 诊断scope（新版geo/social/full，兼容旧版report_style）
            "diagnosis_scope": input_params.get("diagnosis_scope",
                {"sales": "geo", "technical": "full"}.get(
                    input_params.get("report_style", ""), "geo")),
            # 业务上下文（用于复测时使用相同的业务理解和测试问题）
            "business_context": business_context,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Retest data error: {e}")
        return {"error": str(e)}

@app.get("/api/brand/{brand_name}/trend")
def get_brand_trend(brand_name: str):
    """获取同品牌的历史诊断趋势"""
    if not list_diagnoses:
        return {"error": "Database module not loaded"}

    try:
        from db.diagnosis_db import get_connection
        import urllib.parse

        # URL解码品牌名
        decoded_name = urllib.parse.unquote(brand_name)

        conn = get_connection()
        try:
            cursor = conn.cursor()

            # 查询同品牌的所有诊断记录（按时间排序）[返工2 P1-2] published-only(趋势不含退款/生成中)
            cursor.execute("""
                SELECT id, total_score, level, created_at,
                       web_search_score, platform_score, content_quality_score,
                       authority_score, brand_ownership_score, ai_visibility_score,
                       ai_citation_score, update_frequency_score
                FROM diagnosis_records
                WHERE brand_name = %s
                  AND (result_visibility IS NULL OR result_visibility = 'published')
                ORDER BY created_at ASC
            """, (decoded_name,))

            rows = cursor.fetchall()
            conn.close()

            trend_data = []
            for row in rows:
                # [P2-19 fix 2026-05-23] created_at 可能是 datetime 对象(psycopg2 默认)或 str
                # 旧代码 row["created_at"][:10] 对 datetime 报 TypeError
                ca = row["created_at"]
                if hasattr(ca, "isoformat"):
                    date_str = ca.isoformat()[:10]
                elif isinstance(ca, str):
                    date_str = ca[:10]
                else:
                    date_str = ""
                trend_data.append({
                    "id": row["id"],
                    "score": row["total_score"],
                    "level": row["level"],
                    "date": date_str,
                    "dimensions": {
                        "web_search": row["web_search_score"],
                        "platform": row["platform_score"],
                        "content_quality": row["content_quality_score"],
                        "authority": row["authority_score"],
                        "brand_ownership": row["brand_ownership_score"],
                        "ai_visibility": row["ai_visibility_score"],
                        "ai_citation": row["ai_citation_score"],
                        "update_frequency": row["update_frequency_score"],
                    }
                })

            return {
                "brand_name": decoded_name,
                "total_records": len(trend_data),
                "trend": trend_data
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except Exception as e:
        logger.error(f"Brand trend error: {e}")
        return {"error": str(e)}

@app.post("/api/diagnosis/{id}/share-link")
def generate_share_link(id: int, request: Request):
    """生成或获取诊断报告的分享短链"""
    from auth.brand_access import require_diagnosis_access
    require_diagnosis_access(request, id)

    from db.connection import get_connection as _gsc
    import json as _json
    conn = _gsc()
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT share_token FROM diagnosis_records WHERE id = %s", (id,))
        row = cursor.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="诊断记录不存在")

        user = getattr(request.state, "user", {})
        user_id = user.get("user_id") or user.get("id") or 0
        token = row.get("share_token")

        # [self-review r4 2026-05-23] P0-1 闭环:target_url 必须带 st={token} · 防 strict 模式坏链
        # 老板独立 worktree 复审:env=true 时若链接不带 st → 404 · 闭环未成
        # 修法:share_token 即短链 code 同值 · 写 target_url 时 baked in `?st={token}` · 前端 SharedReport 透传
        from services.owned_image_policy import public_base_origin  # [WO_331 · 2026-10-03] 唯一出处
        _origin = public_base_origin()

        def _build_target_url(tk: str) -> str:
            return f"{_origin}/public/report/{id}?st={tk}"

        if token:
            target_url = _build_target_url(token)
            cursor.execute("""
                UPDATE short_links
                   SET target_url = %s,
                       creator_user_id = COALESCE(NULLIF(creator_user_id, 0), %s),
                       metadata = COALESCE(metadata, '{}'::jsonb) || %s::jsonb
                 WHERE code = %s
            """, (
                target_url,
                user_id,
                _json.dumps({"diagnosis_id": id}, ensure_ascii=False),
                token,
            ))
            conn.commit()
            return {"success": True, "share_token": token, "share_url": f"{_origin}/api/sl/{token}"}

        # 生成新的短链 · target_url 先用占位 · 拿到 code 再回填 st
        from api.share_api import _create_short_link
        placeholder_target = f"{_origin}/public/report/{id}"
        code = _create_short_link(
            placeholder_target,
            "report", user_id, {"diagnosis_id": id}
        )
        final_target = _build_target_url(code)
        cursor.execute("UPDATE short_links SET target_url = %s WHERE code = %s", (final_target, code))
        cursor.execute("UPDATE diagnosis_records SET share_token = %s WHERE id = %s", (code, id))
        conn.commit()
        return {"success": True, "share_token": code, "share_url": f"{_origin}/api/sl/{code}"}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"生成分享链接失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        conn.close()


def _build_report_html_context(record: dict) -> tuple[dict, dict, dict]:
    """Build shared meta/modules/completeness context for v2/v3 HTML renderers."""
    modules_jsonb = record.get("report_v2_modules_jsonb")
    if isinstance(modules_jsonb, str):
        try:
            modules_jsonb = json.loads(modules_jsonb)
        except Exception:
            modules_jsonb = {}

    completeness_breakdown = record.get("data_completeness_breakdown")
    if isinstance(completeness_breakdown, str):
        try:
            completeness_breakdown = json.loads(completeness_breakdown)
        except Exception:
            completeness_breakdown = {}

    completeness = {
        "score": record.get("data_completeness_score"),
        "level": (completeness_breakdown or {}).get("level", ""),
        "groups": (completeness_breakdown or {}).get("groups", []),
        "impact_notes": (completeness_breakdown or {}).get("impact_notes", []),
        "missing_summary": (completeness_breakdown or {}).get("missing_summary", ""),
    }
    raw_data = record.get("data") if isinstance(record.get("data"), dict) else None
    from services.report_v2_score import build_canonical_report_meta

    meta = build_canonical_report_meta(record, raw_data=raw_data)
    return meta, modules_jsonb or {}, completeness


def _resolve_report_branding(record: dict, audience: str = "client"):
    """v3.6 白标:解析报告 branding(client→customer surface / internal→agent surface)。

    走 SSOT resolve_branding_context;未授权/解析失败/平台默认 → 返回 None（[P0 Codex 2026-06-06]
    不再返回平台默认 brand dict,否则下游 renderer 会把 _PLATFORM_BRAND 当代理白标显示露平台名）。
    下游 renderer 按 audience 决定 client 留白 / internal 平台兜底。
    client=客户可见→customer;internal=代理审→agent(仅 oem 出代理品牌)。
    """
    try:
        from services.public_whitelabel import resolve_branding_context
        surface = "customer" if (audience or "client").lower() == "client" else "agent"
        ctx = resolve_branding_context(
            surface=surface,
            owner_user_id=record.get("brand_owner_user_id"),
            brand_id=record.get("brand_id"),
        )
        # platform_default(无有效白标)→ None;绝不把平台默认 dict 当代理白标喂渲染层。
        return ctx.get("brand") if ctx.get("source") != "platform_default" else None
    except Exception:
        return None


def _build_v2_report_html(record: dict, audience: str) -> str | None:
    """从 diagnosis_records 行 + W1 W2 数据构建 v2 HTML(供 .html 和 .pdf 端点共用)"""
    if record.get("report_v2_version") != "v2":
        return None

    meta, modules_jsonb, completeness = _build_report_html_context(record)

    from services.report_html_renderer import render_report_html
    return render_report_html(
        meta=meta,
        modules_jsonb=modules_jsonb or {},
        completeness=completeness,
        audience=audience,
        branding=_resolve_report_branding(record, audience),
    )


@app.get("/api/diagnosis/{id}/report-v2.pdf")
def get_diagnosis_v2_pdf(
    id: int,
    request: Request,
    audience: str = "client",
    theme: str = "light_corporate",
    quote_id: int = None,
    background_tasks: BackgroundTasks = None,
):
    """CTO-B 2026-04-26 W5 · v2 咨询版 PDF(决策点 3 · Playwright HTML → PDF)

    流程:
      1. 拉 diagnosis 记录 + W1 modules_jsonb
      2. 调 report_html_renderer 生成 HTML(网页同款 · light)
      3. 写临时 HTML 文件
      4. 调 scripts/pptx_workspace/generate_v2_pdf.js · Playwright 转 PDF
      5. 返 FileResponse · 后台清理临时
    """
    import tempfile
    import subprocess
    import uuid as _uuid
    from fastapi.responses import FileResponse
    from urllib.parse import quote as url_quote

    charge = None
    export_request_id = f"report-export-{_uuid.uuid4().hex}"
    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, id)
    except HTTPException:
        raise

    record = get_diagnosis_by_id(id)
    if not record:
        raise HTTPException(404, detail="报告不存在")
    _gate_diagnosis_visibility(record)   # [返工 P0-2b] withheld/pending 不导出 PDF

    normalized_audience = (audience or "client").strip().lower()
    export_modules_jsonb = None
    if normalized_audience == "client":
        from services.report_export_billing import (
            ClientReportNotReadyError,
            require_client_v2_export_ready,
        )

        try:
            export_modules_jsonb = require_client_v2_export_ready(record)
        except ClientReportNotReadyError as not_ready:
            # This guard must stay before renderer execution, Node invocation and
            # charge_report_export(). A placeholder is not a billable export.
            raise HTTPException(
                status_code=409,
                detail={
                    "code": not_ready.code,
                    "message": not_ready.message,
                },
            ) from not_ready

    from services.report_export_billing import require_report_export_idempotency_key

    # Readiness rejects legacy/partial client artifacts first. Every potentially
    # billable request still requires a stable key before renderer, filesystem
    # and billing work starts.
    export_idempotency_key = require_report_export_idempotency_key(request, id)

    html = None
    try:
        from config.settings_manager import load_settings
        from services.report_v3_gating import (
            is_admin_preview_request,
            resolve_report_v3_subject_user_id,
            should_render_report_v3,
        )

        settings = load_settings()
        subject_uid = resolve_report_v3_subject_user_id(
            request=request,
            diagnosis_record=record,
            shared_by=None,
        )
        if should_render_report_v3(settings, subject_uid, is_admin_preview_request(request)):
            meta, modules_jsonb, _completeness = _build_report_html_context(record)
            from services.report_html_renderer_v3 import render_report_v3_html
            from services.report_v3_pdf_footer import build_report_v3_pdf_footer

            # v3.6 白标:先解析 branding(按 audience 定 surface)· 正文与 footer 同一 source
            # (P1 修 Codex:原 footer 自走 customer-surface,internal 场景与正文 agent-surface 不一致)
            _v3_branding = _resolve_report_branding(record, audience)
            footer = build_report_v3_pdf_footer(
                diagnosis_id=id,
                quote_id=quote_id,
                diagnosis_record=record,
                branding=_v3_branding,
                audience=audience,  # [2026-06-01] client→PDF footer 无留资纯交付 · internal→保留顾问联系
            )
            html = render_report_v3_html(
                meta=meta,
                modules_jsonb=modules_jsonb,
                narrative=None,
                theme=theme,
                as_pdf=True,
                pdf_footer_html=footer,
                branding=_v3_branding,
            )
    except Exception as e:
        logger.warning(f"report v3 render fallback to v2: {e}")

    if not html:
        html = _build_v2_report_html(record, audience=audience)
    if not html:
        raise HTTPException(404, detail="该诊断未生成 v2 报告 · 无法导出 PDF")

    base_dir = os.path.dirname(os.path.abspath(__file__))
    script_path = os.path.join(base_dir, 'scripts', 'pptx_workspace', 'generate_v2_pdf.js')
    if not os.path.exists(script_path):
        logger.error("report PDF generator missing: request_id=%s", export_request_id)
        raise HTTPException(
            500,
            detail={
                "code": "REPORT_EXPORT_GENERATION_FAILED",
                "message": "报告生成失败，请稍后重试。",
                "request_id": export_request_id,
            },
        )

    # Prepare the input file before billing. A full disk, bad permission or
    # other filesystem error must never create a charge that then needs an
    # in-memory-only refund path.
    html_path = None
    pdf_path = None
    try:
        with tempfile.NamedTemporaryFile(
            suffix='.html', delete=False, mode='w', encoding='utf-8'
        ) as f:
            html_path = f.name
            f.write(html)
        pdf_path = html_path.replace('.html', '.pdf')
    except Exception as e:
        if html_path:
            try:
                os.unlink(html_path)
            except Exception:
                pass
        logger.error("v2 PDF input file preparation failed: %s", type(e).__name__)
        raise HTTPException(
            503,
            detail={
                "code": "REPORT_EXPORT_FILE_PREPARATION_FAILED",
                "message": "报告文件暂时无法创建，请稍后重试。",
                "request_id": export_request_id,
            },
        ) from e

    from services.report_export_billing import (
        ReportExportRecoveryPersistenceError,
        ReportExportRefundError,
        charge_client_report_export,
        charge_report_export,
    )

    def cleanup_failed_export_files():
        for fp in [html_path, pdf_path]:
            try:
                if fp and os.path.exists(fp):
                    os.unlink(fp)
            except Exception:
                pass

    def refund_failed_export(reason: str):
        if not charge:
            return
        try:
            charge.refund(reason)
        except ReportExportRefundError as recovery_error:
            # refund() has already written the exact charge identity to the
            # durable fund_recovery_orders queue. Preserve the export error for
            # the client while making the unresolved refund auditable.
            logger.error(
                "report export exact refund queued: diagnosis=%s recovery_order=%s charge_tx=%s ledger=%s",
                id,
                recovery_error.recovery_order_id,
                charge.charge_tx_id,
                charge.ledger_type,
            )
        except ReportExportRecoveryPersistenceError:
            logger.critical(
                "report export refund and durable recovery registration both failed: "
                "diagnosis=%s charge_tx=%s ledger=%s",
                id,
                charge.charge_tx_id,
                charge.ledger_type,
            )

    try:
        if normalized_audience == "client":
            charge = charge_client_report_export(
                request,
                id,
                export_modules_jsonb,
                idempotency_key=export_idempotency_key,
            )
        else:
            charge = charge_report_export(
                request,
                id,
                idempotency_key=export_idempotency_key,
            )
    except HTTPException:
        cleanup_failed_export_files()
        raise
    except Exception as e:
        cleanup_failed_export_files()
        logger.exception(
            "report export billing contract failed: request_id=%s error_type=%s",
            export_request_id,
            type(e).__name__,
        )
        raise HTTPException(
            500,
            detail={
                "code": "REPORT_EXPORT_BILLING_FAILED",
                "message": "导出扣费状态暂时无法确认，请稍后重试。",
                "request_id": export_request_id,
            },
        ) from e

    try:
        result = subprocess.run(
            ['node', script_path, html_path, pdf_path],
            capture_output=True, text=True, timeout=90, cwd=base_dir,
        )
        if result.returncode != 0:
            logger.error(
                "v2 PDF generation failed: request_id=%s stderr=%r",
                export_request_id,
                (result.stderr or "")[:1000],
            )
            raise HTTPException(
                500,
                detail={
                    "code": "REPORT_EXPORT_GENERATION_FAILED",
                    "message": "报告生成失败，请稍后重试。",
                    "request_id": export_request_id,
                },
            )
        if not os.path.exists(pdf_path):
            logger.error("v2 PDF output missing: request_id=%s", export_request_id)
            raise HTTPException(
                500,
                detail={
                    "code": "REPORT_EXPORT_GENERATION_FAILED",
                    "message": "报告生成失败，请稍后重试。",
                    "request_id": export_request_id,
                },
            )

        # 清理临时
        def cleanup():
            for fp in [html_path, pdf_path]:
                try:
                    if fp and os.path.exists(fp):
                        os.unlink(fp)
                except Exception:
                    pass
        if background_tasks:
            background_tasks.add_task(cleanup)

        brand_name = record.get("brand_name", "诊断报告")
        audience_label = "客户版" if audience == "client" else "内部版"
        filename = f"{brand_name}_GEO诊断报告v2_{audience_label}.pdf"
        return FileResponse(
            pdf_path,
            media_type="application/pdf",
            filename=filename,
            headers={"Content-Disposition": f"attachment; filename*=UTF-8''{url_quote(filename)}"},
        )
    except subprocess.TimeoutExpired:
        refund_failed_export("PDF 生成超时")
        cleanup_failed_export_files()
        raise HTTPException(
            504,
            detail={
                "code": "REPORT_EXPORT_TIMEOUT",
                "message": "报告生成超时，请稍后重试。",
                "request_id": export_request_id,
            },
        )
    except HTTPException as e:
        refund_failed_export(f"PDF 生成失败: HTTP {e.status_code}")
        cleanup_failed_export_files()
        raise
    except Exception as e:
        logger.exception(
            "v2 PDF export error: request_id=%s error_type=%s",
            export_request_id,
            type(e).__name__,
        )
        refund_failed_export(f"PDF 生成失败: {type(e).__name__}")
        cleanup_failed_export_files()
        raise HTTPException(
            500,
            detail={
                "code": "REPORT_EXPORT_GENERATION_FAILED",
                "message": "报告生成失败，请稍后重试。",
                "request_id": export_request_id,
            },
        ) from e


@app.get("/api/diagnosis/{id}/report-v2.html")
def get_diagnosis_v2_html(id: int, request: Request, audience: str = "client"):
    """CTO-B 2026-04-26 W5 · 咨询版式 HTML(网页 + PDF 共用 · 决策点 3)

    返回 v2 报告完整 HTML · light 优先 · A4 友好
    audience='client'(公开页/客户门户)· 'internal'(代理审)
    """
    from fastapi.responses import HTMLResponse
    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, id)
    except HTTPException:
        raise
    except Exception:
        # 公开访问场景 · 由调用方决定是否走 share_api 路径
        pass

    record = get_diagnosis_by_id(id)
    if not record:
        raise HTTPException(404, detail="报告不存在")
    _gate_diagnosis_visibility(record)   # [返工 P0-2b] withheld/pending 不出 v2 HTML

    if record.get("report_v2_version") != "v2":
        raise HTTPException(404, detail="该诊断未生成 v2 报告 · 请重新触发诊断或联系运维")

    meta, modules_jsonb, completeness = _build_report_html_context(record)

    from services.report_html_renderer import render_report_html
    html = render_report_html(
        meta=meta,
        modules_jsonb=modules_jsonb or {},
        completeness=completeness,
        audience=audience,
        branding=_resolve_report_branding(record, audience),
    )
    return HTMLResponse(content=html, status_code=200)


@app.get("/api/diagnosis/{id}/content")
def get_diagnosis_content(id: int, request: Request, audience: str = "internal"):
    """Get the markdown content for a specific DB record

    CTO-B 2026-04-26 W4 · 视角切换(决策点 2 落库 + 决策点 5 异常透明):
      audience='internal'(默认 · 代理审用)→ report_v2_internal_md
      audience='client'(客户视角预览)→ report_v2_client_md
      v2 不可用时降级 raw_data_json.report / .md 文件(向后兼容)
      返回:{content, version: 'v1'|'v2', audience, completeness, error}
    """
    if not list_diagnoses:
        return {"error": "Database module not loaded"}

    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, id)
        record = get_diagnosis_by_id(id)
        if not record:
            return {"error": "Record not found"}
        _gate_diagnosis_visibility(record)   # [返工 P0-2b] withheld/pending 正文不可见

        # CTO-B W4 · v2 优先 · 按 audience 切换
        v2_version = record.get("report_v2_version")
        v2_internal = record.get("report_v2_internal_md")
        v2_client = record.get("report_v2_client_md")
        v2_error = record.get("report_v2_error")
        completeness_score = record.get("data_completeness_score")
        completeness_breakdown = record.get("data_completeness_breakdown")
        if isinstance(completeness_breakdown, str):
            try:
                import json as _json
                completeness_breakdown = _json.loads(completeness_breakdown)
            except Exception:
                completeness_breakdown = None

        if v2_version == "v2":
            requested = (audience or "internal").lower()
            if requested == "client" and v2_client and v2_client.strip():
                logger.info(f"[获取报告 v2] ID={id} audience=client")
                return {
                    "content": v2_client,
                    "version": "v2",
                    "audience": "client",
                    "data_completeness_score": completeness_score,
                    "data_completeness_breakdown": completeness_breakdown,
                    "report_v2_error": v2_error,
                }
            if v2_internal and v2_internal.strip():
                logger.info(f"[获取报告 v2] ID={id} audience=internal")
                return {
                    "content": v2_internal,
                    "version": "v2",
                    "audience": "internal",
                    "data_completeness_score": completeness_score,
                    "data_completeness_breakdown": completeness_breakdown,
                    "report_v2_error": v2_error,
                }
            # v2 标记但 markdown 为空 · 决策点 5 透明化 · 不静默降级
            logger.warning(f"[获取报告 v2] ID={id} v2 markdown 为空 · error={v2_error}")
            return {
                "error": "报告生成异常 · 需重新生成",
                "report_v2_error": v2_error,
                "version": "v2",
                "audience": requested,
            }

        # v1 fallback
        if record.get("report"):
            logger.info(f"[获取报告 v1] ID={id} 从数据库读取")
            return {"content": record["report"], "version": "v1", "audience": "legacy"}

        if record.get("data") and isinstance(record.get("data"), dict):
            db_report = record["data"].get("report")
            if db_report:
                logger.info(f"[获取报告 v1] ID={id} 从 data 字段读取")
                return {"content": db_report, "version": "v1", "audience": "legacy"}

        # 文件兜底
        report_path = record.get("report_md_path")
        if not report_path or not os.path.exists(report_path):
            logger.info(f"Report path missing in DB for {id}, searching by session_id...")
            session_id = record.get("session_id", "")
            files = glob.glob(f"output/*{session_id}.md")
            if files:
                report_path = max(files, key=os.path.getmtime)
                logger.info(f"Found report file: {report_path}")
            else:
                return {"error": "Report file missing", "path": report_path}

        with open(report_path, "r", encoding="utf-8") as f:
            return {"content": f.read(), "version": "v1", "audience": "legacy"}

    except HTTPException:
        raise
    except Exception as e:
        return {"error": str(e)}

# ==========================================
#  诊断报告导出 API (PPTX / PDF)
# ==========================================

def _get_diagnosis_md_content(diagnosis_id: int):
    """获取遗留内部诊断报告 Markdown，禁止客户导出端点调用。"""
    record = get_diagnosis_by_id(diagnosis_id)
    if not record:
        return None, None, "Record not found"

    brand_name = record.get("brand_name", "诊断报告")
    md_content = None
    if record.get("report"):
        md_content = record["report"]
    elif record.get("data") and isinstance(record.get("data"), dict):
        md_content = record["data"].get("report")

    if not md_content:
        report_path = record.get("report_md_path")
        if not report_path or not os.path.exists(report_path):
            session_id = record.get("session_id", "")
            files = glob.glob(f"output/*{session_id}.md")
            if files:
                report_path = max(files, key=os.path.getmtime)

        if report_path and os.path.exists(report_path):
            with open(report_path, "r", encoding="utf-8") as f:
                md_content = f.read()

    if not md_content:
        return None, brand_name, "No report content found"

    import re as _re
    edit_task_match = _re.search(
        r'^#\s*编辑任务[\s\S]*?##\s*报告草稿[^\n]*\n',
        md_content,
    )
    if edit_task_match:
        md_content = md_content[edit_task_match.end():].strip()

    return md_content, brand_name, None


def _require_ready_client_v2_export(record: dict) -> dict:
    """Fail closed before any legacy export billing, rendering or LLM work."""
    from services.report_export_billing import (
        ClientReportNotReadyError,
        require_client_v2_export_ready,
    )

    try:
        return require_client_v2_export_ready(record)
    except ClientReportNotReadyError as not_ready:
        raise HTTPException(
            status_code=409,
            detail={"code": not_ready.code, "message": not_ready.message},
        ) from not_ready


@app.get("/api/diagnosis/{diagnosis_id}/export/pptx")
def export_diagnosis_pptx(diagnosis_id: int, request: Request, background_tasks: BackgroundTasks):
    """导出诊断报告为PPTX演示文稿"""
    # The active frontend still calls this legacy URL.  No customer-safe PPTX
    # renderer exists yet, so validate the canonical artifact and stop before
    # the old internal-Markdown/LLM/billing pipeline can run.
    from services.report_export_billing import (
        CLIENT_REPORT_EXPORT_UNSUPPORTED_CODE,
        CLIENT_REPORT_EXPORT_UNSUPPORTED_MESSAGE,
    )

    from auth.brand_access import require_diagnosis_access
    require_diagnosis_access(request, diagnosis_id)
    record = get_diagnosis_by_id(diagnosis_id)
    if not record:
        raise HTTPException(status_code=404, detail="报告不存在")
    _gate_diagnosis_visibility(record)
    _require_ready_client_v2_export(record)
    raise HTTPException(
        status_code=409,
        detail={
            "code": CLIENT_REPORT_EXPORT_UNSUPPORTED_CODE,
            "message": CLIENT_REPORT_EXPORT_UNSUPPORTED_MESSAGE,
        },
    )

@app.get("/api/diagnosis/{diagnosis_id}/export/pdf")
def export_diagnosis_pdf(diagnosis_id: int, request: Request, background_tasks: BackgroundTasks, theme: str = "dark_premium"):
    """导出诊断报告为专业PDF（使用高级排版模板，支持主题选择）"""
    VALID_THEMES = {"dark_premium", "light_corporate", "warm_trust", "bold_gradient"}
    if theme not in VALID_THEMES:
        theme = "dark_premium"

    # The active frontend calls this legacy URL.  Ready V2 customer reports
    # always enter the canonical web-native PDF endpoint, independent of the V3
    # presentation flag.  This happens before any old billing, Markdown read or
    # LLM extraction below.
    from auth.brand_access import require_diagnosis_access
    require_diagnosis_access(request, diagnosis_id)
    record = get_diagnosis_by_id(diagnosis_id)
    if not record:
        raise HTTPException(status_code=404, detail="报告不存在")
    _gate_diagnosis_visibility(record)
    _require_ready_client_v2_export(record)
    from fastapi.responses import RedirectResponse

    return RedirectResponse(
        f"/api/diagnosis/{diagnosis_id}/report-v2.pdf?theme={theme}",
        status_code=307,
    )

