@app.get("/api/monitoring/config")
def get_monitoring_config(request: Request, brand_id: int = None, client_id: str = "_global_"):
    """获取监测配置（含并发数）
    [audit #489 2026-06-10] 加 brand 归属校验(原无 RBAC·任意 monitoring:read 用户按他人 brand_id 越权读配置)"""
    try:
        from auth.brand_access import require_brand_access, require_quote_access
        if brand_id is not None:
            require_brand_access(request, brand_id, allow_null=False)
        elif client_id and client_id != "_global_":
            # [audit #13 返修] brand_id=None + 具体 client_id(实为 quote_id 字符串)旁路:原只校验 brand_id
            #   → 任意用户传 client_id=他人 quote_id 越权读其监测配置。解析 client_id→quote→brand 校验归属。
            try:
                _cfg_qid = int(client_id)
            except (ValueError, TypeError):
                raise HTTPException(status_code=400, detail="client_id 非法")
            require_quote_access(request, _cfg_qid)
        # else: client_id=='_global_'(默认全局并发数等非敏感配置)→ 沿用现状放行
        return api_get_config(brand_id=brand_id, client_id=client_id)
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Get config error: {e}")
        return {"status": "error", "error": str(e)}


