@app.get("/api/monitoring/keywords")
def get_monitoring_keywords(request: Request, brand_id: int = None, client_id: str = None, status: str = "active"):
    """获取客户词条列表
    [P0-3 fix 2026-05-23] Codex 跨 AI 审计 · 加 brand 范围过滤"""
    try:
        from auth.brand_access import require_brand_access, require_quote_access, get_user_brand_filter
        if brand_id is not None:
            require_brand_access(request, brand_id, allow_null=False)
            return api_get_keywords(brand_id=brand_id, client_id=client_id, status=status)
        if client_id is not None:
            try:
                quote_id = int(client_id)
            except (TypeError, ValueError):
                raise HTTPException(status_code=400, detail="client_id 非法")
            require_quote_access(request, quote_id, allow_null=False)
            return api_get_keywords(brand_id=None, client_id=client_id, status=status)
        allowed = get_user_brand_filter(request)
        if allowed is None:
            return api_get_keywords(brand_id=None, client_id=None, status=status)
        if not allowed or allowed == [-1]:
            return {"status": "success", "keywords": [], "count": 0}
        # Never call the legacy unscoped list for an organization member.
        # Aggregate one assigned brand at a time, preserving any source-specific
        # rows while de-duplicating the same source/id pair.
        keywords = []
        seen = set()
        for allowed_brand_id in allowed:
            result = api_get_keywords(
                brand_id=int(allowed_brand_id), client_id=None, status=status
            )
            for row in list((result or {}).get("keywords") or []):
                key = (str(row.get("source") or ""), str(row.get("id") or ""))
                if key in seen:
                    continue
                seen.add(key)
                keywords.append(row)
        return {"status": "success", "keywords": keywords, "count": len(keywords)}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Get keywords error: {e}")
        return {"status": "error", "error": str(e)}


def _require_add_keyword_access(http_request: Request, brand_id=None, quote_id=None, client_id=None):
    """[fast-follow 安全修 2026-05-29] 监测词新增/批量新增的归属校验。

    brand_id 优先 → require_brand_access;否则 quote_id / client_id(实为 quote_id 字符串 · 见 _resolve_id)→ require_quote_access。
    三者全空 → 400(无法定位归属 · fail-closed 不放行)。
    """
    from auth.brand_access import require_brand_access, require_quote_access
    if brand_id is not None:
        require_brand_access(http_request, brand_id)
        return
    if quote_id is not None:
        require_quote_access(http_request, quote_id)
        return
    if client_id is not None:
        try:
            _qid = int(client_id)
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="client_id 非法")
        require_quote_access(http_request, _qid)
        return
    raise HTTPException(status_code=400, detail="缺少 brand_id / quote_id · 无法校验归属")


