# ========== 数据回退API路由 ==========

def _require_monitoring_task_access(request: Request, task_id: int) -> None:
    """[audit P1 2026-06-10 IDOR 修] 监测任务级归属:按 task 反查 brand_id 走 require_brand_access(admin 直通)。
    旧版 rollback/sync-trends 无任何校验 → 任意 monitoring:write 用户按自增 task_id 枚举可破坏性回退他人监测数据。
    brand_id 为 NULL 的历史任务 fail-closed(仅 admin 可操作)。"""
    _user = getattr(request.state, "user", None)
    if _user and _user.get("is_admin"):
        return
    from db.connection import get_connection as _gc
    conn = _gc()
    try:
        cur = conn.cursor()
        cur.execute("SELECT brand_id FROM monitoring_tasks WHERE id = %s", (task_id,))
        row = cur.fetchone()
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        raise HTTPException(status_code=404, detail="监测任务不存在")
    from auth.brand_access import require_brand_access
    require_brand_access(request, row["brand_id"])
    from auth.brand_access import _require_organization_artifact
    _require_organization_artifact(request, "monitoring_task", task_id)


@app.post("/api/monitoring/tasks/{task_id}/cells/{cell_id}/retry")
async def retry_monitoring_task_cell(
    task_id: int,
    cell_id: int,
    payload: MonitoringCellRetryRequest,
    request: Request,
):
    """Retry one failed cell without creating a new charge or changing price."""
    _require_monitoring_task_access(request, task_id)
    from auth.brand_access import _require_organization_artifact
    _require_organization_artifact(request, "monitoring_task", task_id)

    user = getattr(request.state, "user", None) or {}
    raw_user_id = user.get("user_id") or user.get("id")
    try:
        user_id = int(raw_user_id)
        if user_id <= 0:
            raise ValueError
    except (TypeError, ValueError):
        raise HTTPException(status_code=403, detail="当前账号无法执行单格重试")

    from db.connection import get_connection
    conn = get_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT c.brand_id AS cell_brand_id, t.brand_id AS task_brand_id
              FROM public.monitoring_run_cells c
              JOIN public.monitoring_tasks t ON t.id=c.task_id
             WHERE c.id=%s AND c.task_id=%s AND c.brand_id=t.brand_id
            """,
            (cell_id, task_id),
        )
        cell_scope = cur.fetchone()
    finally:
        conn.close()
    if not cell_scope:
        raise HTTPException(status_code=404, detail="监测单格不存在")
    if (
        int(cell_scope["cell_brand_id"]) != int(payload.brand_id)
        or int(cell_scope["task_brand_id"]) != int(payload.brand_id)
    ):
        raise HTTPException(status_code=403, detail="监测单格不属于当前客户")

    from api.monitoring_api import api_retry_monitoring_cell
    from db.monitoring_db import MonitoringCellConflict, MonitoringCellNotFound
    try:
        return await api_retry_monitoring_cell(
            task_id=task_id,
            cell_id=cell_id,
            brand_id=payload.brand_id,
            request_id=str(payload.request_id),
            expected_plan_hash=payload.expected_plan_hash,
            user_id=user_id,
        )
    except MonitoringCellNotFound as exc:
        raise HTTPException(status_code=404, detail=str(exc))
    except MonitoringCellConflict as exc:
        message = str(exc)
        code = "MONITORING_CELL_RETRY_CONFLICT"
        if "different parameters" in message:
            code = "MONITORING_CELL_IDEMPOTENCY_CONFLICT"
        elif "provider outcome" in message:
            code = "MONITORING_PROVIDER_CONFIRMATION_REQUIRED"
        elif "coverage" in message:
            code = "MONITORING_RETRY_NOT_COVERED"
        raise HTTPException(status_code=409, detail={"code": code, "message": message})
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc))


