@app.post("/api/admin/monitoring/tasks/{task_id}/cells/{cell_id}/provider-decision")
def decide_monitoring_provider_review_route(
    task_id: int,
    cell_id: int,
    payload: MonitoringProviderReviewRequest,
    request: Request,
):
    _require_admin_for_global_monitoring(request)
    user = getattr(request.state, "user", None) or {}
    actor_user_id = int(user.get("user_id") or user.get("id") or 0)
    if actor_user_id <= 0:
        raise HTTPException(status_code=403, detail="当前管理员身份无效")
    from db.monitoring_db import (
        MonitoringCellConflict,
        MonitoringCellNotFound,
        decide_monitoring_provider_review,
    )
    try:
        result = decide_monitoring_provider_review(
            task_id=task_id,
            cell_id=cell_id,
            brand_id=payload.brand_id,
            actor_user_id=actor_user_id,
            action=payload.action,
            note=payload.note,
            request_id=str(payload.request_id),
            expected_plan_hash=payload.expected_plan_hash,
        )
        return {"status": "success", "data": result}
    except MonitoringCellNotFound as exc:
        raise HTTPException(status_code=404, detail=str(exc))
    except MonitoringCellConflict as exc:
        raise HTTPException(status_code=409, detail=str(exc))
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc))


