@app.post("/api/monitoring/clear-data")
async def clear_monitoring_data_endpoint(request: Request):
    """清除客户监测数据（密码保护，可恢复）"""
    try:
        body = await request.json()
        password = body.get("password", "")
        brand_id = body.get("brand_id")
        quote_id = body.get("quote_id")
        reason = body.get("reason", "")

        configured_password = os.getenv("MONITORING_CLEAR_DATA_PASSWORD", "").strip()
        if not configured_password:
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "MONITORING_CLEAR_DATA_PASSWORD_NOT_CONFIGURED",
                    "message": "监测数据清除功能尚未配置，请联系平台管理员",
                },
            )
        if not hmac.compare_digest(str(password), configured_password):
            return {"status": "error", "error": "操作密码错误"}
        if not brand_id or not quote_id:
            return {"status": "error", "error": "缺少客户信息"}

        # [audit P1 2026-06-10 IDOR 修] 源码硬编码口令≠鉴权(等于公开)。补真归属校验:
        # 非 admin 必须 brand+quote 双归属(只能清自己客户的数据·可恢复);口令保留作误触二道闸不破坏前端流程
        from auth.brand_access import require_brand_access, require_quote_access
        require_brand_access(request, int(brand_id))
        require_quote_access(request, int(quote_id))

        from db.monitoring_db import clear_monitoring_data
        result = clear_monitoring_data(
            brand_id=brand_id,
            quote_id=quote_id,
            operator=str(getattr(request.state, 'user_id', '')),
            reason=reason
        )
        return {"status": "success" if result.get("success") else "error", **result}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Clear data error: {e}")
        return {"status": "error", "error": str(e)}


@app.post("/api/monitoring/restore-data")
async def restore_monitoring_data_endpoint(request: Request):
    """恢复已清除的监测数据"""
    try:
        body = await request.json()
        archive_key = body.get("archive_key", "")
        if not archive_key:
            return {"status": "error", "error": "缺少归档标识"}

        # [audit P1 2026-06-10 IDOR 修] 旧版无任何校验 → 任意用户持(可枚举到的)archive_key
        # 即可把他人已清除数据恢复/覆盖。按归档反查 brand 做归属校验(admin 直通·无 brand 的归档 fail-closed)
        _user = getattr(request.state, "user", None)
        if not (_user and _user.get("is_admin")):
            from db.connection import get_connection as _gc
            _conn = _gc()
            try:
                _cur = _conn.cursor()
                _cur.execute("SELECT brand_id FROM monitoring_data_archives WHERE archive_key = %s", (archive_key,))
                _row = _cur.fetchone()
            finally:
                try:
                    _conn.close()
                except Exception:
                    pass
            if not _row:
                raise HTTPException(status_code=404, detail="归档不存在")
            from auth.brand_access import require_brand_access
            require_brand_access(request, _row["brand_id"])

        from db.monitoring_db import restore_monitoring_data
        result = restore_monitoring_data(archive_key)
        return {"status": "success" if result.get("success") else "error", **result}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Restore data error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/monitoring/archives")
def list_archives_endpoint(request: Request, brand_id: int = None):
    """列出数据归档记录
    [集成 CF-2 2026-06-10] 取 idor 版:brand_id=None 时下推到 get_user_brand_filter 列本人授权 brand 归档
    (优于 geo-core 的 403·覆盖全租户泄露·archive_key 又喂 restore 越权恢复)"""
    try:
        from auth.brand_access import require_brand_access, get_user_brand_filter
        from db.monitoring_db import list_archives
        if brand_id is not None:
            require_brand_access(request, brand_id, allow_null=False)
            archives = list_archives(brand_id)
        else:
            allowed = get_user_brand_filter(request)
            if allowed is None:
                # admin(filter=None)→ 全量归档
                archives = list_archives(None)
            elif not allowed or allowed == [-1]:
                # 非 admin 且无授权 brand → 不列
                archives = []
            else:
                # [audit #13 返修] 非 admin 有授权 brand → 把授权 brand 列表【下推过滤】,不再
                #   list_archives(None) 读全租户(原残留:有 brand 用户读全平台归档 · #489)。
                #   循环调既有 list_archives(bid)(每次带 WHERE brand_id=%s)等效 SQL 下推 ——
                #   避开红线 db/monitoring_db.py(#13 未授权改红线 · 不新增 list_archives_in)。
                archives = []
                for _abid in allowed:
                    if _abid and _abid != -1:
                        archives.extend(list_archives(_abid))
        return {"status": "success", "archives": archives}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"List archives error: {e}")
        return {"status": "error", "error": str(e)}


