@app.get("/api/monitoring/client/{quote_id}/monitoring-config")
async def get_client_monitoring_config(quote_id: int, request: Request):
    """获取客户的监测配置"""
    # [GEO-R1-CAN-034 安全修] 原 GET 从不校验 quote 归属 → 任意登录用户读他人客户监测配置 + 钱包 paid_points。
    # 与同名 POST sibling(set_client_monitoring_config)一致·守卫放 try 外·403/404 直接传播不被吞。
    from auth.brand_access import require_quote_access
    require_quote_access(request, quote_id, allow_null=False)
    try:
        from db.monitoring_db import get_quote_monitoring_config, get_connection
        config = get_quote_monitoring_config(quote_id)

        conn = get_connection()
        cur = conn.cursor()
        cur.execute("""
            SELECT COUNT(*) as kw_count
            FROM confirmed_keywords
            WHERE quote_id = %s AND (is_core IS NOT FALSE)
        """, (quote_id,))
        row = cur.fetchone()
        conn.close()
        kw_count = row["kw_count"] if row else 0

        cur2_conn = get_connection()
        cur2 = cur2_conn.cursor()
        cur2.execute("""
            SELECT uw.paid_points
            FROM quotes q
            JOIN brands b ON q.brand_id = b.id
            JOIN user_wallets uw ON b.owner_user_id = uw.user_id
            WHERE q.id = %s
        """, (quote_id,))
        wallet_row = cur2.fetchone()
        cur2_conn.close()
        paid_points = wallet_row["paid_points"] if wallet_row else 0

        # [CTO-15.23 2026-05-09 老板报"计算不准"根治] 跟任务 1 daily charge_on_success 模型对齐
        # 老逻辑:cost_per_run = kw × 38(老价)· daily_cost = cost_per_run × runs_per_day(假频率)
        # 真因:任务 1 老板拍板"每日 03:00 daily_monitoring 跑完每个 keyword 即扣 130"
        #       cron 固定 daily 1 次 · 频率选择对实际扣费无效(ScheduleDialog 频率 select 是 obsolete UI)
        # 新逻辑:每天每 keyword 扣 130(= feature_pricing.monitoring_keyword_daily)· 不管 ScheduleDialog interval
        #
        # 单价 SSOT:从 feature_pricing 表读 · 防价格调整时这里漂
        # [WO_240] 这两个 130 都是目录值的**副本**(种子现值也是 130,当前一致)。
        #   副本本身不是缺陷,**副本悄悄漂了没人知道**才是 —— 所以走 fallback 时出声。
        try:
            from db.wallet_db import get_feature_pricing
            from services.fallback_observability import priced as _fb_priced
            _daily_price = int(_fb_priced(
                get_feature_pricing("monitoring_keyword_daily"),
                "cost_points", 130,
                feature="monitoring_keyword_daily",
                where="server.py:get_client_monitoring_config",
            ))
        except Exception as _fb_exc:
            from services.fallback_observability import raised as _fb_raised
            _fb_raised(feature="monitoring_keyword_daily",
                       where="server.py:get_client_monitoring_config",
                       key="cost_points", used=130, exc=_fb_exc)
            _daily_price = 130

        cost_per_run = kw_count * _daily_price       # 一天跑 1 次 · 每 keyword 扣 _daily_price
        daily_cost = cost_per_run                     # daily 模型 · 每日 = 单次(频率不影响)
        monthly_cost = daily_cost * 30
        days_available = paid_points // daily_cost if daily_cost > 0 else 999

        return {
            "status": "success",
            "success": True,
            **config,
            "kw_count": kw_count,
            "cost_per_run": cost_per_run,
            "daily_cost": round(daily_cost, 2),
            "monthly_cost": round(monthly_cost, 2),
            "paid_points": paid_points,
            "days_available": int(days_available),
            # [CTO-15.23 2026-05-09] 提示前端 schedule UI 已固定 daily · 频率 select 应改只读
            "schedule_locked_daily": True,
            "schedule_note": "每天 03:00 自动跑 · 系统打散到 03:00-05:00 之间避免拥堵",
            "unit_price_per_keyword_per_day": _daily_price,
        }
    except Exception as e:
        logger.error(f"Get monitoring config error: {e}")
        return {"status": "error", "success": False, "error": str(e), "message": str(e)}


@app.post("/api/monitoring/client/{quote_id}/monitoring-config")
async def set_client_monitoring_config(quote_id: int, request: Request):
    """设置客户的监测配置（开启/关闭/修改频率）

    [SIB-P1 安全修 2026-05-29] 原有 request 但从不校验 quote 归属 → 任意登录用户改他人客户监测开关/频率/起始时刻(直接影响每日扣费节奏)。
    守卫放在 try 外 · 403/404 直接传播不被吞。
    """
    from auth.brand_access import require_quote_access
    require_quote_access(request, quote_id)
    try:
        body = await request.json()
        enabled = body.get("enabled", False)
        frequency = body.get("frequency")
        interval_hours = body.get("interval_hours")
        start_hour = body.get("start_hour", 8)

        if interval_hours is None:
            frequency = int(frequency or 1)
            interval_hours = {1: 24, 2: 12, 3: 8}.get(frequency)
            if interval_hours is None:
                return {"status": "error", "success": False, "error": "旧频率只支持 1/2/3 次每天"}

        interval_hours = int(interval_hours)
        if interval_hours < 1 or interval_hours > 720:
            return {"status": "error", "success": False, "error": "监测间隔需在 1-720 小时之间"}

        start_hour = int(start_hour)
        if start_hour < 0 or start_hour > 23:
            return {"status": "error", "success": False, "error": "首次执行时间需在 0-23 点之间"}

        legacy_frequency = {8: 3, 12: 2, 24: 1}.get(
            interval_hours,
            max(1, round(24 / interval_hours)) if interval_hours < 24 else 1,
        )

        from db.monitoring_db import update_quote_monitoring_config
        update_quote_monitoring_config(
            quote_id,
            enabled,
            frequency=legacy_frequency,
            start_hour=start_hour,
            interval_hours=interval_hours,
        )

        return {
            "status": "success",
            "success": True,
            "enabled": enabled,
            "frequency": legacy_frequency,
            "interval_hours": interval_hours,
            "start_hour": start_hour,
        }
    except Exception as e:
        logger.error(f"Set monitoring config error: {e}")
        return {"status": "error", "success": False, "error": str(e), "message": str(e)}


@app.get("/api/monitoring/clients")
def get_paid_clients_list(request: Request, limit: int = 100):
    """获取付费客户列表（RBAC 数据隔离）"""
    try:
        result = api_get_clients(limit)
        # RBAC: 非管理员只返回分配品牌关联的客户
        from auth.brand_access import get_user_brand_filter
        allowed = get_user_brand_filter(request)
        if allowed is not None and "clients" in result:
            # 每个 client 有 brand_id 或需要通过 quote 关联 brand
            from db.diagnosis_db import get_connection as diag_conn
            conn = diag_conn()
            cursor = conn.cursor()
            # 获取允许品牌关联的 quote_ids
            placeholders = ",".join(["%s"] * len(allowed))
            cursor.execute(f"SELECT id FROM quotes WHERE brand_id IN ({placeholders})", tuple(allowed))
            allowed_quote_ids = {row["id"] for row in cursor.fetchall()}
            conn.close()
            result["clients"] = [c for c in result["clients"] if c.get("quote_id") in allowed_quote_ids]
            result["count"] = len(result["clients"])
        return result
    except Exception as e:
        logger.error(f"Get clients error: {e}")
        return {"status": "error", "error": str(e)}


@app.put("/api/monitoring/tier")
def update_client_tier(brand_id: int, tier: str, request: Request):
    """更新客户套餐等级
    [CTO-15.23 2026-05-05] status 范围扩到 ('confirmed', 'paid')
    原写死 'confirmed' 排除了已付款客户 · 老板演示时"重庆璧山万家"服务期已开始(paid)→ 改不动套餐
    跟 /api/monitoring/trend 的 quote_ids 解析逻辑对齐

    [SIB-P1/F3 安全修 2026-05-29] 原无 request + 无 RBAC → 任意登录用户按 brand_id 改他人套餐等级。
    守卫放 UPDATE 前 · 403 直接传播不被吞。
    """
    # [WO §8 2026-08-08] 原白名单只认 legacy 的 premium —— 而档位码 SSOT
    #   (api/selection_api.TIER_CONFIG)的规范码是 flagship,报价链写库写的就是它。
    #   于是这个端点**拒绝自己系统里合法的档位码**。两个都放行:flagship 规范、premium legacy
    #   (前端 Monitoring/index.tsx 的下拉框现在仍送 premium,不能把它挡掉)。
    if tier not in ("entry", "standard", "flagship", "premium"):
        return {"status": "error", "error": "无效套餐: entry/standard/flagship"}
    from auth.brand_access import require_brand_access
    require_brand_access(request, brand_id)
    try:
        from db.diagnosis_db import get_connection as get_diag_conn
        conn = get_diag_conn()
        cur = conn.cursor()
        cur.execute(
            "UPDATE quotes SET tier = %s WHERE brand_id = %s AND status IN ('confirmed', 'paid')",
            (tier, brand_id)
        )
        affected = cur.rowcount
        conn.commit()
        conn.close()
        if affected > 0:
            from services.monitoring_tier_target import tier_target as _tier_target_ssot
            return {"status": "success", "message": f"已更新为{_tier_target_ssot(tier)['tier_name']}"}
        return {"status": "error", "error": "未找到该客户的已确认/已付款报价"}
    except Exception as e:
        logger.error(f"Update tier error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/monitoring/clients/{quote_id}/keywords")
def get_client_keywords_list(quote_id: int, request: Request):
    """获取客户的监测词条（RBAC 数据隔离）"""
    try:
        # Monitoring scope is shared customer input: authorize the assigned
        # brand, not the employee who happened to create the quote artifact.
        from auth.brand_access import require_brand_access
        from db.diagnosis_db import get_connection as diag_conn
        conn = diag_conn()
        try:
            cursor = conn.cursor()
            cursor.execute("SELECT brand_id FROM quotes WHERE id = %s", (quote_id,))
            row = cursor.fetchone()
        finally:
            conn.close()
        if not row:
            raise HTTPException(status_code=404, detail="客户报价不存在")
        require_brand_access(request, row.get("brand_id"), allow_null=False)
        return api_get_client_keywords_merged(quote_id)
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Get client keywords error: {e}")
        return {"status": "error", "error": str(e)}


@app.post("/api/monitoring/clients/{quote_id}/service-config")
async def update_service_config(quote_id: int, request: Request):
    """更新客户的**履约达标天数配额**(`quotes.service_days`)。

    [SIB-P1 安全修 2026-05-29] docstring 标"管理员用"但原无任何 admin/owner 闸 → 任意登录用户改他人服务天数/起始日(篡改达标判定窗口)。
    require_quote_access = owner 或 admin · 守卫放在 try 外。

    🔴 [服务期 SSOT 2026-08-06 §1.1/§1.2] 本端点**不再写 service_start_date**。
       这里原来是全站最隐蔽的一个分裂源:它能把合同起始日往前挪,却**从不重算
       service_end_date** —— 起点变了、终点没变,两钟当场错开。晨光富士 #286 就是这个形状
       (start=2026-05-08 / months=1,end 却是 2026-07-23,`start + 1 个月` 怎么算都不是它)。
       服务期(start, end)只由付款激活/服务期调整端点成对写;本端点只管履约配额。
       传了 service_start_date → 400 + 指路,不静默忽略也不静默改。
    """
    from auth.brand_access import require_quote_access
    require_quote_access(request, quote_id)
    try:
        body = await request.json()
        service_days = body.get("service_days")       # int · 累计达标天数配额,不是日历天

        if "service_start_date" in body and body.get("service_start_date") is not None:
            raise HTTPException(
                400,
                detail={
                    "code": "SERVICE_PERIOD_NOT_EDITABLE_HERE",
                    "message": "服务起止日期要在报价单里改 · 这里只调「累计达标天数」",
                    "actions": [
                        {"label": "去报价单改服务期", "type": "open_service_period", "quote_id": quote_id},
                    ],
                },
            )

        if service_days is None or not isinstance(service_days, int) or isinstance(service_days, bool) or service_days < 1:
            return {"status": "error", "error": "累计达标天数必须为正整数"}

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute("UPDATE quotes SET service_days = %s WHERE id = %s", (service_days, quote_id))
            conn.commit()

            # 读回最新值(service_start_date 只读回显,本端点不再写它)
            cur.execute("SELECT service_days, service_start_date, service_end_date FROM quotes WHERE id = %s", (quote_id,))
            row = cur.fetchone()
            conn.close()

            # 审计:这条历史上**完全没有 audit_log**,所以 #286 那种改动今天已经查无对证。
            try:
                from db.auth_db import create_audit_log
                _u_sc = getattr(request.state, "user", None) or {}
                create_audit_log(
                    user_id=_u_sc.get("user_id"),
                    username=_u_sc.get("username"),
                    action="quote_compliance_target_days",
                    module="quotes",
                    entity_type="quote",
                    entity_id=quote_id,
                    summary=f"调整累计达标天数 · {service_days} 天",
                    after={"service_days": service_days},
                    ip_address=getattr(request.client, "host", None) if request.client else None,
                )
            except Exception as _sc_audit_err:
                logger.warning(f"[audit] quote_compliance_target_days fail quote={quote_id}: {_sc_audit_err}")

            return {
                "status": "success",
                "service_days": row["service_days"] if row else service_days,
                "service_start_date": str(row["service_start_date"]) if row and row["service_start_date"] else None,
                "service_end_date": str(row["service_end_date"]) if row and row["service_end_date"] else None,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Update service config error: {e}")
        return {"status": "error", "error": str(e)}


@app.patch("/api/monitoring/clients/{quote_id}/service-period")
async def admin_update_service_period(quote_id: int, request: Request):
    """[客户反馈⑥ 2026-08-09] **admin-only** 直接更正一张报价的服务期起止日。

    为什么要有这个口:`quotes.service_end_date` 全站唯一写入点是**付款激活流程**
    (`selection_api` mark_paid)。于是线下续费、当初日期录错这两件纯行政更正,
    今天只能靠"把用户拖着走一遍完整下单流程"来实现 —— 那会伪造出一个不存在的
    支付会话,资金侧留下假凭证。本端点只改这两列,**不碰任何金额/订单/支付状态**。

    🔴 RBAC:admin-only,且 UPDATE 的 WHERE 逐字用被授权的那个 `quote_id`
      (核验 target = 写 target,不隔着一次查询靠"上面查过了"生效)。
    🔴 资金邻接:`quotes` 是资金表。本端点白名单只有 service_start_date /
      service_end_date 两列,任何其它字段传进来一律忽略(不做部分写入,不做 upsert)。
    🔴 二次确认:必须显式 `confirm=true`,防误点。
    🔴 (start, end) **成对写在同一条 UPDATE 里** —— 服务期 SSOT §1.2:只写一个
      就是新的分裂点(晨光富士 #286 那种 start 挪了 end 没动的形状)。
    🔴 审计留痕:改前值 + 改后值 + 操作人全进 audit_log;写失败不吞。

    入参二选一:
      - `service_start_date` + `service_months` → 走 `resolve_activation_period`
        (全站唯一 months→end 换算点);
      - `service_start_date` + `service_end_date` → 显式一对(纯录入更正)。
    """
    _user = getattr(request.state, "user", None)
    if not (_user and _user.get("is_admin")):
        raise HTTPException(status_code=403, detail="仅管理员可更正服务期")

    from services.service_period import (
        ServicePeriodError, coerce_date, resolve_activation_period,
    )

    body = await request.json()
    if body.get("confirm") is not True:
        raise HTTPException(
            400,
            detail={
                "code": "CONFIRM_REQUIRED",
                "message": "更正服务期会立刻改变这个客户的到期日与续费提醒 · 请确认后再提交",
            },
        )

    start = coerce_date(body.get("service_start_date"))
    if start is None:
        raise HTTPException(400, detail={"code": "SERVICE_START_REQUIRED",
                                         "message": "要填服务期起始日(YYYY-MM-DD)"})
    if body.get("service_months") not in (None, ""):
        try:
            start, end = resolve_activation_period(
                start_date=start, months=body.get("service_months"))
        except ServicePeriodError as _spe:
            raise HTTPException(400, detail={"code": "SERVICE_MONTHS_INVALID",
                                             "message": _spe.user_message,
                                             "actions": (_spe.hint or {}).get("actions", [])})
    else:
        end = coerce_date(body.get("service_end_date"))
        if end is None:
            raise HTTPException(400, detail={"code": "SERVICE_END_REQUIRED",
                                             "message": "要么填服务月数,要么填服务期结束日"})
    if end < start:
        raise HTTPException(400, detail={"code": "SERVICE_PERIOD_INVERTED",
                                         "message": f"结束日 {end} 早于起始日 {start}"})

    # 🔴 [Review 2026-08-09 P1-2] 服务期 UPDATE 与审计 INSERT **必须同一事务**。
    #   改前是"先 commit 业务、再单独写审计,审计异常只记日志仍返 success" ——
    #   那会造出"资金邻接字段已改、却查无对证"的不可追责态,
    #   而且和本端点自己写的"审计留痕:写失败不吞"直接矛盾。
    #   现在两条写在同一个 cursor 上,任一失败整体回滚、接口报 500,绝不返成功。
    from db.diagnosis_db import get_connection
    from db.auth_db import write_audit_log_with_cursor
    conn = get_connection()
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT service_start_date, service_end_date FROM quotes WHERE id = %s",
            (quote_id,),
        )
        before = cur.fetchone()
        if not before:
            conn.rollback()
            raise HTTPException(404, detail="报价单不存在")
        cur.execute(
            """
            UPDATE quotes
               SET service_start_date = %s, service_end_date = %s
             WHERE id = %s
            RETURNING service_start_date, service_end_date
            """,
            (start, end, quote_id),
        )
        after = cur.fetchone()
        write_audit_log_with_cursor(
            cur,
            user_id=_user.get("user_id"),
            username=_user.get("username"),
            action="quote_service_period_admin_fix",
            module="quotes",
            entity_type="quote",
            entity_id=quote_id,
            summary=f"管理员更正服务期 · {start} ~ {end} · 理由:{str(body.get('reason') or '')[:120]}",
            before={"service_start_date": str(before["service_start_date"]) if before["service_start_date"] else None,
                    "service_end_date": str(before["service_end_date"]) if before["service_end_date"] else None},
            after={"service_start_date": str(start), "service_end_date": str(end)},
            ip_address=getattr(request.client, "host", None) if request.client else None,
        )
        conn.commit()
    except HTTPException:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    except Exception as _sp_err:
        try:
            conn.rollback()
        except Exception:
            pass
        logger.error(f"[ServicePeriod] 更正失败已整体回滚 quote={quote_id}: {_sp_err}")
        raise HTTPException(500, detail={
            "code": "SERVICE_PERIOD_UPDATE_FAILED",
            "message": "服务期没有改成 · 系统已把这次改动整体撤回,请重试或联系技术",
        })
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return {
        "status": "success",
        "quote_id": quote_id,
        "service_start_date": str(after["service_start_date"]) if after and after["service_start_date"] else None,
        "service_end_date": str(after["service_end_date"]) if after and after["service_end_date"] else None,
    }


