# ========== Phase 2.0: 趋势统计API ==========

@app.get("/api/monitoring/trend")
def get_monitoring_trend(request: Request, brand_id: int = None, client_id: str = None, days: int = 7):
    """[2026-06-30 kou-jing tong-yi] trend = canonical (realtime + rolling cumulative) per-day.
    today = get_unified_appearance.client_avg (== top avg); history = compliance_log.effective by keyword-set daily avg.
    (2026-06-10 IDOR/RBAC guard preserved verbatim)
    """
    try:
        from auth.brand_access import require_brand_access, require_quote_access
        _user = getattr(request.state, "user", None)
        _is_admin = bool(_user and _user.get("is_admin"))
        if not _is_admin:
            if brand_id is None and client_id is None:
                raise HTTPException(status_code=403, detail="非管理员必须指定 brand_id 或 client_id")
            if brand_id is not None:
                require_brand_access(request, brand_id)
            if client_id is not None:
                try:
                    _qid = int(client_id)
                except (TypeError, ValueError):
                    raise HTTPException(status_code=400, detail="client_id 非法")
                require_quote_access(request, _qid)

        from db.monitoring_db import get_connection as _gc, get_unified_appearance
        from datetime import datetime, timedelta
        safe_days = max(1, min(int(days or 7), 90))

        quote_ids = []
        if client_id:
            try:
                quote_ids = [int(client_id)]
            except Exception:
                quote_ids = []
        elif brand_id:
            conn0 = _gc()
            try:
                c0 = conn0.cursor()
                c0.execute("SELECT id FROM quotes WHERE brand_id=%s AND status IN ('confirmed','paid')", (brand_id,))
                quote_ids = [r["id"] for r in c0.fetchall()]
            finally:
                conn0.close()

        today = datetime.now().date()
        if not quote_ids:
            return {"status": "success", "trend": [
                {"date": (today - timedelta(days=i)).strftime("%m/%d"), "rate": None}
                for i in range(safe_days - 1, -1, -1)
            ]}

        try:
            today_rate = get_unified_appearance(quote_ids[0])["client_avg"]
        except Exception as _e:
            logger.warning(f"[trend] unified today failed: {_e}")
            today_rate = None

        rate_by_date = {}
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT check_date, AVG(effective_rate) AS avg_rate
                FROM keyword_compliance_log
                WHERE (keyword_id, keyword_source) IN (
                        SELECT DISTINCT keyword_id, keyword_source
                        FROM keyword_compliance_log WHERE quote_id = ANY(%s))
                  AND check_date >= CURRENT_DATE - %s::int
                  AND check_date < CURRENT_DATE
                  AND effective_rate IS NOT NULL
                GROUP BY check_date
            """, (quote_ids, safe_days))
            for r in cur.fetchall():
                if r["avg_rate"] is not None:
                    rate_by_date[r["check_date"].strftime("%Y-%m-%d")] = round(float(r["avg_rate"]), 1)
        finally:
            conn.close()

        trend_data = []
        for i in range(safe_days - 1, -1, -1):
            d = today - timedelta(days=i)
            rate = today_rate if i == 0 else rate_by_date.get(d.strftime("%Y-%m-%d"))
            trend_data.append({"date": d.strftime("%m/%d"), "rate": rate})
        return {"status": "success", "trend": trend_data}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取监测趋势失败: {e}")
        return {"status": "error", "trend": [], "message": str(e)}


