from db.monitoring_db import get_all_reports, get_report_by_id, update_report_status, update_report_content

@app.get("/api/reports/all")
def get_all_reports_endpoint(request: Request, status: str = None, report_type: str = None, limit: int = 50, brand_id: int = None):
    """获取所有报告（管理后台）
    [self-review r4 2026-05-23] P0-2 闭环:非 admin 必须按 brand_filter 过滤
    老板复审:原 endpoint 无 Request · 任何 JWT 用户可读全局报告 IDOR
    """
    try:
        from auth.brand_access import get_user_brand_filter, require_brand_access
        user = getattr(request.state, "user", None)
        if not user:
            raise HTTPException(status_code=401, detail="未登录")
        is_admin = bool(user.get("is_admin"))
        # 非 admin:必须传 brand_id 且属于自己的品牌
        if not is_admin:
            allowed = get_user_brand_filter(request)
            if brand_id is None:
                # 无 brand_id:聚合自己所有品牌(allowed 通常很小)
                allowed_set = set(allowed or [])
                if not allowed_set:
                    return {"status": "success", "reports": []}
                # 逐品牌取报告(allowed 列表通常 ≤ 20)
                all_reports = []
                for bid in allowed_set:
                    all_reports.extend(get_all_reports(status, report_type, limit, brand_id=bid) or [])
                # 简单截断到 limit
                from auth.brand_access import filter_organization_artifact_rows
                all_reports = filter_organization_artifact_rows(
                    request, "monitoring_report", all_reports
                )
                return {"status": "success", "reports": all_reports[:limit]}
            require_brand_access(request, brand_id)
        reports = get_all_reports(status, report_type, limit, brand_id=brand_id)
        from auth.brand_access import filter_organization_artifact_rows
        reports = filter_organization_artifact_rows(
            request, "monitoring_report", list(reports or [])
        )
        return {"status": "success", "reports": reports}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Get all reports error: {e}")
        return {"status": "error", "error": str(e)}


