@app.post("/api/reports/{report_id}/ai-write")
async def ai_write_report(report_id: int, request: Request):
    """用LLM自动生成周报/月报内容 · 永远走 v1 LLM 分支

    [CTO-15.23 2026-05-06] v2 分支已禁用
    老板原话: "之前根据现有数据来进行编写的"——v2(8 模块字符串模板装配)
    出来的就是诊断报告 markdown 直接复制 · 没真用 LLM · 不是老板期待的"AI 写报告"
    services/report_writer_v2 module 保留给诊断报告本体用 · 不在此 endpoint 触发
    """
    import asyncio
    try:
        # [self-review r4 2026-05-23] P0-2 闭环:加 owner 校验 · 防 IDOR LLM 滥用
        from auth.brand_access import require_report_access
        require_report_access(request, report_id)
        report = get_report_by_id(report_id)
        if not report:
            return {"status": "error", "error": "报告不存在"}

        summary = report.get("summary_data", {})
        if isinstance(summary, str):
            import json as _json
            summary = _json.loads(summary)

        # 获取品牌信息
        brand_info = {}
        brand_id = report.get("brand_id")

        # v1 分支:LLM 真写报告(下方逻辑保留 4-25 老 prompt 链路)
        if brand_id:
            from db.diagnosis_db import get_connection as get_diag_conn
            conn = get_diag_conn()
            cur = conn.cursor()
            cur.execute("""
                SELECT b.name, b.industry, q.tier, q.total_keywords
                FROM brands b
                LEFT JOIN quotes q ON q.brand_id = b.id AND q.status = 'confirmed'
                WHERE b.id = %s LIMIT 1
            """, (brand_id,))
            row = cur.fetchone()
            if row:
                brand_info = dict(row)
            conn.close()

        # [WO §8 2026-08-08] 这里原来是 api/monitoring_api.TIER_TARGET 的**第二份拷贝**,
        #   同样缺 flagship 键。改走单点(别名收敛 + 数值取自 SSOT),不再各留一份。
        from services.monitoring_tier_target import tier_target as _tier_target_ssot

        # 构建提示词
        report_type = report.get("report_type", "weekly")
        type_label = {"daily": "日报", "weekly": "周报", "monthly": "月报", "quarterly": "季报", "yearly": "年报"}.get(report_type, "周报")
        period = f"{report.get('period_start', '')} ~ {report.get('period_end', '')}"
        rate = summary.get("detection_rate", 0)
        rate_change = summary.get("rate_change", 0)
        total_kw = summary.get("total_keywords", 0)
        total_tests = summary.get("total_tests", 0)
        task_count = summary.get("task_count", 0)

        brand_name = brand_info.get("name", "客户")
        industry = brand_info.get("industry", "")
        # [CTO-15.23 2026-05-06 P1 hallucinate 修复]
        # 老板 E2E 测试:报告 LLM 写"标准版 ≥65%" vs 前端卡片"入门版 ≥50%"撕裂
        # 根因:brand_info["tier"] 为 None/空 时 fallback "standard" 无脑升档 · 误导客户
        # 修法:fallback 改 entry(经济选择 · 防 LLM 自动升档误导)+ warning log 找 root case
        tier_code = brand_info.get("tier") or "entry"
        if not brand_info.get("tier"):
            logger.warning(
                f"[ai_write_report] brand_id={brand_id} quote.tier 为空 · "
                f"fallback 'entry' 防自动升档 · 请检查 quotes.tier 写入流程"
            )
        # [WO §8 2026-08-08] 🔴 这一处的兜底档是 **entry 而不是 standard** ——
        #   CTO-15.23 2026-05-06 P1 专门这么改的("fallback standard 会无脑升档、误导客户")。
        #   所以不能直接把 tier_code 丢进单点(它对认不出的码回落 standard),
        #   必须先问"认不认得出",认不出仍旧回落 entry。**这条语义一个字不改。**
        #   顺带这一处原来对 tier='flagship' 会回落到 entry 50% —— 比 65% 还离谱,一并修好。
        from services.monitoring_tier_target import is_known_tier_code as _tier_known
        tier_info = _tier_target_ssot(tier_code if _tier_known(tier_code) else "entry")
        tier_name = tier_info["tier_name"]
        target_rate = tier_info["target_rate"]
        contracted_kw = brand_info.get("total_keywords", total_kw)

        # 分类关键词：达标 vs 未达标
        achieved = []
        not_achieved = []
        for kw in summary.get("keyword_stats", []):
            item = f"{kw['keyword']}: {kw['avg_rate']}%（{kw['tests_count']}次测试）"
            if kw["avg_rate"] >= target_rate:
                achieved.append(item)
            else:
                not_achieved.append(item)

        achieved_text = "\n".join(f"  ✅ {a}" for a in achieved) if achieved else "  （暂无达标词条）"
        not_achieved_text = "\n".join(f"  ⏳ {a}" for a in not_achieved) if not_achieved else "  （全部达标！）"

        # P0.2 (CTO-15.7 2026-04-24): 抽豆包 + dashscope 2 引擎 evidence · 注入 prompt
        # 事故:12,233 条 AI 回答 citations 在 monitoring_results · 但报告 0 引用(185MB 数据用 0.001%)
        # Codex 修订:Kimi/DeepSeek 物理 0 citations · 仅抽 2 引擎 · Evidence A/B/C 分级
        evidence_anchors_text = ""
        try:
            from services.report_evidence import extract_report_evidence, format_evidence_for_prompt
            period_start = report.get("period_start")
            period_end = report.get("period_end")
            evidences = extract_report_evidence(
                brand_id=brand_id,
                period_start=str(period_start) if period_start else None,
                period_end=str(period_end) if period_end else None,
                brand_name=brand_name,
                max_items=5,
            )
            evidence_anchors_text = "\n" + format_evidence_for_prompt(evidences) + "\n"
            logger.info(f"[ai_write_report] P0.2 evidence 注入: brand_id={brand_id} 抽到 {len(evidences)} 条")
        except Exception as _e:
            logger.warning(f"[ai_write_report] P0.2 evidence 抽取失败(降级无 evidence 段): {_e}")
            evidence_anchors_text = ""

        prompt = f"""你是一家AI搜索优化公司（OmniRank AI / 全域排名引擎）的报告撰写员。请根据以下监测数据，为客户撰写一份专业的{type_label}。

## 公司背景
OmniRank（全域排名引擎）是一家专注于AI搜索可见度优化的服务商。我们通过在权威媒体和行业平台发布高质量内容，让客户品牌在主流AI搜索引擎中被优先推荐。我们监测的四大主流AI平台为：**豆包、DeepSeek、Kimi、通义千问**。

## 客户信息
- 客户名称: {brand_name}
- 所属行业: {industry}
- 签约套餐: {tier_name}（承诺目标检出率 ≥{target_rate}%）
- 合同词条数: {contracted_kw} 个
- 监测平台: 豆包、DeepSeek、Kimi、通义千问（共4个平台）

## 本期监测数据（{period}）
- 整体检出率: {rate}%（目标: {target_rate}%，{"已达标 ✅" if rate >= target_rate else f"差距 {target_rate - rate:.1f}% ⏳"}）
- 环比变化: {'+' if rate_change > 0 else ''}{rate_change}%
- 监测关键词数: {total_kw} 个
- 总测试次数: {total_tests}（在4个AI平台上跨 {task_count} 次监测任务）

## 达标情况（目标: ≥{target_rate}%）
已达标关键词（{len(achieved)}/{total_kw}）:
{achieved_text}

优化中关键词（{len(not_achieved)}/{total_kw}）:
{not_achieved_text}
{evidence_anchors_text}
## 写作要求

**写作原则（最重要）**：忠实于本期监测数据。禁用"有望""稳步提升""持续沉淀""迭代优化""持续迭代"等无数据支撑的宽泛运营话术。数据不足以下趋势结论时，明确写"本期数据不足，不做趋势结论"，不粉饰、不编造。

1. **开头总结**：概述本周工作成果和整体达成率，明确提及套餐承诺目标（{target_rate}%），说明在豆包、DeepSeek、Kimi、通义千问四个主流AI平台上的监测情况
2. **达成分析**：逐一说明达标词条的表现，基于真实监测数据点评，指出哪些平台表现最好
3. **待优化分析**（如有未达标词条）：差距分析、原因推测（如某些AI平台覆盖不足、竞争激烈、内容需增强等）
4. **优化措施**（如有未达标词条）：针对性的下一步计划（如追加媒体投放、调整内容策略、优化特定平台表现等）
5. **如果全部达标**：不需要分析不足，重点表达成绩，提及后续巩固策略（持续投放、扩展新词条、深耕更多平台）
6. **数据驱动的结论**：所有成效判断必须来自本期监测数据或历史环比数据。禁止编造无数据支撑的趋势性承诺（如"检出率会稳步提升"）。数据不足时，明确说"本期数据不足"而非泛泛话术。
7. **下期展望**：基于本期数据短板，简述下一步可验证的具体动作（避免"持续优化""持续迭代"等空泛措辞）

## 格式要求
- 使用Markdown格式，用 **加粗** 和分段让结构清晰
- 语气专业但亲切，像一个负责任的运营经理在向客户做工作汇报
- 不要使用"我们公司"，用"我们团队"或"OmniRank团队"
- 提及AI平台时，必须使用正确名称：豆包、DeepSeek、Kimi、通义千问，不要出现ChatGPT、文心一言等非我们监测范围的平台
- 控制在600-1000字
- 不要生成一级标题（# 标题），直接从正文开始
- 适当使用数据支撑观点（如"检出率从X%提升至Y%"）"""

        from tools.multi_llm_caller import call_llm_with_fallback
        content = await call_llm_with_fallback(prompt, verbose=True)

        if content and "[所有API均失败]" not in content:
            # P0.1b (CTO-15.7 2026-04-24) banned words lint 兜底(非 block · 仅 log WARN)
            # 与 P0.1a prompt 指令配对:LLM 仍复读运营话术时打标,为后续 retry/人工审核提供钩子
            try:
                from utils.banned_words import lint_report_text, format_lint_warning
                lint = lint_report_text(content)
                if lint.has_any:
                    logger.warning(
                        f"[ai_write_report] P0.1b lint 命中(report_id={report_id}): "
                        f"{format_lint_warning(lint)}"
                    )
                else:
                    logger.info(f"[ai_write_report] P0.1b lint 通过(report_id={report_id})")
            except Exception as _lint_err:
                logger.debug(f"[ai_write_report] P0.1b lint 异常(忽略): {_lint_err}")

            # 保存到报告
            update_report_content(report_id, content)

            # M1a T4 埋点 · stage=report event=complete
            try:
                _report = get_report_by_id(report_id)
                _bid = _report.get("brand_id") if _report else None
                if _bid:
                    from db.pipeline_stage_log_db import log_stage_event
                    log_stage_event(
                        brand_id=_bid,
                        stage_name="report",
                        event="complete",
                        meta={
                            "report_id": report_id,
                            "content_length": len(content or ""),
                            "source": "ai_write_report",
                        },
                    )
            except Exception as _le:
                logger.warning(f"[ai_write_report] stage_log 埋点失败(非 block): {_le}")

            return {"status": "success", "content": content}
        else:
            return {"status": "error", "error": "AI生成失败，所有模型均不可用"}
    except Exception as e:
        logger.error(f"AI write report error: {e}")
        import traceback
        traceback.print_exc()
        return {"status": "error", "error": str(e)}


@app.post("/api/reports/{report_id}/send")
def send_report_endpoint(report_id: int, request: Request):
    """发送报告（标记为已发送，生成下载链接）"""
    try:
        from auth.brand_access import require_report_access
        require_report_access(request, report_id)
        report = get_report_by_id(report_id)
        if not report:
            return {"status": "error", "error": "报告不存在"}

        if report.get("status") == "draft":
            return {"status": "error", "error": "请先审核报告"}

        # 更新状态为已发送
        success = update_report_status(report_id, "sent")
        if not success:
            return {"status": "error", "error": "更新状态失败"}

        # 生成下载链接（带token）
        import hashlib
        import time
        token = hashlib.md5(f"{report_id}-{time.time()}".encode()).hexdigest()[:16]
        download_url = f"/api/reports/{report_id}/download?token={token}"

        return {
            "status": "success",
            "message": "报告已标记为已发送",
            "download_url": download_url
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Send report error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/reports/{report_id}/download")
def download_report_endpoint(report_id: int, request: Request, token: str = None):
    """下载报告内容（生成Markdown文件）"""
    from fastapi.responses import PlainTextResponse
    try:
        from auth.brand_access import require_report_access
        require_report_access(request, report_id)
        report = get_report_by_id(report_id)
        if not report:
            return {"status": "error", "error": "报告不存在"}

        content = report.get("content") or ""
        if not content:
            # 如果没有自定义内容，从summary生成
            summary = report.get("summary_data", {})
            content = f"""# 监测报告

- 报告类型: {report.get('report_type', '-')}
- 周期: {report.get('period_start', '-')} ~ {report.get('period_end', '-')}
- 检出率: {summary.get('detection_rate', 0)}%
- 生成时间: {report.get('created_at', '-')}
"""

        return PlainTextResponse(
            content=content,
            media_type="text/markdown",
            headers={
                "Content-Disposition": f"attachment; filename=report_{report_id}.md"
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Download report error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/reports/{report_id}/export/pdf")
def export_report_pdf(report_id: int, request: Request):
    """导出报告为PDF（HTML转PDF）

    2026-07-22 板块B：所有版本共用 services.monitoring_report_html
    -> safe Markdown SSOT；页面、打印与 PDF 仅容器样式不同，
    Markdown 语义和安全策略一致（v2 不再用 markdown 库裸渲染(无 bleach)，
    v1 不再 crude replace 换行）。
    """
    from fastapi.responses import Response
    try:
        from auth.brand_access import require_report_access
        require_report_access(request, report_id)
        report = get_report_by_id(report_id)
        if not report:
            return {"status": "error", "error": "报告不存在"}

        # [2026-07-22 板块B] v1/v2 统一走 services.monitoring_report_html
        # （safe Markdown SSOT：markdown-it-py + bleach 显式白名单；页面/打印/PDF 仅容器样式不同）。
        # 旧实现已删：v2 用 markdown 库渲染(无 bleach) + v1 crude replace('\n','<br>')。
        from services.monitoring_report_html import render_monitoring_report_html
        html_content = render_monitoring_report_html(report)
        # 用 Playwright 将 HTML 渲染为真 PDF
        try:
            from playwright.sync_api import sync_playwright
            with sync_playwright() as p:
                import os
                browser = p.chromium.launch(
                    headless=True,
                    executable_path=os.environ.get("CHROMIUM_PATH"),
                )
                page = browser.new_page()
                # [GEO-R1-CAN-145 SSRF 加固] 报告正文是 owner 自填(PUT /content·markdown 保留原始 HTML)·
                #   set_content + networkidle 会拉取 <img>/<link>/<iframe> 子资源 → 可指向 169.254.169.254
                #   /loopback/内网做 SSRF。拦截所有非 data:/about: 子资源请求·令渲染无对外网络出口。
                def _block_external_subresource(route):
                    try:
                        _u = (route.request.url or "")
                        if _u.startswith("data:") or _u.startswith("about:"):
                            route.continue_()
                        else:
                            route.abort()
                    except Exception:
                        try:
                            route.abort()
                        except Exception:
                            pass
                page.route("**/*", _block_external_subresource)
                page.set_content(html_content, wait_until="networkidle")
                # [2026-07-22 板块B] Chromium print 不排版闭合 <details> 的内容；
                # 隔离导出文档展开证据折叠，不影响网页报告。
                page.locator(".safe-markdown details").evaluate_all(
                    "nodes => nodes.forEach(node => { node.open = true; })"
                )
                pdf_bytes = page.pdf(format="A4", print_background=True, margin={"top": "20mm", "bottom": "20mm", "left": "15mm", "right": "15mm"})
                browser.close()
            return Response(
                content=pdf_bytes,
                media_type="application/pdf",
                headers={
                    "Content-Disposition": f"attachment; filename=report_{report_id}.pdf"
                }
            )
        except Exception as pdf_err:
            logger.warning(f"Playwright PDF 生成失败，降级返回 HTML: {pdf_err}")
            return Response(
                content=html_content,
                media_type="text/html",
                headers={
                    "Content-Disposition": f"attachment; filename=report_{report_id}.html"
                }
            )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Export PDF error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/reports/{report_id}/export/excel")
def export_report_excel(report_id: int, request: Request):
    """导出报告为Excel (CSV格式)"""
    from fastapi.responses import Response
    try:
        from auth.brand_access import require_report_access
        require_report_access(request, report_id)
        report = get_report_by_id(report_id)
        if not report:
            return {"status": "error", "error": "报告不存在"}

        summary = report.get("summary_data", {})

        # 生成CSV内容
        csv_lines = [
            "字段,值",
            f"报告ID,{report.get('id', '')}",
            f"报告类型,{report.get('report_type', '')}",
            f"客户ID,{report.get('client_id', '')}",
            f"周期开始,{report.get('period_start', '')}",
            f"周期结束,{report.get('period_end', '')}",
            f"检出率,{summary.get('detection_rate', 0)}%",
            f"监测次数,{summary.get('task_count', 0)}",
            f"总测试数,{summary.get('total_tests', 0)}",
            f"检出次数,{summary.get('total_detected', 0)}",
            f"状态,{report.get('status', '')}",
            f"生成时间,{report.get('created_at', '')}",
        ]

        csv_content = "\n".join(csv_lines)

        # 添加BOM用于Excel正确显示中文
        bom = '\ufeff'

        return Response(
            content=(bom + csv_content).encode('utf-8'),
            media_type="text/csv",
            headers={
                "Content-Disposition": f"attachment; filename=report_{report_id}.csv"
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Export Excel error: {e}")
        return {"status": "error", "error": str(e)}


