@app.get("/api/publications/{quote_id}")
def get_publications_list(quote_id: int, request: Request, limit: int = 200):
    """获取投放记录：代发订单（实时查 mhz_synced_orders）+ 手动录入（media_publications），合并返回

    [audit P1 2026-06-10 IDOR 修] 原无 request + 无归属校验 → 任意用户按自增 quote_id 枚举
    跨租户读他人投放记录(含媒体名/URL/价格/退款)。加 require_quote_access(admin/owner/portal 同 quote 放行)。
    """
    try:
        from auth.brand_access import require_quote_access
        # [audit #2 返修 E4] 跨租户读投放记录(媒体名/URL/价格/退款)→ NULL-brand fail-closed(不放行)
        require_quote_access(request, quote_id, allow_null=False)
        from db.connection import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()

            # 1. 通过 quote_id 找 brand_id
            cur.execute("SELECT brand_id FROM quotes WHERE id = %s", (quote_id,))
            row = cur.fetchone()
            brand_id = row["brand_id"] if row else None

            records = []

            # 2. 代发订单（状态 0=待接单, 1=发布中, 2=已完成，排除 -1 拒稿 / -2 撤回）
            # [CTO-15.23 2026-05-25] 加 fallback brand 路径
            # · 历史 55% mhz_synced_orders.brand_id NULL(items 回填先后顺序 BUG)
            # · backfill_orphan_fields 救援函数存在但不一定跑过 · 查询层兜底
            # · 通过 mhz_publish_order_items.mhz_order_id = o.order_sn 反查 items.brand_id
            # · 这样 brand_id NULL 的同步记录也能命中, 无需等 Deploy-CTO 跑 backfill
            if brand_id:
                # [WP7 cutover 2026-08-17] 🔴 这个端点的路径参数是 **quote_id**,
                # 但它原来按 `brand_id` 拉代发订单 —— 同品牌两张报价(续费/加词是常态)
                # 会互相看到对方的投放记录。规格 03 §10:「门户只查当前 quote,
                # 不混入同品牌其他报价」。
                #
                # 归属链:mhz_synced_orders.order_sn → mhz_publish_order_items.mhz_order_id
                #        → source_geo_post_id → geo_douyin_posts.quote_id
                #        (回落 orders.article_id → articles/topics.quote_id)。
                # brand_id 只保留为**附加**条件,不再是唯一条件。
                cur.execute("""
                    SELECT o.id, o.order_sn, o.title, o.media_name, o.url, o.status,
                           o.published_at, o.created_at, o.price
                    FROM mhz_synced_orders o
                    WHERE o.status IN (0, 1, 2)
                      AND EXISTS (
                            SELECT 1 FROM mhz_publish_order_items i
                              LEFT JOIN mhz_publish_orders po ON po.id = i.order_id
                              LEFT JOIN geo_douyin_posts gp   ON gp.id = i.source_geo_post_id
                              LEFT JOIN articles a            ON a.id = po.article_id
                              LEFT JOIN topics t              ON t.id = a.topic_id
                             WHERE i.mhz_order_id = o.order_sn
                               AND COALESCE(gp.quote_id, a.quote_id, t.quote_id) = %s
                      )
                    ORDER BY COALESCE(o.published_at, o.created_at) DESC
                    LIMIT %s
                """, (quote_id, limit))
                mhz_orders = cur.fetchall()

                # 批量查退款状态
                order_ids = [r["id"] for r in mhz_orders]
                refund_map = {}
                if order_ids:
                    cur.execute("""
                        SELECT order_id, status, reason, created_at, admin_note
                        FROM mhz_refund_requests
                        WHERE order_id = ANY(%s)
                        ORDER BY created_at DESC
                    """, (order_ids,))
                    for r in cur.fetchall():
                        if r["order_id"] not in refund_map:
                            refund_map[r["order_id"]] = {
                                "status": r["status"],
                                "reason": r["reason"],
                                "created_at": r["created_at"].isoformat() if r.get("created_at") else None,
                                "admin_note": r.get("admin_note", ""),
                            }

                status_labels = {0: "待接单", 1: "发布中", 2: "已完成"}
                for o in mhz_orders:
                    pub_date = None
                    if o.get("published_at"):
                        pub_date = o["published_at"].strftime("%Y-%m-%d") if hasattr(o["published_at"], "strftime") else str(o["published_at"])[:10]
                    elif o.get("created_at"):
                        pub_date = o["created_at"].strftime("%Y-%m-%d") if hasattr(o["created_at"], "strftime") else str(o["created_at"])[:10]

                    records.append({
                        "id": o["id"],
                        "source": "mhz",
                        "platform_name": o.get("media_name", ""),
                        "article_title": (o.get("title") or "").strip(),
                        "platform_url": o.get("url", ""),
                        "publish_date": pub_date,
                        "status": o["status"],
                        "status_label": status_labels.get(o["status"], "未知"),
                        "refund": refund_map.get(o["id"]),
                        "can_refund": o["status"] == 2 and o["id"] not in refund_map,
                    })

            # 3. 手动录入记录（不带 mhz_ 前缀的 operator_id）
            cur.execute("""
                SELECT id, platform_name, platform_url, article_title, publish_date, operator_id
                FROM media_publications
                WHERE quote_id = %s AND (operator_id IS NULL OR operator_id NOT LIKE 'mhz_%%')
                ORDER BY publish_date DESC
            """, (quote_id,))
            for r in cur.fetchall():
                records.append({
                    "id": r["id"],
                    "source": "manual",
                    "platform_name": r.get("platform_name", ""),
                    "article_title": r.get("article_title", ""),
                    "platform_url": r.get("platform_url", ""),
                    "publish_date": r["publish_date"],
                    "status": 2,
                    "status_label": "手动录入",
                    "refund": None,
                    "can_refund": False,
                })

            # 🔴 六阶段投影必须在 `conn.close()` **之前**跑 —— 它复用同一个 cursor。
            #    放在 close 之后会永远抛"connection already closed",被下面的
            #    except 吞掉,门户静默永远看不到合同数字。这类"降级分支把失败吃干净"
            #    的形态,正是本包一路在防的那一类。
            # [WP7] 门户同时给出**合同口径**的六阶段元组 + 全套 source_versions。
            # `records` 是原始条目(用户要看每一条链接),`stages` 才是合同数字。
            # 两者并列,标签分开 —— 谁也不冒充谁。
            stages_payload = None
            try:
                from services.publication_stage_adapters import (
                    quote_stage_tuple, stage_labels,
                )

                _proj = quote_stage_tuple(int(quote_id), cursor=cur)
                stages_payload = {
                    "stages": _proj.get("stages"),
                    "labels": stage_labels(),
                    "cutoff": _proj.get("cutoff"),
                    "source_versions": _proj.get("source_versions"),
                    "watermark": _proj.get("watermark"),
                }
            except Exception as _se:
                logger.warning(f"[publications] 六阶段投影不可用 quote={quote_id}: {_se}")

            conn.close()

            return {
                "status": "success",
                "count": len(records),
                "publications": records,
                "records_basis": "raw_attempts",
                "contract_stages": stages_payload,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise  # [audit P1 2026-06-10] RBAC 403 透传
    except Exception as e:
        logger.error(f"Get publications error: {e}")
        return {"status": "error", "error": str(e)}


