@app.post("/api/logs")
def record_operation_log(request: LogRequest, http_request: Request):
    """记录操作日志"""
    # [GEO-R1-CAN-087 安全修] 原 handler 只收 body·operator_id/brand_id 由调用方任意伪造 → 可伪造他人归属的操作日志。
    # 强制 operator_id = 认证身份·brand_id 若指定必须通过归属校验(与 GET /api/logs 的非 admin 过滤对称)。
    user = getattr(http_request.state, "user", None)
    user_id = (user.get("user_id") or user.get("id")) if user else None
    if not user_id:
        raise HTTPException(status_code=401, detail="需要登录")
    request.operator_id = str(user_id)
    if request.brand_id is not None and not (user and user.get("is_admin")):
        from auth.brand_access import require_brand_access
        require_brand_access(http_request, request.brand_id)
    try:
        return api_log_operation(request)
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Log operation error: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/logs")
def get_operation_logs_list(
    request: Request,
    operator_id: str = None,
    target_type: str = None,
    brand_id: int = None,
    limit: int = 100
):
    """查询操作日志。

    CTO-15.23 2026-05-25 · 非 admin 池过滤兼容历史 brand_id 写入:
    · 老 CTO-13.0 法:强制 operator_id = user_id 注入
    · 但历史 5 处 monitoring_api 写入(line 262/289/365/655)operator_id 实际是 brand_id 或 'system'
      → 永不匹配 user_id → 代理永远"暂无操作日志"
    · 修法:非 admin 构造池 = [str(user_id)] + 用户拥有的所有 brand_id → 用 IN 过滤
    · 老板 2026-05-25 拍"让所有人都知道他们自己的操作日志"
    """
    try:
        user = getattr(request.state, "user", None)
        if not user:
            return {"status": "error", "error": "未认证"}

        if user.get("is_admin"):
            return api_get_logs(operator_id=operator_id, target_type=target_type, limit=limit, brand_id=brand_id)

        user_id = user.get("user_id")
        operator_ids = [str(user_id)]
        owned_brand_ids = set()
        _conn = None
        try:
            from db.connection import get_connection as _gc
            _conn = _gc()
            _cur = _conn.cursor()
            _cur.execute("SELECT id FROM brands WHERE owner_user_id = %s", (user_id,))
            for r in _cur.fetchall():
                owned_brand_ids.add(int(r["id"]))
                operator_ids.append(str(r["id"]))
        except Exception as _e:
            logger.warning(f"[get-logs] 反查 owned brands 失败 · 仅按 user_id 过滤: {_e}")
        finally:
            try:
                if _conn:
                    _conn.close()
            except Exception:
                pass

        if brand_id is not None and int(brand_id) not in owned_brand_ids:
            return {"status": "success", "count": 0, "logs": []}

        return api_get_logs_multi(operator_ids=operator_ids, target_type=target_type, limit=limit, brand_id=brand_id)
    except Exception as e:
        logger.error(f"Get logs error: {e}")
        return {"status": "error", "error": str(e)}


# ========== 通知中心API ==========

def _resolve_notification_brand_id(request: Request, brand_id: int = None):
    """
    通知用户隔离：非管理员只能访问自己品牌的通知。
    返回 (resolved_brand_id, error_response)。
    如果 error_response 非 None，应直接返回该响应。
    """
    user = getattr(request.state, "user", None)
    if not user:
        return None, {"status": "error", "error": "未认证"}

    # 管理员可以访问所有通知（brand_id=None）或指定品牌
    if user.get("is_admin"):
        return brand_id, None

    # 非管理员：必须限制在分配的品牌范围内
    allowed = user.get("client_brand_ids", [])
    if not allowed:
        # 没有分配品牌 → 无通知可看
        return -1, None  # -1 不会匹配任何 brand_id，返回空列表

    if brand_id is not None:
        if brand_id not in allowed:
            return None, {"status": "error", "error": "无权访问该品牌通知"}
        return brand_id, None

    # 未指定 brand_id → 只返回用户拥有的第一个品牌（多品牌场景可扩展）
    return allowed[0], None


@app.get("/api/notifications")
def get_notifications_list(request: Request, brand_id: int = None, limit: int = 50, unread_only: bool = False):
    """品牌监测兼容通知列表；关键业务通知不得写入此旧通道。"""
    try:
        resolved_brand_id, err = _resolve_notification_brand_id(request, brand_id)
        if err:
            status_code = 401 if err.get("error") == "未认证" else 403
            raise HTTPException(status_code=status_code, detail=err.get("error") or "无权访问通知")
        return api_get_notifications(resolved_brand_id, limit, unread_only)
    except HTTPException:
        raise
    except Exception as e:
        logger.error("Get monitoring notifications failed: %s", type(e).__name__, exc_info=True)
        raise HTTPException(status_code=503, detail="通知暂时无法加载，请稍后重试")


