class SendNotificationRequest(BaseModel):
    title: str
    content: str = ""
    link: str = ""
    type: str = "system"
    user_id: Optional[int] = None

@app.post("/api/admin/notifications/send")
def admin_send_notification(req: SendNotificationRequest, request: Request):
    """管理员发送站内信（给指定用户或全部用户）"""
    try:
        user = request.state.user
        if not user.get("is_admin"):
            raise HTTPException(status_code=403, detail="仅管理员可操作")

        title = req.title
        content = req.content
        link = req.link
        msg_type = req.type
        target_user_id = req.user_id

        if not title:
            raise HTTPException(status_code=422, detail="标题不能为空")

        from db.team_db import create_user_notification
        from db.connection import get_connection

        sent = 0
        if target_user_id:
            create_user_notification(target_user_id, msg_type, title, content, link)
            sent = 1
        else:
            conn = get_connection()
            cursor = conn.cursor()
            cursor.execute("SELECT id FROM users WHERE is_active = 1")
            users = cursor.fetchall()
            conn.close()
            for u in users:
                create_user_notification(u["id"], msg_type, title, content, link)
                sent += 1

        return {"status": "success", "sent": sent, "message": f"已发送 {sent} 条通知"}
    except HTTPException:
        raise
    except Exception as e:
        logger.error("Admin send notification failed: %s", type(e).__name__, exc_info=True)
        raise HTTPException(status_code=503, detail="通知发送失败，请稍后重试")


# ========== Compliance v3 算法 admin 控制(P0 事故 2026-05-23 路径 B)==========
# 老板痛点:v2 算法"倒反天罡"导致客户真 100% 检出 · UI 显示不达标
# 路径 A(SSH)Deploy-CTO 已在改 settings.json + 立即重跑
# 路径 B(本组 endpoint)admin 自助开关 + backfill 历史 log · 不依赖 SSH

class ComplianceV3EnableRequest(BaseModel):
    """v3 算法启用请求"""
    enabled: bool = True
    rolling_window_days: Optional[int] = None   # 不传则保持现值
    lazy_threshold_days: Optional[int] = None   # 不传则保持现值
    rerun_today: bool = True                    # 切完立刻重跑今天 daily check


@app.post("/api/admin/compliance/enable-v3")
def admin_enable_compliance_v3(payload: ComplianceV3EnableRequest, request: Request):
    """
    [P0 事故 2026-05-23 路径 B] admin 启用/关闭 compliance v3 公平算法
    成功后 · 后续 daily cron 自动走 v3 · 不再"倒反天罡"
    可选立刻重跑今天的 daily check 让 keyword_compliance_log 今日 row 用 v3 修正
    """
    try:
        user = getattr(request.state, "user", None)
        if not user or not user.get("is_admin"):
            raise HTTPException(status_code=403, detail="仅管理员可操作")

        from config.settings_manager import load_settings, save_settings
        s = load_settings()
        s.compliance_algorithm_v3_enabled = bool(payload.enabled)
        if payload.rolling_window_days is not None:
            s.compliance_v3_rolling_window_days = max(1, min(30, int(payload.rolling_window_days)))
        if payload.lazy_threshold_days is not None:
            s.compliance_v3_lazy_threshold_days = max(1, min(30, int(payload.lazy_threshold_days)))
        ok = save_settings(s)
        if not ok:
            raise HTTPException(status_code=500, detail="保存 settings 失败")

        result = {
            "status": "success",
            "compliance_algorithm_v3_enabled": s.compliance_algorithm_v3_enabled,
            "compliance_v3_rolling_window_days": s.compliance_v3_rolling_window_days,
            "compliance_v3_lazy_threshold_days": s.compliance_v3_lazy_threshold_days,
        }

        if payload.rerun_today:
            try:
                from db.monitoring_db import run_daily_compliance_check
                rerun = run_daily_compliance_check()
                result["today_rerun"] = rerun
            except Exception as e:
                logger.warning(f"[Compliance-V3-Enable] today rerun 失败(非阻塞): {e}")
                result["today_rerun_error"] = str(e)

        logger.info(f"[Compliance-V3-Enable] admin={user.get('username')} {result}")
        return result
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"启用 v3 算法失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class ComplianceBackfillRequest(BaseModel):
    """v3 backfill 请求 · r10 扩大范围 + dry_run + 精确客户过滤"""
    days: int = 30                              # 回填近 N 天 · 1-365 clamp(年度合同)
    quote_id: Optional[int] = None              # 指定 quote · None 走 only_paid_with_monitoring
    force_today: bool = True                    # 顺手跑今天 daily check
    only_paid_with_monitoring: bool = True      # 仅付费 + 自动监测开 + 服务期内 + 有发文
