class SchedulerTriggerRequest(BaseModel):
    """[FF11 P1-3] 手动触发命令的**必填**稳定幂等键。调用方(前端/脚本)每次用户意图生成一个
    (crypto.randomUUID 等),双击/超时重试**复用同一个** → 端到端至多一次;不再是后端可选参数
    (可选=不传时后端每次代生成新 uuid → 重试即新命令 → 双执行)。"""
    request_id: str = Field(..., min_length=8, max_length=128,
                            description="调用方生成的稳定幂等键(同一用户意图复用同一个)")


@app.post("/api/scheduler/trigger/{job_id}")
async def trigger_scheduler_job(job_id: str, request: Request, body: SchedulerTriggerRequest):
    """手动触发定时任务(WORKERS=4 · SPEC §7:入 sched_commands 命令队列 · cron leader 消费执行 job 的
    raw 逻辑[独立 identity·不撞 cron 时间桶]·业务真正结束后才标 done·恰一次可恢复;不再在随机 web
    worker 直接跑副作用。返回 command_id 供轮询。)

    [FF11 幂等端到端] request_id **必填**(422 拒空)→ 作 command_id 入队幂等键,双击/重发去重
    (UNIQUE ON CONFLICT DO NOTHING)· 消费侧只执行 pending、死命令转 retry_pending 不复活(见 sched_control)。"""
    try:
        from services.sched_control import enqueue_command
        uid = None
        try:
            u = getattr(request.state, "user", None)
            if isinstance(u, dict):
                uid = u.get("user_id")
        except Exception:
            pass
        return {"status": "success", **enqueue_command(job_id, requested_by=uid, command_id=body.request_id)}
    except Exception as e:
        logger.error(f"Trigger job error: {e}")
        return {"status": "error", "error": str(e)}


