class ResolveManualRunRequest(BaseModel):
    """[§3.7] 人工处置 settlement_manual run —— operator 不从正文取(端点从认证上下文注入 · 防伪装)。
    [返工2 P0-3] 单表处置:只填 backend/freeze_id/decision(系统检测到双表都冻结时会拒绝,导向双表处置)。
    双表处置(两表都冻结):backend/freeze_id/decision = **保留笔(keeper)** + other_backend/other_freeze_id = **重复笔**
    (始终退款)· 系统对两笔分别审计处置。"""
    backend: str = Field(..., description="keeper: legacy | v35(操作人显式选 · 系统校验三元组匹配)")
    freeze_id: int = Field(..., description="keeper 在所选 backend 表中的 freeze 行 id(取自双表定位现场)")
    decision: str = Field(..., description="keeper 决策:commit(交付 · 冻结转消费) | release(退款)")
    note: str = Field(..., min_length=1, max_length=2000, description="核对结果 / 理由 / 证据")
    other_backend: Optional[str] = Field(None, description="[双表处置]重复笔 backend(与 keeper 分属 legacy/v35)· 始终退款")
    other_freeze_id: Optional[int] = Field(None, description="[双表处置]重复笔 freeze 行 id")


@app.post("/api/admin/diagnosis-runs/{run_token}/resolve")
async def admin_resolve_settlement_manual(run_token: str, request: Request, body: ResolveManualRunRequest):
    """[§3.7] 人工处置 settlement_manual run:验证唯一 FreezeHandle(三元组匹配)→ 回填 → CAS 回 *_pending
    交还 sweeper 正常结算。**禁止**直接改余额/写终态/绕状态机。admin-only · operator 取认证上下文 · 审计留痕。
    [返工2 P0-3] 给了 other_backend/other_freeze_id → 走**双表处置**(keeper 进状态机 + 重复笔直接退款 · 两笔分别审计);
    否则单表处置(若系统检测双表都冻结会返回 double_frozen 提示,要求补两笔)。"""
    _user = _require_admin_user(request)
    operator = f"{_user.get('username') or _user.get('nickname') or 'admin'}(uid={_user.get('user_id')})"
    try:
        if body.other_backend is not None or body.other_freeze_id is not None:
            # 双表处置:两笔都必须给全
            if body.other_backend is None or body.other_freeze_id is None:
                raise HTTPException(status_code=400, detail="双表处置需同时提供 other_backend 与 other_freeze_id")
            from services.diagnosis_runs import resolve_double_frozen
            out = await resolve_double_frozen(
                run_token, operator, body.backend, body.freeze_id, body.decision,
                body.other_backend, body.other_freeze_id, body.note)
        else:
            from services.diagnosis_runs import verify_and_resolve_manual
            out = await asyncio.to_thread(
                verify_and_resolve_manual, run_token, operator,
                body.backend, body.freeze_id, body.decision, body.note)
        if not out.get("ok"):
            # double_frozen 单表处置被拒 → 409 引导补两笔;其余 → 400
            _sc = 409 if out.get("double_frozen") else 400
            raise HTTPException(status_code=_sc, detail=out.get("error", "处置失败"))
        return {"status": "success", **out}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[DiagRuns] resolve settlement_manual 失败 run={run_token}: {e}")
        raise HTTPException(status_code=500, detail=f"处置异常: {e}")


