@app.post("/api/admin/diagnosis-runs/{run_token}/execute-v35-refund")
async def admin_execute_v35_refund(run_token: str, request: Request, body: ExecuteV35RefundRequest):
    """[P1-2] v35 交付缺失(delivery_repair_pending · refund_pending)**精确退款执行 + 确认**闭环(admin-only)。
    单事务:锁 run/冻结/钱包 → 校验(v35/paid/refund_pending/owner+freeze+task_ref 全非空 · 仅 committed 冻结 · 歧义 fail-closed)→
    amount_bonus>0 在首个写操作前返回 BONUS_REFUND_REQUIRES_MANUAL；consume 逐笔核验负号及逐池金额→
    调 customer_credit.refund_credit **仅退 tool/publish 且 bonus_points 恒为 0** → 只读复核退款正号及逐池金额 →
    建 run-bound 退款记录 + CAS→resolved + 审计(全同事务 · 任一步异常回滚含钱包退款)。幂等 · 并发恰一退。
    🔴 **会真实修改钱包**；不调 refund_points · 不写 recharge_orders · 只用 refund_credit 退回工具/发布池 · billing.py 只调不改。
    operator 取认证上下文。legacy 及含赠送额度的 v35 人工退款均走 finance 退款 + /repair confirm_refund
    填真实流水 id；仅 bonus=0 的 v35 使用本自动端点。"""
    _user = _require_admin_user(request)
    operator = f"{_user.get('username') or _user.get('nickname') or 'admin'}(uid={_user.get('user_id')})"
    try:
        from services.diagnosis_runs import refund_and_confirm_v35_delivery
        out = await asyncio.to_thread(refund_and_confirm_v35_delivery, run_token, operator, body.note)
        if not out.get("ok"):
            code = out.get("error_code") or "V35_REFUND_REJECTED"
            status_code = 500 if code == "V35_REFUND_TRANSACTION_FAILED" else 409
            raise HTTPException(
                status_code=status_code,
                detail={"code": code, "message": out.get("error", "v35 退款执行失败")},
            )
        return {"status": "success", **out}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[DiagRuns] execute v35 refund 失败 run={run_token}: {e}")
        raise HTTPException(status_code=500, detail=f"v35 退款执行异常: {e}")


