class TaskExecuteRequest(BaseModel):
    """任务执行请求"""
    tasks_markdown: Optional[str] = None  # 从Markdown解析任务
    tasks: Optional[list] = None           # 直接传入任务列表
    context: str = ""                      # 背景上下文
    participant_ids: Optional[list[str]] = None  # 参会人员ID列表


@app.post("/api/tasks/execute")
async def execute_tasks(request: TaskExecuteRequest):
    """
    执行任务列表（SSE流式）

    用于会议后的任务执行、复杂诊断流程等场景
    """
    from fastapi.responses import StreamingResponse
    from task.task_executor import TaskExecutor, Task, TaskStatus, parse_tasks_from_markdown
    import json

    async def event_generator():
        try:
            tasks = []

            # 从Markdown解析任务
            if request.tasks_markdown:
                tasks = parse_tasks_from_markdown(
                    request.tasks_markdown,
                    request.participant_ids
                )

            # 或直接使用传入的任务列表
            elif request.tasks:
                for i, t in enumerate(request.tasks):
                    task = Task(
                        id=t.get("id", f"task_{i+1}"),
                        name=t.get("name", ""),
                        assignee_id=t.get("assignee_id", "project_director"),
                        assignee_name=t.get("assignee_name", "项目负责人"),
                        input_required=t.get("input_required", ""),
                        output_expected=t.get("output_expected", ""),
                        acceptance_criteria=t.get("acceptance_criteria", ""),
                        estimated_time=t.get("estimated_time", ""),
                    )
                    tasks.append(task)

            if not tasks:
                yield f"data: {json.dumps({'type': 'error', 'data': {'error': '没有可执行的任务'}}, ensure_ascii=False)}\n\n"
                return

            # 创建执行器并执行
            executor = TaskExecutor(tasks, context=request.context)

            async for event in executor.execute_stream():
                yield f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        except Exception as e:
            logger.error(f"Task execution error: {e}")
            yield f"data: {json.dumps({'type': 'error', 'data': {'error': str(e)}}, ensure_ascii=False)}\n\n"

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        }
    )


