@app.post("/api/strategy/generate")
async def create_sales_strategy(request: StrategyRequest):
    """Generate sales strategy using LLM based on diagnosis data"""
    # Check if DB module is available
    if not get_diagnosis_by_id:
        return {"error": "DB module not loaded"}

    try:
        # 1. Get diagnosis data
        record = get_diagnosis_by_id(request.diagnosis_id)
        if not record:
            return {"error": "Diagnosis record not found"}

        # 2. Extract necessary fields
        dimension_scores = {
            "web_search_score": record.get("web_search_score", 0),
            "platform_score": record.get("platform_score", 0),
            "content_quality_score": record.get("content_quality_score", 0),
            "authority_score": record.get("authority_score", 0),
            "brand_ownership_score": record.get("brand_ownership_score", 0),
            "ai_visibility_score": record.get("ai_visibility_score", 0),
            "ai_citation_score": record.get("ai_citation_score", 0),
            "update_frequency_score": record.get("update_frequency_score", 0)
        }

        # AI data
        ai_visibility_data = {
            "overall_mention_rate": record.get("ai_mention_rate", 0),
            "total_tests": record.get("ai_total_tests", 0),
            "engines_mentioned": 0
        }

        # 3. Generate Strategy
        if generate_sales_strategy_with_llm:
            strategy = await generate_sales_strategy_with_llm(
                brand_name=record.get("brand_name", ""),
                industry=record.get("industry", ""),
                industry_category=record.get("industry_category", ""),
                total_score=record.get("total_score", 0),
                level=record.get("level", ""),
                dimension_scores=dimension_scores,
                ai_visibility_data=ai_visibility_data,
                competitor_data={}
            )
            return {"strategy": strategy}
        else:
            return {"error": "Strategy generator not loaded"}

    except Exception as e:
        logger.error(f"Strategy generation failed: {e}")
        return {"error": str(e)}

