@app.get("/api/diagnoses/search")
def search_diagnoses_api(q: str, request: Request):
    """Search diagnoses for frontend autocomplete
    [P0-5 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 加 brand_ids filter + 移除 report_md_path"""
    if not search_diagnoses:
         return {"error": "DB module not loaded"}
    from auth.brand_access import get_user_brand_filter
    allowed = get_user_brand_filter(request)
    if allowed is None:
        # admin 全局
        results = search_diagnoses(q)
    elif not allowed or allowed == [-1]:
        results = []
    else:
        results = search_diagnoses(q)
        # 在 Python 层过滤(避免改 DB 接口)
        results = [r for r in results if r.get("brand_id") in allowed]
    # 非 admin 移除敏感字段 report_md_path
    user = getattr(request.state, "user", None)
    if user and not user.get("is_admin") and isinstance(results, list):
        for r in results:
            r.pop("report_md_path", None)
            r.pop("report_json_path", None)
    return results


