@app.post("/api/articles/plan")
async def plan_articles(request: ArticlePlanRequest, http_request: Request):
    """根据输入数量自动规划文章分配，使用LLM生成高质量标题

    [v2.10 hard 400 · Codex 二审/三审/四审 P0]
    distribution 外部字段废弃 · 传了直接 400 reject(0 后门 · 不走 internal plan 例外)
    用户应改用:
      GET /api/writing/projects/{quote_id}/direction-plan(只读建议)
      POST /api/writing/projects/{quote_id}/apply-distribution(写入)
    """
    # [GEO-R1-CAN-018 安全修] 原 handler 无 Request·从不校验 diagnosis 归属 → 任意登录用户枚举 diagnosis_id
    # 读他人品牌名/行业并生成标题分配。补 require_diagnosis_access(与 siblings 3496/4020/4279 一致)。
    from auth.brand_access import require_diagnosis_access
    require_diagnosis_access(http_request, request.diagnosis_id)

    # v2.10 P1-4 · 旧 distribution 字段 hard 400 · 防绕过医疗/法律 hard rule + company fixed + source 状态机
    if request.distribution is not None:
        raise HTTPException(
            status_code=400,
            detail="distribution 字段已废弃(v2.10)· 请改用 GET /api/writing/projects/{quote_id}/direction-plan 取推荐 + POST /api/writing/projects/{quote_id}/apply-distribution 应用"
        )

    if not calculate_distribution:
        return {"error": "Article generator module not loaded"}

    try:
        # 🔥 FIX: 优先使用前端传入的distribution，没有才用默认计算
        if request.distribution and any(v > 0 for v in request.distribution.values()):
            # 前端传入的是 {type: count} 格式，转换为后端需要的格式
            distribution = {k: {"count": v, "ratio": v/request.total_count if request.total_count > 0 else 0}
                           for k, v in request.distribution.items() if v > 0}
            logger.info(f"📋 使用前端传入的分配方案: {request.distribution}")
        else:
            # v2.7.1:industry 贯穿(P0 #3) · 从诊断记录读 industry
            try:
                _rec = get_diagnosis_by_id(request.diagnosis_id) if get_diagnosis_by_id else None
                _ind = (_rec or {}).get("industry") if _rec else None
            except Exception:
                _ind = None
            distribution = calculate_distribution(request.total_count, _ind)

        # 计算预估时间（基于3并发，每篇约1.5分钟）
        time_per_batch = 1.5  # 分钟
        batches = (request.total_count + 2) // 3  # 向上取整
        estimated_minutes = max(5, batches * time_per_batch)

        # 获取诊断数据用于LLM生成标题
        record = get_diagnosis_by_id(request.diagnosis_id) if get_diagnosis_by_id else None
        if not record:
            return {"error": f"未找到诊断记录: {request.diagnosis_id}"}

        brand_name = record.get("brand_name", "品牌")
        industry = record.get("industry", "行业")

        # Step 1: 如果skip_titles=True，只返回分配方案，不生成标题
        if request.skip_titles:
            logger.info(f"📋 Step 1: 返回分配方案（跳过标题生成）")
            return {
                "distribution": distribution,
                "estimated_time": f"{estimated_minutes:.0f}分钟",
                "topics": []  # 空标题列表
            }

        # ======== Step 2: 使用LLM生成高质量标题 ========
        logger.info(f"🤖 Step 2: 使用LLM生成 {request.total_count} 个标题...")

        try:
            from writing.topic_dispatcher import TopicDispatcher
            from writing.distiller import DistillerPipeline

            # 解析诊断原始数据
            import json
            raw_data = {}
            raw_data_json = record.get("raw_data_json", "{}")
            if raw_data_json:
                try:
                    raw_data = json.loads(raw_data_json)
                except:
                    pass
            data_layer = raw_data.get("data", {})

            # 解析关键词
            keywords_raw = record.get("keywords", "[]")
            keywords = json.loads(keywords_raw) if isinstance(keywords_raw, str) else keywords_raw

            # 构建诊断数据
            diagnosis_data = {
                "brand_name": brand_name,
                "brand": brand_name,
                "industry": industry,
                "keywords": keywords,
                "total_score": record.get("total_score", 0),
                "level": record.get("level", ""),
                "competitor_data": data_layer.get("competitor_analysis", {}),
                "ai_visibility": data_layer.get("ai_visibility", {}),
                "business_context": data_layer.get("business_context", {}),
            }

            # 运行蒸馏管道获取卖点等信息
            distilled_data = {
                "client_profile": json.dumps({
                    "company_name": brand_name,
                    "industry": industry,
                    "service_keywords": keywords
                }, ensure_ascii=False),
                "selling_points": json.dumps({
                    "unique_value": f"{brand_name}专业{industry}服务"
                }, ensure_ascii=False),
                "competitor_analysis": json.dumps({
                    "competitors": []
                }, ensure_ascii=False)
            }

            # 尝试运行完整蒸馏
            try:
                # 优先使用客户已确认的营销资料（唯一权威素材源）
                client_materials = None
                plan_brand_id = record.get("brand_id")
                if plan_brand_id:
                    try:
                        from db.diagnosis_db import get_confirmed_materials
                        client_materials = get_confirmed_materials(plan_brand_id)
                        if client_materials:
                            logger.info(f"  ✅ 使用客户已确认的营销资料 (brand_id={plan_brand_id})")
                    except Exception as e:
                        logger.warning(f"  ⚠️ 获取确认资料失败: {e}")

                # Fallback: 传统客户资料
                if not client_materials:
                    from db.diagnosis_db import get_client_materials
                    client_materials = get_client_materials(request.diagnosis_id)

                # ✅ 备用方案：如果没有client_materials，从input_params.additional_info获取公司简介
                additional_info_text = ""
                if not client_materials:
                    input_params = raw_data.get("input_params", {})
                    additional_info_text = input_params.get("additional_info", "")
                    if additional_info_text and len(additional_info_text) > 100:
                        logger.info(f"  📄 从诊断记录获取公司简介 ({len(additional_info_text)}字符)")
                        # 将公司简介添加到diagnosis_data，供蒸馏器使用
                        diagnosis_data["business_context"] = additional_info_text
                    else:
                        logger.info("  ⚠️ 无客户资料，使用LLM推理")
                else:
                    logger.info(f"  📋 发现客户资料: {len(client_materials.get('core_selling_points', []))}个卖点")

                distiller = DistillerPipeline(diagnosis_data, client_materials=client_materials)
                distilled_data = await distiller.run()
                logger.info("  ✅ 蒸馏完成")
                # 🔥 缓存蒸馏结果，避免Generate阶段重复运行
                distilled_data_cache[request.diagnosis_id] = {
                    "distilled_data": distilled_data,
                    "timestamp": datetime.now()
                }
                logger.info(f"  💾 已缓存蒸馏结果 (diagnosis_id={request.diagnosis_id})")
            except Exception as e:
                logger.warning(f"  ⚠️ 蒸馏失败，使用基础数据: {e}")

            # 构建分配映射（从distribution提取count）
            article_distribution = {}
            for style, config in distribution.items():
                count = config.get("count", 0) if isinstance(config, dict) else config
                article_distribution[style] = count

            # 使用TopicDispatcher生成选题
            dispatcher = TopicDispatcher(
                distilled_data=distilled_data,
                diagnosis_data=diagnosis_data,
                distribution=article_distribution,
                test_mode=False
            )

            llm_topics = await dispatcher.generate_topics()
            logger.info(f"  ✅ LLM生成 {len(llm_topics)} 个选题")

            # v2.7.2 GEO 文体改造 · 删 CONTENT_ANGLE_TO_STYLE 旧固定映射 + 不采用 LLM article_style
            # 根因(Codex P0 #4):旧映射 authority→ranking_v2 / case_study→authority_ranking / expert→authority_ranking
            # 会绕过医疗/法律 0 榜单 hard rule · plan 阶段把 style_code 写死后续 _allocate_style_from_ratios 不再
            # 走 industry override。v2.7.2 改:plan 阶段只产 title · 不产 style_code · 最终模板必走第 2 层 style_ratios。
            from writing.style_registry import WRITING_STYLES
            from writing.article_style_contract import ensure_evidence_first_title

            # 转换为前端需要的格式 · 保留 LLM 生成的 title · style_code=None 走第 2 层分配
            topics = []
            _plan_types = list(article_distribution) or ["implementation_guide"]
            for i, topic in enumerate(llm_topics[:request.total_count]):
                _plan_type = str(topic.get("type") or topic.get("article_type") or _plan_types[i % len(_plan_types)])
                topics.append({
                    "id": i + 1,
                    "title": ensure_evidence_first_title(
                        topic.get("title", ""),
                        brand_name=brand_name, industry=industry,
                        family_or_style=_plan_type, keywords=keywords, index=i + 1,
                    ),
                    # v2.7.2:不固定 style_code · 走系统推荐 · _allocate_style_from_ratios 按 industry override 决定
                    "type": None,
                    "style_code": None,
                    "styleName": "系统推荐",  # 0 暴露工程词
                    "user_choice": "auto",  # 默认 · 用户在 WritingHall 可改
                    "keyword": topic.get("keyword", topic.get("user_search", "")),
                    "platform": topic.get("platform", "知乎"),
                    "intent_type": topic.get("intent_type", "find_provider"),
                    "opening_sentence": topic.get("opening_sentence", ""),
                    "competitors_to_mention": topic.get("competitors_to_mention", [])
                })

            # 如果LLM生成数量不足，用模板补齐
            if len(topics) < request.total_count:
                logger.warning(f"  ⚠️ LLM生成 {len(topics)} 个，需补齐到 {request.total_count}")
                for i in range(len(topics), request.total_count):
                    article_type = list(article_distribution.keys())[i % len(article_distribution)]
                    topics.append({
                        "id": i + 1,
                        "title": generate_title_for_type(brand_name, industry, article_type, keywords, i + 1),
                        "type": article_type,
                        "keyword": "",
                        "platform": "知乎"
                    })

        except Exception as e:
            # LLM失败时使用模板兜底
            logger.warning(f"  ⚠️ LLM生成失败: {e}，使用模板兜底")
            import json
            keywords = []
            try:
                keywords = json.loads(record.get("keywords", "[]"))
            except:
                pass

            topics = []
            topic_id = 1
            for article_type, type_config in distribution.items():
                count = type_config.get("count", 0) if isinstance(type_config, dict) else type_config
                for i in range(count):
                    title = generate_title_for_type(brand_name, industry, article_type, keywords, i + 1)
                    topics.append({
                        "id": topic_id,
                        "title": title,
                        "type": article_type
                    })
                    topic_id += 1

        return {
            "total_articles": request.total_count,
            "distribution": distribution,
            "topics": topics,
            "platforms": ["IT之家", "小红书", "知乎", "百家号", "抖音"],
            "estimated_time": f"约{int(estimated_minutes)}-{int(estimated_minutes * 1.5)}分钟",
            "concurrency_options": {
                "1-2": "最稳定，40篇约80-120分钟",
                "3": "推荐，40篇约30-45分钟",
                "4-5": "较快但可能限流，40篇约20-30分钟"
            },
            "recommended_concurrent": 3,
            "generated_by": "llm" if topics and topics[0].get("keyword") else "template"
        }
    except Exception as e:
        logger.error(f"Article plan error: {e}")
        import traceback
        traceback.print_exc()
        return {"error": str(e)}


