@app.post("/api/articles/generate")
async def generate_articles(request: ArticleGenerateRequest, http_request: Request = None):
    """[v2.10.2 整体废弃 · Codex 二审 v2.10.1 P0-2]

    根因:v2.10.1 把 article_distribution 改 Optional + 传非 None 400 reject · 但不传时继续走
          validate_distribution(None, total_count) → tools/article_generator.py sum(None.values()) 500 崩

    修法:整体废弃 410 Gone · 不进 validate_distribution 路径 · 0 半兼容
    实证:frontend/src/lib/api.ts 暴露但前端无实际调用方(Codex 五审实证)

    替代方案:
      POST /api/writing/projects/{quote_id}/apply-distribution(纯方向 UPDATE 不扣费)
      POST /api/writing/regenerate-titles(带 style_plan · 同步重写)
      POST /api/writing/start-articles(标题就绪后实际生成文章)
    """
    raise HTTPException(
        status_code=410,
        detail="/api/articles/generate 已整体废弃(v2.10.2)· 请改用 /api/writing/projects/{quote_id}/apply-distribution + /api/writing/start-articles · article_distribution 字段不再支持"
    )

    # 以下原代码不可达 · 保留供历史参考(v2.10.2 410 后整体死代码 · 后续 v2.11 可删)
    if not calculate_distribution:
        return {"error": "Article generator module not loaded"}

    # 先做参数校验，避免无效请求扣费
    is_valid, error = validate_distribution(
        request.article_distribution,
        request.total_count
    )
    if not is_valid:
        return {"error": error}

    # [CTO-15.23 2026-05-19 P0 资金漏洞 audit · Agent 复查发现] 跟刚修 BUG#1 同款
    # 之前 _bill_feature_ctx 只扣 1×390 · request.total_count 是 N 篇 · 漏 90% 收费
    _gen_multiplier = max(1, int(request.total_count or 1))
    async with _bill_feature_ctx(http_request, "article_gen", multiplier=_gen_multiplier):
        logger.info(f"📋 收到topics: {len(request.topics) if request.topics else 0} 个 · 扣费 {_gen_multiplier}×390")

        # 🔥 读取缓存的蒸馏结果（跳过重复的DistillerPipeline）
        cached = distilled_data_cache.get(request.diagnosis_id)
        cached_distilled_data = None
        if cached:
            cached_distilled_data = cached.get("distilled_data")
            logger.info(f"💾 从缓存读取蒸馏结果 (diagnosis_id={request.diagnosis_id})")
        else:
            logger.info(f"⚠️ 未找到蒸馏缓存，将重新运行DistillerPipeline")

        # 从诊断记录获取 brand_id，用于检索客户专属知识库
        brand_id = None
        try:
            diag_record = get_diagnosis_by_id(request.diagnosis_id)
            if diag_record:
                brand_id = diag_record.get("brand_id")
                if brand_id:
                    logger.info(f"📚 将使用客户知识库 (brand_id={brand_id})")
        except Exception:
            pass

        # v2.7.4 GEO 文体改造(Codex 抓旧接口绕过修):
        # 从诊断记录读 industry · 用于医疗/法律 hard rule(industry override)
        _v274_industry = None
        try:
            _diag_for_industry = get_diagnosis_by_id(request.diagnosis_id) if get_diagnosis_by_id else None
            if _diag_for_industry:
                _v274_industry = _diag_for_industry.get("industry") or None
        except Exception:
            pass

        # v2.7.4:净化 request.topics · 只保留白名单字段(title + keyword + user_choice)
        # 不让客户传 style_code/style/type/article_style/_trust_legacy_style 等绕过字段
        _v274_VALID_UC = {
            'auto', 'guide', 'comparison', 'risk', 'price', 'data',
            'qa', 'checklist', 'case', 'story',
        }
        _v274_clean_topics = None
        if isinstance(request.topics, list):
            _v274_clean_topics = []
            for _t in request.topics:
                if not isinstance(_t, dict):
                    continue
                _uc = _t.get("user_choice", "auto")
                _v274_clean_topics.append({
                    "id": _t.get("id"),
                    "title": _t.get("title", ""),
                    "keyword": _t.get("keyword", ""),
                    "user_choice": _uc if isinstance(_uc, str) and _uc in _v274_VALID_UC else "auto",
                    # 故意丢弃 style_code/style/type/article_style/_trust_legacy_style(防绕过)
                })

        try:
            result = await start_batch_generation(
                diagnosis_id=request.diagnosis_id,
                article_distribution=request.article_distribution,
                topics=_v274_clean_topics,  # v2.7.4 净化后的 topics
                distilled_data=cached_distilled_data,
                brand_id=brand_id,
                industry=_v274_industry,  # v2.7.4
            )
            # 业务级错误也要触发退费
            if isinstance(result, dict) and result.get("error"):
                raise HTTPException(status_code=500, detail=result["error"])
            return result
        except HTTPException:
            raise
        except Exception as e:
            logger.error(f"Article generation error: {e}")
            # re-raise 让 _bill_feature_ctx 触发退费
            raise HTTPException(status_code=500, detail=str(e))


