@app.get("/api/articles/list/{diagnosis_id}")
def list_articles(diagnosis_id: int, request: Request):
    """获取客户已生成的文章列表 - 基于diagnosis_id精确匹配"""
    import glob

    try:
        from auth.brand_access import require_diagnosis_access
        require_diagnosis_access(request, diagnosis_id)
        # 从诊断记录获取客户名
        record = get_diagnosis_by_id(diagnosis_id) if get_diagnosis_by_id else None
        if not record:
            return {"error": "Diagnosis record not found", "articles": [], "batches": []}

        brand_name = record.get("brand_name", "")

        articles = []
        batches = set()

        # 🔥 FIX: 优先从数据库读取（基于diagnosis_id精确关联）
        try:
            from db.diagnosis_db import get_articles_by_diagnosis
            db_articles = get_articles_by_diagnosis(diagnosis_id)
            for a in db_articles:
                batch = a.get("task_id", "unknown")
                batches.add(batch)
                articles.append({
                    "file_path": a.get("file_path", ""),
                    "filename": os.path.basename(a.get("file_path", "")),
                    "title": a.get("title", ""),
                    "created_at": a.get("created_at", ""),
                    "size": 0,  # 无法从DB获取
                    "batch": batch,
                    "type": a.get("article_type", ""),
                    "word_count": a.get("word_count", 0)
                })
            if db_articles:
                logger.info(f"📚 从数据库读取了 {len(db_articles)} 篇文章 (diagnosis_id={diagnosis_id})")
        except Exception as db_err:
            logger.warning(f"数据库查询失败: {db_err}, 回退到文件扫描")

        # 如果数据库没有记录，回退到文件扫描（兼容旧数据）
        if not articles:
            logger.info(f"📁 数据库无记录, 回退到文件扫描 (diagnosis_id={diagnosis_id}, brand={brand_name})")

            # [GEO-R3-CAN-008 安全修] brand_name 是用户创建诊断时的自填串·直接插进 glob 会把 '*'/'?'/'['
            #   当通配符 → 构造 brand_name='*' 或他人品牌子串可越界匹配其它租户的文章文件元数据。
            #   glob.escape 转义通配符·令 brand_name 只能字面匹配(diagnosis_ 目录用 server 端 id 不受影响)。
            safe_brand = glob.escape(brand_name)
            # 搜索所有可能的文章来源
            all_patterns = [
                # 按diagnosis_id命名的目录
                f"output/articles/diagnosis_{diagnosis_id}/**/*.md",
                # 按brand_name命名的文件(通配符已转义·仅字面匹配)
                f"output/articles/{safe_brand}*.md",
                f"output/articles/**/{safe_brand}*.md",
                f"output/articles/**/*{safe_brand}*.md",
                # replace目录 - 只匹配包含品牌名的文件
                # f"output/articles/replace/*.md",  # 移除：无法区分品牌
            ]

            # 🔥 batch_gen目录需要按品牌名过滤
            batch_patterns = [
                f"output/articles/batch_gen_*/*.md",
            ]

            for pattern in all_patterns:
                for filepath in glob.glob(pattern, recursive=True):
                    try:
                        stat = os.stat(filepath)
                        batch = os.path.basename(os.path.dirname(filepath))
                        batches.add(batch)

                        filename = os.path.basename(filepath)

                        # 尝试从文件元数据读取标题
                        title = filename.replace(".md", "").replace("_", " ")
                        try:
                            with open(filepath, 'r', encoding='utf-8') as f:
                                first_lines = f.read(500)
                            # 解析YAML frontmatter中的title
                            if first_lines.startswith("---"):
                                import re
                                title_match = re.search(r'^title:\s*(.+)$', first_lines, re.MULTILINE)
                                if title_match:
                                    title = title_match.group(1).strip()
                        except:
                            pass

                        articles.append({
                            "file_path": filepath,
                            "filename": filename,
                            "title": title,
                            "created_at": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                            "size": stat.st_size,
                            "batch": batch
                        })
                    except:
                        continue

            # 单独处理batch_gen目录：只返回包含品牌名称的文章
            for pattern in batch_patterns:
                for filepath in glob.glob(pattern, recursive=True):
                    try:
                        stat = os.stat(filepath)
                        batch = os.path.basename(os.path.dirname(filepath))

                        filename = os.path.basename(filepath)

                        # 读取文件内容以检查品牌名称
                        title = filename.replace(".md", "").replace("_", " ")
                        file_content = ""
                        try:
                            with open(filepath, 'r', encoding='utf-8') as f:
                                file_content = f.read(2000)  # 读取前2000字符
                            # 解析YAML frontmatter中的title
                            if file_content.startswith("---"):
                                import re
                                title_match = re.search(r'^title:\s*(.+)$', file_content, re.MULTILINE)
                                if title_match:
                                    title = title_match.group(1).strip()
                        except:
                            pass

                        # 关键过滤：只返回标题包含品牌名称的文章
                        if brand_name and brand_name in title:
                            batches.add(batch)
                            articles.append({
                                "file_path": filepath,
                                "filename": filename,
                                "title": title,
                                "created_at": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                                "size": stat.st_size,
                                "batch": batch
                            })
                    except:
                        continue

        # 去重
        seen = set()
        unique_articles = []
        for a in articles:
            if a["file_path"] not in seen:
                seen.add(a["file_path"])
                unique_articles.append(a)

        # 按创建时间倒序
        unique_articles.sort(key=lambda x: x["created_at"], reverse=True)

        return {
            "diagnosis_id": diagnosis_id,
            "brand_name": brand_name,
            "articles": unique_articles,
            "batches": list(batches),
            "total": len(unique_articles)
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Article list error: {e}")
        return {"error": str(e), "articles": [], "batches": []}


