import zipfile
import io
from fastapi.responses import StreamingResponse

@app.post("/api/articles/download-zip")
def download_zip_articles(request: BatchDownloadRequest, http_request: Request):
    """批量下载文章 - 打包为ZIP文件"""
    try:
        if not request.file_paths:
            raise HTTPException(status_code=400, detail="No files selected")

        # 创建内存中的ZIP文件
        zip_buffer = io.BytesIO()

        with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zip_file:
            for file_path in request.file_paths:
                # [GEO-R1-CAN-020 P2] canonical 包含校验 · 替换旧的 "output/articles" 子串匹配
                # (旧逻辑 `"output/articles" in check_path` 子串匹配可被 /tmp/x/output/articles/../../etc
                #  等绕过;realpath+commonpath 才是边界安全的)
                safe_path = _resolve_safe_article_path(file_path)
                if not safe_path or not os.path.exists(safe_path):
                    continue

                # [Deploy-CTO NO-GO finding 2 v3] 跨租户归属校验:用规范化 safe_path(非 caller 原始串)· 跳过无权文件
                if not _article_path_access_ok(http_request, safe_path):
                    logger.info(f"[download-zip] 跳过无权文件(跨租户防护): {file_path}")
                    continue

                check_path = safe_path.replace('\\', '/')
                try:
                    with open(safe_path, "r", encoding="utf-8") as f:
                        content = f.read()
                    # 清除 AI 废话（安全网）
                    from writing.content_cleaner import clean_llm_article
                    content = clean_llm_article(content)
                    # 使用相对路径作为ZIP内部文件名，避免同名文件冲突
                    # 提取 output/articles/ 之后的路径
                    rel_path = check_path.split('output/articles/')[-1] if 'output/articles/' in check_path else os.path.basename(safe_path)
                    zip_file.writestr(rel_path, content.encode('utf-8'))
                except Exception as e:
                    logger.warning(f"Could not add file {safe_path} to zip: {e}")

        zip_buffer.seek(0)

        # 生成ZIP文件名
        from datetime import datetime
        zip_filename = f"articles_{datetime.now().strftime('%Y%m%d_%H%M%S')}.zip"

        return StreamingResponse(
            zip_buffer,
            media_type="application/zip",
            headers={
                "Content-Disposition": f'attachment; filename="{zip_filename}"',
                "Access-Control-Expose-Headers": "Content-Disposition"
            }
        )
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"ZIP download error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


