@app.post("/api/articles/batch-delete")
def batch_delete_articles(request: BatchDeleteRequest, http_request: Request):
    """批量删除文章

    [Deploy-CTO NO-GO finding 2 返工 2026-07-12] 补 DB 对象归属校验:article_generations.file_path →
    diagnosis_id → require_diagnosis_access(fail-closed)。原注释"文件级归属做不了"不成立 ——
    article_generations 表有 file_path 列可反查归属。无归属线索的文件一律拒删(不再靠"在 output 目录内"放行)。
    """
    try:
        if len(request.file_paths) > 100:
            raise HTTPException(status_code=400, detail="单次批量上限 100")
        deleted = []
        failed = []
        # [GEO-R1-CAN-026 安全修] realpath + 目录分隔符边界·替换旧的无分隔符 startswith(词法前缀)判断。
        # 旧 `abs_path.startswith(output_dir)` 会误放行同级目录 `/app/output_x/...`(前缀匹配)且不解析符号链接/..。
        output_dir = os.path.realpath(os.path.join(os.path.dirname(__file__), "output"))

        for file_path in request.file_paths:
            try:
                if not file_path or not os.path.exists(file_path):
                    failed.append({"path": file_path, "reason": "文件不存在"})
                    continue

                real_path = os.path.realpath(file_path)
                if not (real_path == output_dir or real_path.startswith(output_dir + os.sep)):
                    failed.append({"path": file_path, "reason": "无权删除"})
                    continue

                # [Deploy-CTO NO-GO finding 2 v3] 跨租户归属校验:用规范化 real_path(非 caller 原始串)·
                #   非本租户/无归属线索一律拒删(fail-closed)。real_path 已 realpath 规范化(符号链接/.. 已解析)。
                if not _article_path_access_ok(http_request, real_path):
                    failed.append({"path": file_path, "reason": "无权删除(归属校验未通过)"})
                    continue

                os.remove(real_path)
                deleted.append(file_path)
                logger.info(f"Deleted article: {real_path}")
            except Exception as e:
                failed.append({"path": file_path, "reason": str(e)})

        return {
            "success": True,
            "deleted_count": len(deleted),
            "failed_count": len(failed),
            "deleted": deleted,
            "failed": failed
        }
    except Exception as e:
        logger.error(f"Batch delete error: {e}")
        raise HTTPException(status_code=500, detail=str(e))


