@app.put("/api/settings")
def update_settings(request: SettingsUpdateRequest):
    """更新系统设置"""
    if not load_settings:
        raise HTTPException(status_code=500, detail="Settings module not available")

    try:
        # 加载当前设置
        current = load_settings()

        # 如果API Key是遮蔽的（包含****），则保持原值
        new_dashscope = request.dashscope_api_key
        new_deepseek = request.deepseek_api_key
        new_openrouter = request.openrouter_api_key
        new_doubao = request.doubao_api_key
        new_kimi = request.kimi_api_key
        new_tikhub = request.tikhub_api_key
        new_siliconflow = request.siliconflow_api_key
        new_metaso = request.metaso_api_key

        if "****" in new_dashscope:
            new_dashscope = current.dashscope_api_key
        if "****" in new_deepseek:
            new_deepseek = current.deepseek_api_key
        if "****" in new_openrouter:
            new_openrouter = current.openrouter_api_key
        if "****" in new_doubao:
            new_doubao = current.doubao_api_key
        if "****" in new_kimi:
            new_kimi = current.kimi_api_key
        if "****" in new_tikhub:
            new_tikhub = current.tikhub_api_key
        if "****" in new_siliconflow:
            new_siliconflow = current.siliconflow_api_key
        if "****" in new_metaso:
            new_metaso = current.metaso_api_key

        # 创建新设置
        # 🔴 [BH-011 · 2026-09-05] 从 `current` **复制**,不再从零重建。
        #
        #    原来这里是 `SystemSettings(...)` 加一份**手工维护的 68 个 kwarg 清单**;
        #    模型有 76 个字段,清单从没提到的 8 个于是取**类默认值**,
        #    再被 `save_settings()` 的整文件 `json.dump`(无 merge)覆盖到盘上 ——
        #    每次「保存成功」都在静默重置它们,而 HTTP 仍返回 success。
        #    丢的含 `media_balance_*`(fail-closed 灰度闸唯一读的开关)与两个凭据,
        #    而 settings.json 是它们**唯一的写入方** —— 没有东西会写回来。
        #
        #    🔴 机理**不是** pydantic `extra='ignore'`(BUG_HUNT 报告的归因):
        #    把 extra 改成 allow/forbid 一个都救不了,因为构造调用里根本没有它们。
        #    `extra='ignore'` 只解释「为什么不报 422」,不解释「为什么值没了」。
        #
        #    `model_copy(update=…)` 让「没提到 = 保持原值」成为**语义默认**,
        #    手写清单从此不可能「漏一格 = 丢一格」。
        #    纯 `k=current.k` 的透传行已删除 —— 在这个语义下它们是冗余的,
        #    留着等于把成因(手写清单)又留了一半。
        new_settings = current.model_copy(update={
            "dashscope_api_key": new_dashscope,
            "deepseek_api_key": new_deepseek,
            "openrouter_api_key": new_openrouter,
            "doubao_api_key": new_doubao,
            "doubao_endpoint_id": request.doubao_endpoint_id or current.doubao_endpoint_id,
            "kimi_api_key": new_kimi,
            "tikhub_api_key": new_tikhub,
            "siliconflow_api_key": new_siliconflow,
            "metaso_api_key": new_metaso,
            "diagnosis_model": request.diagnosis_model,
            "diagnosis_provider": request.diagnosis_provider,
            "diagnosis_tasks": request.diagnosis_tasks or current.diagnosis_tasks,
            "writing_model": request.writing_model,
            "writing_provider": request.writing_provider,
            "writing_tasks": request.writing_tasks or current.writing_tasks,
            "social_tasks": request.social_tasks or current.social_tasks,
            "employee_tasks": request.employee_tasks or current.employee_tasks,
            "style_ratios": request.style_ratios or current.style_ratios,
            "concurrent_writers": request.concurrent_writers,
            "default_article_count": request.default_article_count,
            "quote_cluster_mode": request.quote_cluster_mode,
            "quote_content_cost": request.quote_content_cost,
            "quote_media_cost": request.quote_media_cost,
            "quote_operation_cost": request.quote_operation_cost,
            "quote_markup_ratio": request.quote_markup_ratio,
            "quote_ai_reference_count": request.quote_ai_reference_count,
            "quote_default_target_share": request.quote_default_target_share,
            "quote_batch_concurrency": request.quote_batch_concurrency,
            "article_timeout": request.article_timeout,
            "article_retry_count": request.article_retry_count,
            "article_client_position": request.article_client_position,
            "article_client_coverage": request.article_client_coverage,
            "article_max_competitors": request.article_max_competitors,
            "diagnosis_ai_test_timeout": request.diagnosis_ai_test_timeout,
            "diagnosis_step_cache": request.diagnosis_step_cache,
            "diagnosis_metaso_size": request.diagnosis_metaso_size,
            "social_asr_timeout": request.social_asr_timeout,
            "social_asr_model": request.social_asr_model,
            "social_tikhub_timeout": request.social_tikhub_timeout,
            "kb_llm_clean_enabled": request.kb_llm_clean_enabled,
            "kb_llm_clean_model": request.kb_llm_clean_model,
            "kb_embedding_model": request.kb_embedding_model,
            "kb_rerank_enabled": request.kb_rerank_enabled,
            "llm_global_timeout": request.llm_global_timeout,
            "llm_global_max_retries": request.llm_global_max_retries,
            "llm_global_temperature": request.llm_global_temperature,
            "debug_mode": request.debug_mode,
            "sse_heartbeat_interval": request.sse_heartbeat_interval,
            "report_v3_enabled": request.report_v3_enabled,
            "report_v3_whitelist_user_ids": request.report_v3_whitelist_user_ids or [],
            "report_v3_auto_enrich": request.report_v3_auto_enrich,
            "llm_narrative_monthly_yuan": request.llm_narrative_monthly_yuan,
            "llm_narrative_max_concurrent": request.llm_narrative_max_concurrent,
            "llm_narrative_alert_yuan": request.llm_narrative_alert_yuan,
        })

        # 保存
        success = save_settings(new_settings)
        if success:
            # 重新加载缓存
            reload_settings()
            return {"success": True, "message": "设置已保存"}
        else:
            raise HTTPException(status_code=500, detail="保存设置失败")

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"更新设置失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


