@app.post("/api/distill/{diagnosis_id}")
async def run_distiller_for_keywords(diagnosis_id: int, request: Request):
    """
    运行DistillerPipeline提取关键词相关信息
    返回：目标人群、核心卖点、使用场景、竞品名称

    [audit P1 2026-06-10 IDOR 修] 原无 request + 无 require_diagnosis_access → 任意 insights 权限
    代理按自增 diagnosis_id 枚举可读+LLM 重写他人诊断 distilled_data。P0-8 鉴权 sweep 漏网端点,对齐兄弟端点。
    """
    try:
        from auth.brand_access import require_diagnosis_access
        # [audit #2 返修 E4] LLM 重写他人 distilled_data 的写端点 → NULL-brand fail-closed(不放行)
        require_diagnosis_access(request, diagnosis_id, allow_null=False)
        from db.diagnosis_db import get_connection
        from writing.distiller import DistillerPipeline
        import json

        # 1. 获取诊断数据
        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute('''
                SELECT id, brand_name, industry, raw_data_json, distilled_data
                FROM diagnosis_records WHERE id = %s
            ''', (diagnosis_id,))
            row = c.fetchone()

            if not row:
                conn.close()
                raise HTTPException(status_code=404, detail="诊断记录不存在")

            # 辅助函数：清理LLM返回的JSON（去除markdown代码块标记）
            def clean_json(raw: str) -> str:
                if not raw:
                    return '{}'
                text = raw.strip()
                if text.startswith('```json'):
                    text = text[7:]
                elif text.startswith('```'):
                    text = text[3:]
                if text.endswith('```'):
                    text = text[:-3]
                return text.strip()

            # 辅助函数：从蒸馏结果构建keyword_data
            def build_keyword_data(distilled: dict, diagnosis_data: dict = None) -> dict:
                client_profile = {}
                selling_points = {}
                competitor_analysis = {}

                try:
                    client_profile = json.loads(clean_json(distilled.get('client_profile', '{}')))
                except:
                    pass
                try:
                    selling_points = json.loads(clean_json(distilled.get('selling_points', '{}')))
                except:
                    pass
                try:
                    competitor_analysis = json.loads(clean_json(distilled.get('competitor_analysis', '{}')))
                except:
                    pass

                # V9: 优先从AI可见度测试中获取业务竞品，而非社媒账号
                competitor_names = []
                if diagnosis_data:
                    # 从诊断数据提取 ai_mentioned_brands
                    ai_brands = diagnosis_data.get('data', {}).get('ai_visibility', {}).get('detail_table', [])
                    brand_name = diagnosis_data.get('brand', diagnosis_data.get('brand_name', ''))

                    # V10: 增强品牌过滤 - 提取核心品牌词用于模糊匹配
                    brand_keywords = set()
                    if brand_name:
                        # 移除前缀（城市名等）和后缀（公司类型等），提取核心词
                        clean_name = brand_name
                        for prefix in ['上海', '北京', '深圳', '广州', '杭州']:
                            if clean_name.startswith(prefix):
                                clean_name = clean_name[len(prefix):]
                        for suffix in ['有限公司', '科技', '网络', '服务', '豪车租赁', '汽车租赁', '租车', '租赁']:
                            if clean_name.endswith(suffix):
                                clean_name = clean_name[:-len(suffix)]
                        # 添加核心词
                        if len(clean_name) >= 2:
                            brand_keywords.add(clean_name.lower())
                        brand_keywords.add(brand_name.lower())

                        # V11: 进一步提取前2-4个字作为核心标识符（如"骁马"）
                        for length in [2, 3, 4]:
                            if len(clean_name) > length:
                                short_key = clean_name[:length].lower()
                                brand_keywords.add(short_key)

                    seen = set()
                    for row in ai_brands:
                        for engine, res in row.get('results', {}).items():
                            for b in res.get('mentioned_brands', []):
                                if not b:
                                    continue
                                b_lower = b.lower()
                                # 检查是否是自己品牌的变体
                                is_self = any(kw in b_lower or b_lower in kw for kw in brand_keywords)
                                if not is_self and b not in seen:
                                    competitor_names.append(b)
                                    seen.add(b)

                # 回退到LLM分析的竞品
                if not competitor_names:
                    competitor_names = [
                        comp.get('name', '') for comp in competitor_analysis.get('competitors', [])
                    ]

                # V11: 使用场景直接从Stage 2蒸馏的use_scenarios字段获取
                use_scenarios = selling_points.get('use_scenarios', [])
                # 回退：如果没有use_scenarios，从key_technical_terms获取
                if not use_scenarios:
                    use_scenarios = selling_points.get('industry_terms', {}).get('key_technical_terms', [])

                # V12: 从Stage 1获取行业简称、目标城市、种子关键词
                industry_name = client_profile.get('industry', '')
                target_cities = client_profile.get('target_cities', [])
                seed_keywords = client_profile.get('seed_keywords', [])

                # 如果target_cities为空，从geographic_focus提取
                if not target_cities and client_profile.get('geographic_focus'):
                    geo = client_profile.get('geographic_focus', '')
                    if geo:
                        target_cities = [c.strip() for c in geo.replace('、', ',').split(',') if c.strip()]

                return {
                    "target_audience": client_profile.get('target_customer', ''),
                    "core_business": client_profile.get('core_business', ''),
                    "geographic_focus": client_profile.get('geographic_focus', ''),
                    "selling_points": [
                        sp.get('point', '') for sp in selling_points.get('selling_points', [])
                    ][:5],
                    "unique_value": selling_points.get('unique_value', ''),
                    "absolute_pain_point": selling_points.get('absolute_pain_point', ''),
                    "use_scenarios": use_scenarios[:5],
                    "competitor_names": competitor_names[:5],
                    # V12新增字段
                    "industry": industry_name,
                    "target_cities": target_cities[:5],
                    "seed_keywords": seed_keywords[:5]
                }

            # 2. 如果已有缓存，解析并返回（仍需从原始数据获取竞品）
            if row['distilled_data']:
                cached = json.loads(row['distilled_data'])
                # 需要传入原始诊断数据以提取AI竞品
                diagnosis_data_for_competitors = {}
                if row['raw_data_json']:
                    diagnosis_data_for_competitors = json.loads(row['raw_data_json'])
                conn.close()
                keyword_data = build_keyword_data(cached, diagnosis_data_for_competitors)
                return {
                    "success": True,
                    "cached": True,
                    "data": keyword_data
                }

            # 3. 构建诊断数据并运行蒸馏
            diagnosis_data = {}
            if row['raw_data_json']:
                diagnosis_data = json.loads(row['raw_data_json'])
            diagnosis_data['brand_name'] = row['brand_name']
            diagnosis_data['industry'] = row['industry']

            pipeline = DistillerPipeline(diagnosis_data)
            distilled = await pipeline.run()

            # 4. 使用共享函数构建关键词数据（传入诊断数据提取AI竞品）
            keyword_data = build_keyword_data(distilled, diagnosis_data)

            # 5. 缓存完整蒸馏结果
            c.execute('UPDATE diagnosis_records SET distilled_data = %s WHERE id = %s',
                      (json.dumps(distilled, ensure_ascii=False), diagnosis_id))
            conn.commit()
            conn.close()

            return {
                "success": True,
                "cached": False,
                "data": keyword_data
            }
        finally:
            try:
                conn.close()
            except Exception: pass

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"蒸馏失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


