class _CompetitorEntry(BaseModel):
    """单个竞品 entry"""
    name: str
    url: Optional[str] = None
    note: Optional[str] = None


class _BrandCompetitorsBody(BaseModel):
    """整体替换 brand 竞品列表(代理增删改 一次提交)"""
    competitors: List[_CompetitorEntry]


@app.get("/api/brands/{brand_id}/competitors")
def api_get_brand_competitors(brand_id: int, request: Request):
    """C2.2 · 获取 brand 竞品列表(Module 4 真竞品分析数据源)"""
    try:
        from auth.brand_access import require_brand_access
        require_brand_access(request, brand_id)

        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("SELECT competitors_jsonb FROM brands WHERE id = %s", (brand_id,))
            row = cur.fetchone()
        finally:
            conn.close()
        if not row:
            raise HTTPException(status_code=404, detail="brand 不存在")
        comps = row.get("competitors_jsonb") or []
        if isinstance(comps, str):
            try:
                comps = json.loads(comps)
            except (ValueError, TypeError):
                comps = []
        return {"success": True, "brand_id": brand_id, "competitors": comps or []}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[brand-competitors GET] brand={brand_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/api/brands/{brand_id}/competitors")
def api_set_brand_competitors(brand_id: int, body: _BrandCompetitorsBody, request: Request):
    """C2.2 · 替换 brand 竞品列表 · 元指令 16 · 限 5 个

    M2 §Epic 4:代理建档 3-5 个核心竞品 · Module 4 拉真数据替 search_citations 启发式
    """
    try:
        from auth.brand_access import require_brand_access
        require_brand_access(request, brand_id)

        # 限 5 个 + 去空 name
        comps = [
            {"name": c.name.strip(), "url": (c.url or "").strip() or None, "note": (c.note or "").strip() or None}
            for c in body.competitors
            if c.name and c.name.strip()
        ][:5]
        from datetime import datetime as _dt
        for c in comps:
            c["added_at"] = _dt.now().isoformat()

        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute(
                "UPDATE brands SET competitors_jsonb = %s WHERE id = %s",
                (json.dumps(comps, ensure_ascii=False), brand_id),
            )
            conn.commit()
            affected = cur.rowcount
        finally:
            conn.close()
        if not affected:
            raise HTTPException(status_code=404, detail="brand 不存在")

        # audit_log
        try:
            from db.auth_db import create_audit_log
            user = getattr(request.state, "user", None) or {}
            create_audit_log(
                user_id=user.get("id"),
                username=user.get("username") or user.get("nickname"),
                action="brand_competitors_update",
                module="brand",
                entity_type="brand",
                entity_id=brand_id,
                summary=f"更新竞品列表 · {len(comps)} 个",
                after={"brand_id": brand_id, "competitors": comps},
            )
        except Exception:
            pass

        return {"success": True, "brand_id": brand_id, "competitors": comps, "count": len(comps)}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[brand-competitors PUT] brand={brand_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/quotes/{quote_id}/median-check")
def api_quote_median_check(quote_id: int, request: Request):
    """M1b M3 · 报价审计 · 建议模式(非自动降价)

    CTO-15.9 2026-04-25 · 复用 tools.industry_median.industry_median_check
    前端在 quote preview 阶段拉本 endpoint · 展示"偏差 ±X%"/"中位 ¥Y"/"建议降档"

    返 {level, industry_median_p50/p90, deviation_pct, suggestion, single_kw_outliers}
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        quote = get_quote(quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        industry = (quote.get("industry") or "").strip()
        total_monthly = float(quote.get("monthly_price") or 0)

        # 拉关键词 + 单价
        keywords = get_keywords_by_quote(quote_id)
        entries: list[dict] = []
        for kw in keywords or []:
            price = (kw.get("selling_price") or kw.get("standard_price")
                     or kw.get("final_price") or kw.get("price") or 0)
            try:
                entries.append({"keyword": kw.get("keyword", ""), "price": float(price)})
            except (TypeError, ValueError):
                continue

        from tools.industry_median import industry_median_check
        result = industry_median_check(
            total_monthly=total_monthly,
            industry=industry,
            keyword_entries=entries,
        )
        return {
            "quote_id": quote_id,
            "industry": industry,
            "total_monthly": int(total_monthly),
            **result,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[median-check] quote={quote_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class _MedianDecisionBody(BaseModel):
    """A.4 · auditor 拒绝率埋点 body"""
    accepted: bool
    reason: Optional[str] = None
    suggested_cap: Optional[int] = None


@app.post("/api/quotes/{quote_id}/median-check/decision")
def api_quote_median_check_decision(
    quote_id: int, body: _MedianDecisionBody, request: Request
):
    """A.4 (CTO-15.9 session 3 · 2026-04-25) · 代理对 auditor 建议的决策埋点

    Banner 上"采纳建议 / 我已审阅(拒绝)"按钮调用本端点 · 写 audit_logs:
      action='auditor_suggestion' · entity_type='quote' · entity_id=quote_id
      after_snapshot={industry, total_monthly, level, deviation_pct,
                      suggested_cap, accepted, reason}

    M1b 监督机制:
      /api/admin/auditor/rejection-rate 聚合本表 · 拒绝率 > 40% 的行业
      → 触发 prompt 调优 · industry_median seed 校准
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        quote = get_quote(quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        industry = (quote.get("industry") or "").strip()
        total_monthly = float(quote.get("monthly_price") or 0)

        # 复算 median 拿当时建议的级别 + p50/p90 (审计需要)
        from tools.industry_median import (
            get_industry_median, describe_price_health, describe_price_deviation,
        )
        median = get_industry_median(industry)
        level = describe_price_health(total_monthly, industry)
        deviation_pct = describe_price_deviation(total_monthly, industry)

        user = getattr(request.state, "user", None) or {}

        from db.auth_db import create_audit_log
        create_audit_log(
            user_id=user.get("id"),
            username=user.get("username") or user.get("nickname"),
            action="auditor_suggestion",
            module="quote",
            entity_type="quote",
            entity_id=quote_id,
            summary=(
                f"{'采纳' if body.accepted else '拒绝'}行业中位审计建议 · "
                f"{industry or '未知行业'} · level={level} · 偏差 {deviation_pct:+d}%"
            ),
            after={
                "industry": industry,
                "total_monthly": int(total_monthly),
                "level": level,
                "industry_median_p50": median["p50"],
                "industry_median_p90": median["p90"],
                "deviation_pct": deviation_pct,
                "auditor_suggested_cap": body.suggested_cap,
                "accepted": body.accepted,
                "reason": body.reason,
            },
            ip_address=(
                (request.headers.get("X-Forwarded-For") or "").split(",")[0].strip()
                or (request.client.host if request.client else None)
            ),
        )
        return {"success": True, "logged": True}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[median-decision] quote={quote_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== C4.1 (CTO-15.9 session 3 · 2026-04-25 · M1b §P1.3b 主题包+交付映射) ==========

@app.get("/api/quotes/{quote_id}/cluster-delivery")
def api_quote_cluster_delivery(quote_id: int, request: Request):
    """C4.1 · 拉报价 quote 的所有主题包 + 交付映射(平台/周期/包价)

    用途:报价页代理审核 / 客户门户 / Module 4 报告
    返:{ clusters: [...], summary: {cluster_count, total_articles, total_price, total_weeks, all_platforms} }
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)

        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT id, cluster_name, business_tag, city_tag, scenario_tag, description,
                       core_keyword_count, covered_keyword_count,
                       price_entry, price_standard, price_flagship,
                       articles_entry, articles_standard, articles_flagship,
                       full_price_entry, full_price_standard, full_price_flagship,
                       is_selected,
                       platforms_jsonb, weeks_to_complete, delivery_notes
                FROM keyword_clusters
                WHERE quote_id = %s AND (is_selected IS NOT FALSE)
                ORDER BY id ASC
            """, (quote_id,))
            rows = cur.fetchall()
            if not rows:
                cur.execute("""
                    SELECT -MIN(ck.id) AS id,
                           COALESCE(NULLIF(ck.category, ''), '核心关键词交付') AS cluster_name,
                           COALESCE(NULLIF(ck.category, ''), '通用') AS business_tag,
                           NULL::TEXT AS city_tag,
                           '通用'::TEXT AS scenario_tag,
                           '由已确认关键词自动汇总的交付兜底包' AS description,
                           COUNT(*) AS core_keyword_count,
                           COUNT(*) AS covered_keyword_count,
                           0 AS price_entry,
                           COALESCE(SUM(COALESCE(NULLIF(ck.final_price, 0), NULLIF(ck.selling_price, 0), NULLIF(ck.base_price, 0), 0)), 0)::INTEGER AS price_standard,
                           0 AS price_flagship,
                           0 AS articles_entry,
                           COALESCE(SUM(COALESCE(ck.required_articles, 1)), 0)::INTEGER AS articles_standard,
                           0 AS articles_flagship,
                           0 AS full_price_entry,
                           COALESCE(SUM(COALESCE(NULLIF(ck.final_price, 0), NULLIF(ck.selling_price, 0), NULLIF(ck.base_price, 0), 0)), 0)::INTEGER AS full_price_standard,
                           0 AS full_price_flagship,
                           TRUE AS is_selected,
                           '[]'::jsonb AS platforms_jsonb,
                           NULL::INTEGER AS weeks_to_complete,
                           NULL::TEXT AS delivery_notes
                    FROM confirmed_keywords ck
                    WHERE ck.quote_id = %s AND (ck.is_core IS NOT FALSE)
                    GROUP BY NULLIF(ck.category, '')
                    ORDER BY cluster_name ASC
                """, (quote_id,))
                rows = cur.fetchall()
        finally:
            conn.close()

        clusters = []
        for r in rows or []:
            d = dict(r)
            # 解析 JSONB
            if isinstance(d.get("platforms_jsonb"), str):
                try:
                    d["platforms_jsonb"] = json.loads(d["platforms_jsonb"])
                except (ValueError, TypeError):
                    d["platforms_jsonb"] = []
            clusters.append(d)

        # 启发式填默认 platforms / weeks(若 DB 空)
        from services.cluster_delivery_mapping import (
            apply_delivery_defaults, format_delivery_table, get_cluster_delivery_summary,
        )
        for c in clusters:
            apply_delivery_defaults(c)

        return {
            "success": True,
            "quote_id": quote_id,
            "clusters": clusters,
            "summary": get_cluster_delivery_summary(clusters),
            "delivery_table_md": format_delivery_table(clusters),
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[cluster-delivery] quote={quote_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class _ClusterDeliveryUpdateBody(BaseModel):
    """单 cluster 的交付字段更新 body"""
    platforms_jsonb: Optional[List[str]] = None
    weeks_to_complete: Optional[int] = None
    delivery_notes: Optional[str] = None


@app.put("/api/clusters/{cluster_id}/delivery")
def api_cluster_delivery_update(cluster_id: int, body: _ClusterDeliveryUpdateBody, request: Request):
    """C4.1 · 代理调整某主题包的交付映射(平台/周期/备注)

    元指令 16:代理操作 · 客户不直接改
    需 require_quote_access 鉴权(通过 cluster.quote_id)
    """
    try:
        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("SELECT quote_id FROM keyword_clusters WHERE id = %s", (cluster_id,))
            row = cur.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="cluster 不存在")
            qid = row.get("quote_id")
        finally:
            conn.close()

        from auth.brand_access import require_quote_access
        if qid:
            require_quote_access(request, qid)

        sets = []
        params = []
        if body.platforms_jsonb is not None:
            # 限 5 平台
            cleaned = [p.strip() for p in body.platforms_jsonb if p and p.strip()][:5]
            sets.append("platforms_jsonb = %s")
            params.append(json.dumps(cleaned, ensure_ascii=False))
        if body.weeks_to_complete is not None:
            wks = max(1, min(int(body.weeks_to_complete), 52))
            sets.append("weeks_to_complete = %s")
            params.append(wks)
        if body.delivery_notes is not None:
            sets.append("delivery_notes = %s")
            params.append(body.delivery_notes[:500])
        if not sets:
            return {"success": True, "no_change": True}

        sets.append("updated_at = NOW()")
        params.append(cluster_id)
        sql = f"UPDATE keyword_clusters SET {', '.join(sets)} WHERE id = %s"

        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute(sql, params)
            conn.commit()
        finally:
            conn.close()
        return {"success": True, "cluster_id": cluster_id}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[cluster-delivery PUT] cluster={cluster_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


