class _FactCheckBody(BaseModel):
    """文章事实核验 body"""
    content: str
    brand_id: Optional[int] = None  # 给定时拉真客户名单做 fake_case 核验


@app.post("/api/articles/fact-check")
def api_article_fact_check(body: _FactCheckBody, request: Request):
    """C3.2 · 文章事实核验(P1.5 启发式骨架)

    返:{has_risks, risks, summary, high/medium/low_count}
    无 brand_id 时跳过 fake_case 核验
    LLM cross-check 留 TODO(老板批 API 成本后启)
    """
    try:
        if not body.content or not body.content.strip():
            return {"has_risks": False, "risks": [], "summary": "空文章"}

        real_names: list[str] = []
        if body.brand_id:
            try:
                from auth.brand_access import require_brand_access
                require_brand_access(request, body.brand_id)
                from db.diagnosis_db import get_connection as _gc
                conn = _gc()
                try:
                    cur = conn.cursor()
                    # 拉同一 brand 主体的所有 quote brand_name(简化:用 brand.name 自身 + 已有客户案例)
                    cur.execute(
                        "SELECT DISTINCT brand_name FROM quotes WHERE brand_id = %s",
                        (body.brand_id,),
                    )
                    real_names = [r["brand_name"] for r in cur.fetchall() if r.get("brand_name")]
                finally:
                    conn.close()
            except HTTPException:
                raise
            except Exception:
                real_names = []

        from services.article_fact_check import check_article
        result = check_article(body.content, real_client_names=real_names)
        return {"success": True, **result}
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[fact-check] 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== C3.2 (CTO-15.9 session 3 · 2026-04-25 · M2 §P1.4 诊断 19 次趋势图) ==========

@app.get("/api/brands/{brand_id}/diagnosis-history")
def api_brand_diagnosis_history(brand_id: int, request: Request, limit: int = 19):
    """C3.2 · 拉某 brand 历史诊断 score 时序(默认最多 19 次 · M2 §P1.4)

    用途:DiagnosisReport / Dashboard / portal 渲染 score 趋势线图
    返:[{date, total_score, level, diagnosis_id}, ...] 升序(便于 chart x 轴)
    """
    try:
        from auth.brand_access import require_brand_access
        require_brand_access(request, brand_id)
        limit = max(1, min(limit, 100))

        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT id, created_at, total_score, level
                FROM diagnosis_records
                WHERE brand_id = %s AND total_score IS NOT NULL
                  AND (result_visibility IS NULL OR result_visibility = 'published')
                ORDER BY created_at DESC
                LIMIT %s
            """, (brand_id, limit))
            rows = cur.fetchall()
            from auth.brand_access import filter_organization_artifact_rows
            rows = filter_organization_artifact_rows(request, "diagnosis", rows)
        finally:
            conn.close()

        items = []
        for r in (rows or [])[::-1]:  # 反转 · 升序便于 chart
            items.append({
                "diagnosis_id": r.get("id"),
                "date": r.get("created_at").isoformat() if r.get("created_at") else None,
                "total_score": int(r.get("total_score") or 0),
                "level": r.get("level") or "",
            })

        # 计算趋势 stats
        scores = [it["total_score"] for it in items]
        stats = {
            "count": len(items),
            "min": min(scores) if scores else 0,
            "max": max(scores) if scores else 0,
            "avg": round(sum(scores) / len(scores), 1) if scores else 0,
            "delta_first_to_last": scores[-1] - scores[0] if len(scores) >= 2 else 0,
        }
        return {
            "success": True,
            "brand_id": brand_id,
            "items": items,
            "stats": stats,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(f"[diagnosis-history] brand={brand_id} 异常: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== B2.4 (CTO-15.9 session 3 · 2026-04-25 · M1a §8 客户门户续费 CTA) ==========

class _PortalRenewRequestBody(BaseModel):
    """客户门户续费意向 body · 通过 portal_token 鉴权"""
    quote_id: int
    note: Optional[str] = None  # 客户备注(可选 · 续费偏好/特殊需求)


@app.post("/api/portal/renew-request")
def api_portal_renew_request(body: _PortalRenewRequestBody, request: Request):
    """B2.4 · 客户门户"申请续费"按钮入口

    元指令 16:客户不登录 · 不能直接下单(代理收佣金体系)
    流程:
      1. 验证 portal_token 对应的 quote_id 与 body.quote_id 一致
      2. 写 audit_logs(action='renew_request' · entity=quote · 含 brand/客户备注)
      3. 平台内部派发处理通知
      4. 客户端仅确认平台已受理
    """
    try:
        # 鉴权:portal token(无 user state · 走 portal_token header)
        auth_header = request.headers.get("Authorization", "")
        token = auth_header.replace("Bearer ", "").strip() if auth_header.startswith("Bearer ") else ""
        if not token:
            raise HTTPException(status_code=401, detail="缺 portal token")

        from db.monitoring_db import verify_client_token
        valid_quote_id = verify_client_token(token)
        if not valid_quote_id:
            raise HTTPException(status_code=401, detail="无效或已过期 token")
        if int(valid_quote_id) != int(body.quote_id):
            raise HTTPException(status_code=403, detail="token 与 quote_id 不匹配")

        # 拉 quote · 找 owner_user_id 通知代理
        quote = get_quote(body.quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        from db.diagnosis_db import get_connection as _gc
        conn = _gc()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT b.owner_user_id, b.name as brand_name
                FROM quotes q JOIN brands b ON q.brand_id = b.id
                WHERE q.id = %s
            """, (body.quote_id,))
            row = cur.fetchone()
            agent_uid = row.get("owner_user_id") if row else None
            brand_name = row.get("brand_name") or quote.get("brand_name") or "客户"
        finally:
            conn.close()

        # 写 audit_log
        from db.auth_db import create_audit_log
        create_audit_log(
            action="renew_request",
            module="portal",
            entity_type="quote",
            entity_id=body.quote_id,
            summary=f"客户门户申请续费 · {brand_name} · quote_id={body.quote_id}",
            after={
                "quote_id": body.quote_id,
                "brand_id": quote.get("brand_id"),
                "brand_name": brand_name,
                "agent_user_id": agent_uid,
                "client_note": body.note,
                "source": "portal_token",
                "service_end_date": str(quote.get("service_end_date") or ""),
            },
        )

        # 通知代理
        if agent_uid:
            from datetime import datetime, timezone
            from services.notification_events import NotificationEventType, RecipientKind
            from services.notification_outbox import enqueue_user_notification_event_durable

            enqueue_user_notification_event_durable(
                recipient_user_id=int(agent_uid),
                recipient_kind=RecipientKind.AGENT,
                event_type=NotificationEventType.RENEWAL_REQUESTED,
                business_id=f"quote:{int(body.quote_id)}",
                terminal_state="requested",
                facts={
                    "business_no": f"QUOTE-{int(body.quote_id)}",
                    "status": "客户已提交续费申请",
                    "occurred_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                    "summary": "请在客户报价页面准备续费方案。",
                },
            )

        return {
            "success": True,
            "message": "OmniRank 平台已收到续费申请，将尽快处理",
            "request_received": True,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("[portal-renew] request failed for quote_id=%s", body.quote_id)
        raise HTTPException(
            status_code=500,
            detail="续费申请暂时无法提交，请稍后重试",
        ) from e


@app.get("/api/quotes/{quote_id}")
def api_get_quote(quote_id: int, request: Request):
    """获取报价单详情

    M1b 扩展(CTO-15.17 · 2026-04-26):
      - 给每个 keyword 补 layer / layer_label_zh / layer_reason / layer_confidence /
        expected_user_intent / why_this_keyword(优先用 confirmed_keywords.layer 真值
        · 没有则 on-the-fly 启发式分类 · 微秒级 · 不调 LLM 不扣费)
      - 返 theme_packages:
          · 优先 keyword_clusters 表(post-confirm 真值 · source='manual')
          · 兜底 build_theme_packages_from_keywords(fresh quote · source='fallback')
      - 返 layer_distribution:6 层关键词数统计 · 给前端 6 层矩阵 ratio 用
      - 不破坏旧字段 · 不改扣费 · 老 quote 老前端零感知
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        quote = get_quote(quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        try:
            from services.quote_numeric_repair import repair_quote_numeric_fields
            if (not quote.get("monthly_price") or not quote.get("total_articles")) and quote.get("markdown"):
                repaired = repair_quote_numeric_fields(quote_id, quote)
                if repaired.get("monthly_price"):
                    quote["monthly_price"] = repaired["monthly_price"]
                if repaired.get("total_articles"):
                    quote["total_articles"] = repaired["total_articles"]
        except Exception as _repair_err:
            logger.warning(f"[quote-detail-repair] quote_id={quote_id} skipped: {_repair_err}")

        # 获取关联的关键词
        keywords = get_keywords_by_quote(quote_id)

        # 回退：如果数据库没有关键词记录（旧报价未保存），从markdown中解析
        if not keywords and quote.get("markdown"):
            keywords = _parse_keywords_from_markdown(quote["markdown"])

        # 从价格缓存中补充三套餐单价（供前端显示）
        if keywords and quote.get("brand_name"):
            try:
                from db.diagnosis_db import get_cached_keyword_prices
                kw_names = [k.get("keyword", "") for k in keywords if k.get("keyword")]
                cached = get_cached_keyword_prices(quote["brand_name"], kw_names)
                for kw in keywords:
                    kw_name = kw.get("keyword", "")
                    if kw_name in cached:
                        c = cached[kw_name]
                        kw["entry_price"] = c.get("entry_price", 0)
                        kw["standard_price"] = c.get("standard_price", 0)
                        kw["flagship_price"] = c.get("flagship_price", 0)
            except Exception:
                pass  # 缓存查询失败不影响主流程

        # 获取关联的选题
        topics = get_topics_by_quote(quote_id)

        # ========== M1b · 6 层 + 主题包扩展 ==========
        layer_distribution_counts: dict[str, int] = {}
        theme_packages: list[dict] = []
        try:
            brand_context = _build_brand_context_for_quote(quote)
            keywords = _enrich_keywords_with_layer(keywords, brand_context)
            theme_packages, layer_distribution_counts = _build_quote_theme_packages(
                quote, keywords, brand_context
            )
        except Exception as _m1b_err:
            # M1b 扩展失败不破坏主响应 · 老前端不感知
            logger.warning(f"[M1b] 6 层 / 主题包扩展失败 quote_id={quote_id}: {_m1b_err}")

        return {
            "quote": quote,
            "keywords": keywords,
            "topics": topics,
            # M1b 新增字段(老前端忽略 · 新前端 M3 方案页 消费)
            "theme_packages": theme_packages,
            "layer_distribution": layer_distribution_counts,
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取报价详情失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== M1b 辅助:6 层 + 主题包(CTO-15.17 · 2026-04-26)==========

def _build_brand_context_for_quote(quote: dict) -> dict:
    """从 quote 行 + brands 表取 brand_name/industry/city/competitors"""
    brand_name = (quote.get("brand_name") or "").strip()
    industry = (quote.get("industry") or "").strip()
    city = (quote.get("city") or "").strip()
    competitors: list[str] = []
    brand_id = quote.get("brand_id")
    if brand_id:
        try:
            from db.diagnosis_db import get_connection as _gc
            _conn = _gc()
            try:
                _cur = _conn.cursor()
                _cur.execute(
                    "SELECT competitors_jsonb FROM brands WHERE id = %s",
                    (brand_id,),
                )
                _row = _cur.fetchone()
                if _row:
                    raw = _row.get("competitors_jsonb") if isinstance(_row, dict) else _row[0]
                    if isinstance(raw, str):
                        try:
                            raw = json.loads(raw)
                        except (ValueError, TypeError):
                            raw = []
                    if isinstance(raw, list):
                        for c in raw:
                            if isinstance(c, dict):
                                n = (c.get("name") or "").strip()
                                if n:
                                    competitors.append(n)
                            elif isinstance(c, str):
                                n = c.strip()
                                if n:
                                    competitors.append(n)
            finally:
                try:
                    _conn.close()
                except Exception:
                    pass
        except Exception:
            pass  # 取竞品失败不影响 · 留空
    return {
        "brand_name": brand_name,
        "industry": industry,
        "city": city,
        "competitors": competitors,
    }


def _enrich_keywords_with_layer(keywords: list[dict], brand_context: dict) -> list[dict]:
    """给 keywords 数组每条补 layer 系列字段(在线分类 · 优先用 confirmed_keywords.layer 持久化值)"""
    if not keywords:
        return []
    from services.keyword_layer_classifier import (
        classify_keyword_layers_batch as _classify_batch,
        LAYER_LABEL_ZH as _LAYER_LABEL_ZH,
        classify_keyword_layer as _classify_one,
    )
    # 第一次 pass · 找出哪些 keyword 已有持久化的 layer(从 confirmed_keywords 来的)
    needs_classify: list[str] = []
    for kw in keywords:
        if not isinstance(kw, dict):
            continue
        if not kw.get("layer"):
            name = (kw.get("keyword") or "").strip()
            if name:
                needs_classify.append(name)
    # 第二次 pass · 批量分类剩余
    layer_map: dict[str, dict] = {}
    if needs_classify:
        layer_map = _classify_batch(
            needs_classify,
            brand_name=brand_context.get("brand_name", ""),
            city=brand_context.get("city", ""),
            industry=brand_context.get("industry", ""),
            competitors=brand_context.get("competitors") or [],
        )
    # 第三次 pass · 写回字段(label_zh / reason / confidence / why)
    enriched: list[dict] = []
    for kw in keywords:
        if not isinstance(kw, dict):
            continue
        out = dict(kw)
        existing_layer = (out.get("layer") or "").strip()
        if existing_layer in _LAYER_LABEL_ZH:
            # 已持久化 · 用它 · reason/confidence 保 confirmed_keywords 的值(兜底再分类)
            out["layer_label_zh"] = _LAYER_LABEL_ZH[existing_layer]
            if not out.get("layer_reason") or not out.get("layer_confidence"):
                rr = _classify_one(
                    out.get("keyword", ""),
                    brand_name=brand_context.get("brand_name", ""),
                    city=brand_context.get("city", ""),
                    industry=brand_context.get("industry", ""),
                    competitors=brand_context.get("competitors") or [],
                )
                out.setdefault("layer_reason", rr["reason"])
                out.setdefault("layer_confidence", rr["confidence"])
                out.setdefault("expected_user_intent", rr["expected_user_intent"])
                out.setdefault("why_this_keyword", rr["why_this_keyword"])
            else:
                # 持久化已有 reason/confidence · expected_user_intent/why 仍要补
                rr = _classify_one(
                    out.get("keyword", ""),
                    brand_name=brand_context.get("brand_name", ""),
                    city=brand_context.get("city", ""),
                    industry=brand_context.get("industry", ""),
                    competitors=brand_context.get("competitors") or [],
                )
                out.setdefault("expected_user_intent", rr["expected_user_intent"])
                out.setdefault("why_this_keyword", rr["why_this_keyword"])
        else:
            # 没持久化 · 用批量分类结果 · 旧 quote / fresh quote 都走这里
            name = (out.get("keyword") or "").strip()
            res = layer_map.get(name)
            if res:
                out["layer"] = res["layer"]
                out["layer_label_zh"] = res["layer_label_zh"]
                out["layer_reason"] = res["reason"]
                out["layer_confidence"] = res["confidence"]
                out["expected_user_intent"] = res["expected_user_intent"]
                out["why_this_keyword"] = res["why_this_keyword"]
            else:
                # 极端兜底
                out.setdefault("layer", "category_grab")
                out.setdefault("layer_label_zh", _LAYER_LABEL_ZH["category_grab"])
        enriched.append(out)
    return enriched


def _build_quote_theme_packages(
    quote: dict, keywords: list[dict], brand_context: dict
) -> tuple[list[dict], dict[str, int]]:
    """
    构建 theme_packages + layer_distribution

    优先级:
      1. keyword_clusters 表有记录 → serialize_keyword_clusters_as_packages(source='manual')
      2. 没记录(fresh quote)→ build_theme_packages_from_keywords(source='fallback')
    """
    from services.theme_package_builder import (
        build_theme_packages_from_keywords as _build_fallback,
        serialize_keyword_clusters_as_packages as _serialize_clusters,
    )
    from services.keyword_layer_classifier import layer_distribution as _layer_dist

    quote_id = quote.get("id")
    cluster_rows: list[dict] = []
    if quote_id:
        try:
            from db.diagnosis_db import get_connection as _gc
            _conn = _gc()
            try:
                _cur = _conn.cursor()
                _cur.execute(
                    "SELECT * FROM keyword_clusters WHERE quote_id = %s ORDER BY id",
                    (quote_id,),
                )
                cluster_rows = [dict(r) for r in _cur.fetchall()]
            finally:
                try:
                    _conn.close()
                except Exception:
                    pass
        except Exception:
            cluster_rows = []

    packages: list[dict]
    if cluster_rows:
        packages = _serialize_clusters(cluster_rows, quote_keywords=keywords)
    else:
        # 取诊断弱点(可选 · 给 evidence_reason 加引用)
        diag_summary = None
        diag_id = quote.get("diagnosis_id")
        if diag_id:
            try:
                from db.diagnosis_db import get_diagnosis_by_id
                diag = get_diagnosis_by_id(diag_id)
                if diag:
                    weak: list[str] = []
                    sug = diag.get("suggestions")
                    if isinstance(sug, str):
                        try:
                            sug = json.loads(sug)
                        except (ValueError, TypeError):
                            sug = None
                    if isinstance(sug, dict):
                        for it in (sug.get("high_priority") or [])[:2]:
                            if isinstance(it, dict) and it.get("dimension"):
                                weak.append(str(it["dimension"]))
                    if weak:
                        diag_summary = {"weak_dimensions": weak}
            except Exception:
                diag_summary = None

        # 把 enriched keywords 喂给 builder(它需要 layer + standard_price 字段)
        enriched_for_builder: list[dict] = []
        for k in keywords:
            if not isinstance(k, dict):
                continue
            layer = k.get("layer")
            if not layer:
                continue
            enriched_for_builder.append(
                {
                    "keyword": k.get("keyword", ""),
                    "layer": layer,
                    "layer_confidence": k.get("layer_confidence") or "medium",
                    "standard_price": k.get("standard_price") or k.get("final_price") or 0,
                    "entry_price": k.get("entry_price") or 0,
                    "flagship_price": k.get("flagship_price") or 0,
                    "required_articles": k.get("required_articles") or 1,
                }
            )
        packages = _build_fallback(
            enriched_for_builder,
            brand_context=brand_context,
            diagnosis_summary=diag_summary,
            total_articles=int(quote.get("total_articles") or 0),
            source="fallback",
        )

    # 6 层关键词数统计
    layer_counts_raw: dict = {}
    for k in keywords:
        if not isinstance(k, dict):
            continue
        layer = k.get("layer")
        if layer:
            layer_counts_raw[layer] = layer_counts_raw.get(layer, 0) + 1
    return packages, layer_counts_raw


# ========== 服务期管理API ==========

@app.post("/api/quotes/{quote_id}/service-period")
async def set_service_period(quote_id: int, request: Request):
    """设置报价单的服务期"""
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        body = await request.json()
        # [服务期 SSOT 2026-08-06 §1.2] 服务月数不再 `body.get("service_months", 1)` ——
        #   调用方没带月数时静默按 1 个月改写合同期,是"两钟打架"的写入侧成因之一。
        #   现在缺失/非法 → 400 进人工;换算统一走 resolve_activation_period。
        from services.service_period import (
            ServicePeriodError,
            normalize_service_months,
            resolve_activation_period,
        )
        service_start_date = body.get("service_start_date")  # YYYY-MM-DD or null=today
        try:
            service_months = normalize_service_months(body.get("service_months"))
            start, end = resolve_activation_period(
                start_date=service_start_date, months=service_months
            )
        except ServicePeriodError as _spe:
            raise HTTPException(400, _spe.user_message)

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute("""
                UPDATE quotes
                SET service_start_date = %s, service_end_date = %s,
                    service_months = %s, service_status = 'active'
                WHERE id = %s
            """, (start, end, service_months, quote_id))
            conn.commit()

            # 同步 client_access_tokens 有效期
            cur.execute("""
                UPDATE client_access_tokens SET expires_at = %s
                WHERE quote_id = %s AND is_active = 1
            """, (end, quote_id))
            conn.commit()
            conn.close()

            # M3 任务 2.3: audit_logs 写入(报价 4 状态独立审计)
            try:
                from db.auth_db import create_audit_log
                _user_sp = getattr(request.state, "user", None) or {}
                create_audit_log(
                    user_id=_user_sp.get("user_id"),
                    username=_user_sp.get("username"),
                    action="quote_service_period",
                    module="quotes",
                    entity_type="quote",
                    entity_id=quote_id,
                    summary=f"调整服务期 · {start.isoformat()} → {end.isoformat()} · {service_months} 月",
                    after={
                        "service_start_date": start.isoformat(),
                        "service_end_date": end.isoformat(),
                        "service_months": service_months,
                        "service_status": "active",
                    },
                    ip_address=getattr(request.client, "host", None) if request.client else None,
                )
            except Exception as audit_err:
                logger.warning(f"[audit] quote_service_period fail quote={quote_id}: {audit_err}")

            return {
                "status": "success",
                "service_start_date": start.isoformat(),
                "service_end_date": end.isoformat(),
                "service_months": service_months
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"设置服务期失败: {e}")
        return {"status": "error", "error": str(e)}


@app.get("/api/service/overview")
def get_service_overview():
    """获取所有客户的服务状态总览"""
    try:
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute("""
                SELECT q.id, q.brand_name, q.tier, q.monthly_price, q.paid_amount,
                       q.status, q.service_start_date, q.service_end_date,
                       q.service_months, q.service_status,
                       q.confirmed_at, q.paid_at,
                       b.id as brand_id, b.industry,
                       (SELECT COUNT(*) FROM confirmed_keywords ck WHERE ck.quote_id = q.id AND (ck.is_core IS NOT FALSE)) as keyword_count
                FROM quotes q
                LEFT JOIN brands b ON q.brand_id = b.id
                WHERE q.status IN ('confirmed', 'paid')
                ORDER BY q.service_end_date ASC NULLS LAST, q.id DESC
            """)
            rows = [dict(r) for r in cur.fetchall()]
            conn.close()

            # 计算服务状态 —— [服务期 SSOT 2026-08-06] 只读 service_end_date,不再有第二口钟
            from services.service_period import calendar_days_left as _sp_days_left

            # [§1.5 到期不静默] 因服务期被摘出自动监测轮换的客户 · 经营后台必须看得见
            try:
                from db.monitoring_db import get_service_period_blocked_clients
                _blocked = {
                    int(b["quote_id"]): b for b in get_service_period_blocked_clients()
                }
            except Exception as _b_err:
                logger.warning(f"[service/overview] 取被摘出轮换客户失败(不影响总览): {_b_err}")
                _blocked = {}

            for row in rows:
                signed = _sp_days_left(row.get("service_end_date"))
                if signed is None or not row.get("service_start_date"):
                    row["service_status_computed"] = "not_set"
                elif signed < 0:
                    row["service_status_computed"] = "expired"
                elif signed <= 7:
                    row["service_status_computed"] = "expiring"
                else:
                    row["service_status_computed"] = "active"
                row["service_days_left"] = signed  # 带符号 · 负 = 已过期 N 天

                _b = _blocked.get(int(row.get("id") or 0))
                # 🔴 [R9 · Codex 2026-08-17] 上一版只改了文案,**结构化字段照旧** ——
                #   `auto_monitoring_paused=true` 与真行为矛盾(dispatch 从不读 service_end_date,
                #   这些行其实都还在跑)。下游拿这个布尔去做统计/筛选,文案改了它们还是错的。
                #   ⇒ 字段按真行为对齐:日历过期 ≠ 暂停。
                #   保留同名字段但恒 False(不删:删了会让老前端 undefined 走别的分支);
                #   真实语义放进新字段,名字直说它是什么。
                row["auto_monitoring_paused"] = False
                row["service_calendar_expired"] = bool(_b)
                row["auto_monitoring_still_running"] = bool(_b)
                if _b:
                    # 提示铁律:不止说"停了",还要给出去哪儿把它弄好
                    row["auto_monitoring_paused_hint"] = {
                        "code": "AUTO_MONITORING_PAUSED_BY_SERVICE_PERIOD",
                        "reason": _b.get("blocked_reason"),
                        "overdue_days": _b.get("overdue_days"),
                        # 🔴 [WO_MONITORING_PLATFORM_COVERED 2026-08-16 §8①] 按**真行为**改文案。
                        #   取证(三层信源逐条读的,不是推的):
                        #     层1 本横幅谓词 = `service_end_date < CURRENT_DATE`(日历口径)
                        #     层2 真 dispatch 谓词 = quote_service_anchor_condition_sql
                        #         + compliant_days < service_days —— **纯履约,从不读 service_end_date**
                        #     层3 compliance 闸同样按累计达标天数
                        #   而本横幅只取 `service_status NOT IN ('expired','paused')` 的行,
                        #   这些行在 dispatch 谓词里 `<> 'expired'` 恒真 ⇒ **paid 分支整体为真 ⇒ 仍在跑**。
                        #   ⇒ 旧文案「自动监测已暂停」对它标记的**每一行**都是假话:监测没停。
                        #   履约口径(2026-06-04 老板拍板 A)本来就是"没履约完不停服务"。
                        #   按 §8① 要求:横幅与真行为不符就按真行为改文案,**不造第三种说法**。
                        "message": (
                            "服务期日历已过 · 自动监测仍在按累计达标天数继续跑,达标满即完成"
                            if _b.get("blocked_reason") == "service_period_ended"
                            else "还没设服务期 · 到期时间与续费窗口算不出来(监测本身不受影响)"
                        ),
                        "actions": [
                            {"label": "去续费 / 设服务期", "type": "open_service_period",
                             "quote_id": row.get("id")},
                        ],
                    }

            return {
                "status": "success",
                "clients": rows,
                # 汇总一个数,面板一眼看见"有几家在静默停着"
                # [R9] 同上:计数也按真行为改名并保留旧键(恒 0)防老前端 undefined。
                "auto_monitoring_paused_count": 0,
                "service_calendar_expired_count": len(_blocked),
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except Exception as e:
        logger.error(f"获取服务总览失败: {e}")
        return {"status": "error", "error": str(e)}


# ========== 线下报价流程API ==========

class OfflineConfirmRequest(BaseModel):
    """线下订单确认请求"""
    final_price: float
    discount_info: Optional[str] = None
    gift_keywords: Optional[List[str]] = None
    sales_notes: Optional[str] = None
    # [服务期 SSOT 2026-08-06 §1.2] 必填 · 见 SalesConfirmRequest 同款说明
    service_months: int = Field(..., ge=1, le=24, description="服务月数 1-24 · 必填,系统不猜")
    service_start_date: Optional[str] = None  # YYYY-MM-DD


@app.post("/api/quotes/{quote_id}/offline-confirm")
async def offline_confirm_order(quote_id: int, req: OfflineConfirmRequest, request: Request):
    """线下报价确认 — 不经过选词链接，直接由销售确认订单"""
    try:
        # [A-16-2 安全修 2026-05-29] 越权修:原收 request 但未调 require_quote_access
        # → 任意代理可改他人 quote 状态 + 塞赠送词。兄弟端点(3695/3782/3838)均已校验。
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection, update_quote_status
        conn = get_connection()
        try:
            cur = conn.cursor()

            # 检查报价单存在且可确认
            cur.execute("SELECT id, brand_id, brand_name, status FROM quotes WHERE id = %s", (quote_id,))
            quote = cur.fetchone()
            if not quote:
                raise HTTPException(404, "报价单不存在")
            if quote["status"] not in ("draft", "confirmed"):
                raise HTTPException(400, f"当前状态 {quote['status']} 不允许确认")

            from datetime import datetime as dt
            now = dt.now().strftime("%Y-%m-%d %H:%M:%S")

            # [服务期 SSOT 2026-08-06 §1.2] 这里写的是**服务期意向**(月数 + 起始日),
            #   不写 service_end_date —— (start, end) 这一对只在激活事务成对落库。
            #   `req.service_months or 1` 已拔掉:月数缺失/非法 → 400 进人工。
            from services.service_period import ServicePeriodError, normalize_service_months
            try:
                _months = normalize_service_months(req.service_months)
            except ServicePeriodError as _spe:
                raise HTTPException(400, _spe.user_message)

            # 更新报价单
            cur.execute("""
                UPDATE quotes SET
                    status = 'pending_payment',
                    paid_amount = %s,
                    service_months = %s,
                    service_start_date = %s,
                    confirmed_at = %s
                WHERE id = %s
            """, (req.final_price, _months, req.service_start_date, now, quote_id))

            from services.notification_events import NotificationEventType
            from services.notification_outbox import enqueue_brand_owner_notification_event
            enqueue_brand_owner_notification_event(
                cur,
                brand_id=int(quote["brand_id"]),
                event_type=NotificationEventType.PAYMENT_REMINDER,
                business_id=f"quote:{int(quote_id)}",
                terminal_state="pending_payment",
                facts={
                    "business_no": f"QUOTE-{int(quote_id)}",
                    "status": "线下订单已确认，等待收款",
                    "occurred_at": now,
                    "summary": "请在客户报价页面跟进收款。",
                },
            )

            # [P0 2026-06-05 老板定稿] gift_keywords 不再写入 confirmed_keywords(根治"不计价核心词后门")
            #   旧:附赠词 price=0 写 confirmed_keywords(默认 is_core=True)→ 进核心词/监测/写作链 = 不计价即获监测。
            #   现:附赠词仅作服务备注(session 级 · display 读 session.gift_keywords)· 想监测须作为已选核心词单独计价。

            conn.commit()
            cur.close()
            conn.close()

            # M3 任务 2.3: audit_logs 写入(报价 4 状态独立审计)
            try:
                from db.auth_db import create_audit_log
                user = getattr(request.state, "user", None) or {}
                create_audit_log(
                    user_id=user.get("user_id"),
                    username=user.get("username"),
                    action="quote_offline_confirm",
                    module="quotes",
                    entity_type="quote",
                    entity_id=quote_id,
                    summary=f"线下确认 · {quote['brand_name']} · ¥{req.final_price:,.0f}/月 × {req.service_months}",
                    after={
                        "status": "pending_payment",
                        "final_price": req.final_price,
                        "service_months": req.service_months,
                        "service_start_date": req.service_start_date,
                        "gift_keywords": req.gift_keywords or [],
                    },
                    ip_address=getattr(request.client, "host", None) if request.client else None,
                )
            except Exception as audit_err:
                logger.warning(f"[audit] quote_offline_confirm fail quote={quote_id}: {audit_err}")

            return {"success": True, "status": "pending_payment"}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"线下确认订单失败: {e}")
        raise HTTPException(500, str(e))


class OfflineMarkPaidRequest(BaseModel):
    confirm_code: str = ""


@app.post("/api/quotes/{quote_id}/offline-mark-paid")
async def offline_mark_paid(quote_id: int, req: OfflineMarkPaidRequest, request: Request):
    """线下订单标记收款 — 激活服务期，关键词进入写作大厅

    confirm_code 验证已下线(Phase A · CTO-15.10 · 老板红线 2026-04-27):
        SaaS 化无差别一键激活 · 所有用户(含 admin)跳过 confirm_code
        审计仍走 audit_log + stage_log,保留可追溯性
    """
    try:
        # [A-16-1 安全修 2026-05-29] 越权修:原收 request 但未调 require_quote_access
        # → 任意代理可跨租户标他人订单 paid + 激活服务期。兄弟端点(offline-confirm 等)均已校验。
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection, update_quote_status
        conn = get_connection()
        try:
            cur = conn.cursor()

            # 检查报价单
            cur.execute("SELECT id, brand_id, brand_name, status, paid_amount, service_months, service_start_date FROM quotes WHERE id = %s", (quote_id,))
            quote = cur.fetchone()
            if not quote:
                raise HTTPException(404, "报价单不存在")
            if quote["status"] not in ("pending_payment", "confirmed", "draft"):
                raise HTTPException(400, f"当前状态 {quote['status']} 不允许标记收款")

            from datetime import datetime as dt, date
            now = dt.now().strftime("%Y-%m-%d %H:%M:%S")

            # 激活服务期 —— [服务期 SSOT 2026-08-06 §1.2] (start, end) 成对写,换算唯一入口。
            #   `quote["service_months"] or 1` 拔掉:缺失/非法 → 400 进人工,不猜。
            from services.service_period import ServicePeriodError, resolve_activation_period
            try:
                start_date, end_date = resolve_activation_period(
                    start_date=quote["service_start_date"], months=quote["service_months"]
                )
            except ServicePeriodError as _spe:
                raise HTTPException(400, _spe.user_message)
            months = quote["service_months"]

            # [audit #9 返修] P0-6 关键词校验【前置】到激活之前(当年对齐一键激活端点,该端点已随 WO_323 G3a 删):
            #   旧版先 UPDATE paid+active 并 commit → 再 COUNT → kw_count==0 不拒绝
            #   → 留下 paid+active 但 0 关键词的僵尸订单(prod 327/329 · 客户掉单)。
            #   修:先同步关键词(sync 内幂等 + markdown fallback)+ COUNT 兜底,0 词直接拒绝 ——
            #   此时 quote 尚未激活,raise 无副作用(不再有僵尸)。kw_count>0 才往下激活。
            _pre_kw = 0
            try:
                from services.quote_keyword_sync import sync_quote_keywords_to_confirmed
                _pre_kw, _ = sync_quote_keywords_to_confirmed(quote_id)
            except HTTPException:
                raise
            except Exception as _ke:
                logger.warning(f"[offline-mark-paid] 关键词同步失败(非 block): {_ke}")
            if not _pre_kw:
                # 兜底:sync 没拿到但 confirmed_keywords 已有(历史已同步)→ 直接 COUNT 确认
                cur.execute("SELECT COUNT(*) as cnt FROM confirmed_keywords WHERE quote_id = %s", (quote_id,))
                _ex = cur.fetchone()
                _pre_kw = _ex["cnt"] if _ex else 0
            if not _pre_kw:
                logger.warning(f"[offline-mark-paid] P0-6 拒绝激活 quote_id={quote_id} · 0 keyword(激活前拦截·无僵尸)")
                raise HTTPException(
                    status_code=400,
                    detail={
                        "code": "NO_KEYWORDS_FOUND",
                        "message": "这个客户还没选关键词 · 让客户在选词链接里选 · 或者重新生成报价方案",
                    },
                )

            cur.execute("""
                UPDATE quotes SET status = 'paid', paid_at = %s,
                    service_status = 'active', service_start_date = %s, service_end_date = %s
                WHERE id = %s
            """, (now, start_date, end_date, quote_id))
            from services.notification_events import NotificationEventType
            from services.notification_outbox import enqueue_brand_owner_notification_event
            enqueue_brand_owner_notification_event(
                cur,
                brand_id=int(quote["brand_id"]),
                event_type=NotificationEventType.PAYMENT_RECEIVED,
                business_id=f"quote:{int(quote_id)}",
                terminal_state="paid",
                facts={
                    "business_no": f"QUOTE-{int(quote_id)}",
                    "amount": f"{float(quote.get('paid_amount') or 0):,.2f} 元",
                    "status": "已确认收款，服务已激活",
                    "occurred_at": now,
                    "summary": f"{int(_pre_kw)} 个关键词已进入写作大厅。",
                },
            )
            conn.commit()

            # 获取关键词数量(前置校验已确保 >0)
            cur.execute("SELECT COUNT(*) as cnt FROM confirmed_keywords WHERE quote_id = %s", (quote_id,))
            kw_count = cur.fetchone()["cnt"]

            try:
                from services.article_delivery_plan import enqueue_quote_event_in_transaction_if_enabled

                enqueue_quote_event_in_transaction_if_enabled(
                    cur,
                    quote_id,
                    "quote_paid_offline",
                    source_hint="quote_paid_offline",
                )
                conn.commit()
            except Exception as _plan_event_error:
                logger.warning(
                    "[offline-mark-paid] article plan event bypassed without affecting activation quote=%s: %s",
                    quote_id,
                    _plan_event_error,
                )

            cur.close()
            conn.close()

            # M1a T4 埋点 · stage=pay event=complete
            try:
                _user = getattr(request.state, "user", None)
                _uid = _user.get("user_id") if _user else None
                from db.pipeline_stage_log_db import log_stage_event
                log_stage_event(
                    brand_id=quote["brand_id"],
                    stage_name="pay",
                    event="complete",
                    meta={
                        "quote_id": quote_id,
                        "brand_name": quote["brand_name"],
                        "keyword_count": kw_count,
                        "service_months": months,
                        "service_start": start_date.isoformat(),
                        "service_end": end_date.isoformat(),
                        "source": "offline_mark_paid",
                    },
                    actor_user_id=_uid,
                )
            except Exception as _le:
                logger.warning(f"[offline-mark-paid] stage_log 埋点失败(非 block): {_le}")

            # M3 任务 2.3: audit_logs 写入(报价 4 状态独立审计)
            try:
                from db.auth_db import create_audit_log
                _user_a = getattr(request.state, "user", None) or {}
                create_audit_log(
                    user_id=_user_a.get("user_id"),
                    username=_user_a.get("username"),
                    action="quote_offline_mark_paid",
                    module="quotes",
                    entity_type="quote",
                    entity_id=quote_id,
                    summary=f"标记线下收款 · {quote['brand_name']} · {kw_count} 关键词 · {months} 月",
                    after={
                        "status": "paid",
                        "service_status": "active",
                        "keywords_count": kw_count,
                        "service_start": start_date.isoformat(),
                        "service_end": end_date.isoformat(),
                        "expected_articles": expected_articles,
                    },
                    ip_address=getattr(request.client, "host", None) if request.client else None,
                )
            except Exception as audit_err:
                logger.warning(f"[audit] quote_offline_mark_paid fail quote={quote_id}: {audit_err}")

            return {"success": True, "status": "paid", "keywords_count": kw_count,
                    "service_start": start_date.isoformat(), "service_end": end_date.isoformat()}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"线下标记收款失败: {e}")
        raise HTTPException(500, str(e))


