class AddKeywordRequest(BaseModel):
    keyword: str
    category: str = "自定义"
    tier: str = "standard"  # entry / standard / flagship
    final_price: float = 0.0
    required_articles: int = 1
    intent: str = "informational"


def _auto_generate_topics_for_new_keyword(quote_id: int, keyword_id: int, keyword: str, required_articles: int, user_style: str = None) -> int:
    """[CTO-15.23 2026-05-08 P0-C / 2026-05-09 同步化] 给新加的 keyword 生成 topic

    [CTO-15.23 2026-05-09 老板报] add-keyword 提交后立即生成标题
    · 改为同步调用(endpoint 等完返回)· 不再 fire-and-forget thread
    · 用 KeywordTopicGenerator 单 keyword 跑 LLM 生成 topics
    · 直接 INSERT topics 表(不走 save_topics_batch · 那会清掉所有 pending topics)
    · 失败 catch + log · 返回 0 · 不抛异常 · 用户走"立即生成"按钮兜底
    · 老板诉求:加完 keyword 用户进写作大厅就能立即看到标题 · 不需要等 30 秒

    Args:
        user_style: v2.9 Codex P1 修 · 单 kw 路径也接受批量文体强制(10 项 user_choice 之一 · None=系统推荐)

    Returns:
        int · 实际 INSERT 的 topic 数 · 失败/无生成均返回 0
    """
    try:
        import asyncio as _asyncio
        from db.diagnosis_db import get_writing_project_detail, get_connection
        from writing.keyword_topic_generator import KeywordTopicGenerator

        detail = get_writing_project_detail(quote_id)
        if not detail:
            logger.warning(f"[AddKeyword-Topic] quote_id={quote_id} 不存在 · 跳过 topic 生成")
            return 0

        # 找新加的 keyword(精确匹配 keyword_id · 防同名干扰)
        new_kw = next((k for k in detail["keywords"] if k.get("id") == keyword_id), None)
        if not new_kw:
            logger.warning(f"[AddKeyword-Topic] keyword_id={keyword_id} 在 detail 中找不到 · 跳过")
            return 0

        # v2.9 user_style → 中文 article_style 强制(单 kw 路径与批量 generate-titles 同款逻辑)
        _force_chinese = None
        _persist_uc = None
        if user_style and user_style not in ("", "auto"):
            try:
                from writing.style_registry import resolve_user_choice_to_chinese_style
                _force_chinese = resolve_user_choice_to_chinese_style(
                    user_style, detail["quote"].get("industry", "")
                )
                _persist_uc = user_style  # 持久化到 topics.user_choice
            except ValueError as _ve:
                logger.warning(f"[AddKeyword-Topic] user_style 校验失败 user_style={user_style}: {_ve} · 走默认 ratio")
                # 不阻断 · 用户文体非法时退回默认 ratio · 防加词流程因 user_style 错卡死

        # 调 KeywordTopicGenerator 单 kw 生成
        generator = KeywordTopicGenerator(
            keywords=[new_kw],
            brand_name=detail["quote"].get("brand_name", ""),
            industry=detail["quote"].get("industry", ""),
            brand_id=detail["quote"].get("brand_id"),
            quote_id=quote_id,
            force_chinese_style=_force_chinese,  # v2.9 单 kw 路径接 user_style
        )

        # 跑 async generate(sync def 路由内 · FastAPI threadpool · asyncio.run 安全)
        try:
            topics = _asyncio.run(generator.generate())
        except RuntimeError:
            # 如果当前线程已有 event loop · 用 new loop
            new_loop = _asyncio.new_event_loop()
            try:
                topics = new_loop.run_until_complete(generator.generate())
            finally:
                new_loop.close()

        if not topics:
            logger.warning(f"[AddKeyword-Topic] LLM 生成 0 topics · keyword_id={keyword_id}")
            return 0

        # 直接 INSERT(不用 save_topics_batch 防清掉 pending)
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute(
                "SELECT q.article_plan_writing_mode,COALESCE(q.owner_user_id,b.owner_user_id) AS owner_user_id "
                "FROM quotes q JOIN brands b ON b.id=q.brand_id WHERE q.id=%s FOR UPDATE OF q",
                (quote_id,),
            )
            _plan_quote = cur.fetchone() or {}
            _slot_aware = _plan_quote.get("article_plan_writing_mode") == "slot_aware_v1"
            _plan_actor = int(_plan_quote.get("owner_user_id") or 0)
            inserted = 0
            for topic in topics:
                # 仅 insert 这个 keyword_id 的 topic · 防意外
                if topic.get("keyword_id") != keyword_id:
                    continue
                try:
                    cur.execute("SAVEPOINT add_keyword_topic")
                    # 六类 family 与来源跟随 KTG 的 per-slot 计划；统一文体仍兼容旧 user_style。
                    from writing.article_style_contract import normalize_user_choice, resolve_new_generation_style
                    _topic_choice = normalize_user_choice(
                        topic.get("user_choice") or _persist_uc,
                        allow_auto=False,
                    )
                    _article_style = resolve_new_generation_style(topic.get("article_style")) or "buying_guide"
                    _topic_source = topic.get("user_choice_source")
                    if _topic_choice and not _topic_source and _persist_uc:
                        _topic_source = "batch_uniform"
                    # [WO_225-c1 §8.3] 媒体桶:topic 自带优先,否则按这单口径分。
                    from services.media_slot_conversion import plan_buckets as _plan_buckets
                    _topic_bucket = topic.get("media_bucket") or (
                        (_plan_buckets(quote_id, 1, cursor=cur) or [None])[0])
                    cur.execute("""
                        INSERT INTO topics (
                            keyword_id, quote_id, original_keyword, optimized_title,
                            article_style, status, cluster_id, user_choice, user_choice_source,
                            media_bucket
                        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                        RETURNING id
                    """, (
                        topic.get("keyword_id"),
                        quote_id,
                        topic.get("original_keyword") or keyword,
                        topic.get("optimized_title") or "",
                        _article_style,
                        "pending",
                        topic.get("cluster_id"),
                        _topic_choice,
                        _topic_source,
                        _topic_bucket,  # [WO_225-c1] NULL = 一条一槽(老行为)
                    ))
                    _topic_id = int(cur.fetchone()["id"])
                    if _slot_aware:
                        if not _plan_actor:
                            raise RuntimeError("slot_aware_quote_owner_missing")
                        from services.article_closed_loop_metadata import bind_topic_to_slot

                        bind_topic_to_slot(
                            cur,
                            quote_id=quote_id,
                            topic_id=_topic_id,
                            keyword_id=keyword_id,
                            actor_user_id=_plan_actor,
                        )
                    cur.execute("RELEASE SAVEPOINT add_keyword_topic")
                    inserted += 1
                except Exception as ie:
                    cur.execute("ROLLBACK TO SAVEPOINT add_keyword_topic")
                    cur.execute("RELEASE SAVEPOINT add_keyword_topic")
                    logger.warning(f"[AddKeyword-Topic] 单条 topic INSERT 失败(继续): {ie}")
                    continue
            conn.commit()
            logger.info(f"[AddKeyword-Topic] quote_id={quote_id} kid={keyword_id} keyword={keyword!r} "
                        f"已生成 {inserted}/{len(topics)} topics")
            return inserted
        finally:
            try:
                conn.close()
            except Exception:
                pass
    except Exception as e:
        logger.warning(f"[AddKeyword-Topic] 生成 topic 失败 · quote_id={quote_id} kid={keyword_id} kw={keyword!r}: {e}")
        return 0


@app.post("/api/writing/projects/{quote_id}/add-keyword")
def api_add_keyword_to_project(quote_id: int, body: AddKeywordRequest, request: Request):
    """[CTO-15.23 2026-05-05] 写作大厅手动添加关键词
    老板诉求:漏词时不用重新走流程·在写作大厅直接补
    自动同步到监测中心(monitoring 从 confirmed_keywords UNION 拉·下次 fetch 即出现)
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)

        kw = (body.keyword or "").strip()
        if not kw:
            raise HTTPException(status_code=400, detail="关键词不能为空")
        if len(kw) > 100:
            raise HTTPException(status_code=400, detail="关键词长度超过 100 字")
        if body.tier not in ("entry", "standard", "flagship"):
            raise HTTPException(status_code=400, detail="tier 必须是 entry/standard/flagship")
        if body.required_articles < 1 or body.required_articles > 50:
            raise HTTPException(status_code=400, detail="篇数必须 1-50 之间")

        # [WO §2.4.2] 卫生闸(写作大厅补词入口 · 会同步进监测中心,所以同样是付费配置面)
        _hygiene_gate_keywords([kw], quote_id=quote_id)

        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            c = conn.cursor()
            # 校验 quote 存在
            c.execute("SELECT id FROM quotes WHERE id = %s", (quote_id,))
            if not c.fetchone():
                raise HTTPException(status_code=404, detail="项目不存在")
            # 防重 L1 · API 层(返 200 跳过 · 友好提示 · 配合 DB UNIQUE 双保险)
            # [CTO-15.23 2026-05-07 客户 bug 修] 检测 is_core 区分覆盖词 vs 真重复:
            #   - 真重复(is_core IS NOT FALSE) → skip(原行为)
            #   - 覆盖词(is_core=FALSE 由 selection_api.py:2169 / quote_keyword_sync.py:309/386 写入)
            #     → UPDATE is_core=TRUE 升级为核心词 · 同步用户填的 tier/price/篇数
            #   原逻辑用户看不到覆盖词(写作大厅列表过滤 is_core IS NOT FALSE)· 又因防重
            #   全部撞 skip · "已存在跳过但列表没有" → 客户报"添加不了"
            c.execute(
                "SELECT id, is_core FROM confirmed_keywords WHERE quote_id = %s AND keyword = %s",
                (quote_id, kw)
            )
            existing = c.fetchone()
            if existing:
                if existing["is_core"] is not False:
                    # 真重复(已是核心词) · 跳过
                    return {
                        "success": True,
                        "skipped": True,
                        "keyword_id": existing["id"],
                        "message": f"「{kw}」已存在 · 跳过",
                    }
                # 覆盖词升级核心词 · 同步用户填的参数 · status 重置 pending 让"开始写作"能拾起
                # 不动 quotes.total_keywords(覆盖词早已计入 · 升级不是新增)
                c.execute("""
                    UPDATE confirmed_keywords
                    SET is_core = TRUE,
                        category = %s,
                        tier = %s,
                        final_price = %s,
                        required_articles = %s,
                        intent = %s,
                        status = 'pending'
                    WHERE id = %s
                """, (
                    body.category, body.tier, body.final_price,
                    body.required_articles, body.intent,
                    existing["id"],
                ))
                conn.commit()
                logger.info(f"[AddKeyword] quote_id={quote_id} 覆盖词升级核心词「{kw}」id={existing['id']} tier={body.tier}")

                try:
                    from services.article_delivery_plan import enqueue_quote_event_durable

                    enqueue_quote_event_durable(quote_id, "contract_add_on")
                except Exception as _plan_event_error:
                    logger.warning("[AddKeyword] article plan event bypassed quote=%s: %s", quote_id, _plan_event_error)

                # [CTO-15.23 2026-05-09 老板报] 同步生成 topic · 让用户立即看到标题
                # 老 fire-and-forget thread 改成阻塞调用 · _auto_generate_topics_for_new_keyword
                # 内部 swallow 异常 · 失败返 0 · 用户用 amber"立即生成"按钮兜底
                topics_generated = _auto_generate_topics_for_new_keyword(
                    quote_id, existing["id"], kw, body.required_articles
                )

                return {
                    "success": True,
                    "skipped": False,
                    "upgraded": True,
                    "keyword_id": existing["id"],
                    "topics_generated": topics_generated,
                    "message": (
                        f"已激活「{kw}」并生成 {topics_generated} 个标题"
                        if topics_generated > 0
                        else f"已激活「{kw}」(原覆盖词升级核心词 · 标题生成失败 · 请在列表里点'立即生成'重试)"
                    ),
                }
            # INSERT(直接写·不复用 save_confirmed_keywords 防 total_keywords 被覆盖)
            # 防重 L2 · DB 层 UNIQUE (quote_id, keyword) 防 race(migration 已加约束)
            try:
                c.execute("""
                    INSERT INTO confirmed_keywords (
                        quote_id, keyword, category, tier,
                        base_price, city_premium, final_price, competitor_count,
                        required_articles, intent, funnel_stage, status, is_core
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    RETURNING id
                """, (
                    quote_id, kw, body.category, body.tier,
                    body.final_price, 1.0, body.final_price, 0,
                    body.required_articles, body.intent, "awareness", "pending", True,
                ))
            except Exception as ie:
                # UNIQUE 冲突(race · 两个并发 INSERT 跑到同一 keyword)
                conn.rollback()
                if 'uq_ck_quote_keyword' in str(ie) or 'duplicate key' in str(ie).lower():
                    # 找到刚被并发请求 INSERT 的那条
                    c2 = conn.cursor()
                    c2.execute(
                        "SELECT id FROM confirmed_keywords WHERE quote_id = %s AND keyword = %s",
                        (quote_id, kw)
                    )
                    racer = c2.fetchone()
                    return {
                        "success": True,
                        "skipped": True,
                        "keyword_id": racer["id"] if racer else None,
                        "message": f"「{kw}」已存在 · 跳过(并发)",
                    }
                raise
            new_id = c.fetchone()["id"]
            # 同步 quotes.total_keywords += 1
            c.execute(
                "UPDATE quotes SET total_keywords = COALESCE(total_keywords, 0) + 1 WHERE id = %s",
                (quote_id,)
            )
            conn.commit()
            logger.info(f"[AddKeyword] quote_id={quote_id} 新增关键词「{kw}」id={new_id} tier={body.tier}")

            try:
                from services.article_delivery_plan import enqueue_quote_event_durable

                enqueue_quote_event_durable(quote_id, "contract_add_on")
            except Exception as _plan_event_error:
                logger.warning("[AddKeyword] article plan event bypassed quote=%s: %s", quote_id, _plan_event_error)

            # [CTO-15.23 2026-05-09 老板报"无法立即生成标题"] 同步生成 topic
            # 老 fire-and-forget thread 改成阻塞调用 · endpoint 等完整生成才返回
            # FastAPI sync def 路由 run in threadpool · LLM 30s 不阻塞 event loop
            # 内部 swallow 异常 · 失败返 0 · 用户用 amber"立即生成"按钮兜底
            topics_generated = _auto_generate_topics_for_new_keyword(
                quote_id, new_id, kw, body.required_articles
            )

            return {
                "success": True,
                "skipped": False,
                "keyword_id": new_id,
                "topics_generated": topics_generated,
                "message": (
                    f"已添加「{kw}」并生成 {topics_generated} 个标题"
                    if topics_generated > 0
                    else f"已添加「{kw}」(标题生成失败 · 请在列表里点'立即生成'重试)"
                ),
            }
        finally:
            try:
                conn.close()
            except Exception:
                pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"添加关键词失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))

