@app.delete("/api/writing/projects/{quote_id}")
async def api_soft_delete_writing_project(quote_id: int, request: Request):
    """软删除写作大厅项目(quote)· 写 writing_status='deleted' · list 自动过滤
    追回机制:用户在报价系统重新点"确认方案" · from-c-end-plan 默认新建一个新 quote
    """
    from auth.brand_access import require_quote_access
    require_quote_access(request, quote_id, allow_null=False)

    from db.connection import get_connection
    conn = get_connection()
    try:
        cur = conn.cursor()
        organization_identity = getattr(request.state, "organization_identity", None)
        if organization_identity is not None and organization_identity.is_member:
            from services.organization_artifacts import lock_artifact_access_in_transaction
            from services.organization_contract import OrganizationError
            try:
                lock_artifact_access_in_transaction(
                    cur, organization_identity, artifact_type="quote", artifact_id=quote_id
                )
            except OrganizationError as exc:
                request_id = getattr(request.state, "organization_request_id", "unknown")
                raise HTTPException(status_code=exc.http_status, detail=exc.as_detail(request_id)) from exc
        cur.execute(
            """SELECT id, brand_id, brand_name, writing_status,
                      (SELECT COUNT(*) FROM confirmed_keywords k WHERE k.quote_id=quotes.id) AS keyword_count,
                      (SELECT COUNT(*) FROM topics t WHERE t.quote_id=quotes.id) AS topic_count,
                      (SELECT COUNT(*) FROM articles a WHERE a.quote_id=quotes.id) AS article_count
               FROM quotes
               WHERE id = %s AND (writing_status IS NULL OR writing_status != 'deleted')
               FOR UPDATE OF quotes""",
            (quote_id,),
        )
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="项目不存在或已删除")

        cur.execute(
            """UPDATE quotes
               SET writing_status_before_archive=writing_status, writing_status='deleted', updated_at=NOW()
               WHERE id=%s AND (writing_status IS NULL OR writing_status != 'deleted')""",
            (quote_id,),
        )
        conn.commit()

        # audit log
        try:
            from db.auth_db import create_audit_log
            user = getattr(request.state, "user", None) or {}
            create_audit_log(
                user_id=user.get("user_id"),
                username=user.get("username"),
                action="writing_project_soft_delete",
                module="writing",
                entity_type="quote",
                entity_id=quote_id,
                summary=f"软删写作项目 #{quote_id} · {dict(row).get('brand_name', '')}",
                ip_address=getattr(request.client, "host", None) if request.client else None,
            )
        except Exception as _ae:
            logger.warning(f"[soft-delete-project] audit_log 失败(非 block): {_ae}")

        exact = dict(row)
        return {
            "success": True,
            "object": {
                "type": "writing_project",
                "quote_id": quote_id,
                "brand_id": exact.get("brand_id"),
                "display_name": exact.get("brand_name") or f"写作项目 #{quote_id}",
            },
            "associations": {
                "keywords": int(exact.get("keyword_count") or 0),
                "topics": int(exact.get("topic_count") or 0),
                "articles": int(exact.get("article_count") or 0),
            },
            "impact": ["写作大厅不再显示该项目", "全部关联内容保留"],
            "writing_status": "deleted",
            "recovery": {"action": "restore", "target": f"/api/writing/projects/{quote_id}/restore"},
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"[soft-delete-project] 失败: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"删除项目失败: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass


