# ========== Phase 06 · 快速写作(CTO-15.23 2026-05-03) ==========
# /api/writing/projects/quick-create:写作大厅"+ 快速写作"入口的后端
# 与 from-c-end-plan 区别:不算价(quick_writing 来源)· profile_extras 可选写
# 文件上传走前端两步(POST /api/my-clients → POST /api/profile/<id>/knowledge/upload)
# 不在本 endpoint 内处理上传

class QuickWriteProfileExtras(BaseModel):
    """profile_extras · 完整客户资料字段(全选填 · 仅 non-empty 写入)"""
    business: Optional[str] = None
    target_users: Optional[str] = None
    company_intro: Optional[str] = None
    core_value: Optional[str] = None
    selling_points: Optional[list] = None  # JSONB · [{point, evidence}]
    success_cases: Optional[list] = None   # JSONB · [{client, industry, result, timeline}]
    competitors: Optional[list] = None     # JSONB · ["竞品名", ...]


class QuickWriteRequest(BaseModel):
    brand_id: int
    seed_keywords: list[str] = Field(..., min_length=1, max_length=15)
    profile_extras: Optional[QuickWriteProfileExtras] = None
    # mode='reuse' 时 profile_extras 应不传(老板拍板:复用不覆盖原资料)
    # mode 由前端控制 · 后端不强校验 · 但若 profile_extras 传且 brand 已有 profile 字段非空,默认不覆盖


@app.post("/api/writing/projects/quick-create")
async def api_quick_create_writing_project(req: QuickWriteRequest, request: Request):
    """快速写作 · 创建 quote + 落 client_profiles 资料 → 返 quote_id

    流程:
      1. 校验 brand 归属当前用户(require_brand_access)
      2. 取 brand_name / industry / cities(quote 必需)
      3. 若 profile_extras 非空 · UPSERT client_profiles(仅写 non-empty 字段 · 不覆盖已有非空值)
      4. 创建 quote(source_type='quick_writing' · status='confirmed' · paid_amount=0)
      5. 落 confirmed_keywords(每词 1 篇文章 · 基础档 standard · 价格 0)
      6. 写 m3_customer_events 'quick_write_created'

    扣费:本 endpoint 免费(quote 创建仅"待办锁定")· 写作环节才扣 _bill_ctx
    复用 brand 场景:profile_extras 可不传(纯创建 quote 关联老 brand)
    """
    from auth.brand_access import require_brand_access
    try:
        user = request.state.user
    except AttributeError:
        raise HTTPException(status_code=401, detail="未登录")

    require_brand_access(request, req.brand_id)

    from db.connection import get_connection
    import json as _json
    conn = get_connection()
    try:
        cur = conn.cursor()

        # 1. 取 brand 基础信息(quote 必需)
        cur.execute(
            """SELECT id, name, industry, cities
               FROM brands
               WHERE id = %s AND (is_deleted IS NULL OR is_deleted = FALSE)""",
            (req.brand_id,),
        )
        brand = cur.fetchone()
        if not brand:
            raise HTTPException(status_code=404, detail="品牌不存在或已删除")
        brand = dict(brand)
        brand_name = brand.get("name") or f"brand_{req.brand_id}"
        brand_industry = brand.get("industry") or ""
        brand_city = brand.get("cities") or ""

        # 2. profile_extras 写入 client_profiles · 仅 non-empty 字段 + 不覆盖已有非空(SAFE-merge)
        if req.profile_extras:
            extras = req.profile_extras.model_dump(exclude_none=True)
            if extras:
                # 查现有 profile
                cur.execute(
                    "SELECT id, business, target_users, company_intro, core_value, "
                    "selling_points, success_cases, competitors "
                    "FROM client_profiles WHERE brand_id = %s "
                    "AND (is_deleted IS NULL OR is_deleted = 0) LIMIT 1",
                    (req.brand_id,),
                )
                existing_profile = cur.fetchone()

                # 准备字段(JSON 数组 → 字符串;TEXT 字段直接传)
                # 现 client_profiles selling_points/success_cases 是 TEXT · T7 阶段升 JSONB
                # 这里 json.dumps 兼容两种 schema
                def _serialize(v):
                    if isinstance(v, (list, dict)):
                        return _json.dumps(v, ensure_ascii=False)
                    return v

                if existing_profile:
                    # SAFE-merge · 仅当现有字段为空 / 0 / null 时才更新
                    existing_dict = dict(existing_profile)
                    set_clauses = []
                    set_values = []
                    for col, new_val in extras.items():
                        old_val = existing_dict.get(col)
                        # 已有非空(string) / 已有非空 JSON 数组 → 跳过
                        if old_val:
                            if isinstance(old_val, str) and old_val.strip() and old_val.strip() not in ("[]", "null"):
                                continue
                        set_clauses.append(f"{col} = %s")
                        set_values.append(_serialize(new_val))
                    if set_clauses:
                        set_clauses.append("updated_at = NOW()")
                        set_values.append(req.brand_id)
                        cur.execute(
                            f"UPDATE client_profiles SET {', '.join(set_clauses)} WHERE brand_id = %s",
                            set_values,
                        )
                else:
                    # 新建 profile
                    import shortuuid as _su
                    profile_id = _su.uuid()[:8]
                    cols = ["id", "name", "brand_id", "industry", "created_at", "updated_at"]
                    vals = [profile_id, brand_name, req.brand_id, brand_industry, "NOW()", "NOW()"]
                    placeholders = ["%s", "%s", "%s", "%s", "NOW()", "NOW()"]
                    for col, val in extras.items():
                        cols.append(col)
                        vals.append(_serialize(val))
                        placeholders.append("%s")
                    # 修正 placeholders(NOW() 不带 %s)· 仅前 4 + extras
                    actual_vals = [profile_id, brand_name, req.brand_id, brand_industry] + [_serialize(v) for v in extras.values()]
                    actual_cols = ["id", "name", "brand_id", "industry"] + list(extras.keys())
                    actual_phs = ["%s"] * (4 + len(extras))
                    cur.execute(
                        f"INSERT INTO client_profiles ({', '.join(actual_cols)}, created_at, updated_at) "
                        f"VALUES ({', '.join(actual_phs)}, NOW(), NOW())",
                        actual_vals,
                    )

        # [WO §2.4.2] 卫生闸(快速建项目入口)· 同样必须在建 quote 之前,避免留空 quote
        _hygiene_gate_keywords([k for k in req.seed_keywords], brand_id=req.brand_id)

        from db.diagnosis_db import lock_brand_quote_serialization_point
        # 🔴 [工单 V4-A · Codex fix-of-fix P1-2a] 品牌级序列化点:
        #    与门户 token 轮换互斥。少拿这一处,轮换那边「她看到的报价还是不是
        #    canonical」的复核就会从这一处漏回去(新报价是 INSERT,行锁锁不住它)。
        lock_brand_quote_serialization_point(cur, req.brand_id)
        # 3. 创建 quote(source_type='quick_writing')
        cur.execute(
            """INSERT INTO quotes (
                   brand_id, brand_name, industry, city, tier, target_share,
                   total_keywords, total_articles, monthly_price, paid_amount,
                   status, confirmed_at, source_type, owner_user_id, writing_status
               ) VALUES (%s, %s, %s, %s, 'standard', 0.20,
                         %s, %s, 0, 0,
                         'confirmed', CURRENT_TIMESTAMP, 'quick_writing', %s, 'pending')
               RETURNING id""",
            (
                req.brand_id, brand_name, brand_industry, brand_city,
                len(req.seed_keywords), len(req.seed_keywords),
                user["user_id"],
            ),
        )
        quote_row = cur.fetchone()
        quote_id = dict(quote_row)["id"]

        # 4. 落 confirmed_keywords(每词 1 篇 · 基础档 · 价格 0 · 写作时再算)
        for kw in req.seed_keywords:
            kw_clean = kw.strip()
            if not kw_clean:
                continue
            cur.execute(
                """INSERT INTO confirmed_keywords (
                       quote_id, keyword, category, tier,
                       base_price, city_premium, final_price,
                       required_articles, status, is_core
                   ) VALUES (%s, %s, %s, 'standard', 0, 1.0, 0, 1, 'pending', TRUE)""",
                (quote_id, kw_clean, "快速写作"),
            )

        conn.commit()

        try:
            from services.article_delivery_plan import enqueue_quote_event_durable

            enqueue_quote_event_durable(quote_id, "zero_price_writing_project_created")
        except Exception as _plan_event_error:
            logger.warning(
                "[quick-create] article plan event bypassed quote=%s: %s",
                quote_id,
                _plan_event_error,
            )

        # 5. m3_customer_events 'quick_write_created'(非阻塞)
        try:
            from db.m3_events_db import insert_event
            insert_event(
                source="agent_intake",
                event_type="quick_write_created",
                brand_id=req.brand_id,
                quote_id=quote_id,
                metadata={
                    "keyword_count": len(req.seed_keywords),
                    "had_profile_extras": req.profile_extras is not None,
                    "user_id": user["user_id"],
                },
            )
        except Exception as _ee:
            logger.warning(f"[quick-create] m3_customer_events 写入失败(非 block): {_ee}")

        logger.info(
            f"[quick-create] user_id={user['user_id']} brand_id={req.brand_id} "
            f"quote_id={quote_id} keywords={len(req.seed_keywords)} extras={req.profile_extras is not None}"
        )
        return {
            "success": True,
            "brand_id": req.brand_id,
            "quote_id": quote_id,
            "keyword_count": len(req.seed_keywords),
        }
    except HTTPException:
        try: conn.rollback()
        except Exception: pass
        raise
    except Exception as e:
        try: conn.rollback()
        except Exception: pass
        logger.error(f"[quick-create] 失败: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=f"快速写作创建失败: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.get("/api/writing/projects/{quote_id}")
def api_get_writing_project_detail(quote_id: int, request: Request):
    """获取写作项目详情"""
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_writing_project_detail
        detail = get_writing_project_detail(quote_id)
        if not detail:
            raise HTTPException(status_code=404, detail="项目不存在")
        for _topic in detail.get("topics", []):
            if _topic.get("status") == "failed":
                _topic["fail_reason"] = (
                    _topic.get("generation_error_message")
                    or "文章生成未完成，可刷新后安全重试。"
                )
        _organization_identity = getattr(request.state, "organization_identity", None)
        if _organization_identity is not None and _organization_identity.is_member:
            from auth.brand_access import filter_organization_artifact_rows
            _allowed_topics = filter_organization_artifact_rows(
                request,
                "article",
                [row for row in detail.get("topics", []) if row.get("article_id") is not None],
                id_key="article_id",
            )
            _allowed_article_ids = {
                str(row.get("article_id")) for row in _allowed_topics if row.get("article_id") is not None
            }
            for _topic in detail.get("topics", []):
                if _topic.get("article_id") is not None and str(_topic["article_id"]) not in _allowed_article_ids:
                    _topic["article_id"] = None
                    _topic["article_version"] = None
                    _topic["article_updated_at"] = None
                    if _topic.get("status") == "completed":
                        _topic["status"] = "writing"

        # [WO_218-c1b] 「生成标题」按钮上那个「本次将扣 N(上限 M)」的来源。
        #   🔴 挂在**这个**端点而不是列表端点:`add-keyword` 成功后前端调的是
        #      `loadProjectDetail()` —— 也就是说 `keyword_count` 一变,这份 `charge`
        #      **顺带就刷新了**;挂在列表上会停在旧价,而**显示一个过期的价比不显示更糟**
        #      (客户是按那个数同意扣费的)。
        #   🔴 与 `POST /api/writing/generate-titles` **同一个 `charge_card()`**、
        #      同一份 `detail["keywords"]`、同一个 `is_billable()` —— 不各算一份。
        #   🔴 取不到价不阻断详情:这是**只读展示**,为了显示一个数而让整个项目页 500,
        #      方向反了。取不到就 `charge=None` ⇒ 前端不显示价(不是显示 0)。
        _detail_charge = None
        _detail_charge_new_only = None
        try:
            from services.topic_gen_charge import charge_card as _topic_charge_card
            from services.topic_gen_charge import is_billable as _topic_is_billable
            from db.wallet_db import get_feature_pricing as _get_topic_pricing
            _detail_user = getattr(request.state, "user", None)
            _detail_charge = _topic_charge_card(
                detail.get("keywords"),
                billable=_topic_is_billable(
                    is_organization_member=bool(
                        _organization_identity is not None
                        and _organization_identity.is_member),
                    bill_user_id=(None if (not _detail_user or _detail_user.get("is_admin"))
                                  else _detail_user.get("user_id")),
                ),
                lookup=_get_topic_pricing,
            )
            # [WO_241 丙补 · Review 裁定 2026-09-19] 「新词面」点击前要报的价
            #   不是整表的价,是**还没有任何选题行的那些词**的价。
            #   🔴 同一个 `charge_card()`、同一份 `detail["keywords"]`,只多一道过滤 ——
            #      **不新增第二套算法**(两套迟早分家,而分家时两边各自都对)。
            #   🔴 空集给 `None` 不给 `0`:`None` = 没有新词、这一面不显示价;
            #      `0` = 有新词但免费。压成一种,前端就会对客户说错话。
            from services.topic_gen_charge import keywords_without_topics as _kw_no_topics
            _new_kws = _kw_no_topics(detail.get("keywords"), detail.get("topics"))
            _detail_charge_new_only = _topic_charge_card(
                _new_kws,
                billable=bool(_new_kws) and _topic_is_billable(
                    is_organization_member=bool(
                        _organization_identity is not None
                        and _organization_identity.is_member),
                    bill_user_id=(None if (not _detail_user or _detail_user.get("is_admin"))
                                  else _detail_user.get("user_id")),
                ),
                lookup=_get_topic_pricing,
            )
        except Exception:                                  # noqa: BLE001
            logger.warning("[WO_218] 项目详情取 topic_gen 报价失败,charge 置 None",
                           exc_info=True)
            _detail_charge = None
            _detail_charge_new_only = None
        return {"success": True, **detail, "charge": _detail_charge,
                "charge_new_keywords_only": _detail_charge_new_only}
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("获取写作项目详情失败")
        raise HTTPException(
            status_code=500,
            detail={"code": "WRITING_PROJECT_LOAD_FAILED", "message": "项目详情暂时无法读取，请刷新重试。"},
        )


