class WritingTargetEngineRequest(BaseModel):
    """[P1-4] 写作项目目标引擎设定。空串 = 取消定向(回到现行为)。"""
    target_engine: str = ""


@app.post("/api/writing/projects/{quote_id}/target-engine")
def api_set_writing_target_engine(quote_id: int, req: WritingTargetEngineRequest, request: Request):
    """[P1-4 引擎定向 2026-08-14] 设定写作项目的目标引擎(quote 级,复用 geo_douyin 先例)。

    - 值域由 writing/engine_targeting 归一(dashscope/deepseek/kimi/doubao);
    - 空串 = 清除定向(A1:后续生成回到"不定向"现行为);
    - 非法值 → 422(不静默归空 —— 用户显式给了值就要么认要么报,不猜)。
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from writing.engine_targeting import available_target_engines, normalize_target_engine

        raw = str(req.target_engine or "").strip()
        normalized = normalize_target_engine(raw)
        if raw and not normalized:
            raise HTTPException(
                status_code=422,
                detail={"code": "INVALID_TARGET_ENGINE",
                        "message": f"不支持的目标引擎,可选:{'、'.join(available_target_engines().values())},或留空取消定向。"},
            )
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute(
                "UPDATE quotes SET target_engine=%s WHERE id=%s",
                (normalized or None, quote_id),
            )
            if cur.rowcount == 0:
                conn.rollback()
                raise HTTPException(status_code=404, detail="项目不存在")
            conn.commit()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        return {
            "success": True,
            "target_engine": normalized,
            "target_engine_label": (available_target_engines().get(normalized, "") if normalized else ""),
        }
    except HTTPException:
        raise
    except Exception:
        logger.exception("设定目标引擎失败")
        raise HTTPException(status_code=500, detail={"code": "TARGET_ENGINE_SET_FAILED", "message": "目标引擎设定失败，请重试。"})


def _safe_json_item_count(value) -> int:
    if not value:
        return 0
    if isinstance(value, (list, dict)):
        return len(value)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return 0
        try:
            parsed = json.loads(text)
            if isinstance(parsed, (list, dict)):
                return len(parsed)
        except Exception:
            pass
        return 1
    return 0


def _count_writing_knowledge_items(brand_id: int) -> int:
    from db.diagnosis_db import get_connection

    conn = get_connection()
    count = 0
    try:
        cursor = conn.cursor()
        for table in ("client_knowledge_files", "knowledge_documents"):
            try:
                cursor.execute("SELECT to_regclass(%s) AS rel", (table,))
                row = cursor.fetchone()
                if not row or not row.get("rel"):
                    continue
                cursor.execute(f"SELECT COUNT(*) AS cnt FROM {table} WHERE brand_id = %s", (brand_id,))
                count += int((cursor.fetchone() or {}).get("cnt") or 0)
            except Exception:
                conn.rollback()

        try:
            cursor.execute("SELECT to_regclass(%s) AS rel", ("client_profiles",))
            row = cursor.fetchone()
            if row and row.get("rel"):
                cursor.execute(
                    """
                    SELECT knowledge_files, structured_knowledge
                    FROM client_profiles
                    WHERE brand_id = %s
                    ORDER BY updated_at DESC NULLS LAST
                    LIMIT 1
                    """,
                    (brand_id,),
                )
                profile = cursor.fetchone()
                if profile:
                    count += _safe_json_item_count(profile.get("knowledge_files"))
                    count += _safe_json_item_count(profile.get("structured_knowledge"))
        except Exception:
            conn.rollback()

        # 客户上传走 services/knowledge_pipeline 写入 LanceDB knowledge_client_{brand_id}
        # 上面 3 张表只看老路径(关系表 + JSON), 不会数到向量表 → has_knowledge=False
        # 所以闸门必须把向量表行数也算进去 (路径与 api/knowledge_api.py:_client_vector_counts 同源)
        try:
            import lancedb
            from pathlib import Path
            vectordb_root = Path(__file__).resolve().parent / "data" / "vectordb"
            if vectordb_root.exists():
                lance_db = lancedb.connect(str(vectordb_root))
                table_name = f"knowledge_client_{brand_id}"
                try:
                    count += int(lance_db.open_table(table_name).count_rows())
                except Exception:
                    # 表不存在 (该 brand 没上传过) 或读取失败, 不阻断闸门
                    pass
        except Exception as e:
            logger.warning(f"[writing-kb-count] LanceDB 查询失败 brand_id={brand_id}: {e}")

        return count
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _build_writing_knowledge_status(quote_id: int, quote: dict = None) -> dict:
    from db.diagnosis_db import get_quote, get_connection
    from api.m3_material_confirm_api import (
        _build_materials_snapshot,
        _ensure_table,
        _get_brand_info,
        _get_materials_for_brand,
        _get_profile_for_brand,
        _has_any_materials,
        _normalize_session_status,
        _summarize_materials,
    )

    quote = quote or get_quote(quote_id)
    if not quote:
        raise HTTPException(status_code=404, detail="报价单不存在")

    brand_id = quote.get("brand_id")
    if not brand_id:
        return {
            "quote_id": quote_id,
            "brand_id": None,
            "diagnosis_id": quote.get("diagnosis_id"),
            "brand_name": quote.get("brand_name") or "",
            "status": "none",
            "has_materials": False,
            "knowledge_count": 0,
            "has_knowledge": False,
            "can_start_writing": False,
            "can_generate_link": False,
            "token_url": None,
            "customer_notes": "",
            "materials_summary": None,
            "message": "这张报价单没有关联品牌，无法读取客户知识库",
        }

    _ensure_table()
    brand_info = _get_brand_info(brand_id) or {"name": quote.get("brand_name") or ""}
    profile = _get_profile_for_brand(brand_id)
    materials = _get_materials_for_brand(brand_id)
    has_current_materials = _has_any_materials(profile, materials)
    knowledge_count = _count_writing_knowledge_items(brand_id)

    conn = get_connection()
    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT id, token, status, materials_snapshot, customer_notes,
                   confirmed_at, expires_at, created_at
            FROM marketing_confirm_sessions
            WHERE brand_id = %s
            ORDER BY created_at DESC LIMIT 1
            """,
            (brand_id,),
        )
        session = cursor.fetchone()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    current_snapshot = _build_materials_snapshot(brand_info, profile, materials)
    summary = _summarize_materials(current_snapshot)
    token_url = None
    customer_notes = ""
    confirmed_at = None
    expires_at = None
    has_session = False

    if session:
        has_session = True
        session = dict(session)
        status = _normalize_session_status(session)
        token = session.get("token")
        token_url = f"/m/{token}" if token else None
        customer_notes = session.get("customer_notes") or ""
        confirmed_at = session.get("confirmed_at")
        expires_at = session.get("expires_at")
        if session.get("materials_snapshot") and status in ("pending", "feedback", "confirmed", "expired", "revoked"):
            try:
                summary = _summarize_materials(json.loads(session["materials_snapshot"]))
            except Exception:
                pass
    else:
        status = "draft" if has_current_materials or knowledge_count > 0 else "none"

    filled_count = int((summary or {}).get("filled_count") or 0)
    has_materials = bool(has_current_materials or filled_count > 0)
    has_knowledge = bool(has_materials or knowledge_count > 0)
    can_start_writing = has_knowledge
    can_generate_link = bool(
        has_materials and status in ("none", "draft", "expired", "revoked", "feedback", "confirmed")
    )

    if not can_start_writing:
        message = "客户知识库为空，请先在写作大厅补充客户资料，再开始写作"
    elif status == "confirmed":
        message = "客户资料已确认，可以开始写作"
    elif status in ("pending", "feedback"):
        message = "客户资料已整理，可以开始写作；确认链接仍可继续跟进"
    else:
        message = "客户资料已整理，可以开始写作；建议同步发客户确认链接"

    return {
        "quote_id": quote_id,
        "brand_id": brand_id,
        "diagnosis_id": quote.get("diagnosis_id"),
        "brand_name": brand_info.get("name") or quote.get("brand_name") or "",
        "status": status,
        "has_session": has_session,
        "has_materials": has_materials,
        "knowledge_count": knowledge_count,
        "has_knowledge": has_knowledge,
        "can_start_writing": can_start_writing,
        "can_generate_link": can_generate_link,
        "token_url": token_url,
        "customer_notes": customer_notes,
        "confirmed_at": confirmed_at,
        "expires_at": expires_at,
        "materials_summary": summary,
        "message": message,
    }


@app.get("/api/writing/projects/{quote_id}/knowledge-status")
def api_get_writing_knowledge_status(quote_id: int, request: Request):
    """写作前客户资料/知识库状态，用于写作大厅第一屏和开始写作闸门。"""
