class ReferenceCreateRequest(BaseModel):
    title: str
    content: str
    source_url: str = None
    platform: str = None
    industry: str = None
    intent_type: str = None
    success_proof: str = None


@app.post("/api/references")
async def api_create_reference(request: ReferenceCreateRequest):
    """添加范文"""
    try:
        from db.diagnosis_db import save_reference_article
        from writing.imitation_generator import ReferenceArticleAnalyzer

        # 分析范文结构
        analyzer = ReferenceArticleAnalyzer(request.title, request.content)
        analysis = await analyzer.analyze()

        # 保存
        ref_id = save_reference_article({
            "title": request.title,
            "content": request.content,
            "source_url": request.source_url,
            "platform": request.platform,
            "industry": request.industry,
            "intent_type": request.intent_type,
            "analysis": analysis,
            "success_proof": request.success_proof
        })

        return {"success": True, "id": ref_id, "analysis": analysis}
    except Exception as e:
        logger.error(f"添加范文失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/references")
def api_list_references(
    request: Request,
    industry: str = None,
    intent_type: str = None,
    search: str = None,
    platform: str = None,
    time_range: str = None,
    min_usage: int = None
):
    """获取范文列表
    [self-review r5 2026-05-23] P0-6 同类闭环 · 老板复审:
    范文库定位为可共享资产(代理交流借鉴) · 列表保留全量条目方便搜索 ·
    但敏感字段 content/analysis 只在详情接口(已有 owner/admin/public 校验)返
    详情接口仍按 P0-6 强制 owner 或 public · 列表只做卡片 meta 不泄正文
    """
    try:
        from db.diagnosis_db import get_reference_articles
        refs = get_reference_articles(
            industry=industry,
            intent_type=intent_type,
            search=search,
            platform=platform,
            time_range=time_range,
            min_usage=min_usage
        )
        # 列表 strip 敏感字段:content / analysis · 强制走详情才能拿正文
        user = getattr(request.state, "user", None)
        is_admin = bool(user and user.get("is_admin"))
        if not is_admin:
            uid = (user or {}).get("user_id")
            stripped = []
            for r in refs or []:
                owner_uid = r.get("created_by") or r.get("owner_user_id")
                is_public = bool(r.get("is_public"))
                # owner 或 public 才看到 content 预览(裁 200 字)· 其他用户只见 meta
                row = {k: v for k, v in r.items() if k not in ("content", "analysis")}
                if owner_uid == uid or is_public:
                    full_content = r.get("content") or ""
                    row["content_preview"] = (full_content[:200] + "…") if len(full_content) > 200 else full_content
                stripped.append(row)
            return {"success": True, "references": stripped}
        return {"success": True, "references": refs}
    except Exception as e:
        logger.error(f"获取范文列表失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/references/{ref_id}")
def api_get_reference(ref_id: int, request: Request):
    """获取范文详情
    [P0-6 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · admin/owner 反查 · deny-by-default"""
    try:
        user = getattr(request.state, "user", None)
        if not user:
            raise HTTPException(status_code=401, detail="未登录")
        from db.diagnosis_db import get_reference_article
        ref = get_reference_article(ref_id)
        if not ref:
            raise HTTPException(status_code=404, detail="范文不存在")
        # admin 全权 / owner 自家 / 标记 public 才放行
        is_public = bool(ref.get("is_public"))
        owner_uid = ref.get("created_by") or ref.get("owner_user_id")
        if not user.get("is_admin") and not is_public and owner_uid != user.get("user_id"):
            raise HTTPException(status_code=403, detail="无权访问该范文")
        return {"success": True, **ref}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取范文详情失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


