@app.post("/api/references/{ref_id}/imitate")
async def api_imitate(ref_id: int, payload: ImitateRequest, request: Request):
    """基于范文仿写
    [self-review r4 2026-05-23] IDOR 闭环:加 quote owner 校验 + ref owner/public 校验
    防跨租户用别人 quote_id + 别人 ref_id 生成假文章污染他人项目"""
    try:
        from db.diagnosis_db import (
            get_reference_article, update_reference_use_count,
            save_imitation_record, get_writing_project_detail,
            save_imitated_articles
        )
        from writing.imitation_generator import ImitationGenerator
        from auth.brand_access import require_quote_access

        # quote owner 校验(写入 target)
        require_quote_access(request, payload.quote_id)

        # 获取范文 + ref owner/public 校验
        ref = get_reference_article(ref_id)
        if not ref:
            raise HTTPException(status_code=404, detail="范文不存在")
        user = getattr(request.state, "user", None)
        if not user:
            raise HTTPException(status_code=401, detail="未登录")
        is_public = bool(ref.get("is_public"))
        owner_uid = ref.get("created_by") or ref.get("owner_user_id")
        if not user.get("is_admin") and not is_public and owner_uid != user.get("user_id"):
            raise HTTPException(status_code=403, detail="无权使用该范文")

        # 获取客户信息
        project = get_writing_project_detail(payload.quote_id)
        if not project:
            raise HTTPException(status_code=404, detail="项目不存在")

        # 获取关键词
        keywords = project["keywords"]
        if payload.keyword_ids:
            keywords = [k for k in keywords if k["id"] in payload.keyword_ids]

        keyword_list = [k["keyword"] for k in keywords[:payload.count]]

        # 生成仿写
        generator = ImitationGenerator(
            template=ref.get("analysis", {}),
            brand_name=project["quote"]["brand_name"],
            industry=project["quote"]["industry"],
            keywords=keyword_list
        )
        articles = await generator.generate()

        # [标题 AI-only 2026-08-17] 仿写标题只能由 AI 产出。一条都没产出 =
        # 显式失败,不落空记录、不静默返回 success:true 的空列表。
        if not articles:
            from writing.title_ai_only import TITLE_FAILURE_USER_MESSAGE

            return {
                "success": False,
                "record_id": None,
                "article_count": 0,
                "articles": [],
                "message": TITLE_FAILURE_USER_MESSAGE,
            }

        # 更新使用次数
        update_reference_use_count(ref_id)

        # 保存仿写记录
        record_id = save_imitation_record(ref_id, payload.quote_id, len(articles))

        # 保存仿写生成的文章
        article_ids = save_imitated_articles(record_id, ref_id, payload.quote_id, articles)

        # 给每篇文章添加ID
        for i, article in enumerate(articles):
            article["id"] = article_ids[i] if i < len(article_ids) else None

        return {
            "success": True,
            "record_id": record_id,
            "article_count": len(articles),
            "articles": articles
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"仿写生成失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


