@app.post("/api/imitated-articles/{article_id}/rewrite")
async def api_rewrite_imitated_article(article_id: int, request: ImitatedArticleRewriteRequest, http_request: Request = None):
    """根据修改意见重写仿写文章

    [CTO-15.23 2026-05-19 P0 资金漏洞 audit · Agent 复查发现]
    之前完全没扣费 = 100% 白嫖(代理无限点重写不花钱)
    修:_bill_feature_ctx 包整个 LLM logic · article_rewrite=260 积分/次
    跟 /api/articles/replace 同款 pattern(async with 在 try 外 · try-except 在 with 内)

    [self-review r4 2026-05-23] IDOR 闭环:反查 article → quote → owner · 防跨租户白嫖 LLM
    """
    # IDOR 校验放在扣费 ctx 外 · 不属于自己的文章不应触发扣费窗口
    if http_request is not None:
        from auth.brand_access import require_quote_access as _rqa
        from db.diagnosis_db import get_imitated_article as _gia
        _existing = _gia(article_id)
        if not _existing:
            raise HTTPException(status_code=404, detail="文章不存在")
        _rqa(http_request, _existing.get("quote_id"))

    async with _bill_feature_ctx(http_request, "article_rewrite"):
      try:
        from db.diagnosis_db import get_imitated_article, update_imitated_article, get_reference_article
        from writing.llm_utils import get_llm_config
        import httpx

        # 获取原始文章
        article = get_imitated_article(article_id)
        if not article:
            raise HTTPException(status_code=404, detail="文章不存在")

        # 获取范文模板
        ref = get_reference_article(article["reference_id"])
        template = ref.get("analysis", {}) if ref else {}

        # 构建重写Prompt
        rewrite_prompt = f"""# 角色: 文章重写专家

## 任务
根据修改意见重写文章,保持原有结构但按要求改进。

## 原始文章
标题: {article["title"]}
关键词: {article["keyword"]}

内容:
{article["content"][:3000]}

## 修改意见
{request.revision_note}

## 要求
1. 保持原文的核心结构和主题
2. 根据修改意见进行改进
3. 保持专业、权威的语调
4. 直接输出改写后的完整Markdown文章,不要解释

请直接输出重写后的文章:
"""

        # 调用LLM
        api_url, api_key, model, provider = get_llm_config("writing", "writing")

        if not api_key:
            raise HTTPException(status_code=500, detail="LLM未配置")

        async with httpx.AsyncClient(timeout=180.0) as client:
            response = await client.post(
                api_url,
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": model,
                    "messages": [{"role": "user", "content": rewrite_prompt}],
                    "temperature": 0.7,
                    "max_tokens": 8000
                }
            )
            response.raise_for_status()
            result = response.json()
            new_content = result["choices"][0]["message"]["content"]

        # 提取新标题
        new_title = article["title"]
        lines = new_content.strip().split('\n')
        for line in lines:
            if line.strip().startswith('#'):
                new_title = line.strip().lstrip('#').strip()
                break
            if line.strip():
                new_title = line.strip()[:60]
                break

        # 保存修改意见和新内容
        import json
        existing_notes = []
        if article.get("revision_notes"):
            try:
                existing_notes = json.loads(article["revision_notes"])
            except:
                pass
        existing_notes.append({
            "note": request.revision_note,
            "created_at": datetime.now().isoformat()
        })

        update_imitated_article(article_id, {
            "title": new_title,
            "content": new_content,
            "revision_notes": existing_notes
        })

        return {
            "success": True,
            "title": new_title,
            "content": new_content
        }
      except HTTPException:
        raise
      except Exception as e:
        logger.error(f"重写文章失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ========== 文章生成API (新) ==========

class ArticleGenerateRequest(BaseModel):
    """文章生成请求(v2.7.2 加 user_choices + extra_instruction 净化)"""
    model_config = ConfigDict(extra="ignore")  # v2.7.2:静默丢弃伪造字段(防 style_code 等绕过)

    quote_id: int = Field(gt=0)
    topic_ids: List[int] = Field(min_length=1, max_length=500)  # 选中的标题ID
    llm_provider: Optional[str] = Field(None, min_length=1, max_length=40, pattern=r"^[a-z0-9_-]+$")
    llm_model: Optional[str] = Field(None, min_length=1, max_length=160, pattern=r"^[A-Za-z0-9._:/-]+$")
    # v2.7.2 GEO 文体改造 · 客户 API 只接 user_choice(10 项) · 不接 style_code
    user_choices: Optional[dict] = None  # {topic_id(int): user_choice(USER_CHOICE_VALUES)}
    extra_instruction: Optional[str] = Field(None, max_length=200)
    # [2026-06-02 GEO CTO] 写作大厅两开关
    add_images: bool = True    # 自动配图(默认开)· 用客户图库真实图片配图
    add_contact: bool = False  # 插入联系方式(默认关)· 媒体代发会按媒体规则自动软化
    publication_profile: str = Field(
        "standard",
        pattern="^(standard|sohu_geo_strict_v1)$",
        description="GEO 发布安全档；严格档降低审核风险但不承诺平台通过",
    )
    use_structure_guidance: bool = True  # [WP9-P0-1] 默认开:无 active 策略时 writing_structure_guidance 自动回落语料基线/默认模板,不报错;部署即用无休眠 flag(§15.1)

    @field_validator("topic_ids")
    @classmethod
    def validate_topic_ids(cls, values: List[int]) -> List[int]:
        if any(int(value) <= 0 for value in values):
            raise ValueError("topic_ids 只能包含正整数")
        return list(dict.fromkeys(int(value) for value in values))

    @field_validator("user_choices")
    @classmethod
    def validate_user_choices_size(cls, value: Optional[dict]) -> Optional[dict]:
        if value is not None and len(value) > 500:
            raise ValueError("user_choices 单次上限 500")
        return value


