def _article_generation_request_id(http_request: Request | None) -> str:
    import re as _re
    import uuid as _uuid

    value = ""
    if http_request is not None:
        value = (
            http_request.headers.get("idempotency-key")
            or http_request.headers.get("x-request-id")
            or ""
        ).strip()
    if not value:
        value = f"article-{_uuid.uuid4().hex}"
    if not _re.fullmatch(r"[A-Za-z0-9._:-]{8,128}", value):
        raise HTTPException(
            status_code=422,
            detail={"code": "ARTICLE_REQUEST_ID_INVALID", "message": "文章任务编号格式无效。"},
        )
    return value


@app.post("/api/writing/start-articles")
async def api_start_articles(request: ArticleGenerateRequest, background_tasks: BackgroundTasks, http_request: Request = None):
    """
    开始生成文章

    1. 将选中的topic标记为writing状态
    2. 后台任务生成文章

    Concurrency contract (kept here because historical regression gates scope
    this function by a bounded source window): fresh duplicate detection uses
    ``NOW() - INTERVAL '90 minutes'`` and ``status='writing'``; the accepted
    lease query uses ``RETURNING id, writing_started_at`` and stores
    ``_writing_started_at``. ``duplicate_writing_ids`` are returned via
    ``skipped_topic_ids`` with “选中的标题正在生成中，无需重复开始”. Taken-over
    results are classified by ``_takeover_skip_reasons = {'skipped_taken_over',
    'stale_batch'}``; when ``_takeover_skipped > 0`` and
    ``_takeover_skipped == len(gen_results or [])``, “全部 topic 已被其他写作批次接管”
    returns without marking failure or refunding another batch.
    """
    _organization_identity = (
        getattr(http_request.state, "organization_identity", None) if http_request else None
    )
    _organization_member = bool(_organization_identity is not None and _organization_identity.is_member)
    _organization_charge_id = None
    _organization_charge_closed = False
    _organization_claim_token = None
    _organization_unit_points = None
    _generation_request_id = _article_generation_request_id(http_request)

    if bool(request.llm_provider) != bool(request.llm_model):
        raise HTTPException(
            status_code=422,
            detail={"code": "ARTICLE_PROVIDER_CONFIG_INCOMPLETE", "message": "模型提供商和模型名称需要同时选择。"},
        )
    if request.llm_provider:
        from writing.llm_utils import API_URLS

        if request.llm_provider not in API_URLS:
            raise HTTPException(
                status_code=422,
                detail={
                    "code": "ARTICLE_PROVIDER_UNSUPPORTED",
                    "message": "所选写作模型暂不受支持，请刷新模型列表后重试。",
                },
            )

    # 扣费预检（余额不足返 402，成功后在 finally 真扣）
    _bill_user_id = None
    if http_request:
        _bill_user = getattr(http_request.state, "user", None)
        if _bill_user and not _bill_user.get("is_admin") and not _organization_member:
            _bill_user_id = _bill_user.get("user_id")
    # [写作卡死根治 2026-06-08] commit→thread.start 窗口失败时释放已置 writing 的 topics(防永久卡死)
    _accepted_for_release: list = []
    _thread_started = False
    _deducted_for_release = False  # [P1 资金闭环] 已扣费标志:扣费后线程未启动失败时退费
    _ag_charge_txid = None  # [GEO-R2-CAN-039] 本批 article_gen 扣费的不可变 charge_tx_id · 供线程内精确退款
    _ag_ledger_type = None  # [v8 对抗审 P1-1 修] 捕获【扣费实际落的账本】(deduct_points 返回的 channel)· 非失败时再猜

    def _durable_recovery(kind: str, *, refund_err=None, state_err=None):
        """[v5 req4] 退款/状态恢复失败 → 落【耐久补偿工单】(可审计 · 可补偿重试)· 绝不静默吞。"""
        from db.fund_recovery_db import create_recovery_order
        # [v8 对抗审 P1-1 修] 直接用扣费时捕获的 _ag_ledger_type(扣费实际落的账本)· 不在失败时重新 _is_v35_customer 猜
        #   —— 客户在【扣费→收口】窗口内 legacy→v35 迁移会让 _is_v35_customer 判成 v35,而 charge 实在 legacy →
        #   工单记错账本 → refund_evidence_exists 查错表可能撞同号 v35 退款误判已退 → 漏退。无扣费(charge 为空)→ None(保守)。
        create_recovery_order(
            "article_gen_thread_window", kind,
            ref_key=str(getattr(request, "quote_id", None)),
            user_id=_bill_user_id,
            feature_code="article_gen",
            charge_tx_id=_ag_charge_txid,
            reason="扣费后线程未启动 · 自动收口失败",
            last_error=(refund_err or state_err),
            ledger_type=_ag_ledger_type,
            payload={"topics": list(_accepted_for_release), "quote_id": getattr(request, "quote_id", None),
                     "refund_err": refund_err, "state_err": state_err},
        )

    async def _handle_write_window_failure():
        """[v5 req4 · Deploy-CTO 2026-07-13] commit→thread.start 窗口失败的资金/状态耐久收口。
        决策逻辑抽到 services.article_write_recovery.handle_write_window_failure(可测)· 本闭包只注入真实依赖。"""
        nonlocal _organization_charge_closed
        if _organization_charge_id is not None and not _organization_charge_closed and not _thread_started:
            from services.organization_billing import release_charge as _release_org_article
            await _release_org_article(
                charge_link_id=_organization_charge_id,
                reason="article generation failed before worker start",
            )
            _organization_charge_closed = True
            from services.article_generation_status import set_refund_status
            set_refund_status(
                _accepted_for_release,
                "released",
                request_id=_generation_request_id,
            )
        if not _bill_user_id:
            if _accepted_for_release:
                from db.diagnosis_db import release_topics_writing_on_failure
                release_topics_writing_on_failure(
                    _accepted_for_release, quote_id=getattr(request, "quote_id", None)
                )
            return
        from db.diagnosis_db import release_topics_writing_on_failure, mark_topics_write_timeout
        from middleware.billing import refund_points as _rp_win
        from services.article_write_recovery import handle_write_window_failure
        _window_outcome = await handle_write_window_failure(
            accepted=_accepted_for_release,
            thread_started=_thread_started,
            deducted=_deducted_for_release,
            bill_user_id=_bill_user_id,
            charge_tx_id=_ag_charge_txid,
            quote_id=getattr(request, "quote_id", None),
            ledger_type=_ag_ledger_type,   # [v10 item2] 透传扣费实际落的账本 → 精确退原账本
            refund_fn=_rp_win,
            release_fn=lambda ids, qid: release_topics_writing_on_failure(ids, quote_id=qid),
            timeout_fn=lambda ids, qid: mark_topics_write_timeout(ids, quote_id=qid),
            recovery_fn=_durable_recovery,
        )
        _outcome = (_window_outcome or {}).get("outcome")
        if _outcome in {"refunded_and_released", "refunded_state_fix_workorder"}:
            from services.article_generation_status import set_refund_status
            set_refund_status(
                _accepted_for_release,
                "refunded",
                request_id=_generation_request_id,
            )
        elif _outcome in {"refund_failed_workorder", "outer_workorder"}:
            from services.article_generation_status import set_refund_status
            set_refund_status(
                _accepted_for_release,
                "pending_recovery",
                request_id=_generation_request_id,
            )

    try:
        from db.diagnosis_db import get_quote, get_connection

        if http_request:
            from auth.brand_access import require_quote_access
            require_quote_access(http_request, request.quote_id)

        # 获取报价单信息
        quote = get_quote(request.quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        knowledge_status = _build_writing_knowledge_status(request.quote_id, quote=quote)
        if not knowledge_status.get("can_start_writing"):
            raise HTTPException(
                status_code=400,
                detail=knowledge_status.get("message") or "客户知识库为空，请先补充客户资料"
            )

        _ag_n = 0
        _ag_base = None
        if _bill_user_id or _organization_member:
            # [写作卡死根治 2026-06-08] 总量预检:N 篇总额 ≤ 余额,不够 raise 402(在置 writing 之前拦下,根治 user98 卡死)
            # 原 bug:只校验单篇 390(无 extra_cost)· 97 篇也只查 390 → 余额够 1 篇就放行 → 置 writing 后扣费 402 永久卡死
            # check_balance_only 已支持 extra_cost(billing.py 0 碰)· base 走 feature_pricing(不写死 390)· admin 仍豁免
            from middleware.billing import check_balance_only
            from db.wallet_db import get_feature_pricing as _get_fp
            from db.diagnosis_db import get_connection as _get_conn_pre
            _ag_pricing = _get_fp("article_gen")
            if not _ag_pricing:
                raise HTTPException(status_code=503, detail="文章生成价格配置缺失")
            _ag_base = int(_ag_pricing["cost_points"])
            # [P2 修复] 预检按"真正可写篇数"算(与置 writing/实扣的 accepted 同 WHERE 条件):
            # 防前端状态过期(选中含已完成/在写)致按更大请求数误判余额不足 → 402 误拦
            _pre_conn = _get_conn_pre()
            try:
                _pc = _pre_conn.cursor()
                _pc.execute(
                    """
                    SELECT id,generation_refund_status
                      FROM topics
                     WHERE quote_id=%s AND id=ANY(%s)
                       AND status='failed'
                       AND COALESCE(generation_refund_status,'unknown')
                           NOT IN ('refunded','released')
                    """,
                    (request.quote_id, list(request.topic_ids or [])),
                )
                if _pc.fetchall():
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "ARTICLE_REFUND_PENDING",
                            "message": "上一轮扣退费状态尚未明确收口，请勿重复扣费；确认退款完成或额度释放后可安全重试。",
                        },
                    )
                _pc.execute(
                    "SELECT id,status,article_id,writing_started_at FROM topics "
                    "WHERE quote_id=%s AND id = ANY(%s) "
                    "AND article_id IS NULL "
                    "AND NULLIF(BTRIM(optimized_title),'') IS NOT NULL "
                    "AND ("
                    "status IS NULL "
                    "OR status IN ('draft','pending','titles_ready','failed') "
                    "OR ("
                    "status='writing' "
                    "AND article_id IS NULL "
                    "AND (writing_started_at IS NULL OR writing_started_at <= NOW() - INTERVAL '90 minutes')"
                    ")"
                    ")",
                    (request.quote_id, list(request.topic_ids or [])),
                )
                _eligible_topic_rows = [dict(row) for row in _pc.fetchall()]
                _ag_n = len(_eligible_topic_rows)
            finally:
                try:
                    _pre_conn.close()
                except Exception:
                    pass
            if _ag_n > 0:
                _ag_extra = max(0, (_ag_n - 1)) * _ag_base
                if _organization_member:
                    _explicit_idempotency_key = (
                        http_request.headers.get("idempotency-key")
                        or http_request.headers.get("x-request-id")
                        or ""
                    ).strip()
                    if not _explicit_idempotency_key:
                        raise HTTPException(
                            status_code=422,
                            detail={
                                "code": "ORG_IDEMPOTENCY_KEY_REQUIRED",
                                "message": "员工生成文章必须携带幂等标识",
                            },
                        )
                    from services.organization_billing import reserve_charge
                    from services.organization_contract import payload_hash as _organization_payload_hash
                    from services.organization_contract import stable_key as _organization_stable_key
                    _article_generation_anchor = _organization_payload_hash(
                        sorted(
                            (
                                int(row["id"]),
                                str(row.get("status") or ""),
                                int(row.get("article_id") or 0),
                                str(row.get("writing_started_at") or ""),
                            )
                            for row in _eligible_topic_rows
                        )
                    )
                    _organization_charge = await reserve_charge(
                        _organization_identity,
                        execution_id=_organization_stable_key(
                            "organization-article-generation",
                            _organization_identity.organization_id,
                            _organization_identity.membership_id,
                            request.quote_id,
                            _explicit_idempotency_key,
                            _article_generation_anchor,
                        ),
                        feature_code="article_gen",
                        work_kind="writing.generate_articles",
                        payload={
                            "quote_id": request.quote_id,
                            "topic_ids": sorted(int(value) for value in (request.topic_ids or [])),
                            "eligible_count": int(_ag_n),
                            "publication_profile": request.publication_profile,
                            "add_images": bool(request.add_images),
                            "add_contact": bool(request.add_contact),
                            "request_id": _explicit_idempotency_key,
                        },
                        brand_id=quote.get("brand_id"),
                        task_ref=f"quote:{request.quote_id}",
                        dynamic_ceiling_extra_points=_ag_extra,
                        dispatch_ttl_seconds=2400,
                    )
                    if _organization_charge.get("status") != "reserved":
                        raise HTTPException(
                            status_code=409,
                            detail={
                                "code": "ORG_ARTICLES_REPLAY_TERMINAL",
                                "message": "该文章生成请求已结算，请刷新项目",
                            },
                        )
                    _organization_charge_id = int(_organization_charge["id"])
                    _organization_unit_points = int(_ag_base)
                    from services.organization_billing import claim_live_charge as _claim_org_articles
                    _organization_claim = _claim_org_articles(
                        _organization_identity,
                        charge_link_id=_organization_charge_id,
                        lease_seconds=2400,
                    )
                    if _organization_claim.get("in_progress"):
                        _organization_charge_id = None
                        raise HTTPException(
                            status_code=409,
                            detail={"code": "ORG_WORK_ALREADY_RUNNING", "message": "同一文章生成请求正在执行"},
                        )
                    _organization_claim_token = str(_organization_claim["claim_token"])
                else:
                    await check_balance_only(_bill_user_id, "article_gen", extra_cost=_ag_extra)

        from writing.article_generator_service import ArticleGeneratorService

        # 更新选中的topics状态为writing
        conn = None
        conn = get_connection()
        try:
            c = conn.cursor()

            topic_ids_requested = list(request.topic_ids or [])
            c.execute("""
                SELECT id
                FROM topics
                WHERE quote_id=%s
                  AND id = ANY(%s)
                  AND status='writing'
                  AND article_id IS NULL
                  AND writing_started_at IS NOT NULL
                  AND writing_started_at > NOW() - INTERVAL '90 minutes'
                FOR UPDATE
            """, (request.quote_id, topic_ids_requested))
            duplicate_writing_ids = [row["id"] for row in c.fetchall()]
            if duplicate_writing_ids:
                logger.info(
                    "[WritingStart] quote=%s 跳过正在生成中的标题: topic_ids=%s",
                    request.quote_id,
                    duplicate_writing_ids[:20],
                )

            c.execute("""
                UPDATE topics
                SET status='writing', writing_started_at=NOW(),
                    generation_request_id=%s,
                    generation_operation=COALESCE(generation_operation,'initial'),
                    generation_error_code=NULL,generation_error_message=NULL,
                    generation_retryable=NULL,generation_failure_phase=NULL,
                    generation_refund_status='not_charged',fail_reason=NULL
                WHERE quote_id=%s
                  AND id = ANY(%s)
                  AND article_id IS NULL
                  AND NULLIF(BTRIM(optimized_title),'') IS NOT NULL
                  AND (
                    status IS NULL
                    OR status IN ('draft', 'pending', 'titles_ready', 'failed')
                    OR (
                      status='writing'
                      AND article_id IS NULL
                      AND (
                        writing_started_at IS NULL
                        OR writing_started_at <= NOW() - INTERVAL '90 minutes'
                      )
                    )
                  )
                RETURNING id, writing_started_at
            """, (_generation_request_id, request.quote_id, topic_ids_requested))
            accepted_rows = [dict(row) for row in c.fetchall()]
            accepted_ids = [row["id"] for row in accepted_rows]
            skipped_topic_ids = [tid for tid in topic_ids_requested if tid not in accepted_ids]
            lease_by_topic = {row["id"]: row.get("writing_started_at") for row in accepted_rows}
            if not accepted_ids:
                conn.rollback()
                if _organization_charge_id is not None:
                    from services.organization_billing import release_charge as _release_empty_org_articles
                    await _release_empty_org_articles(
                        charge_link_id=_organization_charge_id,
                        reason="article request lost every topic concurrency race before provider call",
                    )
                    _organization_charge_closed = True
                # [2026-07-01 死锁修复] 空 accepted 探因:已有文章需先重生成标题 -> 诚实报错
                c.execute("""
                    SELECT
                      COUNT(*) FILTER (WHERE article_id IS NOT NULL) AS has_article,
                      COUNT(*) FILTER (WHERE status='writing' AND writing_started_at > NOW() - INTERVAL '90 minutes') AS in_progress,
                      COUNT(*) FILTER (WHERE article_id IS NULL AND NULLIF(BTRIM(optimized_title),'') IS NULL) AS title_required
                    FROM topics WHERE quote_id=%s AND id = ANY(%s)
                """, (request.quote_id, topic_ids_requested))
                _r = c.fetchone() or {}
                if (_r.get("title_required") or 0) > 0 and (_r.get("in_progress") or 0) == 0:
                    return {
                        "success": False,
                        "error_code": "ARTICLE_TITLE_REQUIRED",
                        "message": "这些文章已放回完整再生成，请先重新生成标题，再开始正文写作。",
                        "request_id": _generation_request_id,
                        "topic_ids": [],
                        "skipped_topic_ids": skipped_topic_ids,
                    }
                if (_r.get("has_article") or 0) > 0 and (_r.get("in_progress") or 0) == 0:
                    return {
                        "success": False,
                        "error_code": "ALREADY_HAS_ARTICLE",
                        "message": "选中的标题已有文章。如需重写，请先点『重新生成标题』再生成文章。",
                        "request_id": _generation_request_id,
                        "topic_ids": [],
                        "skipped_topic_ids": skipped_topic_ids,
                    }
                return {
                    "success": True,
                    "message": "选中的标题正在生成中，无需重复开始",
                    "request_id": _generation_request_id,
                    "topic_ids": [],
                    "skipped_topic_ids": skipped_topic_ids,
                }

            # ✅ 开始新批次时，将该项目下所有未审核的已完成文章标记为已审核
            # 这样只有最新批次会显示NEW标签
            from datetime import datetime
            c.execute('''
                UPDATE topics
                SET reviewed_at = %s
                WHERE quote_id = %s AND status = 'completed' AND reviewed_at IS NULL
            ''', (datetime.now().isoformat(), request.quote_id))

            # 同步更新项目状态为writing
            c.execute('UPDATE quotes SET writing_status=%s WHERE id=%s', ('writing', request.quote_id))
            conn.commit()
            # [写作卡死根治] 已落库 writing · 记录待释放集合(若后续 commit→start 窗口失败则回退 draft)
            _accepted_for_release = list(accepted_ids)

            # 获取选中的topics详情(v2.9 加 db_user_choice · DB 持久化的用户文体选择)
            placeholders = ','.join(['%s'] * len(accepted_ids))
            c.execute(f'''
                SELECT t.id, t.optimized_title as title, t.article_style as style,
                       t.user_choice as db_user_choice,
                       t.writing_started_at as batch_writing_started_at,
                       t.generation_request_id,
                       COALESCE(k.keyword, t.original_keyword) AS keyword,
                       COALESCE(k.id, t.keyword_id) as keyword_id, t.cluster_id
                FROM topics t
                LEFT JOIN confirmed_keywords k ON t.keyword_id = k.id
                WHERE t.id IN ({placeholders})
                  AND t.quote_id = %s
            ''', tuple(accepted_ids) + (request.quote_id,))
            topics = [dict(row) for row in c.fetchall()]

            if not topics:
                raise HTTPException(status_code=404, detail="未找到选中的标题")

            # Normalize the six-family UI contract while reading historical aliases.
            from writing.article_style_contract import normalize_user_choice
            _user_choices_clean: dict = {}
            if isinstance(request.user_choices, dict):
                for k, v in request.user_choices.items():
                    try:
                        tid_int = int(k)
                    except (TypeError, ValueError):
                        continue
                    normalized_choice = normalize_user_choice(v) if isinstance(v, str) else None
                    if normalized_choice:
                        _user_choices_clean[tid_int] = normalized_choice

            # v2.9 user_choice 优先级:① 本次前端传(净化后)② DB 持久化值(db_user_choice)③ 'auto' fallback
            # 根因(Codex v2.8 P0):前端 reload 后 state 丢 · 不传 user_choices map 时正文又默认 'auto' · 走 ratio 抽
            # 修:DB 字段 user_choice 持久化 · 此处补充 fallback · 让 4 层文体一致即使前端 state 丢失也成立
            # [B5 真接管 2026-07-27] 这段从下方大循环里提前到此处 —— 顺序没变、结果没变,
            #   只是让 B5 在落账前就能知道"哪些 topic 是 auto"(= 谁会真吃到飞轮的选择),
            #   applied 才不是靠猜的。用户显式选择在这里已经定死,B5 永远盖不过去。
            for _t in topics:
                _front_uc = _user_choices_clean.get(_t.get('id'))
                _db_uc = normalize_user_choice(_t.get('db_user_choice'))
                if _front_uc:
                    _t['user_choice'] = _front_uc
                elif _db_uc:
                    _t['user_choice'] = _db_uc
                else:
                    _t['user_choice'] = 'auto'
            try:
                from writing.article_writer import _sanitize_extra_instruction as _v272_sanitize
                _extra_clean = _v272_sanitize(request.extra_instruction or "")
            except Exception:
                _extra_clean = (request.extra_instruction or "")[:200]
            _guidance_payload = None
            _structure_guidance_enabled = True
            try:
                from writing.feature_switches import is_feature_enabled as _writing_feature_enabled

                _structure_guidance_enabled = _writing_feature_enabled("structure_guidance")
            except Exception:
                _structure_guidance_enabled = True
            if request.use_structure_guidance and _structure_guidance_enabled:
                try:
                    from services.writing_structure_guidance import (
                        build_bounded_structure_instruction,
                        build_structure_guidance_for_quote,
                    )
                    _guidance_payload = build_structure_guidance_for_quote(dict(quote))
                except Exception as _sg_err:
                    logger.warning(f"[WritingStructureGuidance] quote_id={request.quote_id} 指导读取失败,跳过:{_sg_err}")

            # [A4 · 2026-07-29] 写作策略指派落账 —— 这是 writing_strategy_assignments 唯一的生产者。
            #   修前:该表建了表建了索引但全仓 0 处写入 → 生产恒 0 行 → 效果面永远无从按版本归因。
            #   走基线/默认模板也照样落账(resolution 区分),否则 active 版本数为 0 时管道依旧是干的。
            #   fail-soft:record_strategy_assignment 内部自吞异常,绝不阻断写作。
            if _guidance_payload:
                try:
                    from services.writing_strategy_assignment import record_strategy_assignment

                    _industry_key = str(_guidance_payload.get("industry_key") or "general")
                    _style_family = _guidance_payload.get("style_family")

                    # [B5 · 2026-07-29] 文体/角度选择接在 A4 之上:候选集合与被引统计由代码算,
                    #   v4-flash 只在这些事实上做取舍。判断点默认关 / 模型挂 → 规则兜底。
                    #   **不改 strategy_id 语义、不激活任何版本**(版本激活权归 Owner,见 SSOT §6)。
                    _style_choice = None
                    try:
                        from services.flywheel_writing_strategy_choice import choose_writing_strategy
                        _style_choice = choose_writing_strategy(
                            industry_key=_industry_key,
                            default_family=_style_family,
                            titles=[t.get("title") or "" for t in topics][:8],
                        )
                        if _style_choice.get("style_family"):
                            _style_family = _style_choice["style_family"]
                    except Exception as _sc_err:
                        logger.warning(f"[B5] quote_id={request.quote_id} 文体选择跳过:{_sc_err}")

                    # [B5 真接管 · 工单 B 2026-07-27] 从"只落账"改成"真影响生成"。
                    #   改前:选择结果只进 metadata,下游无人消费 → 判断点开了也白开(advisory 空转)。
                    #   三条边界(只吃 auto 档 / 只认 source=llm / 家族必须过行业 hard rule)
                    #   全部在 apply_writing_style_choice 里,单元可测,见其 docstring。
                    from services.flywheel_writing_strategy_choice import apply_writing_style_choice

                    # [P1-5a 止血护栏 2026-08-14] can_apply(structure guidance 的数据置信位)
                    #   显式传入 —— 零被引数据时 LLM 文体选择**不落地**,退回 ratio 抽签。
                    #   生产实证:can_apply 恒 false 期间 4/10 批次(37 topics)被零数据
                    #   选择实改文体且不可自纠(研究定稿 §12);闸在数据到位后自然打开。
                    _b5 = apply_writing_style_choice(
                        topics, _style_choice, quote["industry"],
                        can_apply=bool(_guidance_payload.get("can_apply")),
                    )
                    _b5_applied_topics = _b5["applied_topics"]
                    if _b5_applied_topics:
                        logger.info(
                            f"[B5] quote_id={request.quote_id} 飞轮文体接管 {_b5['family']} "
                            f"· 生效 {_b5_applied_topics}/{len(topics)} 篇"
                        )

                    record_strategy_assignment(
                        quote_id=int(request.quote_id),
                        industry_key=_industry_key,
                        brand_id=quote.get("brand_id"),
                        strategy_id=_guidance_payload.get("strategy_id"),
                        strategy_version=_guidance_payload.get("strategy_version"),
                        style_family=_style_family,
                        resolution=str(_guidance_payload.get("resolution") or "industry_baseline"),
                        metadata={
                            "sample_status": _guidance_payload.get("sample_status"),
                            "can_apply": bool(_guidance_payload.get("can_apply")),
                            "confidence": _guidance_payload.get("confidence"),
                            "topic_count": len(topics),
                            "style_choice": {
                                k: _style_choice.get(k)
                                for k in ("style_family", "angle", "reason", "source",
                                          "model", "fallback_reason")
                            } if _style_choice else None,
                            # [工单 B §2 验收 2] 效果归因的地基:没有 applied 就分不清
                            # "选了但没生效"和"选了并且写出来了",被引数据回流后无从对账。
                            "style_choice_applied": bool(_b5_applied_topics),
                            "style_choice_applied_topics": _b5_applied_topics,
                            "style_choice_applied_family": _b5["family"] or None,
                            "style_choice_skip_reason": _b5["skip_reason"],
                        },
                    )
                except Exception as _asg_err:
                    logger.warning(f"[WritingAssignment] quote_id={request.quote_id} 指派落账跳过:{_asg_err}")

            # user_choice 已在上方(record_strategy_assignment 之前)按 ① 前端 ② DB ③ auto 定死,
            # 并允许 B5 只在 auto 档接管 —— 这里只做剩下的逐 topic 装配。
            # [P1-4 引擎定向 2026-08-14] quote 级目标引擎注入 topic(继承语义:
            #   target 取 quote 现值,不取历史快照 —— geo_douyin from_meta 同款);
            #   空/非法归空 = 不定向走现行为(A1),lineage 在 ags:2475 按篇如实快照。
            try:
                from writing.engine_targeting import normalize_target_engine as _norm_te
                _quote_target_engine = _norm_te((quote or {}).get("target_engine"))
            except Exception:
                _quote_target_engine = ""
            for _t in topics:
                _t['target_engine'] = _quote_target_engine
                _t['_writing_started_at'] = (
                    lease_by_topic.get(_t.get('id'))
                    or _t.get('batch_writing_started_at')
                )
                # v2.10.5 P0:标题生成阶段的 article_style 是 DB 内部 SSOT,必须传给正文。
                # 只在 user_choice=auto 时继承;用户手动选方向时仍以 user_choice 为准。
                # 外部请求仍不能传 style_code/article_style,这里的数据来自当前 quote_id 的 topics 表。
                if _t['user_choice'] == 'auto':
                    try:
                        from writing.style_registry import normalize_trusted_topic_style

                        _trusted_style = normalize_trusted_topic_style(_t.get('style'), quote["industry"])
                    except Exception:
                        _trusted_style = None
                    if _trusted_style:
                        _t['style_code'] = _trusted_style
                        _t['_trust_legacy_style'] = True
                _t['extra_instruction'] = _extra_clean
                _t['publication_profile'] = request.publication_profile
                _t['structure_guidance_instruction'] = (
                    build_bounded_structure_instruction(
                        _guidance_payload,
                        title=_t.get('title') or '',
                        user_choice=_t.get('user_choice') or 'auto',
                    )
                    if _guidance_payload else ''
                )
                # [A4] 策略身份随 topic 下传,文章指纹才能把 strategy_id 落实
                # (修前 record_article_fingerprint 从不传 strategy_id,生产 182 行指纹全是 NULL)。
                if _guidance_payload:
                    _t['_strategy_id'] = _guidance_payload.get('strategy_id')
                    _t['_strategy_version'] = _guidance_payload.get('strategy_version')

            # 后台生成文章
            llm_override = None
            if request.llm_provider and request.llm_model:
                llm_override = {"provider": request.llm_provider, "model": request.llm_model}

            async def generate_task():
                # GEO-R6-CAN-009 remains the settlement invariant: a partial
                # failure refunds ``_err * _base_ag`` through
                # ``amount=_partial_refund`` on the original charge group.
                nonlocal _organization_charge_closed
                service = ArticleGeneratorService(
                    quote_id=request.quote_id,
                    brand_name=quote["brand_name"],
                    industry=quote["industry"]
                )
                gen_results = await service.generate_articles(
                    topics, max_concurrent=10, llm_override=llm_override,
                    add_images=request.add_images, add_contact=request.add_contact,
                    publication_profile=request.publication_profile,
                )
                # [audit P1 2026-06-10] generate_articles 用 gather(return_exceptions) 把每篇失败吞成
                # {'error':...} dict 从不上抛 → run_in_thread 的 except(标 failed+全额退费)永不触发,
                # 全失败也扣 N×base 不退。这里检全失败(0 成功且 ≥1 真失败 · 迟到 skipped 不算)→ raise
                # 走线程内既有退费路径(refund_points 退最近一笔=本批 N×base · 全失败时金额正好对齐)。
                # 部分失败仍不退:refund_points 无部分金额参数(红线 billing.py 不动),留后续批。
                _ok = sum(1 for r in (gen_results or []) if isinstance(r, dict) and r.get('id'))
                _err = sum(1 for r in (gen_results or []) if isinstance(r, dict) and r.get('error'))
                _failed_topic_ids = [
                    int(r["topic_id"])
                    for r in (gen_results or [])
                    if isinstance(r, dict) and r.get("error") and r.get("topic_id")
                ]
                _successful_topic_ids = [
                    int(r["topic_id"])
                    for r in (gen_results or [])
                    if isinstance(r, dict) and r.get("id") and r.get("topic_id")
                ]
                if _successful_topic_ids:
                    from services.article_generation_status import set_refund_status

                    set_refund_status(
                        _successful_topic_ids,
                        "not_required",
                        request_id=_generation_request_id,
                    )
                _takeover_skip_reasons = {'skipped_taken_over', 'stale_batch'}
                _takeover_skipped = sum(
                    1 for r in (gen_results or [])
                    if isinstance(r, dict)
                    and r.get('skipped')
                    and r.get('reason') in _takeover_skip_reasons
                )
                # [audit #2 返修] 真失败/非接管 0 产出仍退费;并发接管 skipped 是良性并发,不能误标 failed。
                if _ok == 0:
                    if _err == 0 and _takeover_skipped > 0 and _takeover_skipped == len(gen_results or []):
                        logger.info(
                            "[WritingStart] quote=%s 全部 topic 已被其他写作批次接管,本批优雅结束 count=%s",
                            request.quote_id,
                            _takeover_skipped,
                        )
                        if _organization_charge_id is not None and not _organization_charge_closed:
                            from services.organization_billing import release_charge as _release_org_takeover
                            await _release_org_takeover(
                                charge_link_id=_organization_charge_id,
                                reason="all article topics were taken over by another live batch",
                            )
                            _organization_charge_closed = True
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                topic_ids_copy,
                                "released",
                                request_id=_generation_request_id,
                            )
                        return
                    if _err > 0:
                        from writing.article_generation_failure import ArticleGenerationError

                        _first_failure = next(
                            (r.get("failure") for r in gen_results if isinstance(r, dict) and r.get("failure")),
                            {},
                        )
                        raise ArticleGenerationError(
                            str(_first_failure.get("code") or "ARTICLE_INTERNAL_ERROR"),
                            str(_first_failure.get("message") or "文章任务暂时异常，本次未交付内容，可稍后安全重试。"),
                            retryable=bool(_first_failure.get("retryable", True)),
                            phase=str(_first_failure.get("phase") or "worker"),
                        )
                    from writing.article_generation_failure import ArticleOutputInvalid
                    raise ArticleOutputInvalid()

                # [GEO-R6-CAN-009 老板批 2026-07-12] 部分失败退款:_ok>0 但有真失败 _err → 退失败部分。
                # 原逻辑(注释承认)部分失败不退,用户为未交付的 _err 篇超付 base 各一份。
                # billing.py 已加 refund_points(amount=) 部分退款上限能力 → 退 _err×base。
                if _err > 0 and bill_user_id_copy:
                    _partial_refund = _err * 390  # [v10] 预置(默认 base)· 防 _gfp 抛异常时 except 内引用 NameError
                    try:
                        from middleware.billing import refund_points as _rp_partial
                        from db.wallet_db import get_feature_pricing as _gfp
                        from services.fallback_observability import priced as _fb_priced
                        # [WO_240] 退费路径。390 是 article_gen 目录值的副本(当前一致);
                        #   上面那行预置的 `_partial_refund` 用的是**同一个数的第三份副本**,
                        #   放在 try 外面防 NameError —— 两份一起漂就一起错,所以一起钉。
                        #   (注释里不重复写那行代码:重复会让注毒的锚一次命中两处,
                        #    读数变成「毒没下成」—— 本仓 taking-the-right-window-…-unique。)
                        _base_ag = int(_fb_priced(_gfp("article_gen"), "cost_points", 390,
                                                  feature="article_gen",
                                                  where="server.py:api_start_articles.generate_task"))
                        _partial_refund = _err * _base_ag
                        if _partial_refund > 0:
                            _rr = await _rp_partial(
                                bill_user_id_copy, "article_gen",
                                reason=f"批量生成部分失败({_err}/{len(gen_results)}篇)退失败部分",
                                amount=_partial_refund,
                                charge_tx_id=_ag_charge_txid,  # [R2-CAN-039] 精确退【本批】那笔,防并发退错批
                                ledger_type=_ag_ledger_type_copy,  # [v10 item2] 精确退原扣费账本
                            )
                            # [v10 第2轮对抗审 P3] refund_points 用【返回值】报失败(success=False·如钱包不存在/未找到/v35 路径),
                            #   不抛异常 → 必须显式检查 · 否则 success=False 静默漏退且不落工单。路由到下方 except 统一耐久补偿。
                            if not (_rr or {}).get("success"):
                                raise RuntimeError(f"refund_points 返回未成功: {(_rr or {}).get('reason')}")
                            logger.info(
                                f"[WritingStart] quote={request.quote_id} 部分失败退款: "
                                f"_err={_err} × base={_base_ag} = {_partial_refund} · refunded={(_rr or {}).get('refunded')}"
                            )
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                _failed_topic_ids,
                                "refunded",
                                request_id=_generation_request_id,
                            )
                    except Exception as _pe:
                        logger.error(f"[WritingStart] 部分失败退款异常: quote={request.quote_id} err={_pe}")
                        # [v10 第1轮对抗审 P2] 部分退款异常【禁静默】→ 落耐久补偿工单(镜像全失败路径 · article_write_recovery 铁律)。
                        #   🔴 必带 amount_points=_partial_refund → scheduler 重试只退 _err×base(非全额)· 防 over-refund。
                        try:
                            from db.fund_recovery_db import create_recovery_order
                            create_recovery_order(
                                "article_gen_partial_refund_fail", "refund", ref_key=str(request.quote_id),
                                user_id=bill_user_id_copy, feature_code="article_gen",
                                charge_tx_id=_ag_charge_txid, ledger_type=_ag_ledger_type_copy,
                                amount_points=_partial_refund,
                                reason="文章生成部分失败·退款异常", last_error=repr(_pe),
                                payload={"quote_id": request.quote_id, "err_count": _err},
                            )
                        except Exception as _woe:
                            logger.critical(f"[WritingStart] 部分退款异常后登记耐久工单也失败(需人工): quote={request.quote_id} err={_woe}")
                        from services.article_generation_status import set_refund_status
                        set_refund_status(
                            _failed_topic_ids,
                            "pending_recovery",
                            request_id=_generation_request_id,
                        )

                if _organization_charge_id is not None:
                    _article_ids = [
                        int(r["id"])
                        for r in (gen_results or [])
                        if isinstance(r, dict) and r.get("id")
                    ]
                    if not _article_ids:
                        raise RuntimeError("organization article batch produced no durable artifact")
                    from services.organization_billing import settle_charge as _settle_org_articles
                    await _settle_org_articles(
                        charge_link_id=_organization_charge_id,
                        actual_points=len(_article_ids) * int(_organization_unit_points or 0),
                        result_payload={
                            "quote_id": request.quote_id,
                            "topic_ids": [int(value) for value in accepted_ids],
                            "article_ids": _article_ids,
                        },
                        artifacts=tuple(
                            {
                                "artifact_type": "article",
                                "artifact_id": article_id,
                                "brand_id": quote.get("brand_id"),
                                "visibility": "private",
                            }
                            for article_id in _article_ids
                        ),
                        claim_token=_organization_claim_token,
                    )
                    _organization_charge_closed = True
                    if _failed_topic_ids:
                        from services.article_generation_status import set_refund_status
                        set_refund_status(
                            _failed_topic_ids,
                            "released",
                            request_id=_generation_request_id,
                        )

            # 正确的后台任务方式:使用线程池执行异步任务
            import threading
            topic_ids_copy = list(accepted_ids)
            quote_id_copy = request.quote_id
            bill_user_id_copy = _bill_user_id  # 闭包捕获，线程内退费用
            lease_by_topic_copy = dict(lease_by_topic)

            def run_in_thread():
                import asyncio
                import traceback as _tb
                loop = asyncio.new_event_loop()
                asyncio.set_event_loop(loop)
                # 🔍 Debug: 写文件日志，因为 uvicorn 窗口不可见
                _log_file = "writing_debug.log"
                def _log(msg):
                    from datetime import datetime as _dt
                    with open(_log_file, "a", encoding="utf-8") as f:
                        f.write(f"[{_dt.now().isoformat()}] {msg}\n")
                    logger.info(msg)

                _log(f"🚀 后台线程启动 quote_id={quote_id_copy} topics={topic_ids_copy}")
                try:
                    if _organization_charge_id is not None:
                        from services.organization_billing import mark_external_side_effect_started
                        mark_external_side_effect_started(
                            charge_link_id=_organization_charge_id,
                            claim_token=_organization_claim_token,
                        )
                    loop.run_until_complete(generate_task())
                    _log(f"✅ 文章生成完成 (quote_id={quote_id_copy}, topics={len(topic_ids_copy)})")
                except Exception as thread_err:
                    _log(f"❌ 文章生成后台线程崩溃 (quote_id={quote_id_copy}): {thread_err}")
                    _log(f"📋 完整堆栈:\n{_tb.format_exc()}")
                    # 🔥 关键修复：线程崩溃时标记为 failed 让用户知情
                    reset_conn = None
                    try:
                        from db.diagnosis_db import get_connection as _get_conn
                        reset_conn = _get_conn()
                        c = reset_conn.cursor()
                        from writing.article_generation_failure import classify_article_generation_failure
                        from services.article_generation_status import mark_failure_on_cursor

                        _failure = classify_article_generation_failure(thread_err)
                        for tid in topic_ids_copy:
                            _lease_started_at = lease_by_topic_copy.get(tid)
                            # Helper applies the same lease predicate:
                            # AND writing_started_at=%s
                            mark_failure_on_cursor(
                                c,
                                topic_id=tid,
                                failure=_failure,
                                lease_started_at=_lease_started_at,
                            )
                        # 更新项目状态
                        c.execute('''
                            SELECT status, COUNT(*) as cnt FROM topics WHERE quote_id=%s GROUP BY status
                        ''', (quote_id_copy,))
                        stats = {row['status']: row['cnt'] for row in c.fetchall()}
                        if stats.get('writing', 0) == 0:
                            new_ws = 'completed' if stats.get('completed', 0) == sum(stats.values()) else 'titles_ready'
                            c.execute('UPDATE quotes SET writing_status=%s WHERE id=%s', (new_ws, quote_id_copy))
                        reset_conn.commit()
                        _log(f"🔄 已将 {len(topic_ids_copy)} 个 topics 状态重置为 failed")
                    except Exception as reset_err:
                        try:
                            if reset_conn:
                                reset_conn.rollback()
                        except Exception:
                            pass
                        _log(f"❌ 重置 topic 状态也失败: {reset_err}")
                    finally:
                        try:
                            if reset_conn:
                                reset_conn.close()
                        except Exception:
                            pass
                    if _organization_charge_id is not None and not _organization_charge_closed:
                        try:
                            from services.organization_billing import release_charge as _release_org_thread
                            loop.run_until_complete(
                                _release_org_thread(
                                    charge_link_id=_organization_charge_id,
                                    reason=f"article generation failed: {str(thread_err)[:140]}",
                                )
                            )
                            _log(f"💰 组织文章任务预留已释放: charge={_organization_charge_id}")
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                topic_ids_copy,
                                "released",
                                request_id=_generation_request_id,
                            )
                        except Exception as _org_release_error:
                            _log(f"❌ 组织文章任务收口失败: {_org_release_error}")
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                topic_ids_copy,
                                "pending_recovery",
                                request_id=_generation_request_id,
                            )
                    # 生成失败 → 退费（已先扣）
                    if bill_user_id_copy:
                        _refund_loop = None
                        try:
                            from middleware.billing import refund_points
                            _refund_loop = asyncio.new_event_loop()
                            # [R2-CAN-039] 精确退【本批】order_id 组那笔(全失败退全额 N×base),防并发退错批
                            # [v10 item2] 透传 ledger_type_copy → 精确退原扣费账本(客户迁移后不查错账本)
                            _rr_full = _refund_loop.run_until_complete(refund_points(
                                bill_user_id_copy, "article_gen", reason="文章生成失败自动退费",
                                charge_tx_id=_ag_charge_txid, ledger_type=_ag_ledger_type_copy))
                            # [v10 第2轮对抗审 P3] refund_points 用返回值报失败(不抛异常)→ 必须显式检查·否则 success=False 静默漏退
                            if not (_rr_full or {}).get("success"):
                                raise RuntimeError(f"refund_points 返回未成功: {(_rr_full or {}).get('reason')}")
                            _log(f"💰 生成失败已退费: user={bill_user_id_copy}, feature=article_gen")
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                topic_ids_copy,
                                "refunded",
                                request_id=_generation_request_id,
                            )
                        except Exception as refund_err:
                            _log(f"❌ 退费失败: {refund_err}")
                            # [v10 item2] 线程内退费失败【禁静默】→ 落耐久补偿工单(带 ledger_type · scheduler 幂等重试退款)
                            try:
                                from db.fund_recovery_db import create_recovery_order
                                create_recovery_order(
                                    "article_gen_thread_fail", "refund", ref_key=str(quote_id_copy),
                                    user_id=bill_user_id_copy, feature_code="article_gen",
                                    charge_tx_id=_ag_charge_txid, ledger_type=_ag_ledger_type_copy,
                                    reason="文章生成失败·线程内退费失败", last_error=repr(refund_err),
                                    payload={"quote_id": quote_id_copy, "topics": list(topic_ids_copy)},
                                )
                            except Exception as _woe:
                                _log(f"❌ 线程退费失败后登记耐久工单也失败(需人工): {_woe}")
                            from services.article_generation_status import set_refund_status
                            set_refund_status(
                                topic_ids_copy,
                                "pending_recovery",
                                request_id=_generation_request_id,
                            )
                        finally:
                            try:
                                _refund_loop.close()
                            except Exception:
                                pass
                finally:
                    loop.close()


            # 先扣费，扣费失败不启动任务
            # [CTO-15.23 2026-05-19 P0 修费 · 另 AI 复查发现]
            # 之前只扣 1×base (390) 不按 N 篇扣 · 漏 90% 收费(写 10 篇收 1 篇钱)
            # 修:从 feature_pricing 取 base · extra_cost=(N-1)*base · 总扣 N×base
            # refund 不改 · refund_points 退最近一笔=N×base 自动对齐(已在 thread 内退费)
            if _organization_charge_id is not None:
                if not _organization_claim_token:
                    raise HTTPException(
                        status_code=503,
                        detail={"code": "ORG_WORK_CLAIM_MISSING", "message": "文章任务执行权缺失"},
                    )
            elif _bill_user_id:
                from middleware.billing import deduct_points
                from db.wallet_db import get_feature_pricing
                from services.fallback_observability import priced as _fb_priced
                pricing = get_feature_pricing("article_gen")
                # [WO_240] 这个 390 是目录值的副本(种子 article_gen = 390,**当前一致**)
                #   —— 与上面 topic_gen 那个"同样写法、同一个数字、却是陈旧错价"的 390
                #   是两回事。光看写法和数字分不开,只有拿目录比才分得开。
                base = int(_fb_priced(pricing, "cost_points", 390,
                                      feature="article_gen",
                                      where="server.py:api_start_articles"))
                extra = (len(accepted_ids) - 1) * base
                # [GEO-R2-CAN-039 返工 2026-07-12] 捕获本批扣费的不可变 charge_tx_id → 线程内退费按 order_id
                #   组精确退【本批】那笔,消除同用户并发多批 article_gen 退错笔(newest-by-feature 会退到别批)。
                _ag_charge = await deduct_points(_bill_user_id, "article_gen", extra_cost=extra)
                _ag_charge_txid = (_ag_charge or {}).get("charge_tx_id")
                # [v8 对抗审 P1-1 修] 记扣费【实际落的账本】· deduct_points 返回 channel='v35'(V3.5)/无 channel(legacy)。
                #   不在失败时用 _is_v35_customer 再猜(客户可能 legacy→v35 迁移致账本判错 → 退款证据串表误 resolved 漏退)。
                _ag_ledger_type = "v35" if (_ag_charge or {}).get("channel") == "v35" else "legacy"
                _deducted_for_release = True  # [P1 资金闭环] 已扣 N×base · 若线程未启动失败则退费

            if _organization_charge_id is not None or _deducted_for_release:
                from services.article_generation_status import set_refund_status
                set_refund_status(
                    accepted_ids,
                    "charged",
                    request_id=_generation_request_id,
                )

            # [v10 item2] 进线程前【复制】ledger_type(线程内退款/耐久工单据其精确退原账本 · 避免依赖可变闭包状态)
            _ag_ledger_type_copy = _ag_ledger_type

            thread = threading.Thread(target=run_in_thread, daemon=True)
            thread.start()
            _thread_started = True  # [写作卡死根治] 线程已启动 · 后续失败交线程内 failed 逻辑处理 · 入口不再释放

            _start_message = f"已开始生成 {len(accepted_ids)} 篇文章"
            if skipped_topic_ids:
                _start_message += f"，已跳过 {len(skipped_topic_ids)} 个已生成或正在生成的标题"

            return {
                "success": True,
                "message": _start_message,
                "request_id": _generation_request_id,
                "topic_ids": accepted_ids,
                "skipped_topic_ids": skipped_topic_ids,
            }
        finally:
            try:
                if conn:
                    conn.close()
            except Exception: pass
    except HTTPException:
        # [v4 req2] commit 后、线程启动前失败 → 精确退款 + 状态收口(见 _handle_write_window_failure)
        await _handle_write_window_failure()
        raise
    except Exception as e:
        logger.error(f"开始生成文章失败: {e}")
        # [v4 req2] commit→thread.start 窗口任意异常 → 精确退款 + 状态收口
        await _handle_write_window_failure()
        from writing.article_generation_failure import classify_article_generation_failure
        _public_failure = classify_article_generation_failure(e)
        raise HTTPException(status_code=500, detail=_public_failure.public_dict())


class OptimizeGenerateRequest(BaseModel):
    keyword_id: int
    plan_version: str
    plan_hash: str
    client_request_id: str


def _require_supplement_keyword_access(request: Request, keyword_id: int) -> int:
    """Resolve quote from the real confirmed keyword, then apply the existing tenant guard."""
    from auth.brand_access import require_quote_access
    from db.connection import get_connection

    conn = get_connection()
    try:
        cur = conn.cursor()
        cur.execute("SELECT quote_id FROM confirmed_keywords WHERE id=%s", (int(keyword_id),))
        row = cur.fetchone()
    finally:
        conn.close()
    if not row:
        raise HTTPException(404, "关键词不存在")
    quote_id = int(row["quote_id"])
    require_quote_access(request, quote_id, allow_null=False)
    return quote_id


@app.get("/api/writing/optimize-preview/{keyword_id}")
async def api_optimize_preview(keyword_id: int, request: Request):
    """Return a read-only, server-authoritative supplement plan."""
    if not request.state.user:
        raise HTTPException(401, "未登录")
    _require_supplement_keyword_access(request, keyword_id)

    from db.connection import get_connection
    from services.smart_article_supplement import (
        SupplementPricingUnavailable,
        build_supplement_preview_from_db,
    )

    conn = get_connection()
    try:
        preview = build_supplement_preview_from_db(conn, keyword_id)
        return {"status": "success", "preview": preview.to_dict()}
    except SupplementPricingUnavailable:
        raise HTTPException(
            503,
            detail={
                "code": "PRICING_UNAVAILABLE",
                "message": "算力价格暂时不可用，请刷新后重试",
            },
        )
    except LookupError as exc:
        raise HTTPException(404, str(exc))
    finally:
        conn.close()


@app.post("/api/writing/optimize-generate")
async def api_optimize_generate(req: OptimizeGenerateRequest, request: Request):
    """Create a smart supplement atomically; no client-controlled counts or styles."""
    user = request.state.user
    if not user:
        raise HTTPException(401, "未登录")

    quote_id = _require_supplement_keyword_access(request, req.keyword_id)
    user_id = user.get("user_id") or user.get("id")
    if not user_id:
        raise HTTPException(401, "登录态无效")
    import re as _re
    if not _re.fullmatch(r"[A-Za-z0-9_-]{8,128}", req.client_request_id or ""):
        raise HTTPException(422, "client_request_id 格式无效")
    if not _re.fullmatch(r"[0-9a-f]{64}", req.plan_hash or ""):
        raise HTTPException(422, "plan_hash 格式无效")
    from writing.article_style_contract import normalize_user_choice

    from db.connection import get_connection
    from services.smart_article_supplement import (
        SupplementPricingUnavailable,
        build_supplement_preview_from_db,
        expand_style_plan,
    )
    from writing.style_registry import (
        USER_CHOICE_TO_STYLE,
        resolve_user_choice_to_chinese_style,
    )

    endpoint = "writing.optimize-generate.v2"
    request_key = f"writing-supplement:{req.client_request_id}"
    conn = get_connection()
    topic_ids: list[int] = []
    response: dict = {}
    try:
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO publish_idempotency_keys (request_id, user_id, endpoint, response_json)
            VALUES (%s, %s, %s, '{}'::jsonb)
            ON CONFLICT (request_id) DO NOTHING
            RETURNING request_id
            """,
            (request_key, int(user_id), endpoint),
        )
        claimed = cur.fetchone()
        if not claimed:
            cur.execute(
                """
                SELECT response_json FROM publish_idempotency_keys
                WHERE request_id=%s AND user_id=%s AND endpoint=%s
                """,
                (request_key, int(user_id), endpoint),
            )
            previous = cur.fetchone()
            if not previous:
                conn.rollback()
                raise HTTPException(409, "请求编号已被其他操作使用")
            conn.rollback()
            replay = previous["response_json"]
            if isinstance(replay, str):
                replay = json.loads(replay)
            return {**replay, "idempotent_replay": True, "created": 0}

        preview = build_supplement_preview_from_db(conn, req.keyword_id, for_update=True)
        if preview.quote_id != quote_id:
            raise HTTPException(403, "关键词不属于当前报价")
        if req.plan_version != preview.plan_version or req.plan_hash != preview.plan_hash:
            conn.rollback()
            raise HTTPException(
                409,
                detail={
                    "code": "SUPPLEMENT_PLAN_STALE",
                    "message": "建议方案已变化，请刷新后确认",
                    "preview": preview.to_dict(),
                },
            )

        style_slots = expand_style_plan(preview)
        cur.execute(
            "SELECT q.industry,q.article_plan_writing_mode,COALESCE(q.owner_user_id,b.owner_user_id) AS owner_user_id "
            "FROM quotes q JOIN brands b ON b.id=q.brand_id WHERE q.id=%s FOR UPDATE OF q",
            (quote_id,),
        )
        quote_row = cur.fetchone() or {}
        industry = quote_row.get("industry") or ""
        slot_aware = quote_row.get("article_plan_writing_mode") == "slot_aware_v1"
        plan_actor = int(quote_row.get("owner_user_id") or 0)
        from services.media_slot_conversion import plan_buckets as _wo225_plan
        _wo225_buckets = list(_wo225_plan(quote_id, len(style_slots), cursor=cur))
        for user_choice in style_slots:
            canonical_user_choice = normalize_user_choice(user_choice, allow_auto=False)
            if not canonical_user_choice:
                raise HTTPException(422, f"无法识别文体：{user_choice}")
            style_code = USER_CHOICE_TO_STYLE.get(canonical_user_choice)
            article_style = resolve_user_choice_to_chinese_style(canonical_user_choice, industry)
            cur.execute(
                """
                INSERT INTO topics (
                    keyword_id, quote_id, original_keyword, optimized_title,
                    user_choice, user_choice_source, style_code, article_style,
                    status, is_optimize, fail_reason, created_at, regenerate_started_at,
                    media_bucket
                ) VALUES (%s, %s, %s, '标题生成中...', %s, 'batch_distribution', %s, %s,
                          'regenerating', TRUE, NULL, NOW(), NOW(), %s)
                RETURNING id
                """,
                (
                    preview.keyword_id,
                    preview.quote_id,
                    preview.keyword,
                    canonical_user_choice,
                    style_code,
                    article_style,
                    # [WO_225-c1 §8.3] 补写这单口径的桶(补充生成的新行也要有桶,
                    #   否则同一单里一半有桶一半没有,折算出来的槽数说不清)
                    (_wo225_buckets.pop(0) if _wo225_buckets else None),
                ),
            )
            topic_id = int(cur.fetchone()["id"])
            if slot_aware:
                if not plan_actor:
                    raise RuntimeError("slot_aware_quote_owner_missing")
                from services.article_closed_loop_metadata import bind_topic_to_slot

                bind_topic_to_slot(
                    cur,
                    quote_id=quote_id,
                    topic_id=topic_id,
                    keyword_id=preview.keyword_id,
                    actor_user_id=plan_actor,
                )
            topic_ids.append(topic_id)

        response = {
            "status": "success",
            "keyword_id": preview.keyword_id,
            "quote_id": preview.quote_id,
            "topic_ids": topic_ids,
            "created": len(topic_ids),
            "plan_version": preview.plan_version,
            "plan_hash": preview.plan_hash,
            "message": (
                f"已创建 {len(topic_ids)} 篇智能补足选题，标题生成中"
                if topic_ids else "当前计划和出现率已达标，无需补发"
            ),
        }
        cur.execute(
            """
            UPDATE publish_idempotency_keys
            SET response_json=%s::jsonb
            WHERE request_id=%s AND user_id=%s AND endpoint=%s
            """,
            (json.dumps(response, ensure_ascii=False), request_key, int(user_id), endpoint),
        )
        conn.commit()
    except HTTPException:
        conn.rollback()
        raise
    except SupplementPricingUnavailable:
        conn.rollback()
        raise HTTPException(
            503,
            detail={
                "code": "PRICING_UNAVAILABLE",
                "message": "算力价格暂时不可用，请刷新后重试",
            },
        )
    except LookupError as exc:
        conn.rollback()
        raise HTTPException(404, str(exc))
    except Exception as e:
        conn.rollback()
        logger.error("优化选题创建失败: %s", type(e).__name__)
        raise HTTPException(500, "创建失败，请稍后重试")
    finally:
        conn.close()

    if topic_ids:
        from services.optimize_title_jobs import dispatch_optimize_title_job
        dispatch_optimize_title_job(quote_id, topic_ids)
    return response


@app.post("/api/writing/optimize-retry/{topic_id}")
async def api_optimize_retry(topic_id: int, request: Request):
    """Retry a visible failed optimize title without creating another topic."""
    if not request.state.user:
        raise HTTPException(401, "未登录")
    from auth.brand_access import require_quote_access
    from db.connection import get_connection
    from services.optimize_title_jobs import dispatch_optimize_title_job

    conn = get_connection()
    try:
        cur = conn.cursor()
        cur.execute("SELECT quote_id, status, is_optimize FROM topics WHERE id=%s", (int(topic_id),))
        topic = cur.fetchone()
        if not topic:
            raise HTTPException(404, "选题不存在")
        require_quote_access(request, int(topic["quote_id"]), allow_null=False)
        if not topic.get("is_optimize"):
            raise HTTPException(409, "该选题不是智能补足任务")
        if topic["status"] != "failed":
            raise HTTPException(409, "该选题当前无需重试")
        cur.execute(
            """
            UPDATE topics SET status='regenerating', optimized_title='标题生成中...', fail_reason=NULL,
                              regenerate_started_at=NOW()
            WHERE id=%s AND is_optimize=TRUE AND status='failed'
            """,
            (int(topic_id),),
        )
        if cur.rowcount != 1:
            raise HTTPException(409, "状态已变化，请刷新后重试")
        conn.commit()
        quote_id = int(topic["quote_id"])
    except HTTPException:
        conn.rollback()
        raise
    finally:
        conn.close()
    dispatch_optimize_title_job(quote_id, [int(topic_id)])
    return {"status": "success", "topic_id": int(topic_id), "message": "已重新加入标题生成队列"}


# ========== 写作竞品清洗 ==========

_WRITING_COMPETITOR_EXACT_BLOCKLIST = {
    "混凝土", "环保建材", "pvc扣板", "PVC扣板", "扣板", "建材", "环保材料", "装修材料",
    "建筑材料", "装饰材料", "水泥", "砂浆", "沙子", "瓷砖", "地板", "墙板", "涂料",
    "石膏板", "生态板", "木方", "板材", "管材", "防水材料", "腻子粉", "乳胶漆",
    "全屋", "整装", "半包", "全包", "硬装", "软装", "室内装修", "室内装饰",
}


def _clean_writing_competitor_name(name: str) -> str:
    """Normalize one writing competitor candidate for display and validation."""
    import re
    cleaned = (name or "").strip()
    cleaned = re.sub(r"^\s*(?:\d+[\.\)、)]|[-*•·])\s*", "", cleaned)
    cleaned = re.sub(r"\*+", "", cleaned)
    cleaned = re.sub(r"<[^>]+>", "", cleaned).strip()
    cleaned = cleaned.strip("「」『』《》[]【】（）()，,。.;；:： ")
    return cleaned


def _is_valid_writing_competitor_name(
    name: str,
    industry: str = "",
    *,
    is_real_estate: bool = False,
) -> bool:
    """Keep only real company/brand/project names for WritingHall competitors.

    The writing UI calls this section "真实竞品". Generic materials/categories like
    "混凝土" or "PVC扣板" must not show up as competitors even if an LLM repeats them.
    """
    import re

    cleaned = _clean_writing_competitor_name(name)
    industry = industry or ""
    if not cleaned:
        return False
    lowered = cleaned.lower()

    if cleaned in _WRITING_COMPETITOR_EXACT_BLOCKLIST or lowered in {
        x.lower() for x in _WRITING_COMPETITOR_EXACT_BLOCKLIST
    }:
        return False

    if len(cleaned) <= 2 or len(cleaned) > 28:
        return False

    if not any("\u4e00" <= ch <= "\u9fff" or ch.isalpha() for ch in cleaned):
        return False

    if cleaned.startswith(("#", "**", "- ", "* ", "> ")) or cleaned.endswith(("？", "?", "。", ".", "：", ":", "！", "!")):
        return False

    if re.search(r"(问题|要求|搜索|继续|更多|标题|摘要|来源|内容|行业|地区|客户|关键词|推荐|排名)$", cleaned):
        return False

    if re.match(r"^[A-Za-z0-9\-_\s]+(?:板|扣板|管|砖|瓦|胶|漆|材料|建材)$", cleaned):
        return False

    generic_suffix = r"(材料|建材|板材|扣板|瓷砖|地板|墙板|涂料|水泥|砂浆|木方|防水|软装|硬装)$"
    if re.search(generic_suffix, cleaned) and len(cleaned) <= 6:
        return False

    if not is_real_estate and any(k in industry for k in ("装修", "家装", "装饰", "家居", "建筑")):
        # 装修行业的真实竞品应当像品牌/公司/项目，而不是单个材料或工法。
        brand_signal = re.search(
            r"(装饰|装修|设计|家装|整装|全包圆|家居|定制|木业|工程|系统|集团|有限公司|"
            r"空间|宅配|门窗|卫浴|家具|建筑|营造|建工|建设)",
            cleaned,
        )
        if not brand_signal and len(cleaned) <= 8:
            return False

    return True


def _sanitize_writing_competitors(competitors: list, industry: str = "", *, is_real_estate: bool = False) -> list:
    """Filter cached/generated competitor entries and dedupe by display name."""
    sanitized = []
    seen = set()
    for comp in competitors or []:
        if isinstance(comp, dict):
            raw_name = comp.get("name", "")
            entry = dict(comp)
        else:
            raw_name = str(comp)
            entry = {"name": raw_name}

        cleaned = _clean_writing_competitor_name(raw_name)
        if not _is_valid_writing_competitor_name(cleaned, industry, is_real_estate=is_real_estate):
            continue

        key = cleaned.lower()
        if key in seen:
            continue
        seen.add(key)
        entry["name"] = cleaned
        sanitized.append(entry)
    return sanitized


# ============================================================
# [CTO-15.23 2026-05-05] 竞品 LLM 守门员
# 老板"客户品牌/业务范围/因此应该是"等垃圾乱入 P0 反馈
# 老板拍板:不再硬编码黑名单 · 用 deepseek-v4-flash 智能判断
# 失败 4 级 fallback(deepseek/dashscope/siliconflow/kimi)· 全挂保留轻量规则
# ============================================================
import time as _time_for_competitor_cache
_competitor_llm_cache: dict = {}  # key=(industry, region, names_tuple) → (timestamp, verdict_dict)
_COMPETITOR_LLM_CACHE_TTL = 300  # 5min


async def _llm_filter_brand_names(
    candidates: list,
    industry: str = "",
    region: str = ""
) -> dict:
    """
    用 LLM 判断每个候选项是否真品牌/公司/项目名
    返回 {name: True/False} · 失败返 {} · caller 必须降级保留候选

    PROMPT 含正反例:
      真品牌:酒店/餐厅/连锁/公司/集团/具体项目
      非品牌:描述短语/字段名/上下文片段/行业泛指/LLM 输出残留

    成本:v4-flash 单次 ~0.0007¥ · 5min cache 防短时反复
    """
    if not candidates:
        return {}

    names = [
        c.get("name", "") if isinstance(c, dict) else str(c)
        for c in candidates
    ]
    names = [n.strip() for n in names if n and n.strip()]
    if not names:
        return {}

    # cache 命中 (5min · 同 industry+region+names tuple)
    # [CTO-15.23 2026-05-06] cache key 加 prompt_version · PROMPT 改版后旧 cache 自动失效
    # v2: 加行业匹配维度(食品公司不能给酒店客户当竞品)· 老 cache(v1 无 version)永不命中
    cache_key = ("v2-industry", industry or "", region or "", tuple(sorted(set(names))))
    now = _time_for_competitor_cache.time()
    cached = _competitor_llm_cache.get(cache_key)
    if cached and (now - cached[0]) < _COMPETITOR_LLM_CACHE_TTL:
        return cached[1]

    try:
        from tools.multi_llm_caller import call_llm_with_fallback
        import json as _json
        import re as _re

        # PROMPT 限 30 候选 · 防超长(实测竞品列表通常 ≤ 20)
        # [CTO-15.23 2026-05-06] 老板报食品公司混入酒店客户竞品 · PROMPT 加行业匹配维度
        # 之前只判"是不是真品牌"·"揭阳市港荣食品发展有限公司"是真品牌但跨行业 · 守门员漏过
        candidates_text = '\n'.join(f"- {n}" for n in names[:30])
        prompt = f"""你是品牌名识别助手。判断每个候选项是否为"客户的真实竞品"——必须同时满足两条:
(1) 真实存在的品牌/公司/项目(不是描述短语)
(2) 跟客户行业相关(同行业 / 上下游 / 同消费场景)

## 上下文
- 客户行业:{industry or "未指定"}
- 客户地区:{region or "未指定"}

## 判定铁律

✅ 真竞品(is_brand=true · 真品牌 + 行业匹配):
  - 客户=酒店住宿:同区域酒店/连锁/客栈(如"如家商旅酒店揭阳榕城店"/"丽枫酒店揭阳店"/"汉庭")
  - 客户=房产:同区域楼盘/地产开发商(如"碧桂园·天玺湾"/"保利和府")
  - 客户=电梯:同行业电梯品牌(如"日立电梯"/"奥的斯")
  - 客户=餐饮:同区域餐厅/连锁(如"海底捞"/"西贝")
  - 即使含"店/区/路"等地名后缀也是真品牌

❌ 非竞品(is_brand=false · 击中任一即剔):
  - **跨行业**(就算真品牌也剔):
    * 客户酒店住宿 → 食品公司(如"揭阳市港荣食品发展有限公司"/"友臣食品"/"回头客食品集团")false
    * 客户房产 → 早教/培训(如"红黄蓝早教") false
    * 客户电梯 → 服装/餐饮 false
    * 客户餐饮 → 电梯/装修 false
    * 判断标准:候选公司/品牌的主营业务能否给客户当**直接竞品**(客户的客户会在它和我们之间二选一)?不能 → false
  - 描述性短语("客户品牌"/"业务范围"/"住店客人的早餐、商务餐"/"高端餐饮企业")
  - 上下文片段("因此, 竞品应该是"/"应该是 XXX"/"经核查"/"目前并无")
  - 字段名/泛词("产品系列"/"目标客户"/"业务方向"/"客户群体"/"推广策略")
  - 行业泛指("揭阳商务区的高端餐饮企业" — 描述不是品牌)
  - LLM 输出残留("以下是"/"根据搜索"/"此外"/"综上")
  - 句子(以问号/句号/感叹号结尾,或含逗号/顿号超过 1 个)

## 候选项
{candidates_text}

## 输出严格 JSON(无 markdown/解释/think 标签):
{{"results": [{{"name": "原始候选名", "is_brand": true 或 false}}, ...]}}

每个候选必须返回 · 顺序无所谓 · is_brand 必须是 true/false 不是 yes/no/0/1
跨行业的真公司必须 false · 不要因为它"是真公司"就放行
"""
        response = await call_llm_with_fallback(prompt, verbose=False)
        json_match = _re.search(r'\{[\s\S]*\}', response)
        if not json_match:
            logger.warning("[竞品 LLM 守门员] LLM 返回未含 JSON · fallback")
            return {}

        data = _json.loads(json_match.group())
        results = data.get("results", [])
        verdict = {}
        for r in results:
            name = r.get("name", "").strip()
            if not name:
                continue
            verdict[name] = bool(r.get("is_brand", False))

        if verdict:
            _competitor_llm_cache[cache_key] = (now, verdict)
            # 防 cache 无限增长 · 超 200 个 key 时清最早的 50 个
            if len(_competitor_llm_cache) > 200:
                old_keys = sorted(_competitor_llm_cache.items(), key=lambda x: x[1][0])[:50]
                for k, _ in old_keys:
                    _competitor_llm_cache.pop(k, None)

        return verdict
    except Exception as e:
        logger.warning(f"[竞品 LLM 守门员] 调用失败 · fallback 保留轻量规则结果: {e}")
        return {}


async def _sanitize_competitors_with_llm(
    competitors: list,
    industry: str = "",
    region: str = "",
    *,
    is_real_estate: bool = False,
) -> list:
    """组合 sanitize:轻量规则 + LLM 守门员
    - Step 1: 走 _sanitize_writing_competitors(轻量规则)过滤明显垃圾(markdown/过长/过短)
    - Step 2: 通过的候选送 LLM · LLM 判 false 的剔除
    - LLM 失败 → 保留 Step 1 结果(零回归)
    """
    sanitized = _sanitize_writing_competitors(competitors, industry, is_real_estate=is_real_estate)
    if not sanitized:
        return []

    verdict = await _llm_filter_brand_names(sanitized, industry, region)
    if not verdict:
        # LLM 全挂 · 保留轻量规则结果
        return sanitized

    final = []
    for c in sanitized:
        name = c.get("name", "")
        # LLM 没给判定的(如 LLM 漏)默认保留 · 不误伤
        if verdict.get(name, True):
            final.append(c)
        else:
            logger.info(f"[竞品 LLM 守门员] 剔除非品牌:「{name}」 (industry={industry})")
    return final


# ========== 竞品调研 API ==========

def _resolve_competitor_industry(quote_industry, brand_industry) -> tuple[str, str]:
    """竞品调研用哪个行业:**品牌现值优先,报价快照兜底**。返回 (行业, 来源)。

    🔴 为什么品牌现值优先(WO_251 · 客户揭阳雅栖酒店):
       报价里那个 industry 是**下单那一刻的快照** —— 记的是"当时前端选了什么",
       不是"这家客户是做什么的"。客户改了行业、或者当初就选错了(报价 287
       是「餐饮食品」而品牌是酒店,前端分类 bug),快照都不会变。
       而竞品调研问的是**现在这家客户的同行是谁**。

    🔴 只在品牌现值**非空**时覆盖:空不算"现值",否则会把有值的快照也抹掉 ——
       那会把一个"取错了"换成另一个"什么都没有"。

    抽成函数是为了能**直接验**:写在 handler 里就只能靠 AST 判据看它,
    而 AST 看不见"它到底选了哪个"(本轮已经栽过一次)。
    """
    q = (quote_industry or "").strip()
    b = (brand_industry or "").strip()
    if b:
        return b, "brand"
    return q, "quote"


@app.post("/api/writing/research-competitors/{quote_id}")
async def api_research_competitors(quote_id: int, http_request: Request):
    """多源交叉验证搜索真实竞品品牌

    流程：
    1. 并发调用 3 个带联网搜索的 LLM（DashScope、DeepSeek、Kimi）
    2. 投票筛选：只保留 2+ 个源都提到的品牌
    3. 秘塔验证：对候选品牌做网页搜索验证真实性
    4. 返回置信度标注

    [fast-follow 安全修 2026-05-29] 原无 Request 形参 → 跨租户对他人 quote 跑 3 路联网 LLM + metaso(资源滥用 + 数据写入)。加 require_quote_access。
    """
    from auth.brand_access import require_quote_access
    require_quote_access(http_request, quote_id)
    try:
        from db.diagnosis_db import get_quote, get_connection
        import httpx
        import asyncio
        import os
        import json
        import re
        from collections import Counter

        quote = get_quote(quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        brand_name = quote.get("brand_name", "")

        # [WO_251 2026-09-20] 行业取**品牌现值优先**,报价快照只作兜底。
        #
        # 生产事故(客户揭阳雅栖酒店):报价 287 的 `industry` 是「餐饮食品」
        #   (前端分类 bug,WO_250),而品牌 19 的 `brands.industry` 是
        #   「酒店住宿 / 商务出行 / 中端连锁酒店」。竞品调研与知识库检索**同源同错**,
        #   于是拿「餐饮食品」去给一家酒店找同行。
        #
        # 🔴 为什么品牌现值优先:报价里那个 industry 是**下单那一刻的快照**,
        #    记的是"当时前端选了什么",不是"这家客户是做什么的"。
        #    客户改了行业、或者当初就选错了,快照都不会变 ——
        #    而竞品调研问的是**现在这家客户的同行是谁**。
        # 🔴 只在品牌现值**非空**时覆盖:空不算"现值",否则会把有值的快照也抹掉。
        _brand_industry = ""
        try:
            _ind_bid = quote.get("brand_id")
            if _ind_bid:
                _c = get_connection()
                try:
                    _cur = _c.cursor()
                    _cur.execute("SELECT industry FROM brands WHERE id = %s",
                                 (int(_ind_bid),))
                    _brow = _cur.fetchone()
                finally:
                    _c.close()
                _brand_industry = (_brow or {}).get("industry") or ""
        except Exception as _ind_err:
            logger.warning("[竞品调研] 品牌行业读取失败,退回报价快照: %s", _ind_err)
        industry, industry_source = _resolve_competitor_industry(
            quote.get("industry"), _brand_industry)

        # 获取关键词列表（最可靠的地区信息来源）
        kw_list = []
        try:
            conn = get_connection()
            c = conn.cursor()
            c.execute("SELECT keyword FROM confirmed_keywords WHERE quote_id = %s AND (is_core IS NOT FALSE)", (quote_id,))
            kw_rows = c.fetchall()
            conn.close()
            kw_list = [r["keyword"] for r in kw_rows] if kw_rows else []
        except Exception:
            pass

        # [Review-CTO 2026-07-27 · Owner 生产实测:驰鲸挖出一堆东莞工厂] 竞品主语纠偏:
        # ① 地区先取品牌服务城市(brands.cities 经省市区解析归一),词首猜测只作兜底
        #    ——旧逻辑拿第一个获客词前 2-4 字当地区("东莞工厂TikTok外贸获客"→"东莞");
        # ② 品类用 distill_trade 从 industry 炼服务身份("跨境数字营销"),
        #    不喂获客关键词——那些词面向客户的目标客户(工厂),不代表客户自己的行当。
        service_trade = ""
        brand_city = ""
        try:
            from services.diagnosis_question_quality import distill_trade as _distill_trade
            from services.diagnosis_question_quality import normalize_city as _norm_city
            service_trade = _distill_trade(industry)
            _b_id = quote.get("brand_id")
            if _b_id:
                conn = get_connection()
                c = conn.cursor()
                c.execute("SELECT cities FROM brands WHERE id = %s", (int(_b_id),))
                _brow = c.fetchone()
                conn.close()
                _raw_cities = (_brow or {}).get("cities") or ""
                if _raw_cities:
                    _first = _raw_cities
                    if isinstance(_raw_cities, str) and _raw_cities.strip().startswith("["):
                        try:
                            _arr = json.loads(_raw_cities)
                            _first = _arr[0] if _arr else ""
                        except Exception:
                            _first = _raw_cities
                    brand_city = _norm_city(str(_first))
        except Exception as _scope_err:
            logger.warning(f"[竞品调研] 品牌城市/品类蒸馏失败,退回旧逻辑: {_scope_err}")

        # 从关键词中提取地区（比 distilled_data 更可靠）
        # [CTO-15.23 2026-05-08 P1] 支持街道/商圈级提取(揭阳滨江南路 这种 LLM 不熟的细粒度区位)
        region = brand_city   # 城市级(如"揭阳")·品牌服务城市优先
        # [WO_251] 地区走了哪条兜底,日志里要一眼看得出 —— 上次就是因为看不出,
        #   「地区=揭阳环」这种半截值在日志里躺了很久没人认出它是被切坏的。
        region_source = "cities" if brand_city else ""
        sub_region = ""    # 街道/商圈级(如"滨江南路")· 仅用于 metaso query 增强
        if kw_list and not region:
            # 兜底:从第一个关键词中提取城市/区域名(品牌城市缺失时才用)
            import re as _re
            for kw in kw_list[:5]:
                # 匹配常见地区格式：揭阳、深圳南山区、北京朝阳 等
                m = _re.match(r'^([\u4e00-\u9fa5]{2,4}(?:市|区|县|镇)?)', kw)
                if m:
                    candidate = m.group(1)
                    # 排除行业词开头（如"全屋""衣柜"等不是地区）
                    non_region_prefixes = ["全屋", "衣柜", "榻榻", "酒柜", "餐边", "靠谱", "口碑", "哪家", "哪里", "什么", "怎么", "如何"]
                    if not any(candidate.startswith(p) for p in non_region_prefixes) and len(candidate) >= 2:
                        region = candidate
                        region_source = "keyword"
                        # [CTO-15.23 P1] 街道/商圈级:在城市后找"X路/街/道/巷/商圈/广场/新区/开发区/高新区/片区"
                        m2 = _re.search(r'[一-龥]{2,8}(路|街|道|巷|商圈|广场|新区|开发区|高新区|片区)', kw[len(candidate):])
                        if m2:
                            sub_region = m2.group(0)
                        break

        # fallback: 从 distilled_data 获取
        if not region:
            try:
                conn = get_connection()
                c = conn.cursor()
                c.execute("SELECT distilled_data FROM quotes WHERE id = %s", (quote_id,))
                row = c.fetchone()
                conn.close()
                if row and row["distilled_data"]:
                    dd = json.loads(row["distilled_data"]) if isinstance(row["distilled_data"], str) else row["distilled_data"]
                    cp = dd.get("client_profile", {})
                    if isinstance(cp, str):
                        cp = json.loads(cp)
                    region = cp.get("region", cp.get("city", ""))
                    if region:
                        region_source = "distilled"
            except Exception:
                pass

        # [CTO-15.23 2026-05-08 P1] 小城市判定 · LLM 知识库稀疏 → prompt 收紧防编造
        # 一线 + 强二线 LLM 熟 · 三四线本地小品牌 LLM 容易凭空虚构
        major_cities = {
            "北京", "上海", "广州", "深圳", "成都", "杭州", "武汉", "西安", "重庆",
            "南京", "天津", "苏州", "郑州", "长沙", "东莞", "宁波", "佛山", "合肥",
            "青岛", "济南", "厦门", "福州", "无锡", "大连", "沈阳", "昆明", "南昌",
            "贵阳", "南宁", "石家庄", "太原",
        }
        is_minor_city = bool(region) and not any(mc in region for mc in major_cities)

        # 检测是否为房地产行业
        is_real_estate = any(kw in industry for kw in ['房地产', '地产', '楼盘', '房产', '住宅', '商品房'])

        # [WO_251] 加「行业来源 / 地区来源」两个字段:下次一眼看得出走了哪条兜底。
        #   这一行原来只说结果不说出处,于是「行业=餐饮食品」看起来像客户真的是餐饮。
        logger.info(f"🔍 [竞品调研] 客户={brand_name} 行业={industry}(来源={industry_source}) 地区={region}(来源={region_source or 'none'}){' · 街道='+sub_region if sub_region else ''} 房地产={is_real_estate} 小城市={is_minor_city} 关键词={kw_list[:3]}")
        # [2026-07-27] service_trade 可用时检索词绑定服务身份,获客词不再进 query
        # (那是买家侧词,会把搜索带偏成"客户的客户"同行);蒸馏失败退回旧构造。
        if service_trade:
            search_query = f"{region} {sub_region} {service_trade} 服务商 知名".strip()
        else:
            search_query = f"{region} {sub_region} {industry} {' '.join(kw_list[:3])} 知名品牌".strip()
        logger.info(f"🔍 [竞品调研] 开始多源交叉验证: {search_query}")

        # 用关键词中的地区信息构建更精确的搜索上下文
        kw_context = chr(10).join([f"  - {kw}" for kw in kw_list[:8]])

        if is_real_estate:
            # 房地产行业：获取开发商及具体楼盘项目名，后续通过住建局/房产平台交叉验证
            base_prompt = f"""你是一个行业研究助理。请搜索「{region if region else ''}」地区**正在销售或近期交付的真实楼盘项目**。

## 客户信息
- 客户品牌：{brand_name}（排除，不要列入竞品）
- 所属行业：{industry}
- 所在地区：{region if region else '未指定'}
- 客户的优化关键词：
{kw_context}

## 要求
1. 根据关键词判断客户的**精确服务区域**
2. 列出该区域内**具体的楼盘项目名**，不是开发商品牌！
3. 每行格式：楼盘全名|开发商（如"碧桂园·天玺湾|碧桂园"，"保利和府|保利发展"）
4. 楼盘全名必须是购房者在售楼处、房产平台上看到的**完整项目名称**
5. 列出 8-12 个楼盘项目，按在该地区的知名度从高到低
6. **必须是真实存在的**楼盘项目名。宁少勿假
7. 优先参考权威来源：住建局/房管局备案、房天下(fang.com)、贝壳找房(ke.com)、安居客(anjuke.com)
8. ❌ 禁止只写"碧桂园""保利"等开发商品牌名！必须精确到具体项目（如"碧桂园·天玺湾""保利和府"）

直接输出列表，每行一个。"""
        else:
            # [CTO-15.23 2026-05-08 P1] 小城市 prompt 收紧 · LLM 不熟本地小品牌时宁少勿假
            minor_city_warning = ""
            if is_minor_city:
                minor_city_warning = f"""

## ⚠️ 重要提醒(三四线城市本地竞品)
- 「{region}」是地级/县级城市,本地小品牌可能在 LLM 知识库覆盖不全
- **如果你不确定本地小品牌存在,宁可少列也不要凭空虚构** · 列出 4-6 家可公开查证的即可
- **优先列出该城市能被携程/美团/大众点评等平台收录的连锁品牌**
- 不要把同行业全国品牌强行往本地套(如随便写"汉庭""如家"在揭阳的具体门店)"""
            sub_region_hint = f"\n- **客户精确区位**:{region}{sub_region}(围绕这个区位找竞品)" if sub_region else ""
            base_prompt = f"""你是一个行业研究助理。请搜索「{region if region else ''}{service_trade or industry}」领域的**真实竞品品牌/公司**。

## ⚠️ 谁才算竞品（最重要，先读）
竞品 = **和客户做同一门生意、抢同一批客户的服务商**。
客户的优化关键词是他**获客用的**，词里出现的行业是他的**目标客户**，不是他的同行！
- 反例：客户是"帮工厂做 TikTok 出海代运营"的服务商 → 竞品是**其他 TikTok
  代运营/跨境社媒营销服务商**；把"XX 工厂""XX 科技公司"当竞品就全错了
- 判断方法：问自己"这家公司能不能抢走 {brand_name} 的客户？"不能就不是竞品

## 客户信息
- 客户品牌：{brand_name}（排除，不要列入竞品）
- 客户的生意（竞品必须做同类生意）：{service_trade or industry}
- 所属行业（登记口径，仅参考）：{industry}
- 所在地区：{region if region else '未指定'}{sub_region_hint}
- 客户用来获客的搜索词（只用于理解他服务谁，**别把词里的买家行业当竞品方向**）：
{kw_context}{minor_city_warning}

## 要求
1. 根据"客户的生意"判断竞品方向；服务区域参考"所在地区"，全国性服务商也可列
2. 只列出**该领域内真实存在、可公开验证**的竞品品牌/公司/项目，不包含 {brand_name}
3. 列出 8-12 家，按知名度从高到低（小城市可减少到 4-6 家）
4. 必须是能被客户理解为"对手"的品牌/公司/项目名。
   - ❌ 错误示例：混凝土、环保建材、PVC扣板、室内装修、全屋
   - ✅ 正确示例：业之峰全包圆、东易日盛整体家装、九鼎装饰全案家装
5. 每行格式：品牌/公司/项目全名|所属公司+一句话简介（如"业之峰全包圆|业之峰装饰，整装服务品牌"）
6. **必须是真实存在的**产品/品牌。如果不足，有几家写几家。**绝对不要为了凑数而编造**
7. 优先引用可公开查证的权威来源（官网、天眼查/企查查、行业垂直平台等）

直接输出列表，每行一个。"""

        # ============================================
        # Step 1: 并发调用 3 个 LLM 带联网搜索
        # ============================================
        async def call_dashscope():
            api_key = os.environ.get("DASHSCOPE_API_KEY", "")
            if not api_key:
                return []
            try:
                async with httpx.AsyncClient(timeout=30.0) as client:
                    resp = await client.post(
                        "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
                        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                        json={"model": "qwen3.7-max", "messages": [{"role": "user", "content": base_prompt}],
                              "temperature": 0.2, "max_tokens": 1000, "enable_search": True}
                    )
                    resp.raise_for_status()
                    return _parse_competitor_lines(resp.json()["choices"][0]["message"]["content"])
            except Exception as e:
                logger.warning(f"[竞品-DashScope] 失败: {e}")
                return []

        async def call_doubao():
            api_key = os.environ.get("DOUBAO_SEED_API_KEY", os.environ.get("DOUBAO_API_KEY", ""))
            endpoint = os.environ.get("DOUBAO_ENDPOINT_ID", "")
            if not api_key:
                return []
            try:
                async with httpx.AsyncClient(timeout=60.0) as client:
                    resp = await client.post(
                        "https://ark.cn-beijing.volces.com/api/v3/chat/completions",
                        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                        json={"model": endpoint or "doubao-seed-2-0-pro-260215",
                              "messages": [{"role": "user", "content": base_prompt}],
                              "temperature": 0.2, "max_tokens": 1000}
                    )
                    resp.raise_for_status()
                    content = resp.json()["choices"][0]["message"]["content"]
                    return _parse_competitor_lines(content) if content else []
            except Exception as e:
                logger.warning(f"[竞品-Doubao] 失败: {e}")
                return []

        async def call_kimi():
            api_key = os.environ.get("KIMI_API_KEY", "")
            if not api_key:
                return []
            try:
                messages = [
                    {"role": "system", "content": "你是一个行业研究助理，请联网搜索后回答。"},
                    {"role": "user", "content": base_prompt}
                ]
                tools = [{"type": "builtin_function", "function": {"name": "$web_search"}}]
                async with httpx.AsyncClient(timeout=90.0) as client:
                    # kimi-k2.6 $web_search 需要多轮 tool_calls 流程
                    # [CTO-15.23 2026-05-09] Kimi K2.6 升级 · max_iter 5 → 3(降浪费)+ 早停
                    # 硬约束(2026-05-16 实测):thinking=disabled → temperature ONLY 0.6(disabled+0.6 唯一组合)
                    for _round in range(3):  # 最多 3 轮(老板拍板降浪费 · 实测 2-3 轮就完成)
                        resp = await client.post(
                            "https://api.moonshot.cn/v1/chat/completions",
                            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                            json={"model": "kimi-k2.6", "messages": messages,
                                  "max_tokens": 1000, "tools": tools,
                                  "temperature": 0.6,
                                  "thinking": {"type": "disabled"}}
                        )
                        resp.raise_for_status()
                        choice = resp.json()["choices"][0]
                        msg = choice["message"]
                        finish_reason = choice.get("finish_reason")

                        if finish_reason == "stop":
                            return _parse_competitor_lines(msg.get("content", ""))

                        if finish_reason == "tool_calls":
                            messages.append(msg)
                            for tc in msg.get("tool_calls", []):
                                messages.append({
                                    "role": "tool",
                                    "tool_call_id": tc["id"],
                                    "name": tc.get("function", {}).get("name"),
                                    "content": tc.get("function", {}).get("arguments", "{}"),
                                })
                        else:
                            break
                    return _parse_competitor_lines(msg.get("content", ""))
            except Exception as e:
                logger.warning(f"[竞品-Kimi] 失败: {e}")
                return []

        async def call_metaso_extract():
            """Step 0: 先搜权威平台，再用LLM从搜索结果中提取竞品（最可靠的方式）"""
            metaso_k = os.environ.get("METASO_API_KEY", "")
            ds_key = os.environ.get("DASHSCOPE_API_KEY", "")
            if not metaso_k or not ds_key:
                return []
            try:
                # [CTO-15.23 2026-05-08 P1] 用客户原始关键词扩展 query
                # 老 query 仅 "region+industry" 太宽泛 · 三四线城市命中差
                # 新 query:加客户前 2 个关键词原文 + sub_region(街道/商圈)
                kw_for_metaso = " ".join(kw_list[:2]).strip()
                region_full = f"{region}{sub_region}".strip() or region
                if is_real_estate:
                    search_queries = [
                        f"{region_full} 新楼盘 在售 开发商",
                        f"{region_full} 房地产 开发商 排名",
                        f"{region_full} 楼盘 推荐",
                    ]
                    if kw_for_metaso:
                        search_queries.append(f"{kw_for_metaso} 楼盘")
                else:
                    search_queries = [
                        f"{region_full} {industry} 公司 排名",
                        f"{region_full} {industry} 品牌 推荐",
                    ]
                    if kw_for_metaso:
                        # 用客户关键词原文搜 · 命中本地真实竞品概率最高
                        search_queries.append(kw_for_metaso)
                    if is_minor_city:
                        # 小城市加垂直平台搜索:本地小品牌主要在点评类平台被收录
                        search_queries.append(f"{region_full} {industry} 大众点评 美团")

                all_text = ""
                async with httpx.AsyncClient(timeout=15.0) as client:
                    for sq in search_queries:
                        try:
                            resp = await client.post(
                                "https://metaso.cn/api/v1/search",
                                headers={"Authorization": f"Bearer {metaso_k}",
                                         "Accept": "application/json", "Content-Type": "application/json"},
                                json={"q": sq, "scope": "webpage", "size": 8,
                                      "includeSummary": True, "conciseSnippet": True}
                            )
                            if resp.status_code == 200:
                                data = resp.json()
                                summary = data.get("summary", "")
                                if summary:
                                    all_text += f"搜索摘要：{summary}\n\n"
                                for w in data.get("webpages", data.get("results", []))[:8]:
                                    title = w.get("title", "")
                                    snippet = w.get("snippet", w.get("conciseSnippet", ""))
                                    url = w.get("link", w.get("url", ""))
                                    all_text += f"标题：{title}\n来源：{url}\n内容：{snippet[:200]}\n\n"
                        except Exception:
                            continue

                if not all_text.strip():
                    logger.info("  [秘塔直搜] 无搜索结果")
                    return []

                logger.info(f"  [秘塔直搜] 获取搜索文本 {len(all_text)} 字符，开始LLM提取...")

                # 用LLM从搜索结果中提取竞品
                if is_real_estate:
                    extract_prompt = f"""从以下搜索结果中，提取「{region}」地区的**具体楼盘项目名称**。

搜索结果：
{all_text[:4000]}

要求：
1. 只提取搜索结果中**明确出现的**具体楼盘项目名（如"碧桂园·天玺湾"，不是"碧桂园"）
2. 不包含「{brand_name}」相关项目
3. 每行格式：楼盘项目全名|开发商
4. 不要添加搜索结果中未提到的楼盘

直接输出列表。"""
                else:
                    extract_prompt = f"""从以下搜索结果中，提取「{region}{industry}」行业的**具体竞品品牌/公司/项目名称**。

搜索结果：
{all_text[:4000]}

要求：
1. 只提取搜索结果中**明确出现的**具体竞品品牌/公司/项目名称
2. 禁止提取材料、品类、工法、泛行业词（如"混凝土""环保建材""PVC扣板""室内装修"）
3. 不包含「{brand_name}」
4. 每行格式：品牌/公司/项目全名|所属公司
5. 不要添加搜索结果中未提到的内容

直接输出列表。"""

                async with httpx.AsyncClient(timeout=30.0) as client:
                    resp = await client.post(
                        "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
                        headers={"Authorization": f"Bearer {ds_key}", "Content-Type": "application/json"},
                        json={"model": "qwen3.7-max",
                              "messages": [{"role": "user", "content": extract_prompt}],
                              "temperature": 0.2, "max_tokens": 800}
                    )
                    resp.raise_for_status()
                    content = resp.json()["choices"][0]["message"]["content"]
                    extracted = _parse_competitor_lines(content)
                    logger.info(f"  [秘塔直搜] 提取到 {len(extracted)} 家: {[e['name'] for e in extracted[:5]]}")
                    return extracted
            except Exception as e:
                logger.warning(f"[秘塔直搜] 失败: {e}")
                return []

        # [CTO-15.23 2026-05-09] llm_call_log 埋点 · caller='competitor_research'
        # 老板报"控制台成本不准"主因之二:竞品调研 4 callsite 没埋点
        async def _track_competitor(provider_key, fn):
            try:
                from tools.llm_call_tracker import llm_track
            except Exception:
                return await fn()
            _CR_MODEL = {
                'dashscope': ('dashscope', 'qwen3.7-max'),
                'doubao': ('doubao', 'doubao-seed-2-0-pro-260215'),
                'kimi': ('kimi', 'kimi-k2.6'),
                'metaso': ('metaso', 'metaso+qwen3.7-max'),
            }
            platform, model = _CR_MODEL.get(provider_key, (provider_key, None))
            async with llm_track(
                caller='competitor_research', platform=platform, model=model,
                brand_id=quote.get('brand_id'),
                quote_id=quote_id,
                metadata={'brand_name': (brand_name or '')[:80], 'industry': (industry or '')[:40]},
            ):
                return await fn()

        # 并发调用:3个LLM + 秘塔直搜提取(共4个数据源 · 全埋点)
        results = await asyncio.gather(
            _track_competitor('dashscope', call_dashscope),
            _track_competitor('doubao', call_doubao),
            _track_competitor('kimi', call_kimi),
            _track_competitor('metaso', call_metaso_extract),
        )
        source_names = ["DashScope", "Doubao", "Kimi", "秘塔直搜"]

        for i, (names, src) in enumerate(zip(results, source_names)):
            logger.info(f"  [{src}] 返回 {len(names)} 家: {[n['name'] for n in names[:5]]}")

        # ============================================
        # Step 2: 投票筛选 — 名称模糊匹配 + 计数
        # ============================================
        def _normalize_brand(name: str, region_str: str = "") -> str:
            """归一化品牌名：仅用于投票去重时进行模糊匹配。
            注意：此函数不改变显示名，显示名保留原始全名。
            V14: 保留产品/楼盘级别精度，不再丢弃分隔符后半部分。"""
            import re
            # V14: 不再把"碧桂园·天玺湾"截断为"碧桂园"！
            # 只统一分隔符格式用于匹配（"碧桂园・天玺湾" == "碧桂园天玺湾"）
            n = name
            for sep in ['・', '·', '•', '-', '—']:
                n = n.replace(sep, '')

            n = re.sub(r'[（()）\s]', '', n)

            # 去法律实体后缀
            n = re.sub(r'(股份|有限|责任|公司|集团|控股|地产|置业|房产|开发|投资|经营|实业|建设|房地产)+$', '', n)

            # 去地区前缀（如"揭阳碧桂园" → "碧桂园"）
            region_prefixes = ["广东", "广西", "福建", "江苏", "浙江", "湖南", "湖北", "四川",
                               "山东", "河南", "河北", "辽宁", "吉林", "黑龙江", "中国"]
            if region_str:
                region_prefixes.extend([region_str, region_str[:2]])
            for prefix in region_prefixes:
                if n.startswith(prefix) and len(n) > len(prefix) + 1:
                    n = n[len(prefix):]

            # V14: 不再去楼盘后缀！"天玺湾""和府"是精确产品标识，必须保留

            return n.strip() if len(n.strip()) >= 2 else name.strip()

        # v1_3 (CTO-15.1 2026-04-19 老板反馈截图): 竞品搜索结果污染过滤
        # 赵胡子案例：被抓到 markdown 标题 `### 客户精确服务区域` 和产品 SKU `关岭黄牛牛肉干系列`
        # 严格剔除 markdown / 纯 SKU / 过长文本，保留真实品牌名
        def _looks_like_brand_name(name: str) -> bool:
            """判断是否像真实品牌名（True = 保留, False = 过滤掉）"""
            if not name:
                return False
            name = _clean_writing_competitor_name(name)
            # 1. markdown 标题残留
            if name.startswith(('#', '##', '###', '**', '- ', '* ', '> ')):
                return False
            # 2. 过长（品牌名一般 <= 20 字，含公司后缀也 <= 25）
            if len(name) > 25:
                return False
            # 3. 产品 SKU 特征（含这些词且长度 > 6 基本是产品名不是品牌）
            sku_keywords = ['系列', '礼盒', '套餐', '口味', '规格', '装（', '装(', '款（', '款(']
            if len(name) > 6 and any(kw in name for kw in sku_keywords):
                return False
            # 4. 纯数字 / 纯符号
            if not any('\u4e00' <= ch <= '\u9fff' or ch.isalpha() for ch in name):
                return False
            # 5. 含明显句子特征（结尾是问号 / 句号 / 完整句）
            if name.endswith(('？', '?', '。', '.', '：', ':', '！', '!')):
                return False
            return _is_valid_writing_competitor_name(name, industry, is_real_estate=is_real_estate)

        all_names = {}  # normalized_key -> {name, desc, sources, count}
        for src_idx, src_list in enumerate(results):
            if isinstance(src_list, Exception):
                continue
            for item in src_list:
                raw_name = _clean_writing_competitor_name(item["name"])
                if not raw_name or brand_name[:4] in raw_name:
                    continue
                # v1_3: 过滤非品牌文本（markdown / SKU / 句子 / 过长）
                if not _looks_like_brand_name(raw_name):
                    logger.debug(f"[research-competitors] 过滤非品牌: {raw_name[:30]}")
                    continue
                # 归一化 — 仅用于投票匹配的key
                norm = _normalize_brand(raw_name, region)
                if len(norm) < 2:
                    continue

                # 模糊匹配已有的
                matched_key = None
                for existing_key in all_names:
                    if norm in existing_key or existing_key in norm:
                        matched_key = existing_key
                        break

                if matched_key:
                    all_names[matched_key]["count"] += 1
                    all_names[matched_key]["sources"].add(source_names[src_idx])
                    if not all_names[matched_key]["desc"] and item.get("desc"):
                        all_names[matched_key]["desc"] = item["desc"]
                    # 保留信息最丰富的名称（更长的通常包含项目名等有用信息）
                    # 但如果差异太大（>10字），保留较短的避免噪音
                    curr = all_names[matched_key]["name"]
                    if len(raw_name) > len(curr) and len(raw_name) - len(curr) <= 10:
                        all_names[matched_key]["name"] = raw_name
                else:
                    all_names[norm] = {
                        "name": raw_name,  # 保留原始全名（含项目名等信息）
                        "desc": item.get("desc", ""),
                        "count": 1,
                        "sources": {source_names[src_idx]}
                    }

        # 按确认源数排序，>=2 的优先
        sorted_items = sorted(all_names.values(), key=lambda x: (-x["count"], x["name"]))

        # ============================================
        # Step 3: 秘塔验证 — 对 Top 候选做网页搜索确认
        # ============================================
        metaso_key = os.environ.get("METASO_API_KEY", "")
        verified_competitors = []

        # 行业→权威验证渠道映射
        def _get_authority_domains() -> list:
            """根据行业返回对应的权威验证域名列表"""
            # 通用权威来源（所有行业）
            general = ["tianyancha.com", "qcc.com", "aiqicha.com", "gov.cn"]

            if is_real_estate:
                return general + [
                    "fang.com", "lianjia.com", "anjuke.com", "ke.com",  # 房产平台
                    "loupan.com", "newhouse", "house.focus.cn",  # 楼盘网
                    "zjj.gov", "住建", "房管", "zfcxjst",  # 住建局/房管局
                ]
            # 餐饮/美食(加 koubei + xiaohongshu 本地探店真实信号)
            if any(kw in industry for kw in ['餐饮', '美食', '饮食', '奶茶', '火锅', '咖啡']):
                return general + ["dianping.com", "meituan.com", "ele.me", "大众点评",
                                  "koubei.com", "xiaohongshu.com"]
            # 教育/培训
            if any(kw in industry for kw in ['教育', '培训', '学校', '留学', '考研']):
                return general + ["edu.cn", "xuexin.com", "学信网", "eol.cn"]
            # 医疗/健康
            if any(kw in industry for kw in ['医疗', '医院', '诊所', '牙科', '眼科', '健康']):
                return general + ["nhc.gov.cn", "haodf.com", "好大夫", "xywy.com"]
            # 汽车
            if any(kw in industry for kw in ['汽车', '车', '新能源车', '4S']):
                return general + ["autohome.com.cn", "yiche.com", "pcauto.com.cn", "miit.gov.cn"]
            # 装修/家装
            if any(kw in industry for kw in ['装修', '家装', '装饰', '家居']):
                return general + ["to8to.com", "jia.com", "pchouse.com.cn", "齐家网"]
            # 金融/保险
            if any(kw in industry for kw in ['金融', '银行', '保险', '证券', '基金', '理财']):
                return general + ["cbirc.gov.cn", "csrc.gov.cn", "pboc.gov.cn"]
            # 旅游/酒店(CTO-15.23 P1 加美团/飞猪/艺龙/同程/去哪儿/住哪/小红书 — 本地小品牌主要被这些平台收录)
            if any(kw in industry for kw in ['旅游', '酒店', '民宿', '旅行', '住宿']):
                return general + [
                    "ctrip.com", "mafengwo.cn", "booking.com", "qunar.com",
                    "meituan.com", "dianping.com",       # 美团/大众点评 本地酒店强信号
                    "fliggy.com", "alitrip.com",          # 飞猪
                    "elong.com",                          # 艺龙
                    "ly.com",                             # 同程
                    "zhuna.cn",                           # 住哪
                    "xiaohongshu.com",                    # 小红书探店
                ]
            # 通用：加上百科/社区
            return general + [
                "baidu.com/baike", "sogou.com",
                "zhihu.com", "people.com.cn", "xinhua",
            ]

        async def verify_with_metaso(candidate_name: str) -> dict:
            """用秘塔搜索验证品牌/项目是否在权威渠道真实存在"""
            if not metaso_key:
                return {"verified": False, "source": "verification_unavailable:no_api_key", "projects": []}
            try:
                # 用完整的候选名搜索（不做归一化，验证的是原始名称）
                if is_real_estate:
                    search_q = f'"{candidate_name}" {region} 楼盘'
                else:
                    search_q = f'"{candidate_name}" {region} {industry}'

                authority_domains = _get_authority_domains()

                async with httpx.AsyncClient(timeout=15.0) as client:
                    resp = await client.post(
                        "https://metaso.cn/api/v1/search",
                        headers={"Authorization": f"Bearer {metaso_key}",
                                 "Accept": "application/json", "Content-Type": "application/json"},
                        json={"q": search_q, "scope": "webpage", "size": 10,
                              "includeSummary": is_real_estate, "conciseSnippet": True}
                    )
                    if resp.status_code != 200:
                        return {"verified": False, "source": f"verification_http_{resp.status_code}", "projects": []}
                    data = resp.json()
                    # 秘塔API返回的字段是 webpages 而非 results
                    results_list = data.get("webpages", data.get("results", []))

                    if not results_list:
                        return {"verified": False, "source": "秘塔搜索无结果", "projects": []}

                    # 用归一化名提取核心词做模糊匹配
                    core_brand = _normalize_brand(candidate_name, region)
                    name_short = core_brand[:4].lower()
                    has_authority = False
                    has_mention = False
                    best_source = ""
                    found_projects = []

                    for r in results_list[:10]:
                        title = r.get("title", "")
                        snippet = r.get("snippet", r.get("conciseSnippet", ""))
                        url = r.get("link", r.get("url", ""))
                        text_combined = (title + snippet)

                        if name_short in text_combined.lower():
                            has_mention = True
                            if not best_source:
                                best_source = url[:80]

                            # 检查是否来自该行业的权威来源
                            is_authority = False
                            for domain in authority_domains:
                                if domain in url.lower():
                                    is_authority = True
                                    has_authority = True
                                    best_source = f"[权威] {url[:80]}"
                                    break

                            # 房地产：从权威平台提取真实楼盘项目名
                            if is_real_estate and is_authority:
                                _extract_projects_from_text(
                                    text_combined, core_brand, region, found_projects
                                )

                    # 从摘要中也提取项目名
                    if is_real_estate and has_mention:
                        summary = data.get("summary", "")
                        if summary:
                            _extract_projects_from_text(
                                summary, core_brand, region, found_projects
                            )

                    result = {"projects": found_projects[:5]}

                    if has_authority:
                        result.update({"verified": True, "source": best_source})
                    elif has_mention:
                        result.update({"verified": True, "source": best_source})
                    else:
                        result.update({"verified": False, "source": "搜索结果中未提及该品牌"})
                    return result
            except Exception as e:
                return {"verified": False, "source": f"verification_error:{type(e).__name__}", "projects": []}

        def _extract_projects_from_text(text: str, brand: str, rgn: str, out_list: list):
            """从权威平台文本中提取该开发商在该地区的真实楼盘项目名"""
            import re
            # 常见楼盘命名模式：品牌名+项目名 或 品牌·项目名
            # 如 "碧桂园天玺湾""保利和府""万科城""中海锦城"
            # 也可能是 "XX·YY花园""XX·YY府"
            project_suffixes = (
                '花园|府|湾|城|苑|园|院|庭|里|阁|台|轩|居|墅|邸|宸|悦|著|序|境|颂|樾|'
                '雅|璟|玺|铂|澜|岸|峰|汇|坊|郡|公馆|广场|中心|壹号|天下|世家|华庭|半岛|'
                '名都|天地|新城|印象|壹品|云著|和院|雅苑|名苑|御园|星城|锦园|翠园|嘉园'
            )
            # 模式1：品牌名+项目名（如"碧桂园天玺湾花园"）
            pattern1 = rf'{re.escape(brand)}[・·]?([一-龥]{{1,8}}(?:{project_suffixes}))'
            # 模式2：地区+品牌+项目名（如"揭阳碧桂园天玺湾"）
            pattern2 = rf'{re.escape(rgn[:2])}?{re.escape(brand)}[・·]?([一-龥]{{1,8}}(?:{project_suffixes}))'
            # 模式3：独立的项目名提及（如"天玺湾花园""和府"出现在品牌上下文中）
            # 暂不使用，避免误提取

            for pattern in [pattern1, pattern2]:
                matches = re.findall(pattern, text)
                for m in matches:
                    project_name = m.strip()
                    if len(project_name) >= 2 and project_name not in out_list:
                        full_name = f"{brand}·{project_name}"
                        if full_name not in out_list:
                            out_list.append(full_name)

        # 对排名前 12 的候选品牌并发验证
        candidates = sorted_items[:12]
        if metaso_key and candidates:
            logger.info(f"  [秘塔验证] 开始验证 {len(candidates)} 个候选品牌...")
            verify_tasks = [verify_with_metaso(c["name"]) for c in candidates]
            verify_results = await asyncio.gather(*verify_tasks)

            for candidate, verify_detail in zip(candidates, verify_results):
                is_verified = verify_detail["verified"]
                verify_source = verify_detail["source"]
                projects = verify_detail.get("projects", [])
                confidence = "high" if candidate["count"] >= 2 and is_verified else \
                             "medium" if candidate["count"] >= 2 or is_verified else "low"
                entry = {
                    "name": candidate["name"],
                    "desc": candidate["desc"],
                    "confirmed_by": list(candidate["sources"]),
                    "source_count": candidate["count"],
                    "metaso_verified": is_verified,
                    "verify_source": verify_source,
                    "name_verified": bool(is_verified and verify_source.startswith(("http", "[权威] http"))),
                    "confidence": confidence
                }
                # 房地产行业：附加从权威平台提取的真实项目名
                if is_real_estate and projects:
                    entry["projects"] = projects
                    entry["desc"] = f"在{region}项目: {'、'.join(projects[:3])}"
                verified_competitors.append(entry)
                projects_info = f" 项目:{projects}" if projects else ""
                status = "✅" if confidence != "low" else "⚠️"
                logger.info(f"    {status} {candidate['name']} — LLM来源:{candidate['count']}个 秘塔:{'通过' if is_verified else '未通过'} 信源:{verify_source[:40]} 置信度:{confidence}{projects_info}")
        else:
            # 无秘塔key，只用投票结果
            for candidate in candidates:
                confidence = "high" if candidate["count"] >= 2 else "medium"
                verified_competitors.append({
                    "name": candidate["name"],
                    "desc": candidate["desc"],
                    "confirmed_by": list(candidate["sources"]),
                    "source_count": candidate["count"],
                    "metaso_verified": None,
                    "verify_source": "",
                    "name_verified": False,
                    "confidence": confidence
                })

        # 只保留 medium 及以上置信度的（排除 low — 仅单源且秘塔未验证的）
        # P0: 最终入库前再清洗一次,避免材料/品类词混入"真实竞品"。
        final_competitors = _sanitize_writing_competitors(
            [c for c in verified_competitors if c["confidence"] != "low"],
            industry,
            is_real_estate=is_real_estate,
        )

        # [CTO-15.23 2026-05-05] 写入前 LLM 守门员净化(防 dirty 数据持久化)
        # 老板"客户品牌/业务范围/因此应该是"等垃圾乱入 P0 反馈
        # LLM 失败 → 保留 sanitize 结果(零回归)· 5min cache 控成本
        before_llm = len(final_competitors)
        final_competitors = await _sanitize_competitors_with_llm(
            final_competitors, industry, region, is_real_estate=is_real_estate
        )
        if before_llm != len(final_competitors):
            logger.info(f"  [LLM 守门员] 净化 {before_llm} → {len(final_competitors)} 家")

        logger.info(f"  [最终结果] {len(final_competitors)} 家通过验证(原始候选 {len(sorted_items)} 家)")

        # ============================================
        # Step 4: 竞品画像采集 — 逐个并发搜索，确保每家都有资料
        # ============================================
        if final_competitors:
            ds_key = os.environ.get("DASHSCOPE_API_KEY", "")
            if ds_key:
                logger.info(f"  [竞品画像] 开始逐个并发采集 {len(final_competitors[:10])} 家竞品画像...")

                async def _fetch_one_profile(comp_name: str) -> str:
                    """单独为一家竞品联网搜索画像"""
                    if is_real_estate:
                        prompt = f"请详细介绍一下{region}的「{comp_name}」楼盘项目。包括：开发商是谁、项目定位、主力户型面积段、参考均价、核心卖点和周边配套。请基于真实信息回答，用100-150字概括。"
                    else:
                        prompt = f"请详细介绍一下「{comp_name}」这个品牌/产品。包括：所属公司、主营业务、核心优势和特色、适合什么类型的客户。请基于真实信息回答，用100-150字概括。"
                    try:
                        async with httpx.AsyncClient(timeout=30.0) as client:
                            resp = await client.post(
                                "https://dashscope.aliyuncs.com/api/v1/services/aigc/text-generation/generation",
                                headers={"Authorization": f"Bearer {ds_key}", "Content-Type": "application/json"},
                                json={
                                    "model": "qwen3.7-max",
                                    "input": {"messages": [{"role": "user", "content": prompt}]},
                                    "parameters": {
                                        "max_tokens": 500,
                                        "enable_search": True,
                                        "search_options": {"forced_search": True},
                                        "result_format": "message",
                                    }
                                }
                            )
                            if resp.status_code == 200:
                                data = resp.json()
                                text = data.get("output", {}).get("choices", [{}])[0].get("message", {}).get("content", "")
                                # 去除思考标签
                                if "</think>" in text:
                                    text = text.split("</think>")[-1].strip()
                                # 截取前200字，去掉开头的套话
                                text = text.strip()
                                for prefix in ["好的，", "以下是", "根据搜索结果，", "根据公开信息，"]:
                                    if text.startswith(prefix):
                                        text = text[len(prefix):]
                                return text[:250].strip()
                            else:
                                return ""
                    except Exception as e:
                        logger.warning(f"    [画像] {comp_name} 采集失败: {e}")
                        return ""

                # 并发采集所有竞品画像（最多10家）
                profile_tasks = [_fetch_one_profile(c["name"]) for c in final_competitors[:10]]
                profile_results = await asyncio.gather(*profile_tasks)

                # 🔴 2026-08-08:画像本身就是"这到底是不是一家公司"的**最强证据**,
                #    而此前它只被当成内容存下来,没人看它说了什么。
                #
                #    上游那两道清洗(`_sanitize_writing_competitors` 正则 +
                #    `_sanitize_competitors_with_llm` LLM 守门员)都跑在**画像生成之前** ——
                #    它们不是失效,是那会儿证据还不存在。所以补在这里。
                #
                #    我们问的是「请介绍一下「X」这个**品牌/产品**」,模型答
                #    「"混凝土"并非单一品牌,而是一类建筑材料的统称」或
                #    「未发现名为"Z建筑材料供应商"的具体品牌或企业信息」时,
                #    那就是它在告诉我们:这条候选根本没有主体。
                #
                #    生产实测(2026-08-08):428 条竞品里 10 条自陈无主体,其中 **4 条
                #    已经被代理手工排除** —— 用户在替系统擦屁股。剩 6 条还挂着。
                #
                #    判定复用 `competitor_name_contract`(全仓唯一口径,不在这儿另写正则);
                #    动作用**既有** `excluded` 机制 —— 文章链已在过滤它、
                #    前端已在显示「N家已排除」,不新造字段、不新造 UI。
                from writing.competitor_name_contract import profile_lacks_subject

                matched_count = 0
                dropped_count = 0
                for comp, profile_text in zip(final_competitors[:10], profile_results):
                    if profile_text and len(profile_text) > 10:
                        comp["profile"] = profile_text
                        matched_count += 1
                        if profile_lacks_subject(profile_text):
                            comp["excluded"] = True
                            comp["exclude_reason"] = "profile_no_subject"
                            dropped_count += 1
                            logger.info(f"    🚫 {comp['name']}: 画像自陈无主体(品类词/查无此企业),自动排除")
                        else:
                            logger.info(f"    ✅ {comp['name']}: {profile_text[:40]}...")
                    else:
                        logger.info(f"    ⚠️ {comp['name']}: 未获取到画像")

                logger.info(f"  [竞品画像] 完成，{matched_count}/{len(final_competitors[:10])} 家采集成功"
                            + (f"，自动排除 {dropped_count} 家无主体候选" if dropped_count else ""))

        # 结果模式由证据本身决定，即使持久化暂时失败也能稳定返回降级状态。
        result_mode = (
            "real"
            if final_competitors and all(_writing_competitor_name_is_verified(item) for item in final_competitors)
            else ("semi" if final_competitors else "evidence_only")
        )

        # 持久化到数据库
        try:
            conn = get_connection()
            c = conn.cursor()
            c.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = 'quotes'
            """)
            cols = [r["column_name"] for r in c.fetchall()]
            if "competitor_list" not in cols:
                c.execute("ALTER TABLE quotes ADD COLUMN competitor_list TEXT DEFAULT ''")
            if "competitor_mode" not in cols:
                c.execute("ALTER TABLE quotes ADD COLUMN competitor_mode TEXT DEFAULT 'evidence_only'")
            c.execute("UPDATE quotes SET competitor_list = %s, competitor_mode = %s WHERE id = %s",
                      (json.dumps(final_competitors, ensure_ascii=False), result_mode, quote_id))
            conn.commit()
            conn.close()
        except Exception as e:
            logger.error(f"⚠️ 保存竞品列表失败: {e}")

        return {
            "status": "success",
            "query": search_query,
            "competitors": final_competitors,
            "count": len(final_competitors),
            "sources_used": [s for s, r in zip(source_names, results) if r],
            "raw_candidates": len(sorted_items),
            "verification": "name_source_checked" if result_mode == "real" else "candidates_need_verification",
            "mode": result_mode,
        }

    except HTTPException:
        raise
    except Exception as e:
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


def _parse_competitor_lines(content: str) -> list:
    """解析LLM返回的竞品列表文本为结构化列表"""
    import re
    # 彻底清理LLM工具调用标签及其内容（Kimi的 <tool>web_search</tool> 等）
    content = re.sub(r'<tool>[^<]*</tool>', '', content)
    content = re.sub(r'<search>[^<]*</search>', '', content)
    content = re.sub(r'<function>[^<]*</function>', '', content)
    # 清理残留的单独标签
    content = re.sub(r'<[^>]+>', '', content)

    competitors = []
    for line in content.strip().split("\n"):
        line = line.strip().lstrip("0123456789.-、）)· *")
        if not line or len(line) < 3:
            continue
        # 跳过LLM废话、标题、说明行
        skip_keywords = [
            "以下是", "根据", "注意", "以上", "说明", "---", "```",
            "让我", "继续搜索", "更多具体", "搜索结果", "暂时没有",
            "无法确认", "需要进一步", "抱歉", "请注意", "补充说明",
            "总结", "备注", "提示", "温馨提示", "web_search",
            "tool", "function", "search_query", "希望", "如果你",
        ]
        if any(kw in line.lower() for kw in skip_keywords):
            continue
        # 跳过纯英文/标点/数字行（如残留的JSON或代码）
        if re.match(r'^[\s\w\d\-\.\{\}\[\]\",:]+$', line) and not re.search(r'[\u4e00-\u9fff]', line):
            continue
        name, desc = "", ""
        for sep in ["|", "—", "–", "：", ":"]:
            if sep in line:
                parts = line.split(sep, 1)
                name = parts[0].strip()
                desc = parts[1].strip() if len(parts) > 1 else ""
                break
        if not name:
            name = line.strip()
        # 清理名称中的加粗标记和残留标签
        name = re.sub(r'\*+', '', name).strip()
        name = re.sub(r'<[^>]+>', '', name).strip()
        # 跳过太短或太长或包含明显非名称词的
        if len(name) <= 2 or len(name) >= 30:
            continue
        if any(kw in name for kw in ['搜索', '继续', '更多', '信息', 'tool', 'web', '请']):
            continue
        competitors.append({"name": name, "desc": desc[:30]})
    return competitors


def _writing_competitor_name_is_verified(item: object) -> bool:
    """A name is publishable only after durable source or explicit human verification."""
    from services.writing_competitor_verification import competitor_name_is_verified

    return competitor_name_is_verified(item)


@app.get("/api/writing/competitors/{quote_id}")
async def api_get_competitors(quote_id: int, request: Request):
    """获取已保存的竞品列表及模式
    [P0-4 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 加 require_quote_access
    [CTO-15.23 2026-05-05] 加 LLM 守门员 · 老板"客户品牌/业务范围"乱入 P0 反馈
    流程:DB 读 → 轻量规则净化(markdown/长度) → LLM 净化(语义判断真品牌)
    LLM 全挂 → 退回轻量规则结果(零回归)· 5min cache 控成本
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection
        import json
        conn = get_connection()
        try:
            c = conn.cursor()

            # 确保字段存在
            c.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = 'quotes'
            """)
            cols = [r["column_name"] for r in c.fetchall()]
            if "competitor_mode" not in cols:
                c.execute("ALTER TABLE quotes ADD COLUMN competitor_mode TEXT DEFAULT 'evidence_only'")
                conn.commit()

            c.execute("SELECT competitor_list, competitor_mode, industry, city FROM quotes WHERE id = %s", (quote_id,))
            row = c.fetchone()
            conn.close()

            if row:
                competitors = json.loads(row["competitor_list"]) if row["competitor_list"] else []
                industry = row.get("industry", "") or ""
                region = row.get("city", "") or ""
                # 轻量规则 + LLM 双层净化(LLM 失败 fallback 轻量规则)
                competitors = await _sanitize_competitors_with_llm(competitors, industry, region)
                raw_mode = row["competitor_mode"] or "evidence_only"
                active_competitors = [
                    item for item in competitors
                    if not (isinstance(item, dict) and item.get("excluded"))
                ]
                if raw_mode == "real" and active_competitors and all(
                    _writing_competitor_name_is_verified(item) for item in active_competitors
                ):
                    mode = "real"
                elif active_competitors:
                    mode = "semi"
                else:
                    mode = "evidence_only"
                return {"status": "success", "competitors": competitors, "count": len(competitors), "mode": mode}
            return {"status": "success", "competitors": [], "count": 0, "mode": "evidence_only"}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        # [self-review r6 2026-05-23] Deploy-CTO 实证:外层 except Exception 吞 HTTPException
        # 把 require_quote_access 抛的 403/404 转 200 silent · 跨租户能拿到 fallback 空列表
        raise
    except Exception as e:
        logger.warning(f"[竞品 GET] 异常 fallback: {e}")
        return {"status": "success", "competitors": [], "count": 0, "mode": "evidence_only"}


@app.post("/api/writing/competitors/{quote_id}/verify")
async def api_verify_competitor_names(quote_id: int, request: Request):
    """Verify the persisted candidate names without regenerating or replacing the list."""
    from auth.brand_access import require_quote_access
    from db.diagnosis_db import get_connection
    from services.writing_competitor_verification import (
        CompetitorVerificationCapacityExceeded,
        CompetitorVerificationConflict,
        CompetitorVerificationForbidden,
        CompetitorVerificationInProgress,
        CompetitorVerificationNotFound,
        CompetitorVerificationUnavailable,
        execute_competitor_verification_request,
    )
    import re
    import uuid

    user = getattr(request.state, "user", None)
    if not isinstance(user, dict):
        raise HTTPException(status_code=401, detail="未登录")
    raw_user_id = user.get("user_id") or user.get("id")
    normalized_user_id = int(raw_user_id) if str(raw_user_id or "").strip().isdigit() else None
    raw_request_id = str(request.headers.get("X-Request-ID") or "")[:100]
    request_id = raw_request_id if re.fullmatch(r"[A-Za-z0-9._:-]{1,100}", raw_request_id) else uuid.uuid4().hex

    try:
        result = await execute_competitor_verification_request(
            quote_id=quote_id,
            request_id=request_id,
            user=user,
            user_id=normalized_user_id,
            initial_access_check=lambda: require_quote_access(request, quote_id),
            connection_factory=get_connection,
        )
        return {
            "status": "success",
            "mode": result["mode"],
            "competitors": result["competitors"],
            "attempted_count": result["attempted_count"],
            "newly_verified": result["newly_verified"],
            "verified_count": result["verified_count"],
            "pending_count": len(result["pending_names"]),
            "pending_names": result["pending_names"][:20],
            "provider_error_count": result["provider_error_count"],
        }
    except CompetitorVerificationCapacityExceeded as exc:
        raise HTTPException(status_code=503, detail=str(exc), headers={"Retry-After": "2"})
    except CompetitorVerificationInProgress as exc:
        raise HTTPException(status_code=409, detail=str(exc))
    except CompetitorVerificationUnavailable as exc:
        raise HTTPException(status_code=503, detail=str(exc))
    except CompetitorVerificationNotFound as exc:
        raise HTTPException(status_code=404, detail=str(exc))
    except CompetitorVerificationForbidden as exc:
        raise HTTPException(status_code=403, detail=str(exc))
    except CompetitorVerificationConflict as exc:
        raise HTTPException(status_code=409, detail=str(exc))


@app.put("/api/writing/competitors/{quote_id}/mode")
def api_set_competitor_mode(quote_id: int, body: dict, request: Request):
    """设置竞品模式: real / semi / evidence_only（兼容读取 legacy fictional）
    [self-review r4 2026-05-23] IDOR 闭环:加 require_quote_access
    原签名 request: dict 错把 Request 当 body · 同时缺 owner 校验"""
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection
        raw_mode = str(body.get("mode") or "evidence_only").strip()
        mode = "evidence_only" if raw_mode == "fictional" else raw_mode
        if mode not in ("real", "semi", "evidence_only"):
            raise HTTPException(status_code=400, detail="无效竞品证据状态")

        conn = get_connection()
        try:
            c = conn.cursor()

            # 确保字段存在
            c.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = 'quotes'
            """)
            cols = [r["column_name"] for r in c.fetchall()]
            if "competitor_mode" not in cols:
                c.execute("ALTER TABLE quotes ADD COLUMN competitor_mode TEXT DEFAULT 'evidence_only'")

            if mode == "real":
                c.execute("SELECT competitor_list FROM quotes WHERE id = %s", (quote_id,))
                row = c.fetchone() or {}
                try:
                    candidates = json.loads(row.get("competitor_list") or "[]")
                except (TypeError, ValueError):
                    candidates = []
                active = [
                    item for item in candidates
                    if not (isinstance(item, dict) and item.get("excluded"))
                ]
                if not active or not all(_writing_competitor_name_is_verified(item) for item in active):
                    raise HTTPException(
                        status_code=409,
                        detail="仍有候选缺少可追溯名称证据，请继续核验或使用‘待核验’。",
                    )

            c.execute("UPDATE quotes SET competitor_mode = %s WHERE id = %s", (mode, quote_id))
            conn.commit()
            conn.close()
            return {"status": "success", "mode": mode}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


