@app.put("/api/writing/competitors/{quote_id}/exclude")
def api_toggle_competitor_exclude(quote_id: int, body: dict, request: Request):
    """切换单个竞品的排除状态（黑名单）

    Body: {"name": "竞品名", "excluded": true/false}
    [self-review r4 2026-05-23] IDOR 闭环:加 require_quote_access · 修复 request:dict 把 Request 当 body 错误
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection
        import json

        comp_name = body.get("name", "")
        excluded = body.get("excluded", True)

        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute("SELECT competitor_list FROM quotes WHERE id = %s", (quote_id,))
            row = c.fetchone()
            if not row or not row["competitor_list"]:
                conn.close()
                raise HTTPException(status_code=404, detail="竞品列表不存在")

            competitors = json.loads(row["competitor_list"])
            updated = False
            for comp in competitors:
                if isinstance(comp, dict) and comp.get("name") == comp_name:
                    comp["excluded"] = excluded
                    updated = True
                    break

            if updated:
                c.execute("UPDATE quotes SET competitor_list = %s WHERE id = %s",
                          (json.dumps(competitors, ensure_ascii=False), quote_id))
                conn.commit()

            conn.close()
            return {"status": "success", "name": comp_name, "excluded": excluded}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/writing/competitors/{quote_id}/add")
async def api_add_competitor(quote_id: int, body: dict, request: Request):
    """手动添加竞争对手：输入公司名，AI联网搜索自动填充资料

    Body: {"name": "好莱客全屋定制"}
    [self-review r4 2026-05-23] IDOR 闭环:加 require_quote_access · 修复 request:dict 错位
    """
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_quote, get_connection
        import httpx
        import json
        import os

        comp_name = body.get("name", "").strip()
        if not comp_name:
            raise HTTPException(status_code=400, detail="请输入竞争对手名称")

        quote = get_quote(quote_id)
        if not quote:
            raise HTTPException(status_code=404, detail="报价单不存在")

        brand_name = quote.get("brand_name", "")
        industry = quote.get("industry", "")
        if not _is_valid_writing_competitor_name(comp_name, industry):
            raise HTTPException(status_code=400, detail="请输入真实公司、品牌或项目名称，不要填写材料/品类词")

        # 检查是否已存在
        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute("SELECT competitor_list, competitor_mode FROM quotes WHERE id = %s", (quote_id,))
            row = c.fetchone()
            existing = json.loads(row["competitor_list"]) if row and row["competitor_list"] else []
            current_mode = row["competitor_mode"] if row else "evidence_only"

            # 去重检查
            for comp in existing:
                if isinstance(comp, dict) and comp.get("name", "").strip() == comp_name:
                    conn.close()
                    raise HTTPException(status_code=409, detail=f"竞品「{comp_name}」已存在")

            # 用 DashScope（qwen-max + enable_search）联网搜索该公司信息
            api_key = os.environ.get("DASHSCOPE_API_KEY", "")
            desc = ""
            if api_key:
                search_prompt = f"""请联网搜索「{comp_name}」这家公司/品牌的信息，用1-2句话概括：
    1. 该公司/品牌的核心业务是什么
    2. 在「{industry}」行业中的定位或特点
    3. 如果能找到具体的规模、成立时间等信息也请包含

    要求：只输出1-2句话的简介，不要有格式标记，不要有多余解释。如果搜不到信息就直接回复"未找到详细信息"。"""

                try:
                    async with httpx.AsyncClient(timeout=20.0) as client:
                        resp = await client.post(
                            "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",
                            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                            json={
                                "model": "qwen3.7-max",
                                "messages": [{"role": "user", "content": search_prompt}],
                                "temperature": 0.2,
                                "max_tokens": 300,
                                "enable_search": True
                            }
                        )
                        resp.raise_for_status()
                        desc = resp.json()["choices"][0]["message"]["content"].strip()
                        # 清理：去掉可能的markdown格式
                        desc = desc.replace("**", "").replace("*", "").strip()
                        if desc.startswith('"') and desc.endswith('"'):
                            desc = desc[1:-1]
                except Exception as e:
                    logger.warning(f"[手动添加竞品] AI搜索失败: {e}")
                    desc = "手动添加，暂无详细信息"
            else:
                desc = "手动添加，暂无详细信息"

            # 构建新竞品对象
            new_competitor = {
                "name": comp_name,
                "desc": desc,
                "confidence": "manual",
                "source_count": 1,
                "confirmed_by": ["手动添加"],
                "name_verified": False,
                "excluded": False
            }

            # 追加到列表
            existing.append(new_competitor)

            # 手工录入只是候选；即使原列表已核验，加入新名称后也必须整体降为待核验。
            new_mode = "semi"

            # 确保字段存在
            c.execute("""
                SELECT column_name FROM information_schema.columns
                WHERE table_name = 'quotes'
            """)
            cols = [r["column_name"] for r in c.fetchall()]
            if "competitor_mode" not in cols:
                c.execute("ALTER TABLE quotes ADD COLUMN competitor_mode TEXT DEFAULT 'evidence_only'")

            c.execute("UPDATE quotes SET competitor_list = %s, competitor_mode = %s WHERE id = %s",
                      (json.dumps(existing, ensure_ascii=False), new_mode, quote_id))

            # CTO-15.23 2026-05-25 · 已核验/待核验候选回流 brands.competitors_jsonb 全局字段
            # · 修法:写作 add 竞品时 · 同步 brand 级 competitors_jsonb 池(merge 去重 · 不覆盖)
            # · 让诊断/报价/监测/其他写作流程预填命中(不让用户每次重选)
            # · brand_id 来自 quote → quote.brand_id(diagnosis_db.py:167 brands.competitors_jsonb 实证存在)
            try:
                brand_id_for_sync = quote.get("brand_id")
                if brand_id_for_sync:
                    c.execute("SELECT competitors_jsonb FROM brands WHERE id = %s", (brand_id_for_sync,))
                    brand_row = c.fetchone()
                    brand_comps = []
                    if brand_row and brand_row.get("competitors_jsonb"):
                        bc = brand_row["competitors_jsonb"]
                        # psycopg2 JSONB 返 list/dict · 老数据可能是 str
                        if isinstance(bc, str):
                            try:
                                brand_comps = json.loads(bc) or []
                            except Exception:
                                brand_comps = []
                        elif isinstance(bc, list):
                            brand_comps = list(bc)
                    existing_names = {
                        (b.get("name") or "").strip()
                        for b in brand_comps if isinstance(b, dict)
                    }
                    if comp_name not in existing_names:
                        from datetime import datetime as _dt
                        brand_comps.append({
                            "name": comp_name,
                            "desc": desc,
                            "source": "writing_select",  # 来源标记 · 区分诊断/手填
                            "source_quote_id": quote_id,
                            "added_at": _dt.now().isoformat(),
                        })
                        c.execute(
                            "UPDATE brands SET competitors_jsonb = %s WHERE id = %s",
                            (json.dumps(brand_comps, ensure_ascii=False), brand_id_for_sync),
                        )
                        logger.info(
                            f"[竞品候选回流] {comp_name} → brand_id={brand_id_for_sync} · "
                            f"brand 池 {len(brand_comps)} 个"
                        )
            except Exception as _sync_err:
                # 回流失败不阻塞主流程(quote 已 commit · brand 同步只是 nice-to-have)
                logger.warning(f"[竞品候选回流] 同步 brand 失败(非阻塞) quote={quote_id}: {_sync_err}")

            conn.commit()
            conn.close()

            logger.info(f"✅ [手动添加竞品] {comp_name} → 项目{quote_id}，简介: {desc[:50]}...")

            return {
                "status": "success",
                "competitor": new_competitor,
                "mode": new_mode,
                "total_count": len(existing)
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"手动添加竞品失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


