@app.get("/api/writing/config")
def api_get_writing_config(request: Request):
    """获取写作配置（LLM 模型 + 所有提示词模板）
    [P0-7 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 非 admin 隐藏 prompt 正文"""
    try:
        user = getattr(request.state, "user", None)
        if not user:
            raise HTTPException(status_code=401, detail="未登录")
        from writing.style_registry import get_writing_config_for_frontend
        config = get_writing_config_for_frontend()
        # 非 admin: 隐藏 prompt 正文(只返样式名/has_prompt 标记)
        if not user.get("is_admin"):
            styles = config.get("styles") or []
            for s in styles:
                if isinstance(s, dict) and "prompt" in s:
                    s["has_prompt"] = bool(s.get("prompt"))
                    s.pop("prompt", None)
        return {"success": True, "data": config}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取写作配置失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


