@app.get("/api/writing/progress/{quote_id}")
def api_get_writing_progress(quote_id: int, request: Request):
    """获取文章生成进度"""
    try:
        from auth.brand_access import require_quote_access
        require_quote_access(request, quote_id)
        from db.diagnosis_db import get_connection

        conn = get_connection()
        try:
            c = conn.cursor()

            # 统计各状态数量 (topics表有quote_id字段)
            c.execute('''
                SELECT status, COUNT(*) as count
                FROM topics
                WHERE quote_id=%s
                GROUP BY status
            ''', (quote_id,))

            stats = {row['status']: row['count'] for row in c.fetchall()}

            # 获取写作中的标题
            c.execute('''
                SELECT id, optimized_title as title, status, article_id
                FROM topics
                WHERE quote_id = %s AND status = 'writing'
            ''', (quote_id,))
            writing = [dict(row) for row in c.fetchall()]

            # 获取已完成的标题
            c.execute('''
                SELECT t.id, t.optimized_title as title, t.status, t.article_id,
                       a.word_count, a.version
                FROM topics t
                LEFT JOIN articles a ON t.article_id = a.id
                WHERE t.quote_id = %s AND t.status = 'completed'
                ORDER BY a.created_at DESC
            ''', (quote_id,))
            completed = [dict(row) for row in c.fetchall()]

            # Stable customer-safe failure projection. Legacy rows use a
            # generic message; raw provider/database text is never returned.
            c.execute('''
                SELECT id,optimized_title AS title,status,generation_request_id,
                       COALESCE(generation_error_code,'ARTICLE_LEGACY_FAILURE') AS generation_error_code,
                       COALESCE(generation_error_message,'文章生成未完成，可刷新后重试。') AS generation_error_message,
                       COALESCE(generation_retryable,TRUE) AS generation_retryable,
                       generation_failure_phase,
                       generation_refund_status,
                       generation_revision
                  FROM topics
                 WHERE quote_id=%s AND status='failed'
                 ORDER BY writing_started_at DESC NULLS LAST,id DESC
            ''', (quote_id,))
            failed = [dict(row) for row in c.fetchall()]
            from services.article_generation_status import refund_status_message
            for item in failed:
                item["generation_refund_message"] = refund_status_message(
                    item.get("generation_refund_status")
                )
            _organization_identity = getattr(request.state, "organization_identity", None)
            if _organization_identity is not None and _organization_identity.is_member:
                from auth.brand_access import filter_organization_artifact_rows
                completed = filter_organization_artifact_rows(
                    request, "article", completed, id_key="article_id"
                )
                stats["completed"] = len(completed)

            conn.close()

            total = sum(stats.values())
            completed_count = stats.get('completed', 0)

            return {
                "success": True,
                "quote_id": quote_id,
                "total": total,
                "pending": stats.get('pending', 0),
                "writing": stats.get('writing', 0),
                "completed": completed_count,
                "failed": stats.get('failed', 0),
                "progress": round(completed_count / total * 100, 1) if total > 0 else 0,
                "writing_list": writing,
                "completed_list": completed,
                "failed_list": failed,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("获取写作进度失败")
        raise HTTPException(
            status_code=500,
            detail={"code": "ARTICLE_PROGRESS_FAILED", "message": "写作进度暂时无法读取，请刷新重试。"},
        )


@app.post("/api/writing/rewrite/{topic_id}")
async def api_rewrite_article(topic_id: int, request: ArticleRewriteRequest, http_request: Request = None):
    """重写文章

    [CTO-15.23 2026-05-19 P0 修费 · 另 AI 复查发现]
    之前完全没扣费 = 代理可以无限点重写 100% 白嫖
    修:_bill_feature_ctx 包业务 logic · article_rewrite=260 积分/次 · 后扣费(完成才扣)
    """
    try:
        from db.diagnosis_db import get_quote, get_connection
        from writing.article_generator_service import ArticleGeneratorService

        async with _bill_feature_ctx(http_request, "article_rewrite"):
            conn = get_connection()
            try:
                c = conn.cursor()

                # 获取topic关联的quote_id
                c.execute('''
                    SELECT k.quote_id, q.brand_name, q.industry
                    FROM topics t
                    JOIN confirmed_keywords k ON t.keyword_id = k.id
                    JOIN quotes q ON k.quote_id = q.id
                    WHERE t.id = %s
                ''', (topic_id,))
                row = c.fetchone()
                conn.close()

                if not row:
                    raise HTTPException(status_code=404, detail="标题不存在")

                # [GEO-R1-CAN-143 P1] 跨租户重写防护:校验调用者对该 quote 的归属,
                # 镜像批量重写路径 _get_batch_rewrite_context 的 require_quote_access。
                if http_request is not None:
                    from auth.brand_access import require_quote_access
                    require_quote_access(http_request, row['quote_id'])

                service = ArticleGeneratorService(
                    quote_id=row['quote_id'],
                    brand_name=row['brand_name'],
                    industry=row['industry']
                )

                article = await service.rewrite_article(
                    topic_id=topic_id,
                    reference_article=request.reference_article,
                    revision_note=request.revision_note,
                    preserve_title=request.advisory_repair,
                    advisory_repair=request.advisory_repair,
                )

                # [audit P2 2026-06-10] rewrite_article 失败 return {'error':...} 不 raise →
                # _bill_feature_ctx(完成才扣)语义被绕过,LLM 失败照扣 260。显式判 error raise 触发不扣。
                if isinstance(article, dict) and article.get('error'):
                    # 重写失败,本次未收费：raise 退出完成后扣费上下文。
                    failure = article.get("failure") or {}
                    raise HTTPException(
                        status_code=502,
                        detail={
                            "code": failure.get("code") or "ARTICLE_REWRITE_FAILED",
                            "message": failure.get("message") or "重写未完成，原稿已保留，本次未收费。",
                        },
                    )

                return {
                    "success": True,
                    "article": article
                }
            finally:
                try:
                    conn.close()
                except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("重写文章失败")
        from writing.article_generation_failure import classify_article_generation_failure
        failure = classify_article_generation_failure(e)
        raise HTTPException(status_code=500, detail=failure.public_dict())


def _batch_rewrite_current_user(http_request: Request = None) -> dict:
    if not http_request:
        return {}
    user = getattr(http_request.state, "user", None)
    return user or {}


def _batch_rewrite_actor_key(http_request: Request = None) -> str:
    user = _batch_rewrite_current_user(http_request)
    if user.get("is_admin"):
        return f"admin:{user.get('user_id') or user.get('id') or 'unknown'}"
    if user.get("user_id") or user.get("id"):
        return f"user:{user.get('user_id') or user.get('id')}"
    return "anonymous"


def _batch_rewrite_bill_user_id(http_request: Request = None):
    user = _batch_rewrite_current_user(http_request)
    if user and not user.get("is_admin"):
        return user.get("user_id") or user.get("id")
    return None


def _get_batch_rewrite_context(topic_ids: List[int], http_request: Request = None) -> dict:
    """Load and validate topic/quote context before queueing a rewrite job."""
    from db.diagnosis_db import get_connection

    unique_topic_ids = sorted({int(tid) for tid in topic_ids})
    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute(
            """
            SELECT
                t.id AS topic_id,
                k.quote_id,
                q.brand_name,
                q.industry
            FROM topics t
            JOIN confirmed_keywords k ON t.keyword_id = k.id
            JOIN quotes q ON k.quote_id = q.id
            WHERE t.id = ANY(%s)
            """,
            (unique_topic_ids,),
        )
        rows = c.fetchall()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    if len(rows) != len(unique_topic_ids):
        raise HTTPException(status_code=404, detail="部分标题不存在，无法批量重写")

    quote_ids = {int(row["quote_id"]) for row in rows if row.get("quote_id") is not None}
    if len(quote_ids) != 1:
        raise HTTPException(status_code=400, detail="批量重写只能选择同一个报价下的文章")

    quote_id = next(iter(quote_ids))
    if http_request:
        from auth.brand_access import require_quote_access

        require_quote_access(http_request, quote_id)

    first = rows[0]
    return {
        "quote_id": quote_id,
        "brand_name": first.get("brand_name") or "",
        "industry": first.get("industry") or "",
        "topic_ids": unique_topic_ids,
    }


async def _run_batch_rewrite_job(batch_ref: str, context: dict, bill_user_id=None) -> None:
    """Background worker: rewrite first, then charge by actual successful count."""
    if _BATCH_REWRITE_JOBS is None:
        logger.error("批量重写后台任务无法启动: 幂等存储不可用")
        return

    job = _BATCH_REWRITE_JOBS.get(batch_ref)
    if not job:
        return

    try:
        from writing.article_generator_service import ArticleGeneratorService

        _BATCH_REWRITE_JOBS.mark_running(batch_ref)
        service = ArticleGeneratorService(
            quote_id=context["quote_id"],
            brand_name=context.get("brand_name", ""),
            industry=context.get("industry", ""),
        )

        logger.info(
            f"📝 批量重写后台开始: batch_ref={batch_ref} quote={context['quote_id']} topics={len(job.topic_ids)}"
        )
        results = await service.batch_rewrite_articles(job.topic_ids)
        success_count = int(results.get("success") or 0)
        failed_count = int(results.get("failed") or 0)
        from writing.article_rewrite_jobs import (
            batch_rewrite_failure_message,
            public_batch_rewrite_errors,
        )

        public_errors = public_batch_rewrite_errors(results.get("errors", []))
        logger.info(
            f"✅ 批量重写后台完成: batch_ref={batch_ref} success={success_count} failed={failed_count}"
        )

        if success_count <= 0:
            failure_message = batch_rewrite_failure_message(results.get("errors", []))
            logger.warning(
                "批量重写未产生成稿: batch_ref=%s reasons=%s",
                batch_ref,
                [item.get("reason") for item in public_errors],
            )
            _BATCH_REWRITE_JOBS.mark_failed(
                batch_ref,
                error=failure_message,
                message=failure_message,
                result={
                    "success": 0,
                    "failed": failed_count,
                    "errors": public_errors,
                },
            )
            return

        charged_points = 0
        if bill_user_id:
            try:
                from middleware.billing import check_balance_only, deduct_points
                from db.wallet_db import get_feature_pricing

                from services.fallback_observability import priced as _fb_priced
                pricing = get_feature_pricing("article_rewrite")
                # [WO_240] 260 是目录值的副本(种子 article_rewrite = 260,当前一致)。
                # 🔴 `(pricing or {})` 原样保留:取价返 None 时这里**静默取默认**,
                #    而 api_generate_titles 那条同样情形是 **AttributeError 当场炸**。
                #    两条资金路径对同一种异常给出相反处置 —— 这个不对称本身是缺陷,
                #    但"哪种才是本意"读不出来,属资金语义,**不在本单自行统一**,已报 Review。
                base = int(_fb_priced((pricing or {}), "cost_points", 260,
                                      feature="article_rewrite",
                                      where="server.py:_run_batch_rewrite_job"))
                extra = max(0, success_count - 1) * base
                await check_balance_only(bill_user_id, "article_rewrite", extra_cost=extra)
                await deduct_points(bill_user_id, "article_rewrite", extra_cost=extra)
                charged_points = base + extra
                logger.info(
                    f"💰 批量重写成功后扣费: batch_ref={batch_ref} user={bill_user_id} count={success_count} points={charged_points}"
                )
            except Exception as bill_err:
                logger.error(f"❌ 批量重写成功但扣费异常: batch_ref={batch_ref} error={bill_err}")
                results["billing_error"] = str(bill_err)[:200]

        _BATCH_REWRITE_JOBS.mark_completed(
            batch_ref,
            result={
                "async": True,
                "rewritten": success_count,
                "success": success_count,
                "failed": failed_count,
                "errors": public_errors,
                **({"billing_error": results.get("billing_error")} if results.get("billing_error") else {}),
            },
            charged_count=success_count if charged_points else 0,
            charged_points=charged_points,
        )
    except Exception as e:
        logger.error(f"批量重写后台失败: batch_ref={batch_ref} error={e}")
        safe_message = "批量重写服务暂时异常，原稿已保留，本次未收费"
        _BATCH_REWRITE_JOBS.mark_failed(
            batch_ref,
            error=safe_message,
            message=safe_message,
        )


@app.get("/api/writing/batch-rewrite/{batch_ref}")
async def api_get_batch_rewrite_status(batch_ref: str, http_request: Request = None):
    """查询批量重写后台进度。"""
    if _BATCH_REWRITE_JOBS is None:
        raise HTTPException(status_code=503, detail="批量重写服务暂不可用")

    job = _BATCH_REWRITE_JOBS.get(batch_ref)
    if not job:
        raise HTTPException(status_code=404, detail="批量重写任务不存在或已过期")

    user = _batch_rewrite_current_user(http_request)
    if not user.get("is_admin") and _batch_rewrite_actor_key(http_request) != job.actor_key:
        raise HTTPException(status_code=403, detail="无权查看该批量重写任务")

    return job.to_public_dict()


@app.post("/api/writing/batch-rewrite")
async def api_batch_rewrite_articles(request: BatchRewriteRequest, http_request: Request = None):
    """提交批量重写任务,立即返回 batch_ref,后台完成后按真实成功篇数扣费."""
    if _BATCH_REWRITE_JOBS is None:
        raise HTTPException(status_code=503, detail="批量重写服务暂不可用")
    if not request.topic_ids:
        raise HTTPException(status_code=400, detail="topic_ids不能为空")

    context = _get_batch_rewrite_context(request.topic_ids, http_request)
    actor_key = _batch_rewrite_actor_key(http_request)
    bill_user_id = _batch_rewrite_bill_user_id(http_request)
    job, created = _BATCH_REWRITE_JOBS.get_or_create(
        actor_key=actor_key,
        quote_id=context["quote_id"],
        topic_ids=context["topic_ids"],
        payload_fingerprint="batch_rewrite_v1",
    )

    if not created:
        logger.info(
            f"🔁 批量重写幂等命中: batch_ref={job.batch_ref} status={job.status} quote={context['quote_id']}"
        )
        data = job.to_public_dict()
        data["idempotent_hit"] = True
        data["message"] = "这批文章已提交，正在后台重写或已完成，请勿重复点击"
        return data

    try:
        if bill_user_id:
            from middleware.billing import check_balance_only
            from db.wallet_db import get_feature_pricing

            from services.fallback_observability import priced as _fb_priced
            pricing = get_feature_pricing("article_rewrite")
            # [WO_240] 同 _run_batch_rewrite_job:260 是目录副本,`(pricing or {})` 原样保留。
            base = int(_fb_priced((pricing or {}), "cost_points", 260,
                                  feature="article_rewrite",
                                  where="server.py:api_batch_rewrite_articles"))
            extra = max(0, len(context["topic_ids"]) - 1) * base
            # 只做余额预检,不在长同步请求里提前扣费;后台按真实成功篇数扣.
            await check_balance_only(bill_user_id, "article_rewrite", extra_cost=extra)
    except Exception:
        _BATCH_REWRITE_JOBS.remove(job.batch_ref)
        raise

    asyncio.create_task(_run_batch_rewrite_job(job.batch_ref, context, bill_user_id))
    data = job.to_public_dict()
    data.update(
        {
            "accepted": True,
            "async": True,
            "idempotent_hit": False,
            "message": "已提交，后台正在重写；可以稍后刷新查看结果",
        }
    )
    return data


@app.post("/api/writing/reset-to-pending")
def api_reset_to_pending(request: ResetToPendingRequest, http_request: Request):
    """Retire title/body and start a revision-preserving full regeneration.

    ResetToPendingRequest 在 HTTP 边界执行单次批量上限 500。
    """
    try:
        from db.diagnosis_db import get_connection
        from auth.brand_access import require_quote_access
        request_id = _article_generation_request_id(http_request)
        _conn = get_connection()
        try:
            _cur = _conn.cursor()
            _cur.execute("SELECT DISTINCT quote_id FROM topics WHERE id = ANY(%s)", (list(request.topic_ids),))
            _qids = [r["quote_id"] for r in _cur.fetchall()]
        finally:
            try:
                _conn.close()
            except Exception:
                pass
        if len(_qids) != 1 or not _qids[0]:
            raise HTTPException(
                status_code=400,
                detail={"code": "ARTICLE_RESET_SCOPE_MISMATCH", "message": "只能重置同一项目内的文章。"},
            )
        _user = getattr(http_request.state, "user", None) or {}
        _is_admin = bool(_user.get("is_admin"))
        for _qid in _qids:
            if _qid:
                require_quote_access(http_request, _qid)
            elif not _is_admin:
                raise HTTPException(status_code=403, detail="含归属不明选题 · 仅管理员可批量回退")

        conn = get_connection()
        try:
            c = conn.cursor()
            from services.article_generation_reset import reset_topics_for_full_regeneration
            result = reset_topics_for_full_regeneration(
                c,
                quote_id=int(_qids[0]),
                topic_ids=list(request.topic_ids),
                actor_user_id=_user.get("user_id") or _user.get("id"),
                request_id=request_id,
            )
            # Idempotent replays and already-pending topics must be true no-ops.
            # Rewriting the quote here could roll a completed project back to
            # pending long after the original reset had already been handled.
            if result["reset_topic_ids"]:
                c.execute("UPDATE quotes SET writing_status='pending' WHERE id=%s", (int(_qids[0]),))
            conn.commit()
            reset_count = len(result["reset_topic_ids"])
            logger.info(
                "[ArticleFullReset] quote=%s reset=%s replayed=%s published=%s request=%s",
                _qids[0], reset_count, len(result["replayed_topic_ids"]),
                len(result["published_topic_ids"]), request_id,
            )
            return {
                "success": True,
                "request_id": request_id,
                "reset_count": reset_count,
                "idempotent_replay_count": len(result["replayed_topic_ids"]),
                "already_pending_count": len(result["already_pending_topic_ids"]),
                "published_revision_count": len(result["published_topic_ids"]),
                "total": len(request.topic_ids),
                "requires_title_generation": True,
                "message": "旧标题和正文已归档为历史修订；请重新生成标题，再生成完整正文。",
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        from services.article_generation_reset import ArticleResetConflict
        if isinstance(e, ArticleResetConflict):
            raise HTTPException(
                status_code=409,
                detail={"code": e.code, "message": e.message},
            )
        logger.exception("重置为待写失败")
        raise HTTPException(
            status_code=500,
            detail={"code": "ARTICLE_RESET_FAILED", "message": "文章暂时无法重置，请刷新后重试。"},
        )


def _require_article_access(request: Request, article_id: int):
    """[P0-8 fix 2026-05-23 老板授权] 反查 article → topic → quote → owner"""
    from auth.brand_access import require_quote_access
    from db.diagnosis_db import get_connection
    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute("""
            SELECT t.quote_id FROM articles a
            LEFT JOIN topics t ON a.topic_id = t.id
            WHERE a.id = %s
        """, (article_id,))
        row = c.fetchone()
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        raise HTTPException(status_code=404, detail="文章不存在")
    quote_id = row.get("quote_id")
    if not quote_id:
        # 无 quote 归属的旧数据 · 只 admin 可访问
        user = getattr(request.state, "user", None)
        if not user or not user.get("is_admin"):
            raise HTTPException(status_code=403, detail="文章归属不明 · 仅管理员可访问")
        return
    require_quote_access(request, quote_id)
    from auth.brand_access import _require_organization_artifact
    _require_organization_artifact(request, "article", article_id)


@app.get("/api/articles/{article_id}")
def api_get_article(article_id: int, request: Request):
    """获取文章详情
    [P0-8 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 反查 quote owner"""
    try:
        _require_article_access(request, article_id)
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute('SELECT * FROM articles WHERE id=%s', (article_id,))
            row = c.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="文章不存在")
            article = dict(row)
            from writing.article_length_contract import build_length_guidance_projection

            article["length_guidance"] = build_length_guidance_projection(
                article.get("generation_request_snapshot"),
                article.get("content"),
            )
            # [工单 C-2 T1 2026-07-27] 交付副本:content 是编辑 SSOT(存占位符原文),
            # 但下载/导出面直接拿 content 打包会把 [CLIENT_IMAGE]/[NEED_IMAGE] 裸露给
            # 客户(生产 8/10 深档实证)。content_export = 发布口径渲染(绝对公网 URL,
            # 逐图校验归属),渲染失败剥离,任何情况下零占位符裸露。
            try:
                from services.image_placeholder import render_for_publish_fail_closed
                _export_bid = None
                if article.get("quote_id"):
                    c.execute("SELECT brand_id FROM quotes WHERE id=%s", (article["quote_id"],))
                    _bid_row = c.fetchone()
                    _export_bid = _bid_row.get("brand_id") if _bid_row else None
                article["content_export"] = render_for_publish_fail_closed(
                    article.get("content") or "", _export_bid,
                )
            except Exception as _export_err:
                from services.image_placeholder import strip_client_images
                logger.warning(f"文章交付副本渲染失败,fail-closed 剥离: {_export_err}")
                article["content_export"] = strip_client_images(article.get("content") or "")
            return {"success": True, "article": article}
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取文章失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/articles/{article_id}/advisory")
def api_get_article_advisory(article_id: int, request: Request):
    """[WO_MEDIA_BOARD_UX_CLOSURE §2] 一篇文章的「N 条提示」明细(只读)。

    存在的理由:发布中心那颗 `{n} 条提示 · 可发布` 徽章**全站没有任何明细入口**
    —— 代理看到"3 条提示"却点不开、不知道是哪 3 条、也没法处理。铁律
    (`feedback_hint_must_help_or_hide`):提示要么帮人解决问题,要么不显示。

    🔴 三处刻意复用而非另写(不写第二份口径):
      1. 鉴权走 `_require_article_access` —— 与 repair-finding / 文章详情同一道边界;
      2. 计数走 `services.article_review_gate._advisory_state` —— 与列表里那颗徽章
         **同一个函数**。前端显示 N 条、点开看到 M 条这种事从源头上不可能发生;
      3. 明细走 `services.article_findings_aggregate.aggregate_article_findings`
         —— 与写作大厅的提示面板同一份聚合(含 `ai_repairable` 标注)。

    🔴 语义红线(工单点名):本端点只说「提示」,任何字段都不许把它包装成
       「审核通过」。`advisory_state` 原样透出,判定一字不改。

    `topic_id` 反查是给「忽略(留痕)」用的:落库口径在 topics 层
    (`/api/articles/batch-advisory-continue` → `api_mark_topic_reviewed`),
    前端拿不到 topic_id 就只能另造一套忽略 = 第二份口径。查不到 → null,
    前端据此**不渲染**忽略按钮(不给点了没反应的按钮)。
    """
    _require_article_access(request, article_id)
    from db.diagnosis_db import get_connection
    from services.article_findings_aggregate import aggregate_article_findings
    from services.article_review_gate import _advisory_state

    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute(
            "SELECT a.id, a.title, a.quality_warning, q.industry "
            "  FROM articles a LEFT JOIN quotes q ON q.id = a.quote_id "
            " WHERE a.id = %s",
            (article_id,),
        )
        row = c.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="文章不存在")
        c.execute("SELECT id FROM topics WHERE article_id = %s ORDER BY id LIMIT 1", (article_id,))
        topic_row = c.fetchone()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    industry = str(row.get("industry") or "")
    title = str(row.get("title") or "")
    quality_warning = row.get("quality_warning")
    advisory_state, advisory_open_count = _advisory_state(quality_warning)

    try:
        cards = aggregate_article_findings(quality_warning, industry=industry, title=title)
    except Exception as exc:
        # fail-soft:聚合炸了也要把计数与状态给出去(徽章不该因为明细挂了而说谎)。
        logger.warning(f"[advisory] 文章 {article_id} findings 聚合失败: {exc}")
        cards = []

    # 高风险(医疗/法律/金融)整篇不给 AI 修复出口 —— 与 repair-finding 端点
    # **同一个判定函数**,前端据此不渲染按钮(两层同源,不是两份口径)。
    try:
        from services.span_level_repair import article_ai_repair_blocked

        ai_repair_blocked = bool(article_ai_repair_blocked(industry, title))
    except Exception:
        ai_repair_blocked = True  # fail-closed:判不出来就不给 AI 修复按钮

    return {
        "success": True,
        "article_id": article_id,
        "topic_id": (topic_row.get("id") if topic_row else None),
        "title": title,
        "advisory_state": advisory_state,
        "advisory_open_count": advisory_open_count,
        "cards": cards,
        "ai_repair_blocked": ai_repair_blocked,
    }


class ArticleFindingRepairRequest(BaseModel):
    """[WP9-P0-7 ② · D8] 只修一处 finding 所在段。"""
    finding_code: str = Field(..., min_length=1, max_length=80)
    matched_text: str = Field(..., min_length=1, max_length=400)


@app.post("/api/articles/{article_id}/repair-finding")
async def api_repair_article_finding(
    article_id: int, payload: ArticleFindingRepairRequest, request: Request
):
    """[WP9-P0-7 ② · D8]「AI 仅修复此 finding 所在段」。

    D8 放行权归用户:findings 只是定位标注,用户可选修或忽略。本动作**只重写命中所在的
    那一段**,不重跑整篇、**不产生第二次全文费用**(修复已付费内容的局部瑕疵,不另计费);
    修完自验仍违规则原文一字不动并诚实回报(§13 合同带重试/手改/忽略出口)。
    """
    _require_article_access(request, article_id)
    from db.diagnosis_db import get_connection
    from services.governance_alerts import (
        cannot_fix_without_fabrication_alert,
        high_risk_no_ai_repair_alert,
        span_repair_failed_alert,
        span_repair_quota_exhausted_alert,
        span_repair_service_unavailable_alert,
    )
    from services.span_level_repair import (
        FREE_REPAIRS_PER_FINDING,
        INFRA_FAILURE_REASONS,
        article_ai_repair_blocked,
        finding_fingerprint,
        free_repairs_used,
        quota_should_refund,
        release_free_repair,
        reserve_free_repair,
        span_ai_repair_blocked,
    )
    from services.writing_span_repair import repair_finding_span

    conn = get_connection()
    try:
        c = conn.cursor()
        # [工单 C-3 T3] 连 evidence_pack / brand_fact_snapshot 一起取:精度族 finding
        # 的段级自验需要 pack 上下文(_still_violates 走 precision 评估器)。
        # [span 级 AI 免费修复 2026-07-30] 再加 title/quality_warning + quote 的
        # industry/brand_name:高风险排除(§2.1)、免费额度(§6)、品牌全称保护
        # (§3.1 硬性要求 3)都要它们。
        c.execute(
            "SELECT a.content, a.evidence_pack, a.brand_fact_snapshot, a.title, "
            "       a.quality_warning, q.industry, q.brand_name "
            "  FROM articles a LEFT JOIN quotes q ON q.id = a.quote_id "
            " WHERE a.id=%s",
            (article_id,),
        )
        row = c.fetchone()
        if not row:
            # [返修 P2-4] 404 也走 §13 合同,不裸串(用户面永远有下一步)
            from services.governance_contract import build_alert_safe
            raise HTTPException(status_code=404, detail=build_alert_safe(
                "ARTICLE_NOT_FOUND", "找不到这篇文章,可能已被删除。",
                reason="按这个文章编号没有查到内容。",
                impact="本次没有做任何修改。",
                repair_hint="回到文章列表重新选择,或刷新后再试。",
                actions=[{"id": "back_to_list", "label": "回到文章列表", "type": "nav"},
                         {"id": "refresh", "label": "刷新重试", "type": "retry"}],
                rule_version="article-finding-v1",
            ))
        original = row["content"] or ""
        _repair_evidence_pack = row.get("evidence_pack") if isinstance(row.get("evidence_pack"), dict) else None
        _repair_brand_snapshot = row.get("brand_fact_snapshot") if isinstance(row.get("brand_fact_snapshot"), dict) else None
        _repair_industry = str(row.get("industry") or "")
        _repair_title = str(row.get("title") or "")
        _repair_brand = str(row.get("brand_name") or "")
    finally:
        try:
            conn.close()
        except Exception:
            pass

    # [§2.1 / 锁 6] 医疗/法律/金融高风险:**不调模型、不给"再试一次"**,
    # 只有"提交人工签发"与"自己手动改"。它缺的是人工签发,不是措辞;
    # 让 AI 软化措辞会让判定转绿而风险一点没减。前端也不渲染按钮(两层同源)。
    if article_ai_repair_blocked(_repair_industry, _repair_title):
        return {"success": False, **high_risk_no_ai_repair_alert("high_risk_article")}
    if span_ai_repair_blocked(payload.matched_text):
        return {"success": False, **high_risk_no_ai_repair_alert("high_risk_span")}

    # [§6 / 锁 7] 免费额度:同一条 finding 首修 + 1 次重试。第 3 次直接拒,
    # **零计费**(本端点全程不碰任何扣费函数:修复已付费内容的局部瑕疵不另计费)。
    # 占位刻意在调用模型**之前**,并在同一事务里 FOR UPDATE 串行化 —— 否则连点
    # 两下会各读到 used=1 各自放行,额度成了摆设。
    from datetime import datetime as _dt, timezone as _tz

    _fingerprint = finding_fingerprint(payload.finding_code, payload.matched_text)
    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute("SELECT quality_warning FROM articles WHERE id=%s FOR UPDATE", (article_id,))
        _qw_row = c.fetchone() or {}
        _qw_now = _qw_row.get("quality_warning") if isinstance(_qw_row.get("quality_warning"), dict) else {}
        _quota = reserve_free_repair(
            _qw_now, _fingerprint,
            code=payload.finding_code,
            at=_dt.now(_tz.utc).isoformat(),
        )
        if _quota is None:
            conn.rollback()
            return {
                "success": False,
                **span_repair_quota_exhausted_alert(
                    payload.finding_code,
                    free_repairs_used(_qw_now, _fingerprint),
                    FREE_REPAIRS_PER_FINDING,
                ),
            }
        c.execute(
            "UPDATE articles SET quality_warning = COALESCE(quality_warning,'{}'::jsonb) || %s::jsonb "
            "WHERE id=%s",
            (json.dumps({"span_repair_quota": _quota}, ensure_ascii=False), article_id),
        )
        conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    async def _llm(prompt: str) -> str:
        from tools.multi_llm_caller import MultiLLMCaller
        text, _provider = await MultiLLMCaller(timeout=90.0, temperature=0.3).call(prompt, verbose=False)
        return text

    result = await repair_finding_span(
        original,
        {
            "code": payload.finding_code,
            "matched_text": payload.matched_text,
            "message": "该处表述需要改为有依据的相对表述。",
            "evidence_pack": _repair_evidence_pack,
            "brand_fact_snapshot": _repair_brand_snapshot,
        },
        _llm,
        industry=_repair_industry,
        title=_repair_title,
        # 品牌全称不许被顺手删掉(机械校验,不靠提示词自觉)。
        preserve_terms=(_repair_brand,) if _repair_brand else (),
        # [R5.1] 主体核对:修本文品牌的 span,不得用竞品/别家条目作来源。
        target_entity=_repair_brand,
    )
    if not result.get("ok"):
        # 诚实失败:正文未改,给重试/手改/忽略出口(不是阻断)。
        _reason = str(result.get("reason") or "")
        # [误报治理 2026-07-30 · T2] 额度退还:平台自身故障(超时/5xx/连接失败)
        # 或**压根没调过模型**时,不该扣用户的免费次数。
        # 🔴 占位仍在调用模型之前(上面那段 FOR UPDATE),这里只是事后显式退还 ——
        # 绝不能为了"失败不计次"把占位挪到调用之后(那会重开连点两下绕过的洞)。
        _used_after = _quota.get(_fingerprint, {}).get("used") or 0
        if quota_should_refund(_reason, bool(result.get("llm_invoked"))):
            conn = get_connection()
            try:
                c = conn.cursor()
                c.execute("SELECT quality_warning FROM articles WHERE id=%s FOR UPDATE", (article_id,))
                _rf_row = c.fetchone() or {}
                _rf_qw = _rf_row.get("quality_warning") if isinstance(_rf_row.get("quality_warning"), dict) else {}
                _refunded = release_free_repair(_rf_qw, _fingerprint)
                if _refunded is not None:
                    c.execute(
                        "UPDATE articles SET quality_warning = COALESCE(quality_warning,'{}'::jsonb) || %s::jsonb "
                        "WHERE id=%s",
                        (json.dumps({"span_repair_quota": _refunded}, ensure_ascii=False), article_id),
                    )
                    _used_after = _refunded.get(_fingerprint, {}).get("used") or 0
                conn.commit()
            except Exception as _refund_err:
                logger.warning(f"[repair-finding] 额度退还失败(不影响本次结果): {_refund_err}")
            finally:
                try:
                    conn.close()
                except Exception:
                    pass

        _left = max(0, FREE_REPAIRS_PER_FINDING - _used_after)
        if _reason in ("high_risk_article", "high_risk_span"):
            return {"success": False, "free_repairs_left": _left,
                    **high_risk_no_ai_repair_alert(_reason)}
        if _reason == "cannot_fix_without_fabrication":
            # 🔴 模型的诚实出口(§7 锁 5):**正文零改动**,直接转人工。
            # 刻意不给"再试一次" —— 它已经声明"不编造就修不好",再抽一次
            # 只会逼它补一个新编造,那比不修更糟。
            return {"success": False, "free_repairs_left": _left,
                    **cannot_fix_without_fabrication_alert()}
        if _reason in INFRA_FAILURE_REASONS:
            # 我们的故障,不是用户的问题:文案与"修复失败"分开,且不计次。
            return {"success": False, "free_repairs_left": _left,
                    **span_repair_service_unavailable_alert()}
        return {
            "success": False,
            "free_repairs_left": _left,
            **span_repair_failed_alert(_reason),
        }

    new_content = result["content"]
    # 重新评估:修好后清掉 needs_legal_fix,让发布门放行(修完即放行)。
    # [工单 C-3 T3] 同步重算 soft(evidence)与精度(evidence_precision)两路:
    # 类型卡"一键修复本类"修的正是 advisory findings —— 不重算它们,前端刷新后
    # 计数不掉,用户会以为修复无效。
    try:
        from writing.evidence_first_policy import evaluate_content_trust
        _trust = evaluate_content_trust("", new_content, evidence_mode="unknown")
        _qw_patch = {
            "evidence_legal": _trust.warning_payload(),
            "evidence": _trust.warning_payload(),
            "needs_legal_fix": bool(_trust.hard),
        }
        try:
            from writing.evidence_precision_policy import evaluate_evidence_precision
            _qw_patch["evidence_precision"] = evaluate_evidence_precision(
                new_content, _repair_evidence_pack or {}, _repair_brand_snapshot,
            ).payload()
        except Exception:
            pass
    except Exception:
        _qw_patch = {}

    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute(
            "UPDATE articles SET content=%s, quality_warning = COALESCE(quality_warning,'{}'::jsonb) || %s::jsonb "
            "WHERE id=%s",
            (new_content, json.dumps(_qw_patch, ensure_ascii=False), article_id),
        )
        # [工单 C-4 · B3] 修完必须刷新机审结论:旧代码只改 content+quality_warning,
        # article_review_status 仍是修复前的 blocked → "修好了发布门还拦"。
        # refresh_article_review 重跑 lineage(会清人工签发四字段,与编辑路由同口径)。
        try:
            from services.article_review_gate import refresh_article_review
            refresh_article_review(article_id, cursor=c)
        except Exception as _refresh_err:
            logger.warning(f"[repair-finding] 机审刷新失败(修复已落盘): {_refresh_err}")
        conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return {
        "success": True,
        "article_id": article_id,
        "repaired": True,
        "needs_legal_fix": bool(_qw_patch.get("needs_legal_fix")),
        "paragraph_before": result.get("paragraph_before"),
        "paragraph_after": result.get("paragraph_after"),
        # [span 级 2026-07-30] span 级路径额外回 span 前后 + 剩余免费次数(0 扣费)。
        "span_level": bool(result.get("category")),
        "span_before": result.get("span_before"),
        "span_after": result.get("span_after"),
        "free_repairs_left": max(
            0, FREE_REPAIRS_PER_FINDING - (_quota.get(_fingerprint, {}).get("used") or 0),
        ),
        "charged": False,
    }


@app.post("/api/articles/{article_id}/auto-repair")
async def api_auto_repair_article(article_id: int, request: Request):
    """[工单 C-4] 一键修复本篇剩余 hard findings(汇总卡入口)。

    - 一次调用 = 1 轮(对当前全部可定位 hard 各修一次);
    - **累计轮数上限 MAX_ONE_CLICK_ROUNDS(=2),服务端硬闸**(防修复循环烧钱),
      记在 quality_warning.auto_repair.manual_rounds;
    - 成本平台侧(段级小 prompt,与写作续写重试同口径),用户 0 扣费;
    - 修完刷新机审:全修好 → article_review_status 变 approved,发布门放行;
      仍有残留 → 保持 blocked,发布门照拦(红线不放松)。
    """
    _require_article_access(request, article_id)
    from db.diagnosis_db import get_connection
    from services.article_review_autopilot import (
        autopilot_repair_hard,
        merge_auto_repair_state,
        one_click_rounds_left,
    )
    from services.governance_contract import build_alert_safe

    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute(
            "SELECT a.title, a.content, a.evidence_pack, a.brand_fact_snapshot, "
            "       a.quality_warning, q.industry, b.name AS brand_name "
            "  FROM articles a LEFT JOIN quotes q ON q.id = a.quote_id "
            "  LEFT JOIN brands b ON b.id = q.brand_id "
            " WHERE a.id=%s",
            (article_id,),
        )
        row = c.fetchone()
    finally:
        try:
            conn.close()
        except Exception:
            pass
    if not row:
        raise HTTPException(status_code=404, detail="文章不存在")

    # [span 级 AI 免费修复 2026-07-30 · §2.1 / 锁 6] 医疗/法律/金融高风险文章:
    # 批量 AI 修复同样不给(与逐处 repair-finding、前端按钮同一个判定函数)。
    # 该类缺的是人工签发 —— 而它本来就永远拿不到 machine approved
    # (geo_article_expert: high_risk → pending_human_review),所以"必须人过一遍"
    # 这条不会因为不修而丢失,反倒是"让 AI 把措辞改软"才会把风险洗白。
    from services.governance_alerts import high_risk_no_ai_repair_alert
    from services.span_level_repair import article_ai_repair_blocked

    if article_ai_repair_blocked(str(row.get("industry") or ""), str(row.get("title") or "")):
        return {"success": False, **high_risk_no_ai_repair_alert("high_risk_article")}

    _qw = row.get("quality_warning") if isinstance(row.get("quality_warning"), dict) else {}
    rounds_left = one_click_rounds_left(_qw)
    if rounds_left <= 0:
        # 轮数用尽:诚实拒绝,导去详情逐处手改(不是静默烧第 3 轮)。
        return {
            "success": False,
            "rounds_left": 0,
            **build_alert_safe(
                "AUTO_REPAIR_ROUNDS_EXHAUSTED",
                "自动修复次数已用完,剩余问题需要手动处理。",
                reason="本篇一键修复已用满 2 轮,继续自动重试大概率还是修不好。",
                impact="正文未改动;已修好的部分都已保存。",
                repair_hint="打开详情逐处查看,手动修改或忽略。",
                actions=[{"id": "view_findings", "label": "查看详情", "type": "nav"},
                         {"id": "edit_manually", "label": "手动修改", "type": "nav"}],
                rule_version="review-autopilot-v1",
            ),
        }

    outcome = await autopilot_repair_hard(
        str(row.get("title") or ""),
        str(row.get("content") or ""),
        evidence_mode="unknown",
        evidence_pack=row.get("evidence_pack") if isinstance(row.get("evidence_pack"), dict) else None,
        brand_fact_snapshot=row.get("brand_fact_snapshot") if isinstance(row.get("brand_fact_snapshot"), dict) else None,
        max_rounds=1,
        # [R5.1] 主体核对:修本文品牌的 span 不得用竞品/别家条目作来源。
        target_entity=str(row.get("brand_name") or ""),
    )
    new_qw = merge_auto_repair_state(_qw, outcome, trigger="one_click")

    # 与 repair-finding 同口径重算三路 findings + 刷新机审结论。
    try:
        from writing.evidence_first_policy import evaluate_content_trust
        _trust = evaluate_content_trust("", outcome["content"], evidence_mode="unknown")
        new_qw["evidence_legal"] = _trust.warning_payload()
        new_qw["evidence"] = _trust.warning_payload()
        new_qw["needs_legal_fix"] = bool(_trust.hard)
        try:
            from writing.evidence_precision_policy import evaluate_evidence_precision
            new_qw["evidence_precision"] = evaluate_evidence_precision(
                outcome["content"],
                row.get("evidence_pack") if isinstance(row.get("evidence_pack"), dict) else {},
                row.get("brand_fact_snapshot") if isinstance(row.get("brand_fact_snapshot"), dict) else None,
                title=str(row.get("title") or ""),
            ).payload()
        except Exception:
            pass
    except Exception:
        pass

    conn = get_connection()
    try:
        c = conn.cursor()
        c.execute(
            "UPDATE articles SET content=%s, quality_warning=%s::jsonb WHERE id=%s",
            (outcome["content"], json.dumps(new_qw, ensure_ascii=False, default=str), article_id),
        )
        try:
            from services.article_review_gate import refresh_article_review
            _review = refresh_article_review(article_id, cursor=c)
        except Exception as _refresh_err:
            logger.warning(f"[auto-repair] 机审刷新失败(修复已落盘): {_refresh_err}")
            _review = {}
        conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return {
        "success": True,
        "article_id": article_id,
        "rounds_used": outcome["rounds_used"],
        "rounds_left": one_click_rounds_left(new_qw),
        "repaired_count": len(outcome["repaired"]),
        "remaining": outcome["remaining"],
        "article_review_status": (_review or {}).get("article_review_status"),
    }


# ===========================================================================
# [P3a 批量审核 2026-08-01 · 工单 §6] 同步批量端点
# ===========================================================================
# 为什么是同步而不是 SSE:实测 refresh_article_review → build_article_lineage →
# review_article 全链**没有一个 await、没有一次 provider 调用**(纯规则评估),
# 一篇是毫秒级。把它做成长任务 + SSE 是给自己加一套没用的状态机。
# 真正需要 SSE 的是「一键修复全部系统问题」(span 级修复要调 LLM),那条走 P3b。
#
# 🔴 零扣费:这两个端点与它们调到的服务层都不含任何计费调用(锁 4 用 AST 钉住,
#    并枚举前端面板全部 authFetch URL 必须落在零扣费白名单里)。

class BatchArticleReviewRequest(BaseModel):
    article_ids: List[int] = Field(default_factory=list)


class BatchAdvisoryContinueRequest(BaseModel):
    topic_ids: List[int] = Field(default_factory=list)


@app.post("/api/articles/batch-review")
def api_batch_review_articles(payload: BatchArticleReviewRequest, request: Request):
    """批量跑 GEO 机审并重评发布资格(审核选中 / 当前分组 / 全部已完成 共用这一个)。

    逐项隔离:每一项自带连接与事务、异常在循环里被吃掉 —— 第 7 篇炸了不会回滚
    前 6 篇已 commit 的结果,也不会让整批 500。
    """
    from services.article_batch_review import run_batch, review_one_article

    return {
        "success": True,
        **run_batch(
            payload.article_ids,
            review_one_article,
            # 鉴权也走逐项:混进一篇越权的文章 → 那一篇 403,其余照常。
            access_check=lambda aid: _require_article_access(request, aid),
            id_field="article_id",
        ),
    }


@app.post("/api/articles/batch-advisory-continue")
def api_batch_advisory_continue(payload: BatchAdvisoryContinueRequest, request: Request):
    """批量「忽略普通提示并继续」。

    🔴 这是工单 §6 点名的"一键通过"入口,红线是 **只能通过 A1 与可跳过的人审建议**。
    每一项的顺序刻意是 鉴权 → 护栏 → 动作:
      1. `require_quote_access` —— 与单篇 mark-reviewed 同一道边界,先鉴权再谈其它,
         否则护栏那次 evaluate 会向无权者泄露"这篇存不存在 / 卡在哪一档";
      2. `assert_bulk_pass_allowed` —— 重算发布资格,只有 h0=='clear' 才继续。
         法律硬门 / 平台档 / operator_hard(跨租户·资金·hash lineage·人工拒稿·
         对象不存在)一律拒绝,批量权限**严格窄于**单篇端点;
      3. 复用既有单篇处理函数 `api_mark_topic_reviewed(..., evidence_advisory_continue=True)`
         —— 落库口径、审计事件、409 语义全部与单篇逐字相同。不复制一份 SQL 出来,
         就没有"两份口径慢慢漂开"的机会。
    """
    from services.article_batch_review import (
        BatchItemRejected,
        assert_bulk_pass_allowed,
        run_batch,
    )

    def _continue_one(topic_id: int) -> dict:
        from auth.brand_access import require_quote_access
        from db.diagnosis_db import get_connection

        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute(
                "SELECT t.quote_id, t.article_id FROM topics t WHERE t.id=%s",
                (topic_id,),
            )
            row = c.fetchone()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        if not row:
            raise BatchItemRejected("topic_not_found", "找不到这条选题,可能已被删除。")
        require_quote_access(request, row.get("quote_id"))
        article_id = row.get("article_id")
        if not article_id:
            raise BatchItemRejected("article_not_generated", "这条选题还没有生成文章。")
        assert_bulk_pass_allowed(int(article_id))
        result = api_mark_topic_reviewed(topic_id, request, evidence_advisory_continue=True)
        return {
            "article_id": int(article_id),
            "evidence_advisory_acknowledged": bool(
                (result or {}).get("evidence_advisory_acknowledged")
            ),
        }

    return {
        "success": True,
        **run_batch(payload.topic_ids, _continue_one, id_field="topic_id"),
    }


# ===========================================================================
# [P3b 一键修复全部系统问题 2026-08-01 · 工单 §6 后半] SSE 可恢复批任务
# ===========================================================================
# 与 P3a 的两个同步端点不同:span 级修复要**调模型**,一篇里十几处就是十几次调用,
# 同步等着必然超时。所以这条走 SSE,模式与 /api/meetings/stream、
# /api/social/rewrite-stream 一致(含开头 8KB padding —— 阿里云 ESA 要第一个 chunk
# 够大才进 chunked,否则整个 response 被 buffer 到 100s 触发 524,那条是实证过的)。
#
# 🔴 三个依赖用注入,注进去的就是**既有的单篇端点处理函数**:
#    api_repair_article_finding(免费 + 额度闸 + 鉴权)与 refresh_article_review。
#    不复制第二份实现 = 不会有第二套口径慢慢漂开,也就没有"批量比单篇宽松"的洞。

class BatchRepairStreamRequest(BaseModel):
    article_ids: List[int] = Field(default_factory=list)
    #: 重连传上次拿到的 job_id;不传 = 新建。
    job_id: Optional[str] = None
    #: 重连传上次收到的最后一个 seq;服务端把它之后的事件补齐再接着推。
    last_event_id: int = 0


@app.post("/api/articles/batch-repair-stream")
async def api_batch_repair_stream(payload: BatchRepairStreamRequest, request: Request):
    """一键修复全部系统问题(SSE)。事件九种,每条带工单 §6 规定的八个字段。"""
    from starlette.responses import StreamingResponse

    from services.article_batch_review import normalize_ids
    from services.article_repair_job import (
        HEARTBEAT_INTERVAL_SEC,
        JobOwnershipError,
        MAX_JOB_ARTICLES,
        attach_or_create,
        run_repair_job,
    )

    # SSE 的 generator 里读不到 request.state.user(BaseHTTPMiddleware +
    # StreamingResponse 的已知坑,server.py 里已有同款注释),所以在这里先取出来。
    _user = getattr(request.state, "user", None) or {}
    _user_id = _user.get("user_id") or _user.get("id")
    if not _user_id and not _user.get("is_admin"):
        raise HTTPException(status_code=401, detail="未登录")

    article_ids = normalize_ids(payload.article_ids)[:MAX_JOB_ARTICLES]
    # 🔴 鉴权在建任务之前、在 generator 之外:一旦进了 StreamingResponse,
    # 抛 HTTPException 就变成"流里一段乱码",客户端看到的是连接断了而不是 403。
    for article_id in article_ids:
        _require_article_access(request, article_id)

    try:
        job, created = attach_or_create(
            job_id=payload.job_id, article_ids=article_ids, owner_user_id=_user_id,
        )
    except JobOwnershipError:
        raise HTTPException(status_code=403, detail="这个任务不属于当前账号")

    if created:
        if not article_ids:
            raise HTTPException(status_code=400, detail="没有选中任何文章")

        async def _load_article(article_id: int):
            from db.diagnosis_db import get_connection

            conn = get_connection()
            try:
                c = conn.cursor()
                c.execute(
                    "SELECT a.title, a.quality_warning, q.industry "
                    "  FROM articles a LEFT JOIN quotes q ON q.id = a.quote_id "
                    " WHERE a.id=%s",
                    (article_id,),
                )
                row = c.fetchone()
            finally:
                try:
                    conn.close()
                except Exception:
                    pass
            return dict(row) if row else None

        async def _repair_one(article_id: int, finding_code: str, matched_text: str):
            # 复用既有免费端点处理函数:额度闸(reserve_free_repair 在调模型**之前**
            # 占位)、高风险排除、三态结果、charged:False 全部原样继承。
            return await api_repair_article_finding(
                article_id,
                ArticleFindingRepairRequest(finding_code=finding_code, matched_text=matched_text),
                request,
            )

        async def _validate_article(article_id: int):
            from services.article_review_gate import (
                evaluate_publication_eligibility,
                refresh_article_review,
            )

            def _work():
                from db.diagnosis_db import get_connection

                conn = get_connection()
                try:
                    c = conn.cursor()
                    updated = refresh_article_review(article_id, cursor=c)
                    verdict = evaluate_publication_eligibility(article_id, cursor=c)
                    conn.commit()
                    return {
                        "article_review_status": updated.get("article_review_status"),
                        "remaining_hard": updated.get("article_review_status") == "blocked",
                        "publication_eligible": bool(verdict.get("eligible")),
                    }
                except Exception:
                    try:
                        conn.rollback()
                    except Exception:
                        pass
                    raise
                finally:
                    try:
                        conn.close()
                    except Exception:
                        pass

            return await asyncio.to_thread(_work)

        job.task = asyncio.create_task(run_repair_job(
            job,
            load_article=_load_article,
            repair_one=_repair_one,
            validate_article=_validate_article,
        ))

    async def event_generator():
        # 与 /api/social/rewrite-stream 同款:先吐一个 8KB 的 SSE 注释块,
        # 让 CDN 立刻 flush 进 chunked 模式(5 字节的 ":open" 不够)。
        yield ": " + (" " * 8192) + "\n\n"
        last_seq = max(0, int(payload.last_event_id or 0))
        while True:
            pending = job.events_since(last_seq)
            for event in pending:
                last_seq = event["seq"]
                yield f"id: {event['seq']}\ndata: {json.dumps(event, ensure_ascii=False, default=str)}\n\n"
            if job.finished and not job.events_since(last_seq):
                break
            await job.wait_for_change(HEARTBEAT_INTERVAL_SEC)
            if not job.events_since(last_seq) and not job.finished:
                # heartbeat 也走同一套字段(工单 §6 要求每条都带那八个),
                # 但**不进 job.events** —— 它不是进度,回放时补一堆心跳没有意义。
                yield "data: " + json.dumps({
                    "seq": last_seq, "kind": "heartbeat", "job_id": job.job_id,
                    "article_id": None, "finding_id": None,
                    "done": job.done, "total": job.total,
                    "success_count": job.success_count, "failed_count": job.failed_count,
                    "message": "还在跑",
                }, ensure_ascii=False) + "\n\n"

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
            # 客户端断线重连要带回来的两个值
            "X-Job-Id": job.job_id,
        },
    )


@app.put("/api/articles/{article_id}")
def api_update_article(article_id: int, payload: ArticleEditRequest, request: Request):
    """编辑文章
    [P0-8 fix 2026-05-23 老板授权] 加 owner 反查"""
    try:
        _require_article_access(request, article_id)
        # [GEO-R2-CAN-003 一致性修] 原 PUT 只更新 content·不同步 title·编辑正文 H1 后 stored title 与 body H1 漂移
        #   (生成时 title==H1·发布/下载分别读 title 与 content)。从编辑后正文取首个 Markdown H1 重导出 title。
        import re as _re_h1
        from db.diagnosis_db import get_connection
        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute(
                "SELECT a.quote_id,a.topic_id,a.content,a.generation_request_snapshot,q.brand_id "
                "FROM articles a LEFT JOIN quotes q ON q.id=a.quote_id "
                "WHERE a.id=%s FOR UPDATE OF a",
                (article_id,),
            )
            _before_article = c.fetchone()
            if not _before_article:
                raise HTTPException(status_code=404, detail="文章不存在")
            _updated_content = payload.content
            from services.contact_placeholder import (
                contact_consent_from_snapshot,
                enforce_contact_opt_out,
                hard_strip_contact_without_lookup,
            )
            _contact_consent = contact_consent_from_snapshot(
                _before_article.get("generation_request_snapshot")
            )
            if _contact_consent is False:
                try:
                    _updated_content = enforce_contact_opt_out(
                        _updated_content,
                        _before_article.get("brand_id"),
                    )
                except Exception:
                    try:
                        _updated_content = hard_strip_contact_without_lookup(_updated_content)
                    except Exception:
                        raise HTTPException(status_code=500, detail="contact_opt_out_edit_failed_closed")
            _new_title = None
            for _line in _updated_content.splitlines():
                _m = _re_h1.match(r'^#\s+(.+?)\s*$', _line)
                if _m:
                    _new_title = _m.group(1).strip()
                    break
            if _new_title:
                c.execute('''
                    UPDATE articles
                    SET content=%s, word_count=%s, title=%s, updated_at=CURRENT_TIMESTAMP
                    WHERE id=%s
                ''', (_updated_content, len(_updated_content), _new_title, article_id))
            else:
                c.execute('''
                    UPDATE articles
                    SET content=%s, word_count=%s, updated_at=CURRENT_TIMESTAMP
                    WHERE id=%s
                ''', (_updated_content, len(_updated_content), article_id))
            from services.article_review_gate import refresh_article_review

            review = refresh_article_review(article_id, cursor=c)
            from writing.article_length_contract import build_length_guidance_projection

            _length_guidance = build_length_guidance_projection(
                _before_article.get("generation_request_snapshot"),
                _updated_content,
            )
            _actor = getattr(request.state, "user", None) or {}
            _actor_id = _actor.get("user_id") or _actor.get("id")
            if _actor_id and _before_article.get("quote_id"):
                from services.article_closed_loop_metadata import record_correction_signal_in_transaction_if_enabled

                record_correction_signal_in_transaction_if_enabled(
                    c,
                    quote_id=int(_before_article["quote_id"]),
                    topic_id=_before_article.get("topic_id"),
                    article_id=article_id,
                    before_text=str(_before_article.get("content") or ""),
                    after_text=_updated_content,
                    correction_type="content_fact_or_claim_edit",
                    reason="agent_explicit_article_edit",
                    actor_user_id=int(_actor_id),
                )
            conn.commit()
            return {
                "success": True,
                "message": "文章已更新并重新执行 GEO 文章审核",
                "article": {
                    "id": article_id,
                    "title": _new_title,
                    "content": _updated_content,
                    "length_guidance": _length_guidance,
                },
                "article_review_status": review.get("article_review_status"),
                "publication_profile": review.get("publication_profile"),
                "contact_consent": (
                    "enabled" if _contact_consent is True
                    else "disabled" if _contact_consent is False
                    else "legacy_unknown"
                ),
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"更新文章失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/topics/{topic_id}/mark-reviewed")
def api_mark_topic_reviewed(
    topic_id: int,
    request: Request,
    evidence_advisory_continue: bool = False,
):
    """
    标记 topic 已查看；显式 evidence_advisory_continue 另记录人工继续审计。
    [P0-8 fix 2026-05-23 老板授权] 反查 topic → quote → owner
    """
    try:
        from auth.brand_access import require_quote_access
        from db.diagnosis_db import get_connection
        from datetime import datetime, timezone
        from psycopg2.extras import Json

        # 反查 topic 所属 quote
        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute(
                """
                SELECT t.quote_id,t.article_id,q.brand_id
                FROM topics t
                LEFT JOIN quotes q ON q.id=t.quote_id
                WHERE t.id=%s
                """,
                (topic_id,),
            )
            row = c.fetchone()
        finally:
            try:
                conn.close()
            except Exception:
                pass
        if not row:
            raise HTTPException(status_code=404, detail="topic 不存在")
        require_quote_access(request, row.get("quote_id"))

        conn = get_connection()
        try:
            c = conn.cursor()
            c.execute('''
                UPDATE topics
                SET reviewed_at = %s
                WHERE id = %s AND reviewed_at IS NULL
            ''', (datetime.now().isoformat(), topic_id))
            _advisory_acknowledged = False
            _advisory_replay = False
            _audit_log_id = None
            if evidence_advisory_continue:
                user = getattr(request.state, "user", None) or {}
                actor_user_id = user.get("user_id") or user.get("id")
                if not actor_user_id:
                    raise HTTPException(status_code=401, detail="无法识别人工确认操作人")
                acknowledgment = {
                    "acknowledged": True,
                    "actor_user_id": actor_user_id,
                    "acknowledged_at": datetime.now(timezone.utc).isoformat(),
                    "action": "human_continue",
                }
                c.execute(
                    """
                    UPDATE articles AS a
                    SET quality_warning=jsonb_set(
                        COALESCE(a.quality_warning,'{}'::jsonb),
                        '{human_continue}',
                        %s::jsonb,
                        true
                    )
                    FROM topics AS t
                    WHERE t.id=%s
                      AND a.id=t.article_id
                      AND (
                        jsonb_path_exists(
                            COALESCE(a.quality_warning,'{}'::jsonb),
                            '$.evidence.soft[*]'
                        )
                        OR jsonb_path_exists(
                            COALESCE(a.quality_warning,'{}'::jsonb),
                            '$.evidence_precision.warnings[*]'
                        )
                      )
                      AND COALESCE(a.article_review_status,'legacy_unreviewed')
                          NOT IN ('blocked','rewrite_required')
                      AND (
                          COALESCE(
                              (a.quality_warning->'human_continue'->>'acknowledged')::boolean,
                              false
                          ) IS FALSE
                          OR COALESCE(a.article_human_review_status,'') <> 'approved'
                      )
                    RETURNING a.id
                    """,
                    (Json(acknowledgment), topic_id),
                )
                _ack_row = c.fetchone()
                _advisory_acknowledged = bool(_ack_row)
                if _advisory_acknowledged:
                    from services.article_review_gate import set_human_review

                    try:
                        set_human_review(
                            int(_ack_row["id"]),
                            reviewer_user_id=int(actor_user_id),
                            decision="approved",
                            reason="操作员确认证据提示后继续",
                            cursor=c,
                        )
                    except ValueError as exc:
                        if str(exc) in {
                            "content_changed_after_review",
                            "evidence_changed_after_review",
                            "blocked",
                            "rewrite_required",
                        }:
                            raise HTTPException(
                                status_code=409,
                                detail="文章仍有法律、技术或数据完整性硬门，不能人工覆盖",
                            ) from exc
                        raise
                if not _advisory_acknowledged:
                    c.execute(
                        """
                        SELECT
                            COALESCE(
                                (a.quality_warning->'human_continue'->>'acknowledged')::boolean,
                                false
                            ) AS already_acknowledged,
                            a.article_human_review_status,
                            (
                                jsonb_path_exists(
                                    COALESCE(a.quality_warning,'{}'::jsonb),
                                    '$.evidence.soft[*]'
                                )
                                OR jsonb_path_exists(
                                    COALESCE(a.quality_warning,'{}'::jsonb),
                                    '$.evidence_precision.warnings[*]'
                                )
                            ) AS has_advisory
                        FROM topics t
                        JOIN articles a ON a.id=t.article_id
                        WHERE t.id=%s
                        """,
                        (topic_id,),
                    )
                    _ack_state = c.fetchone() or {}
                    _advisory_replay = bool(
                        _ack_state.get("already_acknowledged")
                        and _ack_state.get("article_human_review_status") == "approved"
                    )
                    if not _ack_state.get("has_advisory"):
                        raise HTTPException(status_code=409, detail="该文章没有待确认的证据提示")
                    if _ack_state.get("already_acknowledged") and not _advisory_replay:
                        raise HTTPException(
                            status_code=409,
                            detail="文章内容或审核状态已变化，请刷新后重新确认",
                        )
            conn.commit()

            if evidence_advisory_continue and _advisory_acknowledged:
                try:
                    from db.pipeline_stage_log_db import log_stage_event

                    _audit_log_id = log_stage_event(
                        brand_id=row.get("brand_id"),
                        stage_name="write",
                        event="complete",
                        meta={
                            "action": "evidence_advisory_human_continue",
                            "quote_id": row.get("quote_id"),
                            "topic_id": topic_id,
                            "article_id": row.get("article_id"),
                        },
                        actor_user_id=actor_user_id,
                    )
                except Exception:
                    _audit_log_id = None

            return {
                "success": True,
                "message": (
                    "证据提示已人工确认，可继续后续流程"
                    if evidence_advisory_continue
                    else "已标记为已审核"
                ),
                "evidence_advisory_acknowledged": (
                    _advisory_acknowledged or _advisory_replay
                ),
                "idempotent_replay": _advisory_replay,
                "article_human_review_status": (
                    "approved"
                    if _advisory_acknowledged or _advisory_replay
                    else None
                ),
                "audit_log_id": _audit_log_id,
            }
        finally:
            try:
                conn.close()
            except Exception: pass
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"标记已审核失败: {e}")
        raise HTTPException(status_code=500, detail=str(e))


# ============================================
# 复杂任务 API (Project Director Handoffs)
# ============================================

# ============================================
# 工作台 API (Workspace)
