@app.post("/api/knowledge/upload")
async def api_upload_knowledge(request: KBUploadRequest, background_tasks: BackgroundTasks = None):
    """上传文档到知识库

    对于客户知识库(kb_type=client)，会自动进行：
    1. LLM清洗 - 提取知识点和关键词
    2. 向量化 - 生成语义向量
    3. 存储 - 保存到LanceDB
    """
    try:
        from tools.unified_knowledge import get_unified_rag
        rag = get_unified_rag()

        # 1. 先保存原文件
        result = rag.add_document(
            kb_type=request.kb_type,
            kb_id=request.kb_id,
            role_type=request.role_type,
            filename=request.filename,
            content=request.content,
        )

        if not result.get("success"):
            return {"status": "error", "error": result.get("error", "保存失败")}

        # 2. 对客户知识库进行实时处理（LLM清洗 + 向量化）
        pipeline_result = None
        if request.kb_type == "client" and request.kb_id:
            try:
                from services.knowledge_pipeline import get_knowledge_pipeline
                pipeline = get_knowledge_pipeline()

                # 异步处理
                pipeline_result = await pipeline.process_document(
                    content=request.content,
                    filename=request.filename,
                    brand_id=int(request.kb_id),
                    skip_clean=False
                )

                if pipeline_result.success:
                    logger.info(f"知识处理完成: {request.filename}, "
                              f"chunks={pipeline_result.chunk_count}, "
                              f"知识点={pipeline_result.knowledge_point_count}")
                else:
                    logger.warning(f"知识处理失败: {pipeline_result.error}")

            except Exception as e:
                logger.warning(f"知识处理流水线异常（原文已保存）: {e}")

        # 构建响应
        response = {
            "status": "success",
            **result
        }

        if pipeline_result:
            response["pipeline"] = {
                "processed": pipeline_result.success,
                "chunk_count": pipeline_result.chunk_count,
                "knowledge_points": pipeline_result.knowledge_point_count,
                "keywords": pipeline_result.keywords[:5],  # 返回前5个关键词
                "processing_time_ms": pipeline_result.processing_time_ms
            }

        return response

    except Exception as e:
        logger.error(f"上传知识库文档失败: {e}")
        return {"status": "error", "error": str(e)}


