@app.post("/api/knowledge/upload-file")
async def api_upload_knowledge_file(
    file: UploadFile = File(...),
    kb_type: str = Form(...),
    kb_id: str = Form(...)
):
    """上传文件到知识库（支持PDF、MD、TXT）"""
    try:
        filename = file.filename
        ext = filename.split('.')[-1].lower() if '.' in filename else ''

        if ext not in ['pdf', 'md', 'txt']:
            return {"status": "error", "error": "仅支持 .pdf, .md, .txt 格式"}

        file_bytes = await file.read()
        content = ""

        if ext == 'pdf':
            try:
                import io
                from pypdf import PdfReader
                pdf_reader = PdfReader(io.BytesIO(file_bytes))
                text_parts = []
                for page in pdf_reader.pages:
                    text = page.extract_text()
                    if text:
                        text_parts.append(text)
                content = "\n\n".join(text_parts)

                if not content.strip():
                    return {"status": "error", "error": "PDF内容为空或无法提取文本"}
            except ImportError:
                return {"status": "error", "error": "服务器未安装pypdf库"}
            except Exception as e:
                return {"status": "error", "error": f"PDF解析失败: {str(e)}"}
        else:
            try:
                content = file_bytes.decode('utf-8')
            except:
                content = file_bytes.decode('gbk', errors='ignore')

        if not content.strip():
            return {"status": "error", "error": "文件内容为空"}

        from tools.unified_knowledge import get_unified_rag
        rag = get_unified_rag()
        result = rag.add_document(
            kb_type=kb_type,
            kb_id=kb_id,
            role_type="",
            filename=filename,
            content=content,
        )

        if not result.get("success"):
            return {"status": "error", "error": result.get("error", "保存失败")}

        pipeline_result = None
        if kb_type == "client" and kb_id:
            try:
                from services.knowledge_pipeline import get_knowledge_pipeline
                pipeline = get_knowledge_pipeline()
                pipeline_result = await pipeline.process_document(
                    content=content,
                    filename=filename,
                    brand_id=int(kb_id),
                    skip_clean=False
                )
            except Exception as e:
                logger.warning(f"知识处理流水线异常: {e}")

        response = {"status": "success", **result}
        if pipeline_result:
            response["pipeline"] = {
                "processed": pipeline_result.success,
                "chunk_count": pipeline_result.chunk_count,
                "knowledge_points": pipeline_result.knowledge_point_count,
                "keywords": pipeline_result.keywords[:5],
                "processing_time_ms": pipeline_result.processing_time_ms
            }
        return response

    except Exception as e:
        logger.error(f"文件上传失败: {e}")
        return {"status": "error", "error": str(e)}


class KBSearchRequest(BaseModel):
    """知识库搜索请求"""
    query: str
    brand_id: int = None  # 客户ID，用于搜索客户知识库
    top_k: int = 5
    use_rerank: bool = True  # 是否使用Rerank重排序


@app.post("/api/knowledge/search")
async def api_search_knowledge(request: KBSearchRequest):
    """语义检索知识库

    流程：
    1. Query向量化 (text-embedding-v4)
    2. 向量检索 LanceDB (top-50)
    3. Rerank重排序 (qwen3-vl-rerank) → top-k
    """
    try:
        import lancedb
        from pathlib import Path
        from services.knowledge_pipeline import get_knowledge_pipeline, get_rerank_service

        pipeline = get_knowledge_pipeline()

        # 1. Query向量化
        query_vectors = await pipeline.batch_embed([request.query])
        if not query_vectors:
            return {"status": "error", "error": "Query向量化失败"}

        query_vector = query_vectors[0]

        # 2. 向量检索
        db_path = Path("data/vectordb")
        if not db_path.exists():
            return {"status": "success", "results": [], "message": "知识库为空"}

        db = lancedb.connect(str(db_path))

        # 确定要搜索的表
        tables_to_search = []
        if request.brand_id:
            table_name = f"knowledge_client_{request.brand_id}"
            # [2026-06-11 修分页bug] table_names() 默认分页(返10)·表存在却漏列→误判不存在→"知识库为空"·limit 拿全
            if table_name in db.table_names(limit=100000):
                tables_to_search.append(table_name)
        else:
            tables_to_search = [t for t in db.table_names(limit=100000) if t.startswith("knowledge_client_")]

        if not tables_to_search:
            return {"status": "success", "results": [], "message": "无匹配知识库"}

        # 在所有相关表中搜索
        all_results = []
        for table_name in tables_to_search:
            try:
                table = db.open_table(table_name)
                search_results = table.search(query_vector).limit(50).to_list()
                for r in search_results:
                    all_results.append({
                        "content": r.get("content", ""),
                        "filename": r.get("filename", ""),
                        "brand_id": r.get("brand_id"),
                        "keywords": r.get("keywords", ""),
                        "_distance": r.get("_distance", 0)
                    })
            except Exception as e:
                logger.warning(f"搜索表 {table_name} 失败: {e}")

        if not all_results:
            return {"status": "success", "results": []}

        # 按距离排序
        all_results.sort(key=lambda x: x.get("_distance", 0))
        candidates = all_results[:50]

        # 3. Rerank重排序
        if request.use_rerank and len(candidates) > 1:
            try:
                rerank_service = get_rerank_service()
                documents = [c["content"] for c in candidates]
                reranked = await rerank_service.rerank(
                    query=request.query,
                    documents=documents,
                    top_n=request.top_k
                )

                final_results = []
                for r in reranked:
                    idx = r.get("index", 0)
                    if idx < len(candidates):
                        candidate = candidates[idx]
                        final_results.append({
                            "content": candidate["content"],
                            "filename": candidate["filename"],
                            "brand_id": candidate["brand_id"],
                            "keywords": candidate["keywords"],
                            "score": r.get("score", 0)
                        })

                return {"status": "success", "results": final_results, "reranked": True}

            except Exception as e:
                logger.warning(f"Rerank失败，使用向量距离排序: {e}")

        # 直接返回向量检索结果
        final_results = [{
            "content": r["content"],
            "filename": r["filename"],
            "brand_id": r["brand_id"],
            "keywords": r["keywords"],
            "score": 1 - r.get("_distance", 0)
        } for r in candidates[:request.top_k]]

        return {"status": "success", "results": final_results, "reranked": False}

    except Exception as e:
        logger.error(f"知识库搜索失败: {e}")
        return {"status": "error", "error": str(e)}

