@app.get("/api/dashboard/enhanced-stats")
def get_enhanced_dashboard_stats(request: Request):
    """获取Dashboard增强统计数据
    [P1-18 fix 2026-05-23 老板授权] Codex 跨 AI 审计 · 非 admin 返用户级 / admin 全局"""
    try:
        user = getattr(request.state, "user", None)
        if not user:
            raise HTTPException(status_code=401, detail="未登录")
        from db.dashboard_stats import get_enhanced_dashboard_stats as get_stats
        from auth.brand_access import get_user_brand_filter
        allowed = get_user_brand_filter(request)
        if allowed is None:
            # admin 全局
            return {"status": "success", "data": get_stats()}
        # 非 admin 走用户作用域 · 老板 home-stats 已是 user-specific
        try:
            data = get_stats(brand_ids=allowed)  # 若支持 brand_ids 参数
        except TypeError:
            # 老 DB 函数 fallback 用 home-stats endpoint 数据
            data = {"_scoped": "user", "message": "请使用 /api/user/home-stats 查看个人统计"}
        return {"status": "success", "data": data, "scope": "user"}
    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"获取增强统计失败: {e}")
        return {"status": "error", "error": str(e)}


